let allNews = [];
// Marque du concurrent, ancree en DEBUT de titre. Definie ICI (avant loadHistory qui l utilise) :
// une const n est pas hoistee, l employer plus haut jetterait au chargement.
const _COMPETITOR_BRAND = /^\s*(?:PMT|Prime\s+(?:Market\s+)?Terminal)\b/i;
// Plafond du magasin de news QUI PROTÈGE LES RAPPORTS DTP (20/08, flood 22:24 constaté par le user) :
// un simple slice(0, 2000) évinçait les rapports du matin les jours à très fort volume (FOMC), et le
// rattrapage du boot suivant les croyait manquants → re-publication en bloc horodatée « maintenant ».
// Les rapports (_reportType) sont gardés à part (bornés à 300, ~1 mois) et réinjectés après la coupe.
// Créneaux Paris des briefings quotidiens : un rapport RATTRAPÉ après un redémarrage portait
// l'heure du boot (pile de neuf rapports à 22:33, constatée par le user) : on le retamponne à
// l'heure de son créneau, même jour. Marge 90 min : un rapport publié À son créneau n'est jamais
// touché ; FX Daily Recap (23:45 voulu), analyses d'événement (heure de l'événement) et Synthèses
// de séance (_marketWrap) ne figurent pas dans la table : jamais retamponnés.
const _SLOTS_RAPPORT = [
  [/asia.?pac opening|dtp daily asia/i, 1, 30],
  [/london opening/i, 7, 45],
  [/asia session recap/i, 9, 30],
  [/^dtp daily$/i, 12, 0],
  [/us opening/i, 14, 45],
  [/london session recap/i, 17, 30],
  [/daily market recap/i, 22, 0],
  [/us session recap/i, 22, 15],
  [/daily event review/i, 23, 0],
];
function _snapRapportTs(i) {
  try {
    const cible = String(i._reportType || '') + ' ' + String(i.headline || '').slice(0, 40);
    for (const [rx, h, m] of _SLOTS_RAPPORT) {
      if (!rx.test(cible)) continue;
      // Heure du créneau CE JOUR-LÀ (Paris), reconstruite depuis le jour de l'item.
      const d = new Date(i.timestamp || Date.now());
      const paris = new Date(d.toLocaleString('en-US', { timeZone: 'Europe/Paris' }));
      const dec = d.getTime() - paris.getTime();   // décalage local->Paris à cette date (DST compris)
      const slot = new Date(paris); slot.setHours(h, m, 0, 0);
      const slotTs = slot.getTime() + dec;
      if (slotTs > Date.now()) return;   // jamais d horodatage dans le futur (creneau du jour pas encore atteint)
      if (Math.abs((i.timestamp || 0) - slotTs) > 90 * 60 * 1000) i.timestamp = slotTs;
      return;
    }
  } catch (e) {}
}
function _capNews(arr) {
  const rapports = [], flux = [];
  for (const i of arr) { if (i && i._reportType) { _snapRapportTs(i); rapports.push(i); } else if (i) flux.push(i); }
  const vus = new Set();
  return [...flux.slice(0, 2000), ...rapports.slice(0, 300)]
    .filter(i => { const k = i.id; if (k == null) return true; if (vus.has(k)) return false; vus.add(k); return true; })
    .sort((x, y) => (y.timestamp || 0) - (x.timestamp || 0));
}
let allCalendar = [];   // FF calendar events served separately
let isFirstLoad = true;
let _saveTimer  = null;
let _mosaicImages     = [];
let _mosaicRefreshedAt = 0;
let _swCache      = [];
let _swFetchedAt  = 0;
let _swSilenceAlerte = 0;   // dernière alerte « source muette » (max 1/jour)
let _brCache     = [];
let _brFetchedAt = 0;

function loadHistory() {
  try {
    const raw    = JSON.parse(fs.readFileSync(HISTORY_FILE, 'utf8'));
    const cutoff = Date.now() - HISTORY_TTL;
    const items  = (raw.items || []).filter(i => i.timestamp > cutoff);
    console.log(`[History] Loaded ${items.length} items from disk (last 7 days)`);
    return items;
  } catch { return []; }
}

function saveHistory() {
  if (_saveTimer) clearTimeout(_saveTimer);
  _saveTimer = setTimeout(() => {
    try {
      fs.writeFileSync(HISTORY_FILE, JSON.stringify({ savedAt: Date.now(), items: allNews }));
    } catch (e) { console.error('[History] Save error:', e.message); }
  }, 5000);
}

// Economic data agency detection — defined early so loadHistory remapping can use it
const ECON_AGENCIES_EARLY = [
  [/\bpmi\b|purchasing managers|markit/i,                              'S&P Global'],
  [/\bism\b/i,                                                          'ISM'],
  [/nfp|non.?farm payroll|initial claims|continuing claims|challenger|jobless claims/i, 'BLS'],
  [/payroll|unemployment rate|employment change|average hourly|workweek/i, 'BLS'],
  [/\bpce\b|personal income|personal spending|unit labor|labor cost/i, 'BEA'],
  [/consumer credit/i,                                                  'Federal Reserve'],
  [/\bifo\b/i,                                                          'IFO Institute'],
  [/\bzew\b/i,                                                          'ZEW'],
  [/eurozone.*cpi|cpi.*eurozone|eurozone.*gdp|gdp.*eurozone|eurozone.*retail|eurostat/i, 'Eurostat'],
  [/\buk\b.*cpi|cpi.*\buk\b|\buk\b.*gdp|gdp.*\buk\b|\brpi\b/i,       'ONS'],
  [/australia.*cpi|cpi.*australia|australia.*trade|aus.*gdp/i,         'ABS'],
  [/canada.*cpi|cpi.*canada|canadian.*employment|canadian.*unemployment/i, 'Statistics Canada'],
  [/japan.*cpi|japan.*gdp|japan.*pmi|tankan/i,                         'Statistics Japan'],
  [/china.*pmi|china.*cpi|china.*gdp|\bnbs\b/i,                        'NBS China'],
  [/swiss.*cpi|cpi.*swiss|swiss.*gdp|switzerland.*unemployment/i,      'Statistics CH'],
  [/turkish.*cpi|cpi.*turkish|turkey.*cpi/i,                           'TURKSTAT'],
  [/\bnfib\b/i,                                                         'NFIB'],
  [/house price|home price|existing home|pending home|housing starts/i,'NAR / Census'],
  [/consumer confidence|consumer sentiment/i,                           'Conference Board'],
];

function _detectEconAgencyEarly(text) {
  for (const [rx, agency] of ECON_AGENCIES_EARLY) {
    if (rx.test(text)) return agency;
  }
  return null;
}

allNews = loadHistory().filter(item => item && !/^\s*\[?\s*primer\b/i.test(item.headline || '') && !_COMPETITOR_BRAND.test(item.headline || '')).map(item => {   // purge des "PRIMER" déjà persistés
  if (item.category === 'Economic Commentary' && item.source === 'FinancialJuice') {
    const agency = _detectEconAgencyEarly(item.headline);
    if (agency) return { ...item, source: agency };
  }
  return item;
});

// ─── Session ──────────────────────────────────────────────────────────────────
// ⚠️ Si SESSION_SECRET n'est pas posé, les cookies de session sont signés avec un littéral du code —
// FORGEABLES par quiconque a vu le dépôt, y compris une session admin. On ne remplace PAS le repli en
// aveugle (un secret aléatoire par boot déconnecterait tous les membres à chaque déploiement si l'env
// manquait) : on hurle dans les logs pour que l'absence se voie au premier docker logs. (07/08)
if (!process.env.SESSION_SECRET) console.error('[Sécurité] SESSION_SECRET ABSENT → cookies signés avec le littéral du code, sessions forgeables. Posez SESSION_SECRET dans l\'environnement immédiatement.');
const _sessionMw = session({
  name:     'dtp_session',
  /* ⚠️ PLUS DE SECRET DE REPLI ECRIT EN DUR. Un secret constant present dans le code signifie que
     quiconque lit le depot peut FORGER un cookie de session, donc se declarer administrateur, le
     jour ou la variable d environnement manque. Le depot ayant ete public jusqu au 21/08, cette
     valeur etait connue.
     On ne coupe pas le service pour autant : sans variable, on tire un secret ALEATOIRE au
     demarrage. Consequence assumee et volontairement visible : les sessions ne survivent pas a un
     redemarrage, ce qui se remarque tout de suite et pousse a corriger la configuration, la ou un
     secret constant ne se remarque jamais. */
  secret:   process.env.SESSION_SECRET || require('crypto').randomBytes(32).toString('hex'),
  httpOnly: true,
  sameSite: 'lax',
  secure:   process.env.NODE_ENV === 'production',  // HTTPS uniquement en prod
  domain:   process.env.NODE_ENV === 'production' ? '.datatradingpro.com' : undefined,  // login PARTAGÉ apex ↔ www ↔ desk
  maxAge:   24 * 60 * 60 * 1000,   // 24 h (demande user : session-timeout desk à 24 h → reconnexion quotidienne)
});
app.use(_sessionMw);
// « Rester connecté » : la durée longue doit être ré-imposée à CHAQUE requête, pas seulement à la
// connexion. cookie-session relit `req.sessionOptions` chaque fois qu'il ré-écrit le cookie ; sans
// cette ligne, la première écriture suivante le ramènerait à 24 h et la case serait de nouveau sans
// effet au bout d'une journée — exactement le symptôme qu'on corrige.
app.use((req, _res, next) => {
  if (req.session && req.session.remember) { try { req.sessionOptions.maxAge = _SESSION_MAX_LONG_MS; } catch (e) {} }
  next();
});

// ─── Présence "en ligne" (suivi des connexions WebSocket par utilisateur) ─────
const _onlineUsers = new Map();   // userId → nombre d'onglets/WS ouverts
function _isUserOnline(id) { return _onlineUsers.has(String(id)); }
// « Vu la dernière fois » : timestamp de la dernière présence (WS connect/disconnect). Persisté (survit
// aux redéploiements) + flush périodique (pas à chaque event). Permet au support d'afficher « hors ligne
// depuis 10 min » dans l'en-tête d'une conversation. _loadJsonMap est hoisté (function declaration).
const _LASTSEEN_FILE = path.join(_CACHE_DIR, 'cache_lastseen.json');
const _lastSeen = _loadJsonMap(_LASTSEEN_FILE);   // userId → ts
let _lastSeenDirty = false;
function _stampSeen(id) { if (id) { _lastSeen.set(String(id), Date.now()); _lastSeenDirty = true; } }
function _userPresence(id) { const k = String(id); return { online: _onlineUsers.has(k), lastSeen: _lastSeen.get(k) || null }; }
function _msOf(v) { if (!v) return 0; const t = new Date(v).getTime(); return isNaN(t) ? 0 : t; }
// Presence AVEC repli « derniere activite » = dernier message du client, quand aucune connexion WS n'a
// ete enregistree (ex. apres un redemarrage serveur). Evite le « Hors ligne » nu → toujours « depuis X ».
function _presenceWithFallback(id, lastActivity) {
  const p = _userPresence(id);
  return { online: p.online, lastSeen: p.lastSeen || (_msOf(lastActivity) || null) };
}
setInterval(() => {
  if (!_lastSeenDirty) return;
  _lastSeenDirty = false;
  try { const cut = Date.now() - 30 * 24 * 3600 * 1000; for (const [k, v] of _lastSeen) if (!v || v < cut) _lastSeen.delete(k); } catch {}   // purge > 30 j
  try { _saveJsonMap(_LASTSEEN_FILE, _lastSeen); } catch {}
}, 120000).unref?.();
function _wsUserIdFromReq(req) {
  try {
    const fakeRes = { end() {}, setHeader() {}, getHeader() {}, writeHead() {} };
    _sessionMw(req, fakeRes, () => {});
    return req.session && req.session.userId ? String(req.session.userId) : null;
  } catch { return null; }
}

