// Mot de passe oublié : génère un MDP temporaire et l'envoie par email.
// Réponse toujours { ok:true } (ne révèle pas si l'email existe).
const _recentForgot = new Map();            // email → ts du dernier reset RÉELLEMENT émis
const FORGOT_COOLDOWN_MS = 2 * 60 * 1000;   // 2 min : un 2e « mot de passe oublié » trop rapproché ne régénère PAS
app.post('/api/auth/forgot-password', (req, res) => {
  const email = (req.body?.email || '').toLowerCase().trim();
  res.json({ ok: true });   // réponse IMMÉDIATE (UX instantanée + anti-énumération)
  // Anti-abus : max 5 demandes / 10 min / IP (au-delà, on ignore silencieusement)
  if (_rateLimited('forgot:' + _clientIp(req), 5, 10 * 60 * 1000)) return;
  if (!email) return;
  // VERROU PAR EMAIL (posé SYNCHRONEMENT, avant tout await) : un double-clic générait DEUX MDP
  // temporaires différents — le 2e changePassword écrasait le MDP stocké — tandis que l'anti-doublon
  // <12s du mailer SUPPRIMAIT le 2e email. Résultat : l'utilisateur recevait le MDP n°1 mais la base
  // contenait le n°2 → « identifiants incorrects ». On ne régénère donc qu'UNE fois par fenêtre :
  // l'email déjà envoyé reste valide. (Node mono-thread : set avant le 1er await => atomique.)
  if (Date.now() - (_recentForgot.get(email) || 0) < FORGOT_COOLDOWN_MS) {
    console.log(`[Auth] forgot ignoré (reset déjà émis <2 min) → ${email}`);
    return;
  }
  _recentForgot.set(email, Date.now());
  if (_recentForgot.size > 5000) _recentForgot.clear();   // garde-fou mémoire
  // Le travail (lookup + hash bcrypt + update DB + email) se fait en arrière-plan, après la réponse.
  (async () => {
    try {
      const users = await auth.getAllUsers();
      const u = users.find(x => (x.email || '').toLowerCase() === email);
      if (u) {
        // SÉCURITÉ : réinitialisation RÉSERVÉE aux abonnements ACTIFS (staff toujours OK). Un compte
        // suspendu/expiré reçoit un e-mail « abonnement inactif » (aucun mot de passe n'est régénéré).
        const _staff = u.role === 'admin' || u.role === 'support';
        const _expMs = u.expires_at ? new Date(u.expires_at).getTime() : null;
        const _GRACE = 24 * 60 * 60 * 1000;   // même tolérance que la connexion (renouvellement en cours)
        const _active = _staff || (u.active !== false && (!_expMs || _expMs + _GRACE >= Date.now()));
        if (_active) {
          /* ⚠️ ON ENVOIE D'ABORD, ON CHANGE LE MOT DE PASSE ENSUITE (26/08, incident client : « j'ai
             reset mon mdp, je l'ai pas reçu »). L'ordre était inverse — `changePassword` PUIS un
             envoi en « fire-and-forget » — et surtout `_send` ne LÈVE PAS quand tous les
             fournisseurs échouent : il rend `false`. Le `.catch(() => {})` ne pouvait donc jamais se
             déclencher, la valeur de retour était jetée, et le journal écrivait « Mot de passe
             réinitialisé » quoi qu'il arrive. Résultat : l'ancien mot de passe était détruit, le
             nouveau n'arrivait jamais, et le client se retrouvait ENFERMÉ DEHORS — sans trace autre
             que la ligne d'échec du mailer, à laquelle rien ne renvoyait.
             Dans ce sens-ci, un envoi qui échoue ne coûte RIEN : le compte n'a pas bougé, l'ancien
             mot de passe fonctionne toujours, et l'utilisateur peut réessayer tout de suite. Le
             risque symétrique — envoi réussi puis écriture qui échoue — laisse l'utilisateur avec un
             mot de passe qui ne marche pas MAIS son ancien intact : il n'est jamais enfermé dehors. */
          const temp = require('crypto').randomBytes(9).toString('base64').replace(/[^a-zA-Z0-9]/g, '').slice(0, 10) + 'A1';
          const envoye = await mailer.sendPasswordReset({ to: u.email, name: u.name, password: temp }).catch(e => {
            console.error(`[Auth] forgot : envoi impossible → ${u.email} :`, e.message);
            return false;
          });
          if (!envoye) {
            // Rien n'a été touché. On libère le verrou : sans ça l'utilisateur réessaie et sa demande
            // est ignorée en silence pendant deux minutes, pour un e-mail qui n'est jamais parti.
            _recentForgot.delete(email);
            console.error(`[Auth] ❌ forgot ABANDONNÉ → ${u.email} : aucun fournisseur n'a accepté l'e-mail, MOT DE PASSE INCHANGÉ (le client peut toujours se connecter avec l'ancien).`);
            return;
          }
          try {
            await auth.changePassword(u.id, temp);
            console.log(`[Auth] Mot de passe réinitialisé (forgot) → ${u.email} (e-mail parti via ${envoye})`);
          } catch (e) {
            _recentForgot.delete(email);
            console.error(`[Auth] ⚠️ forgot : e-mail PARTI mais écriture du mot de passe ÉCHOUÉE → ${u.email} :`, e.message,
              '— le client doit utiliser son ANCIEN mot de passe et refaire une demande.');
          }
        } else {
          const envoye = await mailer.sendForgotNoSub({ to: u.email, name: u.name }).catch(e => {
            console.error(`[Auth] forgot (inactif) : envoi impossible → ${u.email} :`, e.message);
            return false;
          });
          if (!envoye) _recentForgot.delete(email);
          console.log(`[Auth] forgot REFUSÉ (abonnement inactif) → ${u.email} : e-mail de réactivation ${envoye ? 'envoyé via ' + envoye : 'NON PARTI'}`);
        }
      } else {
        _recentForgot.delete(email);   // email inexistant → on libère le verrou (aucun reset effectué)
      }
    } catch (e) { _recentForgot.delete(email); console.error('[Auth] forgot-password error:', e.message); }
  })();
});

app.get('/api/auth/me', async (req, res) => {
  if (!req.session?.userId) return res.json({ loggedIn: false });
  // COUPERET 24 h (le heartbeat du desk ~20 s passe ICI, pas par requireAuth — /api/auth/ est public) :
  // session plus vieille que 24 h → déconnexion immédiate sur TOUTES les plateformes (web/app/mobile).
  if (_sessionExpired(req)) { req.session = null; return res.json({ loggedIn: false, reason: 'expired' }); }
  try {
    // Toujours relire depuis la DB → les changements admin (active, plan…) sont immédiatement reflétés
    const fresh = await auth.getUserById(req.session.userId);
    if (!fresh) { req.session = null; return res.json({ loggedIn: false }); }
    // Éjection : blacklisté, suspendu (client non-actif), déconnexion admin, ou session supplantée par une
    // connexion plus récente (session unique par compte) → logout immédiat.
    const _mep = _sessionEpoch.get(String(req.session.userId));
    // Même garde que dans requireAuth : une session sans jeton est ANTÉRIEURE au mécanisme, elle ne
    // doit pas être éjectée par la restauration du registre au démarrage.
    const _tokenSupplante = !!(_mep && req.session.stoken && _mep !== req.session.stoken);

    /* SECOND VERROU : le navigateur. Le desk annonce son identifiant à CHAQUE battement, mais ne
       RÉCLAME le compte qu'au chargement de la page (en-tête `x-dtp-appareil-neuf`). Sans cette
       distinction, deux navigateurs se réclameraient le compte toutes les 20 secondes et se
       chasseraient l'un l'autre sans fin. */
    const _dev = _devDeLaRequete(req), _uidS = String(req.session.userId);
    let _devSupplante = false;
    if (_dev && String(req.headers['x-dtp-appareil-neuf'] || '') === '1') {
      if (_devReclamer(_uidS, _dev)) _fermerSocketsAppareil(_uidS, _dev);   // reprise : on coupe l'ancien flux
    } else if (_dev) {
      const _det = _sessionDevice.get(_uidS);
      _devSupplante = !!(_det && _det.dev !== _dev);
    }
    const _superseded = _tokenSupplante || _devSupplante;
    if (_forceLogout.has(String(req.session.userId)) || auth.isEmailBlacklisted(fresh.email)
        || (fresh.role !== 'admin' && fresh.role !== 'support' && fresh.active === false) || _superseded) {
      req.session = null; return res.json({ loggedIn: false, reason: _superseded ? 'elsewhere' : undefined });
    }
    // (Audit 28/07) Échéance dépassée AU-DELÀ de la grâce de 24 h (même règle que le login) → la
    // session en cours est éjectée aussi. Avant : un compte marqué expiré gardait son desk ouvert
    // tant que sa session vivait, seule la reconnexion était bloquée.
    if (fresh.role !== 'admin' && fresh.role !== 'support' && fresh.expires_at) {
      const _expT = new Date(fresh.expires_at).getTime();
      if (Number.isFinite(_expT) && _expT + 24 * 3600e3 < Date.now()) { req.session = null; return res.json({ loggedIn: false, reason: 'expired' }); }
    }
    const expiresAt = fresh.expires_at || null;
    const isTrial = _isTrialAccount(fresh);
    // Libellé du badge profil : « TYPE · CADENCE » (ex. « Professionnel · Mensuel ») — remplace le
    // libellé codé en dur du desk. Type depuis le compte, cadence dérivée/override (_cadOf).
    const _tl = fresh.role !== 'client' ? '' : (_isFriend(fresh) ? 'Amis' : (isTrial ? 'Essai gratuit' : 'Professionnel'));
    const _cl = _CAD_LBL[_cadOf(fresh)] || '';
    const planLabel = _tl ? (_cl && _tl !== 'Essai gratuit' ? _tl + ' · ' + _cl : _tl) : 'Professionnel';
    const user = { id: fresh.id, email: fresh.email, name: fresh.name, role: fresh.role, plan: fresh.plan, active: !!fresh.active, expiresAt, isTrial, planLabel };
    req.session.user = user; // maintenir la session à jour
    // loginAt = ancre ABSOLUE du login (déjà posée pour le couperet 24 h). Exposée au front pour
    // qu'il distingue « nouvelle connexion » de « rechargement de page » — sessionStorage ne sait
    // pas faire la différence. C'est un horodatage, pas un secret.
    res.json({ loggedIn: true, user, loginAt: req.session.loginAt || 0, feat: _newFeat });
  } catch {
    // Fallback si DB inaccessible : utiliser la session
    res.json({ loggedIn: true, user: req.session.user, loginAt: req.session.loginAt || 0, feat: _newFeat });
  }
});

// ── Historique « Recent Searches » de la recherche symbole, PERSISTANT PAR COMPTE ──
// Stockage léger via le KV durable Supabase (auth.aiCacheSet/Get), clé symrecent:<userId> → suit la
// reconnexion (même sur un autre appareil). Valeur = { recent: [<6 codes de paire>] }. 0 schéma, 0 charge notable.
const _SYM_RX = /^[A-Z]{6}$/;
app.get('/api/sym-recent', async (req, res) => {
  if (!req.session?.userId) return res.json({ recent: [] });
  try {
    const v = await auth.aiCacheGet('symrecent:' + req.session.userId);
    const recent = (v && Array.isArray(v.recent)) ? v.recent.filter(p => typeof p === 'string' && _SYM_RX.test(p)).slice(0, 8) : [];
    res.json({ recent });
  } catch { res.json({ recent: [] }); }
});
app.post('/api/sym-recent', async (req, res) => {
  if (!req.session?.userId) return res.status(401).json({ ok: false });
  try {
    const arr = Array.isArray(req.body?.recent) ? req.body.recent : [];
    const recent = arr.filter(p => typeof p === 'string' && _SYM_RX.test(p)).slice(0, 8);
    await auth.aiCacheSet('symrecent:' + req.session.userId, { recent });
    res.json({ ok: true, recent });
  } catch { res.status(500).json({ ok: false }); }
});

// ── Rapports Analyst « LUS » (cartes grisées), PERSISTANT PAR COMPTE (KV durable Supabase, modèle
//    symrecent → suit la reconnexion / le changement d'appareil ; dual-write KV survit au blackout egress).
//    Valeur = { ids: [<clés de lecture stables = _reportReadKey côté client : id stable, wk:…, fxr:…>] }.
app.get('/api/read-reports', async (req, res) => {
  if (!req.session?.userId) return res.json({ ids: [] });
  try {
    const v = await auth.aiCacheGet('readreports:' + req.session.userId);
    const ids = (v && Array.isArray(v.ids)) ? v.ids.filter(x => typeof x === 'string' && x.length <= 160).slice(-500) : [];
    res.json({ ids });
  } catch { res.json({ ids: [] }); }
});
app.post('/api/read-reports', async (req, res) => {
  if (!req.session?.userId) return res.status(401).json({ ok: false });
  try {
    const arr = Array.isArray(req.body?.ids) ? req.body.ids : [];
    const ids = [...new Set(arr.filter(x => typeof x === 'string' && x && x.length <= 160))].slice(-500);
    await auth.aiCacheSet('readreports:' + req.session.userId, { ids });
    res.json({ ok: true });
  } catch { res.status(500).json({ ok: false }); }
});

/* ══════════════════════════════════════════════════════════════════════════════════════════════
   LES DIRECTS DANS LA CARTE — ON RÉSOUT LA CHAÎNE, ON NE DEVINE PAS UN IDENTIFIANT (04/09)
   ══════════════════════════════════════════════════════════════════════════════════════════════
   Demande de l'utilisateur, capture à l'appui : « pour Bloomberg et Yahoo on doit avoir la vidéo
   DANS le widget, tu comprends le but du widget ? ». Il a raison : une carte nommée « Bloomberg
   Live » qui n'affiche qu'un bouton « Ouvrir le direct » ne fait pas ce que son nom promet.

   ⚠️ POURQUOI UN ENDPOINT SERVEUR ET PAS UN IDENTIFIANT ÉCRIT EN DUR. Deux raisons, et la seconde
   est la vraie :
     1. Un identifiant de vidéo écrit dans le code est PÉRIMABLE. Une chaîne d'information en
        continu redémarre son flux régulièrement (maintenance, changement d'émission), et chaque
        redémarrage crée une NOUVELLE vidéo. Le desk afficherait alors un cadre mort, sans que rien
        ne le signale — la panne silencieuse que ce dépôt traque partout ailleurs.
     2. Personne ici n'a pu VÉRIFIER cet identifiant. L'environnement de développement de cette
        session n'a pas accès à YouTube (refus 403 du proxy, mesuré). Écrire un identifiant de
        mémoire aurait été livrer une supposition à des clients payants. On livre donc le MÉCANISME
        qui va le chercher, et un repli qui vaut exactement le comportement d'aujourd'hui.

   COMMENT. On demande à YouTube la page « /<poignée>/live » de la chaîne : elle redirige vers la
   diffusion EN COURS, et son lien canonique porte l'identifiant du jour. On en tire deux choses,
   par ordre de préférence :
     · l'identifiant de la diffusion en cours (`videoId`) → cadre exact, celui que le client veut ;
     · à défaut l'identifiant de CHAÎNE (`channelId`) → cadre « dernière diffusion de cette chaîne »,
       qui ne périme jamais mais montre un écran d'attente hors antenne.
   Aucun des deux → la carte-lien d'avant. Trois étages, chacun honnête sur ce qu'il sait.

   ⚠️ ET ON CACHE, PARCE QU'UN VPS À 512 Mo NE FAIT PAS UNE REQUÊTE PAR OUVERTURE DE CARTE. Le KV
   Supabase (`direct:<clé>`) porte le résultat ; la diffusion en cours est revérifiée toutes les
   30 min, l'identifiant de chaîne est gardé une semaine (il ne change jamais). Un échec de
   résolution NE VIDE PAS le cache : mieux vaut servir la diffusion d'il y a une heure — qui est
   presque toujours la même, ces chaînes tournant en continu — qu'un cadre vide.
   ⚠️ PLUSIEURS POIGNÉES PAR CHAÎNE, ESSAYÉES DANS L'ORDRE. Une chaîne peut être renommée ; la
   première poignée qui répond gagne. C'est ce qui permet au mécanisme de se réparer seul sans
   redéploiement le jour où l'une d'elles disparaît. */
const _DIRECTS = {
  bloomberg: { nom: 'Bloomberg Television', poignees: ['@markets', '@BloombergTelevision', '@business'],
               site: 'https://www.bloomberg.com/live/us',
               env: 'DTP_DIRECT_BLOOMBERG', graine: 'UCIALMKvObZNtJ6AmdCLP7Lg', attendu: /bloomberg/i },
  yahoo:     { nom: 'Yahoo Finance',        poignees: ['@YahooFinance', '@yahoofinance'],
               site: 'https://finance.yahoo.com/live/',
               env: 'DTP_DIRECT_YAHOO', graine: 'UCEAZeUIeJs0IjQiqTCdVSIg', attendu: /yahoo/i },
};
const _DIRECT_TTL_VIDEO = 30 * 60 * 1000;           // la diffusion en cours : revue toutes les 30 min
const _DIRECT_TTL_CHAINE = 7 * 24 * 60 * 60 * 1000; // l'identifiant de chaîne ne bouge pas
/* ⚠️ ET ON SE SOUVIENT AUSSI DES ÉCHECS, 5 MINUTES. Sans ça, une carte qui ne résout pas relance
   la volée complète de lectures à CHAQUE ouverture — sur un VPS à 512 Mo, c'est le défaut qui coûte
   le plus cher, et il ne se voit pas puisque la carte, elle, se replie proprement. */
const _DIRECT_TTL_ECHEC = 5 * 60 * 1000;
const _DIRECT_BUDGET_MS = 12000;                    // le temps TOTAL qu'une résolution peut prendre
const _directMem = new Map();                       // tampon mémoire : évite même la lecture KV en rafale

/* ⚠️ LE BANDEAU DE CONSENTEMENT EST LA PREMIÈRE CAUSE D'UNE LECTURE VIDE DEPUIS UN SERVEUR. Google
   renvoie aux adresses de centre de données une page « Before you continue » (ou une redirection
   vers consent.youtube.com) qui répond 200 et ne contient AUCUN des identifiants cherchés : la
   lecture « réussit » et ne rapporte rien, ce qui est exactement le symptôme observé en production.
   Les deux témoins de consentement ci-dessous sont ceux qu'un navigateur pose après acceptation ;
   ils font servir la vraie page. On les envoie sur TOUTES les lectures YouTube. */
const _DIRECT_ENTETES = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36',
  'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
  'Accept-Language': 'en-US,en;q=0.9',
  'Cookie': 'CONSENT=YES+1; SOCS=CAI',
};
/* Reconnaître le mur, pour pouvoir le DIRE. Une lecture qui rapporte 200 et rien d'exploitable est
   indiscernable d'une chaîne hors antenne : sans ce test, le diagnostic ne peut pas trancher. */
function _directMur(url, corps) {
  return /consent\.(youtube|google)\.com/.test(String(url || ''))
      || /Before you continue|Avant de continuer|consentBumpV2/.test(String(corps || '').slice(0, 30000));
}
/* La lecture. Isolée pour être remplaçable au banc : le banc ne doit JAMAIS sortir sur le réseau,
   et un banc qui teste une fonction qu'il a réécrite ne teste rien. Elle rend TOUJOURS un objet —
   le statut et l'adresse finale sont la matière du diagnostic, les jeter serait se priver du seul
   moyen de savoir POURQUOI une résolution échoue sur une machine qu'on n'a pas sous la main. */
async function _directHttp(url) {
  try {
    const ac = new AbortController(); const t = setTimeout(() => ac.abort(), 6000);
    const r = await fetch(url, { signal: ac.signal, redirect: 'follow', headers: _DIRECT_ENTETES });
    clearTimeout(t);
    const corps = r.ok ? (await r.text()).slice(0, 400000) : '';   // le début de page suffit
    return { statut: r.status, finale: r.url || url, corps, mur: _directMur(r.url || url, corps) };
  } catch (e) {
    return { statut: 0, finale: url, corps: '', mur: false, erreur: String((e && e.message) || e).slice(0, 120) };
  }
}
/* L'EXTRACTION, ET SES TROIS FILETS. Un seul motif serait fragile : la page change de forme sans
   prévenir. On accepte donc plusieurs écritures du même fait, et on ne retient un identifiant que
   s'il a la FORME attendue — 11 caractères pour une vidéo, « UC » + 22 pour une chaîne. Sans ce
   contrôle de forme, un morceau de script quelconque passerait pour un identifiant et le desk
   afficherait un cadre mort en croyant avoir réussi. */
function _directExtraire(html) {
  const h = String(html || '');
  const chaine = (h.match(/"(?:externalId|channelId|browseId)"\s*:\s*"(UC[\w-]{22})"/)
    || h.match(/<meta[^>]+itemprop="(?:identifier|channelId)"[^>]+content="(UC[\w-]{22})"/)
    || h.match(/<link[^>]+rel="canonical"[^>]+href="https:\/\/www\.youtube\.com\/channel\/(UC[\w-]{22})"/)
    || h.match(/channel_id=(UC[\w-]{22})/)
    || h.match(/\/channel\/(UC[\w-]{22})/) || [])[1] || null;
  /* La vidéo : le lien canonique d'abord (c'est LUI qui désigne la diffusion en cours sur une page
     « /live »), puis les formes internes. On exige `isLive` sur la forme interne : sans elle, on
     ramasserait la dernière vidéo ARCHIVÉE de la chaîne et on l'appellerait « direct ». */
  let video = (h.match(/<link[^>]+rel="canonical"[^>]+href="https:\/\/www\.youtube\.com\/watch\?v=([\w-]{11})"/) || [])[1] || null;
  if (!video && /"isLiveNow"\s*:\s*true|"isLive"\s*:\s*true/.test(h)) {
    video = (h.match(/"videoId"\s*:\s*"([\w-]{11})"/) || [])[1] || null;
  }
  return { video, chaine };
}
/* ══ LA VÉRIFICATION D'UNE CHAÎNE, ET POURQUOI ELLE CHANGE TOUT ═══════════════════════════════
   Le flux RSS d'une chaîne (`/feeds/videos.xml?channel_id=…`) est un point d'entrée PRÉVU POUR LES
   MACHINES : du XML court, pas de bandeau de consentement, pas de script. Il répond 404 pour une
   chaîne inconnue et porte le NOM de la chaîne pour une chaîne connue. C'est donc lui qui permet
   d'employer une graine sans la croire sur parole : on ne la sert que si YouTube confirme qu'elle
   existe ET que son nom est bien celui qu'on attend. Une graine fausse est REFUSÉE, pas affichée. */
async function _directVerifierChaine(id, attendu) {
  if (!/^UC[\w-]{22}$/.test(String(id || ''))) return { ok: false, pourquoi: 'forme invalide' };
  const r = await _directHttp('https://www.youtube.com/feeds/videos.xml?channel_id=' + id);
  if (r.statut !== 200 || !r.corps) return { ok: false, pourquoi: 'flux ' + (r.erreur || r.statut) };
  const titre = (r.corps.match(/<title>([^<]{1,120})<\/title>/) || [])[1] || '';
  if (!titre) return { ok: false, pourquoi: 'flux sans titre' };
  if (attendu && !attendu.test(titre)) return { ok: false, titre, pourquoi: 'nom inattendu' };
  /* ⚠️ ET LA DERNIÈRE ÉMISSION, TANT QU'ON Y EST (05/09). Le même flux porte les quinze dernières
     vidéos de la chaîne, en clair. C'est ce qui permet à une carte de rester utile quand la chaîne
     n'est PAS à l'antenne — le cas de Yahoo Finance, qui ne diffuse qu'aux heures de marché, alors
     que Bloomberg Television tourne en continu. Sans elle, la carte de Yahoo est vide la moitié de
     la journée, et c'est exactement ce que l'utilisateur a signalé.
     ⚠️ ON COUPE AVANT LA PREMIÈRE ENTRÉE POUR LE TITRE : le premier `<title>` du flux est celui de
     la CHAÎNE, pas celui de la vidéo. Les lire dans le même document sans découper donnerait le nom
     de la chaîne en guise de titre d'émission. */
  const iEntree = r.corps.indexOf('<entry');
  const entree = iEntree >= 0 ? r.corps.slice(iEntree, iEntree + 4000) : '';
  const vid = (entree.match(/<yt:videoId>([\w-]{11})<\/yt:videoId>/) || [])[1] || null;
  const vtitre = (entree.match(/<title>([^<]{1,200})<\/title>/) || [])[1] || '';
  const vdate = (entree.match(/<published>([^<]{1,40})<\/published>/) || [])[1] || '';
  return { ok: true, titre, derniere: vid ? { id: vid, titre: vtitre, date: vdate } : null };
}
/* ══ LA RÉSOLUTION, PAR ORDRE DE CONFIANCE DÉCROISSANTE ═══════════════════════════════════════
   1. la CONSIGNE DE L'EXPLOITANT (`DTP_DIRECT_<CLÉ>` dans le .env du VPS) — elle passe avant tout,
      c'est la porte de sortie qui ne peut pas échouer le jour où YouTube refuse nos lectures ;
   2. ce qu'on a DÉJÀ appris (KV `direct:<clé>`) ;
   3. la LECTURE DES PAGES — le seul chemin qui donne la diffusion EN COURS, donc le cadre exact ;
   4. la GRAINE, et seulement après confirmation par le flux RSS.
   ⚠️ UN BUDGET DE TEMPS, PAS UN NOMBRE DE TENTATIVES. Trois poignées × trois formes de page font
   neuf lectures : à six secondes chacune, une carte pourrait attendre une minute. On s'arrête au
   budget, et l'échec est mémorisé cinq minutes. */
async function _directResoudre(cle, opts) {
  const d = _DIRECTS[cle]; if (!d) return null;
  const diag = (opts && opts.diag) ? [] : null;
  const now = Date.now();
  const echeance = now + _DIRECT_BUDGET_MS;
  const mem = _directMem.get(cle);
  if (!diag && mem && (now - mem.ts) < (mem.vide ? _DIRECT_TTL_ECHEC : _DIRECT_TTL_VIDEO)) return mem;
  let cache = null;
  try { cache = await auth.aiCacheGet('direct:' + cle); } catch {}
  if (!diag && cache && cache.ts && (now - cache.ts) < _DIRECT_TTL_VIDEO) { _directMem.set(cle, cache); return cache; }

  /* ⚠️ « HORS ANTENNE » EST UNE RÉPONSE, PAS UNE ABSENCE DE RÉPONSE (05/09). Une page « /live » lue
     avec succès qui ne porte AUCUNE diffusion en cours dit quelque chose de précis : la chaîne
     existe et n'émet pas. Le confondre avec « je n'ai rien pu lire » coûtait cher — on servait
     alors un cadre `live_stream` qui ne pouvait QUE échouer, et le client voyait une carte morte.
     Trois états, donc : true (à l'antenne), false (lu, et pas à l'antenne), null (rien de lisible). */
  let video = null, chaine = null, source = null, enAntenne = null, derniere = null;
  const impose = String(process.env[d.env] || '').trim();
  if (/^UC[\w-]{22}$/.test(impose)) { chaine = impose; source = 'consigne'; }
  else if (impose && diag) diag.push({ etape: 'consigne', ok: false, detail: d.env + ' posé mais pas à la forme UC + 22 caractères' });
  if (!chaine && cache && cache.chaine) { chaine = cache.chaine; source = 'cache'; }

  /* Les formes de page, dans l'ordre de leur rendement : « /live » porte la diffusion EN COURS ;
     la page de chaîne ne la porte pas mais donne l'identifiant de chaîne presque à coup sûr ;
     « /streams » rattrape les chaînes dont la page d'accueil est un aiguillage. */
  const formes = ['/live', '', '/streams'];
  for (const poignee of d.poignees) {
    for (const forme of formes) {
      if (video || Date.now() > echeance) break;
      if (forme !== '/live' && chaine && source !== 'cache') break;   // on a déjà de quoi cadrer
      const url = 'https://www.youtube.com/' + poignee + forme;
      const r = await _directHttp(url);
      const x = _directExtraire(r.corps);
      if (diag) diag.push({ etape: 'page', url, statut: r.statut, finale: r.finale, octets: r.corps.length,
                            mur: r.mur, erreur: r.erreur || null, video: x.video, chaine: x.chaine });
      if (x.chaine && source !== 'consigne') { chaine = x.chaine; source = 'page'; }
      if (forme === '/live' && r.statut === 200 && !r.mur && r.corps) enAntenne = !!x.video;
      if (x.video) { video = x.video; break; }
    }
    if (video || Date.now() > echeance) break;
  }

  if (!chaine && d.graine && Date.now() <= echeance) {
    const ver = await _directVerifierChaine(d.graine, d.attendu);
    if (diag) diag.push({ etape: 'graine', id: d.graine, ...ver });
    if (ver.ok) { chaine = d.graine; source = 'graine'; derniere = ver.derniere || null; }
  }
  /* La dernière émission de la chaîne retenue, quand la graine ne nous l'a pas déjà donnée. Un
     appel de plus, sur du XML court sans bandeau — et c'est lui qui garde la carte utile hors
     antenne. On ne le tente pas si le budget est épuisé : mieux vaut une carte sans repli qu'une
     carte qui met une minute à s'afficher. */
  if (chaine && !derniere && Date.now() <= echeance) {
    const f = await _directVerifierChaine(chaine, null);
    if (diag) diag.push({ etape: 'derniere', id: chaine, ok: f.ok, titre: f.titre, derniere: f.derniere });
    if (f.ok && f.derniere) derniere = f.derniere;
  }

  /* ⚠️ UN ÉCHEC NE VIDE PAS LE CACHE. Ces chaînes diffusent en continu : la dernière diffusion
     connue est presque toujours la bonne, et l'afficher vaut mieux qu'un cadre vide au premier
     hoquet de réseau. On ne réécrit le cache que si l'on a appris quelque chose. */
  if (!video && !chaine) {
    const rien = { ts: now, cle, nom: d.nom, site: d.site, video: null, chaine: null, vide: true, diag };
    _directMem.set(cle, rien);
    return cache || rien;
  }
  const out = { ts: now, cle, nom: d.nom, site: d.site, source, enAntenne,
                video: video || (cache && cache.video) || null,
                chaine: chaine || null, derniere: derniere || (cache && cache.derniere) || null,
                tsChaine: chaine ? now : (cache && cache.tsChaine) || 0, diag };
  _directMem.set(cle, out);
  try { await auth.aiCacheSet('direct:' + cle, { ...out, diag: undefined }); } catch {}
  return out;
}
app.get('/api/direct/:cle', async (req, res) => {
  const cle = String(req.params.cle || '').toLowerCase();
  const d = _DIRECTS[cle];
  if (!d) return res.status(404).json({ ok: false });
  try {
    const r = await _directResoudre(cle);
    if (!r || (!r.video && !r.chaine)) return res.json({ ok: false, nom: d.nom, site: d.site });
    res.json({ ok: true, nom: d.nom, site: d.site, video: r.video || null, chaine: r.chaine || null,
               enAntenne: (r.enAntenne === undefined ? null : r.enAntenne), derniere: r.derniere || null });
  } catch { res.json({ ok: false, nom: d.nom, site: d.site }); }
});
/* ⚠️ LE DIAGNOSTIC, PARCE QU'ON NE CORRIGE PAS CE QU'ON NE VOIT PAS. La résolution se fait sur le
   VPS ; la machine de développement n'a pas accès à YouTube (refus 403 du mandataire, mesuré). Sans
   cette vue, toute correction suivante serait une supposition. Elle dit, lecture par lecture : le
   statut, l'adresse finale, la taille, si un bandeau de consentement a été servi, et ce qui a été
   extrait. Réservée à l'administrateur : elle expose des adresses internes et force les lectures. */
app.get('/api/admin/direct/:cle', requireAdmin, async (req, res) => {
  const cle = String(req.params.cle || '').toLowerCase();
  const d = _DIRECTS[cle];
  if (!d) return res.status(404).json({ ok: false, cles: Object.keys(_DIRECTS) });
  try {
    _directMem.delete(cle);
    const r = await _directResoudre(cle, { diag: true });
    res.json({ ok: true, cle, nom: d.nom, consigne: d.env,
               consigneP: !!String(process.env[d.env] || '').trim(),
               source: (r && r.source) || null, video: (r && r.video) || null,
               chaine: (r && r.chaine) || null, enAntenne: (r && r.enAntenne),
               derniere: (r && r.derniere) || null, etapes: (r && r.diag) || [] });
  } catch (e) { res.status(500).json({ ok: false, erreur: String((e && e.message) || e).slice(0, 200) }); }
});

// ── Filtre des catégories de news (« Filtrer les sections »), PERSISTANT PAR COMPTE (KV durable, modèle
//    symrecent → suit la reconnexion / le changement d'appareil). On stocke les catégories DÉSACTIVÉES
//    (décochées) : une nouvelle catégorie absente de la liste reste ACTIVE par défaut. Valeur = { off: [...] }.
//    (off === null → aucune préférence enregistrée : le client garde son localStorage / défaut.)
app.get('/api/cat-filter', async (req, res) => {
  if (!req.session?.userId) return res.json({ off: null });
  try {
    const v = await auth.aiCacheGet('catfilter:' + req.session.userId);
    const off = (v && Array.isArray(v.off)) ? v.off.filter(x => typeof x === 'string' && x.length <= 60).slice(0, 80) : null;
    res.json({ off });
  } catch { res.json({ off: null }); }
});
app.post('/api/cat-filter', async (req, res) => {
  if (!req.session?.userId) return res.status(401).json({ ok: false });
  try {
    const arr = Array.isArray(req.body?.off) ? req.body.off : [];
    const off = [...new Set(arr.filter(x => typeof x === 'string' && x && x.length <= 60))].slice(0, 80);
    await auth.aiCacheSet('catfilter:' + req.session.userId, { off });
    res.json({ ok: true });
  } catch { res.status(500).json({ ok: false }); }
});

// ── Config du panneau ALERTES (notifications), PERSISTANTE PAR COMPTE (KV durable, modèle
//    symrecent/catfilter → suit la reconnexion / le changement d'appareil ; demande user 16/07
//    « que le système retienne le choix de config des notifs de chaque user »).
//    Valeur = { enabled, volume, chime, push, catsOff:[...] } ; cfg:null = aucune préférence
//    enregistrée (le client garde son localStorage / défauts). Le fil et l'onglet actif restent volatils.
const _NP_VOLUMES = new Set(['fort', 'doux', 'mute']);
const _NP_CHIMES  = new Set(['chime', 'ding', 'alert', 'none']);
function _npCleanCfg(b) {
  return {
    enabled: b.enabled !== false,
    volume:  _NP_VOLUMES.has(b.volume) ? b.volume : 'fort',
    chime:   _NP_CHIMES.has(b.chime) ? b.chime : 'chime',
    push:    b.push !== false,
    catsOff: Array.isArray(b.catsOff) ? [...new Set(b.catsOff.filter(x => typeof x === 'string' && x && x.length <= 40))].slice(0, 30) : [],
  };
}
// ── NOUVEAUTÉS DTP (changelog produit → panneau ALERTES, onglet DTP) ────────────────────────────
// RÈGLE DE TRAVAIL (demande user 10/08 « à chaque développement on doit mettre dans le système de
// notifs ») : à CHAQUE évolution VISIBLE PAR LES CLIENTS, ajouter une entrée ici DANS LE MÊME COMMIT
// (id stable 'dtpu-AAAAMMJJ-slug', ts = date du déploiement, ton annonce produit, zéro jargon).
// Le client les injecte en silence dans l'onglet DTP des alertes (fenêtre de fraîcheur 7 j côté panneau).
const DTP_UPDATES = [
  { id: 'dtpu-20260905-force-cadre', ts: Date.UTC(2026, 8, 5, 17, 0), title: 'Force des Devises montre toujours toutes les courbes, et la fiche macro parle plus clair', desc: 'Deux corrections sur la lecture des devises et de la macro, toutes deux signalées captures à l’appui. UN CADRE QUI NE COUPE PLUS AUCUNE COURBE. Sur Force des Devises, la courbe du yen sortait par le haut du cadre et n’y revenait jamais ; sa pastille avait disparu de la colonne de droite. Ce n’était pas un défaut de calcul mais un arbitrage devenu mauvais : le graphique resserrait son cadre sur le groupe des devises pour qu’on les distingue les unes des autres, quitte à sacrifier celle qui s’en échappe. C’était la bonne réponse à une demande plus ancienne ; ce n’est plus celle qui convient. Le resserrement ne s’applique donc plus que s’il ne coupe RIEN. Dès qu’une courbe en sortirait, le cadre s’ouvre et montre tout. UNE PRÉCISION QUI FAIT TOUTE LA DIFFÉRENCE : la vérification porte sur TOUS les points de chaque courbe, pas sur son point d’arrivée. Un pic peut monter très haut puis revenir sagement dans le groupe ; en ne regardant que la fin, on n’aurait rien vu, et c’est exactement le cas qui posait problème. DEUX LIBELLÉS RÉÉCRITS DANS LA FICHE MACRO. Les cartes Croissance économique et Emploi affichaient deux lignes nommées Niveau et Dynamique. Le reproche est juste, et il est plus précis qu’il n’y parait : la ligne disait « Niveau : Haussière ». Un niveau qui vaut haussière ne veut rien dire, un niveau se lit haut ou bas. Le mot décrivait le calcul, pas ce que la ligne répond. Ces deux lignes disent en réalité où on en est et dans quel sens ça va : elles s’appellent désormais Situation actuelle et Évolution récente. Le mot Niveau RESTE sur la carte Inflation, et ce n’est pas un oubli : la valeur y est bien un niveau, élevée, modérée ou faible. Le terme n’était ambigu que là où il portait une valeur de tendance.' },
  { id: 'dtpu-20260905-journal-largeur', ts: Date.UTC(2026, 8, 5, 15, 0), title: 'Le journal de trading occupe toute la largeur de votre écran', desc: 'Retour utilisateur, capture à l’appui : « pourquoi tu n’as pas exploité toute la largeur ». Il avait raison, et c’était une erreur de ma part, pas un compromis. La refonte de ce matin bornait la page du journal à une largeur de lecture confortable. Mesuré sur son écran de 1920 pixels : le contenu s’arrêtait à 1055, soit près de la MOITIÉ de l’écran laissée en noir, sous un desk dont tout le reste va d’un bord à l’autre. Le raisonnement d’origine, qu’une ligne de tuiles étirée sur 1900 pixels se lit mal, était juste ; mais il se règle là où il se pose, dans les grilles, en ajoutant des COLONNES quand la place existe, et pas en rendant la moitié de l’écran au vide. Le plafond est retiré : les trois onglets occupent toute la largeur disponible. Les grilles, elles, comptent désormais leurs colonnes sur la place réelle. Les chiffres clés passent à quatre colonnes au-delà d’une certaine largeur, parce que les sections en portent quatre ou huit : quatre colonnes remplissent donc TOUJOURS leurs rangées. Les douze pavés de mois se coupent en six et six, ou quatre et quatre et quatre, jamais en neuf et trois, qui ne ressemble ni à une année ni à un calendrier. UNE PRÉCISION QUI ÉVITE UN DÉFAUT CLASSIQUE : ces seuils sont mesurés sur la BOÎTE qui contient le journal, pas sur la fenêtre. Le journal se monte aussi dans une carte de votre desk, où la fenêtre peut faire 1900 pixels pendant que la carte en fait 400. Une règle calée sur la fenêtre y forcerait six colonnes dans un mouchoir de poche.' },
  { id: 'dtpu-20260905-directs-antenne2', ts: Date.UTC(2026, 8, 5, 13, 0), title: 'Les cartes de direct gagnent leur bandeau en hauteur d’image, et restent utiles hors antenne', desc: 'Deux corrections sur les cartes Bloomberg Live et Yahoo Finance Live, toutes deux signalées captures à l’appui. LA BARRE SOUS LA VIDÉO DISPARAIT. Elle portait le nom de la chaîne et un lien « Ouvrir chez l’éditeur ». Le nom était déjà écrit dans l’en-tête de la carte, juste au-dessus, et le lecteur porte lui-même son lien vers la chaîne : la barre répétait donc deux fois la même chose en prenant 32 pixels de hauteur d’image. Le lien reste ENTIER dans le cas où aucune vidéo ne peut être affichée, puisque le bouton est alors la seule chose que la carte a à offrir. HORS ANTENNE N’EST PAS EN PANNE. La carte Yahoo restait vide alors que celle de Bloomberg fonctionnait. La différence n’était pas dans le desk, les deux cartes partagent le même mécanisme : elle est dans les chaînes. Bloomberg Television diffuse en continu, Yahoo Finance seulement aux heures de marché. En dehors, il n’y a tout simplement rien à afficher, et la carte se repliait sur son bouton la moitié de la journée. Le serveur fait désormais la différence entre trois états : à l’antenne, lu et pas à l’antenne, et rien de lisible. Quand la chaîne n’émet pas, la carte affiche sa DERNIÈRE ÉMISSION plutôt que rien. ET ELLE LE DIT. Une pastille discrète, posée sur l’image, écrit « Hors antenne ». Montrer un enregistrement sous un titre « Live » sans le préciser serait un mensonge, et cette pastille n’apparait jamais sur une vraie diffusion en cours.' },
  { id: 'dtpu-20260905-directs-erreur', ts: Date.UTC(2026, 8, 5, 11, 0), title: 'Une carte de direct ne vous montre plus la page d’erreur de YouTube', desc: 'Suite du correctif publié plus tôt aujourd’hui, sur le dernier trou qui restait. Le serveur confirme désormais qu’une chaîne EXISTE avant de la servir. Nécessaire, mais pas suffisant : qu’une chaîne existe ne dit ni qu’elle passe à l’antenne, ni qu’elle s’autorise à être encadrée. Dans ces deux cas, le lecteur affichait SA propre page d’erreur, en anglais, aux couleurs de YouTube, à l’intérieur d’une carte du desk. C’est pire que le repli, qui lui est honnête et vous emmène chez l’éditeur en un clic. Le lecteur sait pourtant le dire. On le lui demande maintenant, et quand il annonce une erreur, la carte se replie sur son bouton au lieu de laisser l’erreur à l’écran. UNE PRÉCISION QUI EST TOUT LE SOIN DU CORRECTIF : on ne se replie QUE sur une erreur annoncée, jamais sur le silence. Un simple délai d’attente aurait été plus court à écrire et faux : le jour où le lecteur tarde à répondre sur une connexion lente, ou change sa façon de parler, on démonterait une antenne qui marche très bien. Le silence laisse donc le cadre en place. Au pire on revient au comportement d’avant, jamais en dessous. Les messages venus d’ailleurs que du lecteur sont ignorés, et une carte fermée cesse d’écouter.' },
  { id: 'dtpu-20260905-directs-antenne', ts: Date.UTC(2026, 8, 5, 9, 0), title: 'Bloomberg Live et Yahoo Finance Live : l’antenne s’affiche et démarre dans la carte', desc: 'Votre capture montrait la carte repliée sur son bouton : « Le direct n’a pas pu être chargé dans la carte ». La résolution du flux échouait donc sur le serveur, et la carte se repliait proprement, ce qui est le bon comportement mais pas celui qu’on lui demande. CE QUI SE PASSAIT. Le serveur allait lire la page de la chaîne pour y trouver la diffusion en cours. Cause la plus probable, et de loin : Google sert aux adresses de centre de données un bandeau de consentement à la place de la page. Il répond correctement, il ne contient simplement AUCUN identifiant. La lecture réussissait donc en ne rapportant rien, ce qui est le pire des échecs : silencieux. Les témoins de consentement sont désormais envoyés à chaque lecture, exactement comme le fait un navigateur après acceptation. TROIS AUTRES CHEMINS ONT ÉTÉ AJOUTÉS, parce qu’un seul point d’entrée est un point unique de panne. La page de chaîne et l’onglet des diffusions sont lus quand la page du direct ne dit rien, et l’identifiant de chaîne se reconnait désormais sous quatre écritures au lieu de deux. Un identifiant de chaîne suffit à cadrer l’antenne : c’est le second étage, celui qui marche même quand la diffusion en cours n’est pas identifiable. UNE GRAINE, CONFIRMÉE ET JAMAIS CRUE SUR PAROLE. La chaîne de chaque rédaction porte un identifiant PERMANENT, à ne pas confondre avec celui d’une vidéo, qui change à chaque redémarrage du flux et reste interdit en dur pour cette raison. Cet identifiant permanent sert donc de dernier recours, mais il n’est pas affiché sur la foi de ce qui est écrit : le serveur le confirme d’abord auprès du flux de la chaîne, qui répond en erreur pour une chaîne inconnue et porte le nom pour une chaîne connue. Un identifiant faux, ou qui désignerait une autre chaîne, est REFUSÉ et la carte garde son repli honnête. ET LA VIDÉO DÉMARRE TOUTE SEULE, SON COUPÉ. Une carte nommée Live qui affiche une vignette et un bouton de lecture ne fait pas ce qu’elle promet : sur un desk, l’antenne doit être à l’écran quand on regarde la carte. Le son coupé n’est pas de la politesse, c’est la seule forme de démarrage automatique que les navigateurs acceptent ; le lecteur porte son propre bouton pour le rétablir.' },
  { id: 'dtpu-20260905-journal-notion', ts: Date.UTC(2026, 8, 5, 5, 0), title: 'Le journal de trading est repris en entier : plus aéré, plus clair, sur ses trois onglets', desc: 'Sur demande utilisateur : une refonte plus propre et plus épurée du journal, sur ses trois onglets, avec la même grammaire visuelle que le reste du desk. UN SEUL CADRE PAR IDÉE. Chaque section du tableau de bord était une boîte encadrée qui contenait des cartes elles-mêmes encadrées : deux bordures pour une seule idée, et l’œil finit par compter les cadres au lieu de lire les chiffres. La boîte extérieure disparaît. La hiérarchie est désormais portée par ce qui la porte naturellement : un titre, un filet, et du blanc. La page, puis la section, puis la carte. Trois niveaux de lecture, un seul cadre. Le titre de section gagne au passage un cran de taille et un filet de départ : une étiquette qui flotte dans le vide ne dit pas « ici commence autre chose », un titre souligné, oui. LE TABLEAU DES TRADES PERD SON DAMIER. Chaque cellule portait un filet à droite ET en bas. Mesure faite en remettant le défaut : 2641 traits verticaux sur la page, qui la découpaient en damier. Les filets horizontaux suffisent à suivre une ligne du regard, et c’est ainsi qu’on lit un tableau. Une exception est gardée, parce qu’elle n’est pas décorative : la colonne des paires reste collée à gauche et flotte au-dessus des colonnes qui défilent sous elle. Son filet est le bord d’un élément fixe, pas une ligne de quadrillage. UNE LARGEUR DE LECTURE. Le contenu s’étalait sur toute la largeur de l’écran : sur un moniteur large, quatre chiffres de synthèse s’étiraient sur près d’un mètre et l’œil devait traverser le vide entre eux. Le journal est maintenant borné à une largeur de lecture confortable, et calé à gauche, dans l’axe de la barre d’onglets. Les respirations entre sections, les marges des cartes et les espacements du bilan annuel sont repris ensemble : plus d’air là où il sépare, pas de vide là où il éloigne deux choses qui vont ensemble. LA COHÉRENCE AVEC LE DESK. Les coins doux, les bordures fines et le survol doré sont la charte du desk depuis toujours, et le journal était le seul écran qui ne les appliquait pas. Il les applique désormais, sur les cartes, sur les tuiles de chiffres et sur les pavés du bilan annuel. Aérer cet écran ne l’éloigne donc pas du desk : cela l’en rapproche. Le format téléphone reçoit ses propres marges, plus serrées, pour que la mise en air ne coûte pas un défilement supplémentaire. Quatre contrôles automatiques accompagnent la reprise. Ils ouvrent le vrai journal dans un navigateur et vérifient que la section n’a plus de cadre, que la carte garde le sien, que le tableau a bien perdu son quadrillage vertical, et que la colonne collante a gardé sa frontière. Chacun a été éprouvé en remettant le défaut : les quatre rougissent séparément.' },
  { id: 'dtpu-20260905-fx-fraicheur', ts: Date.UTC(2026, 8, 5, 3, 0), title: 'Le tableau FX vous dit quand ses prix ne sont plus d’actualité', desc: 'Audit de fiabilité sur l’onglet FX, et ce qu’il a trouvé n’était pas une erreur de calcul : c’était un silence. Le tableau ne disait plus rien de l’âge de ses prix. Le petit MAJ HH:MM du coin droit avait été retiré en août, à votre demande, parce qu’il occupait la place sans être consulté ; le code qui l’écrivait, lui, est resté et s’est neutralisé tout seul. Personne ne l’a vu, parce qu’un code qui ne fait rien ne casse rien. OR LE TABLEAU A TROIS RAISONS D’ÊTRE VIEUX. Le week-end, le desk sert délibérément la photo de vendredi et coupe le rafraîchissement des cotations, marché fermé : un dimanche à 15 h vous lisiez des prix de vendredi 22 h, sans un mot. Un rafraîchissement en échec laisse le tableau précédent en place, sans un mot. Et un serveur qui redémarre sert son dernier instantané enregistré, qui peut dater. Les prix ne sont pas faux : ce sont les vrais prix d’un autre moment, affichés comme s’ils étaient de maintenant. C’est exactement ce qu’un terminal ne doit pas faire. CE QUI CHANGE, ET CE QUI NE CHANGE PAS. L’horodatage permanent ne revient pas : le retirer était une bonne décision, et pour la bonne raison, un indicateur qu’on lit tous les jours sans jamais rien y voir cesse d’être lu. Le tableau applique donc la règle que le desk suit déjà sur le graphique de réaction : le cas ordinaire n’écrit rien, le cas anormal garde sa phrase. En semaine, cotations à jour, vous ne voyez rien de nouveau. Si elles ont plus de dix minutes, une pastille orange dit depuis quand. Et quand le marché est fermé, une pastille sobre nomme le jour de clôture : Marché fermé, clôture de vendredi à 22:58. C’est le serveur qui décide si le marché est fermé, au moment où il vous répond, et non une seconde règle recopiée dans le navigateur qui finirait par diverger de la première. Un banc éprouve les quatre cas dans un vrai navigateur, et ils vont par paires : ne rien dire quand c’est frais serait vert sur un code qui ne dit jamais rien, c’est-à-dire sur le défaut d’origine ; parler quand c’est vieux serait vert sur un code qui parle tout le temps, c’est-à-dire sur la nuisance retirée en août. Le quatrième contrôle exige que le retour à la normale efface la pastille.' },
  { id: 'dtpu-20260905-devise-couleur', ts: Date.UTC(2026, 8, 5, 1, 0), title: 'Une devise a désormais UNE couleur dans tout le desk', desc: 'Le récap hebdomadaire écrit le code de chaque devise en couleur : USD, EUR, JPY… Ces huit couleurs venaient d’une table qui lui était propre, différente de celle du graphique Force des Devises. Les huit divergeaient, et l’USD changeait carrément de famille : doré dans le récap, blanc dans le graphique. La même devise portait donc deux couleurs dans le même produit, et l’or, qui est la couleur de MARQUE du desk, faisait au passage un travail de donnée. PLUS GÊNANT : CETTE COPIE N’AVAIT PAS DE VARIANTE POUR LE THÈME CLAIR. Mesuré sur fond blanc, quatre des huit codes tombaient sous le contraste minimum exigé pour du gros texte : l’USD à 1,96, le franc suisse à 1,92, la livre à 2,28, le yen à 2,43. Le graphique avait reçu ce correctif fin août, avec ses couleurs assombries pour le fond blanc ; la copie, elle, ne l’avait jamais reçu. C’est la définition d’une duplication : on répare une fois sur deux sans le savoir. Le récap demande maintenant sa couleur au même endroit que le graphique. Une devise, une couleur, sur les deux thèmes. Rien ne change à l’œil sur le thème sombre, où les deux tables étaient déjà proches, sauf l’USD qui prend enfin la couleur qu’il a partout ailleurs. UN CONTRÔLE AUTOMATIQUE QUI NE POUVAIT PAS VOIR CE DÉFAUT LE VOIT MAINTENANT. Le banc qui vérifie le contraste des huit couleurs existait depuis fin août, mais il tournait derrière le chargement du moteur graphique : sur un poste sans accès à ce moteur, c’est-à-dire pendant tout le développement courant, il ne tournait jamais. Il est remonté avant, avec le reste de ce qui se lit dans le code sans avoir besoin d’un écran. Il refuse désormais aussi qu’une seconde table de couleurs de devises réapparaisse ailleurs, sous quelque nom que ce soit.' },
  { id: 'dtpu-20260904-journal-lisible', ts: Date.UTC(2026, 8, 4, 23, 30), title: 'Deux panneaux de réaction s’ouvrent enfin ensemble, et le journal se resserre', desc: 'DEUX PUBLICATIONS, DEUX GRAPHIQUES, EN MÊME TEMPS. Vous nous aviez envoyé la capture : deux chiffres de 14 h 30 ouverts côte à côte, celui du bas affichant ses bougies, celui du haut réduit à un rectangle noir où ne restaient que le trait en pointillé et le rond rouge. Le graphique, son capteur de largeur et son rafraîchisseur vivaient dans une seule et même place pour tout le desk : ouvrir un second panneau DÉTRUISAIT le premier. Le rectangle noir s’expliquait jusqu’au détail, puisque la destruction efface le dessin mais laisse le repère que le desk pose lui-même par dessus. Chaque panneau a désormais le sien, et le ménage qui évitait les fuites de mémoire se fait panneau par panneau au lieu de tout balayer. Vous pouvez comparer deux réactions sans que l’une efface l’autre. LE JOURNAL DE TRADING SE LIT PLUS VITE. Vous demandiez d’en améliorer la lisibilité et de vérifier la cohérence avec le reste du desk. Mesure avant reprise : TREIZE cadrans de 98 pixels, tous de la même taille, sur près de 800 pixels de hauteur. Trois défauts, et aucun n’était affaire de goût. Aucune hiérarchie d’abord : le total en R, le chiffre qui juge une année, avait exactement le poids visuel du nombre de trades du mois. Quand tout crie, rien ne se lit. Onze cercles sur treize étaient PLEINS ensuite : un arc plein est une jauge à fond, il annonce un maximum atteint là où il n’y a pas de maximum du tout. Et la densité, enfin, qui est la charte de ce desk : c’était l’écran le plus aéré du produit, avec un cercle de 98 pixels pour écrire 120. Les chiffres passent en TUILES : trois lignes de texte, alignées en grille, un filet de couleur à gauche. La jauge n’a pas disparu, elle prend la place du filet exactement quand la valeur a une échelle : le taux de réussite, la part de positions longues (qui n’en avait pas et la méritait) et les mois travaillés. Le cercle devient donc le signal « ce chiffre a un maximum » au lieu d’être la décoration de tous. La section Performance clé tient sur une rangée là où elle en prenait trois. LA COULEUR NE SERT PLUS À RIEN QU’À DIRE QUELQUE CHOSE. Treize chiffres peints de treize teintes différentes, ce sont treize couleurs qui ne veulent rien dire, et le vert et le rouge, qui eux en veulent une, s’y noyaient. Un simple compte s’écrit maintenant à l’encre du desk et c’est le filet à sa gauche qui porte son identité ; un total signé, lui, garde sa couleur d’état. SUR TÉLÉPHONE ET TABLETTE, LES NOMS DE PAIRES SE LISENT ENFIN EN ENTIER. Le bouton d’ouverture d’une fiche n’apparaît au survol que sur un ordinateur ; au doigt, faute de survol, il reste affiché en permanence, et il était posé PAR-DESSUS le nom. Mesure : la cellule fait 85 pixels, le nom court jusqu’à 88, le bouton commençait à 57. Quatre caractères mangés à chaque ligne, dans la toute première colonne du journal : EURUSD ne se distinguait plus d’EURJPY. Le libellé du bouton cède la place à son icône seule, et la cellule réserve le reste. TROIS DÉTAILS ENFIN. Les deux graphiques du tableau de bord se taisaient quand ils ne pouvaient pas s’afficher, alors que les deux graphiques annuels, eux, l’écrivaient : les quatre le disent désormais de la même façon. La carte Résultat des mois ne se laisse plus étirer à la hauteur de ses voisines, ce qui lui faisait 200 pixels de noir sous ses trois lignes. Et le mois en cours affiche son nom en entier dans les pavés annuels, au lieu du Septe… d’avant.' },
  { id: 'dtpu-20260904-directs-video', ts: Date.UTC(2026, 8, 4, 22, 0), title: 'Bloomberg Live et Yahoo Finance Live affichent la vidéo dans la carte', desc: 'Vous nous l’aviez signalé, capture à l’appui : une carte qui s’appelle Bloomberg Live et qui n’affiche qu’un bouton ne fait pas ce que son nom promet. Les deux cartes encadrent désormais la diffusion officielle de la rédaction, directement dans le desk : son lecteur, sa marque, sa publicité. Le texte descriptif qui occupait la carte a été retiré, il n’a plus lieu d’être. Et le lien vers le site de l’éditeur reste présent sous le cadre, dans tous les cas : le desk vous emmène chez la source, il ne la remplace pas. L’AIDE DE CES DEUX CARTES DISAIT LE CONTRAIRE, ET ELLE AVAIT TORT. Elle expliquait que l’éditeur interdit techniquement d’intégrer sa page. C’est exact de la page de son site, qui refuse d’être encadrée. Ça ne l’est pas de la diffusion officielle en continu de ces deux rédactions, dont le lecteur est fait pour être intégré. L’argument servait donc contre quelque chose que personne n’avait essayé ; il est retiré des deux aides. L’ADRESSE DU DIRECT N’EST PAS ÉCRITE EN DUR, ET C’EST LE POINT TECHNIQUE QUI COMPTE. Une chaîne d’information en continu redémarre son flux régulièrement, et chaque redémarrage crée une nouvelle diffusion. Une adresse figée dans le code serait devenue un cadre noir au premier redémarrage, sans que rien ne le signale. Le desk va donc chercher l’adresse de la diffusion en cours et la garde en mémoire une demi-heure. Trois niveaux, du plus précis au plus sûr : la diffusion en cours ; à défaut la chaîne, qui ne périme jamais ; à défaut la carte avec son bouton, exactement comme avant. Vous ne perdez donc rien si la chaîne n’est pas en antenne. LES DEUX VIGNETTES DE LA BIBLIOTHÈQUE SONT ENFIN DIFFÉRENTES. Vous demandiez aussi de meilleurs aperçus. Le défaut n’était pas l’absence de vignette, mais pire : les deux cartes retombaient sur la même icône, copiée de l’une à l’autre. Deux lignes voisines de la bibliothèque affichaient donc le même dessin, et la vignette, censée aider à choisir, ne distinguait rien. Chacune montre maintenant un lecteur avec le bandeau propre à sa rédaction : dépêches façon terminal pour Bloomberg, cotations pour Yahoo, c’est-à-dire la différence de ligne éditoriale entre les deux.' },
  { id: 'dtpu-20260904-journal-couleurs', ts: Date.UTC(2026, 8, 4, 20, 0), title: 'Journal de trading : les couleurs des données, et l’année en douze pavés', desc: 'Deux changements sur le journal, demandés captures à l’appui. LES DONNÉES NE SE PEIGNENT PLUS À L’OR DU DESK. L’or est la couleur de MARQUE de DataTradingPro : il habille les titres, les bordures, l’onglet actif. Employé EN PLUS pour peindre une barre de résultat ou une courbe de performance, il cessait de vouloir dire DataTradingPro sans pour autant vouloir dire autre chose, et l’on ne savait plus si la couleur portait une information ou une signature. Le tableau de bord et la vue annuelle passent donc à une palette de données : cinq teintes, bleu, magenta, violet, sarcelle et orange. La courbe de performance et le pourcentage cumulé de l’année sont désormais bleus, la section Reconnaissance de schémas se distingue en violet de la section Optimisation, et les cadrans qui restaient dorés prennent leur teinte de la palette. Ce qui NE change pas, et c’est volontaire : le vert, le rouge et l’ambre gardent leur sens. Un résultat gagnant reste vert, un perdant reste rouge, un neutre reste ambré, que ce soit dans une barre, dans un cadran ou dans le camembert de répartition. Aucune des cinq teintes n’est verte, rouge ni ambrée, précisément pour cela : dans un journal de trading, une catégorie peinte en vert est lue comme gagnante avant d’être lue comme catégorie. Les cinq teintes ne sont pas choisies à l’œil : elles ont été mesurées sur le fond sombre du desk (clarté, saturation, contraste, et surtout séparation de chaque paire voisine pour un œil daltonien). Un banc relit la couleur RÉELLEMENT peinte à l’écran, pas le code : c’est la seule vérification qui aurait vu une règle de style repeindre une barre en or malgré un code correct. L’ANNÉE SE LIT EN DOUZE PAVÉS. Sous le tableau de bord annuel, une nouvelle section R par mois pose douze cases de même taille, une par mois : le R du mois, une barre à l’échelle du plus gros mois de l’année, le nombre de trades et le taux de réussite. Le tableau mois par mois, juste en dessous, porte déjà ces chiffres, mais un tableau se lit ligne à ligne quand une année se lit d’un coup. Douze cases côte à côte rendent visible ce qu’aucune ligne ne montre : le trou de trois mois sans rien, les deux mois qui portent l’année entière, la grappe de mois rouges d’affilée. La barre est rapportée au plus gros mois de l’année affichée et non à une échelle fixe, qui écraserait une année calme et saturerait une bonne année. Un mois sans trade reste VIDE, en pointillé, sans barre et sans zéro : un zéro se lit comme un résultat nul obtenu en travaillant, une absence se lit comme une absence, et les deux n’enseignent pas la même chose à qui relit son année. Le mois en cours est marqué comme tel, pour la même raison : il n’est pas comparable à un mois clos.' },
  { id: 'dtpu-20260904-calibrage', ts: Date.UTC(2026, 8, 4, 18, 0), title: 'Le journal calibre votre capital, et sait dire quand il n’a rien à conseiller', desc: 'Trois changements, dont un né du retour d’un de vos clients sur le Discord. LE JOURNAL VOUS AIDE MAINTENANT À CALIBRER VOTRE CAPITAL. « Je l’utilise, mais pour calibrer mon capital je trouve assez moyen ; ça reste un très bon outil pour tracker. » Le diagnostic était juste : le journal savait dire ce qui s’était passé, pas ce que vos résultats impliquent sur la taille à prendre au trade suivant. Un bloc CALIBRAGE DU CAPITAL rejoint donc le tableau de bord, et tout y est calculé sur VOS trades. D’abord ce que vous risquez réellement : votre perte moyenne, en dollars et en pourcentage de votre capital. Ensuite le coût du retour de votre pire série déjà traversée, à 0,5%, 1% et 2% de risque par trade : ce n’est pas une prévision, c’est l’arithmétique d’une série que vous avez vécue. Enfin un verdict. ET CE VERDICT PEUT ÊTRE UN REFUS, C’EST MÊME LE POINT. Quand vos statistiques dégagent un avantage, le desk propose un risque par trade, calculé par le critère de Kelly dont il ne retient que la MOITIÉ, plafonnée à 2% : la formule suppose des probabilités connues, les vôtres sont estimées sur un échantillon, et le Kelly plein impose des baisses de capital que personne ne tient. Quand vos statistiques ne dégagent AUCUN avantage, le desk le dit et ne conseille aucune taille : aucune taille de position ne rend une série perdante gagnante, c’est la méthode qu’il faut reprendre. Et sous trente trades clos, il refuse de conclure, parce qu’un taux de réussite sur dix trades ne distingue pas un avantage d’une bonne série. Un bloc de calibrage qui conseille toujours quelque chose se tromperait une fois sur deux. UNE NOUVELLE CARTE : LE SCENARIO DESK. Elle dit à partir de quel chiffre une publication fait bouger sa devise, une échéance après l’autre, avec deux encadrés face à face, haussier et baissier. Les seuils sont calculés d’un pas de la dernière décimale publiée autour du consensus, dans le sens propre à chaque indicateur : pour le chômage, un chiffre plus élevé est une mauvaise nouvelle et la carte le dit ainsi. Sans consensus publié, aucun seuil n’est affiché. LE JOURNAL ET LA CALCULATRICE S’AFFICHENT EN GRAND. Vous nous avez signalé que la rangée d’onglets visible dans ces deux écrans n’était pas celle de votre modèle. Elle ne pouvait pas l’être : c’était la navigation du desk classique, qui appartient à un autre écran. Ces deux vues sont des outils, pas des onglets du desk : elles prennent désormais toute la hauteur, et les trois icônes de la barre du haut restent le chemin de retour.' },
  { id: 'dtpu-20260904-scenario-desk', ts: Date.UTC(2026, 8, 4, 16, 0), title: 'Scenario Desk : à partir de quel chiffre une publication fait bouger sa devise', desc: 'Une nouvelle carte rejoint la bibliothèque de Mon Desk : le Scenario Desk. Elle répond à une question que le calendrier ne traite pas. Le calendrier dit quand tombe un chiffre et quel consensus l’attend ; celle-ci dit À PARTIR DE QUEL CHIFFRE la publication change quelque chose pour la devise. C’est la question qu’on se pose la veille, pas pendant. COMMENT ELLE SE LIT. Les prochaines échéances, groupées par jour, avec leur heure, leur devise, leur impact, leur consensus et leur précédent. Un clic déplie deux encadrés face à face : le scénario haussier et le scénario baissier, chacun avec son seuil chiffré. Deux réglages : l’impact minimum retenu et l’horizon, de quarante-huit heures à quatorze jours. D’OÙ VIENNENT LES SEUILS, ET POURQUOI C’EST IMPORTANT. Ils sont CALCULÉS, jamais rédigés : un pas de la dernière décimale publiée, de part et d’autre du consensus. Un consensus à 0,5% donne donc 0,6% ou plus d’un côté, 0,4% ou moins de l’autre, exactement comme sur le terminal de référence que vous nous avez montré. Le pas suit la NOTATION du chiffre : un consensus écrit 0,25 se déplace de 0,01, un chiffre d’emploi écrit 75K se déplace de 1K. Un pas fixe inventerait une marche que la publication ne connaît pas. ET LE SENS DE LECTURE EST CELUI DE L’INDICATEUR. Pour le chômage, les inscriptions ou les stocks, un chiffre au-dessus des attentes est une MAUVAISE nouvelle : la carte place alors le scénario haussier sous le consensus, pas au-dessus. Elle utilise pour cela la même fiche d’indicateurs que le Décryptage DTP, plutôt qu’une seconde table qui finirait par diverger. Enfin, une échéance sans consensus publié n’affiche AUCUN seuil et le dit : il n’y a alors rien à comparer, et fabriquer une référence absente serait pire que se taire. Conformément à votre précision, la carte ne porte aucun graphique de prix : c’est une liste d’échéances et de seuils, et un contrôle automatique veille à ce qu’elle le reste.' },
  { id: 'dtpu-20260904-journal-annuel', ts: Date.UTC(2026, 8, 4, 14, 0), title: 'Journal de trading : un onglet Annuel, et des cadrans qui disent combien', desc: 'Votre journal gagne un troisième onglet, ANNUEL, et ses cadrans changent de nature. POURQUOI UN TROISIÈME ONGLET. « Trades » montre la ligne, « Tableau de bord » montre le cumul depuis toujours. Ni l’un ni l’autre ne répond à « comment s’est passé mars » ni à « est-ce que je progresse d’un mois sur l’autre » — or c’est la question que l’on se pose en relisant une année. L’onglet Annuel la traite, à partir des mêmes trades et des mêmes calculs : seule la maille change, aucun chiffre n’est inventé. CE QU’IL CONTIENT. Un sélecteur d’année, qui ne propose que les années où vous avez réellement tradé. Un tableau de bord annuel : la répartition de vos mois positifs, neutres et négatifs, votre R mois par mois en colonnes, votre pourcentage cumulé sur l’année, puis quatre cadrans, le R de l’année, le taux de réussite, le nombre de trades et le nombre de mois réellement travaillés. En dessous, le tableau des DOUZE mois : résultat, R, pourcentage, taux de réussite avec sa barre, total de trades, perdants, seuils et gagnants, et le capital atteint. Enfin la performance par trade, chaque position de l’année dans l’ordre du temps, en R ou en dollars, avec le total. DEUX PARTIS PRIS QUI COMPTENT. Un mois SANS trade garde sa ligne, en tiret : il n’est pas ramené à zéro, parce qu’un zéro se lit comme un résultat nul alors qu’il n’y a eu aucune prise de position, et cette différence est précisément ce qu’on vient lire. Et le mois en cours est marqué comme tel, avec un filet doré : le comparer à un mois clos reviendrait à le comparer à autre chose que lui. LES CADRANS DISENT DÉSORMAIS COMBIEN. Ils étaient un cercle de couleur uniforme autour d’un nombre : la couleur portait toute l’information et la surface du cercle ne voulait rien dire. Ils remplissent maintenant un arc proportionnel à la valeur, si bien que quatre cadrans côte à côte se comparent d’un coup d’œil, avant même de lire les chiffres. Un cadran sans maximum honnête, un total en R ou un nombre de trades, garde un arc plein : on ne fabrique pas une proportion là où il n’y en a pas. Un cadran s’ajoute au tableau de bord, le nombre de trades du mois en cours : un journal peut afficher un excellent cumul et n’avoir rien tenu depuis trois semaines. Le widget Journal de Mon Desk reprend tout cela sans rien de particulier à faire : il affiche le vrai journal, pas une copie.' },
  { id: 'dtpu-20260904-bande-noire', ts: Date.UTC(2026, 8, 4, 12, 0), title: 'La bande noire sur les blocs mobiles, et les boutons empilés du lecteur', desc: 'Deux corrections d’affichage signalées par vos captures, et la seconde valait pour bien plus que le widget concerné. SUR TÉLÉPHONE, UNE BANDE NOIRE SE POSAIT SUR LE PREMIER BLOC DE MON DESK. Vous nous l’avez décrite ainsi : « je n’arrive pas à voir tout le widget entier, ça me montre une case noire ». C’était la barre de vos modèles de desk, qui se plaçait par-dessus la première carte au lieu de se ranger sous la barre du haut, là où la place lui était pourtant réservée. La cause est inattendue et n’avait rien à voir avec cette barre : le léger fondu qui accompagne le changement d’onglet faisait glisser la vue de quatre pixels, et un navigateur traite alors cette vue comme le cadre de référence de tout élément fixe qu’elle contient. La barre se positionnait donc par rapport au panneau et non par rapport à l’écran. Mesuré dans un navigateur en mode téléphone : 130 pixels avec l’animation, 47 sans. Le glissement de quatre pixels est retiré, le fondu reste. Ce défaut aurait touché de la même façon n’importe quel autre élément fixe posé dans une vue, volet ou menu compris : un contrôle automatique vérifie désormais qu’aucune vue ne porte ce genre de déplacement, en plus de vérifier que la barre ne recouvre plus rien. OUVERTURE D’UN RAPPORT INSTITUTION : LES BOUTONS SE CHEVAUCHAIENT. Sur écran étroit, le bandeau du lecteur a le droit de passer à la ligne, mais sa hauteur restait figée : ses deuxième et troisième rangées, le bouton des éclairages, le badge de l’institution et le titre du rapport, sortaient de sa boîte et se dessinaient par-dessus la rangée d’étiquettes. Le bandeau grandit maintenant avec son contenu. C’est la même correction que le lecteur Analystes avait reçue le 2 septembre et que celui des Institutions n’avait pas eue : deux bandeaux jumeaux écrits deux fois, dont un seul complété. Un contrôle apparié exige désormais les mêmes réglages des deux côtés, pour que la prochaine correction ne puisse plus n’en servir qu’un.' },
  { id: 'dtpu-20260904-modele-persistant', ts: Date.UTC(2026, 8, 4, 10, 0), title: 'Votre modèle de desk ne change plus tout seul quand vous naviguez', desc: 'Vous nous avez écrit, captures à l’appui : « j’avais sélectionné mon template personnalisé JOT, puis en naviguant simplement vers Journal de trading et en revenant sur Accueil, mon layout a changé automatiquement ». C’est corrigé, et la cause n’était pas un effet de bord : le code le faisait exprès. CE QUI SE PASSAIT. Une règle posée en juillet voulait que le desk s’ouvre sur le modèle marqué d’une étoile « à l’arrivée sur Mon Desk ». Le mot arrivée avait été traduit par « chaque fois que la vue s’affiche » — or revenir d’un autre onglet affiche la vue. Le modèle étoilé se réimposait donc à chaque aller-retour, et le modèle que vous veniez de choisir était effacé. Un seul changement d’onglet suffisait. CE QUI CHANGE. Le modèle actif est celui que vous avez choisi, et il le reste jusqu’à ce que vous en changiez vous-même. Naviguer d’un onglet à l’autre ne le modifie plus, jamais, et le choix était déjà enregistré sur votre compte : il vous suit donc aussi après un rechargement et d’un appareil à l’autre. L’étoile garde un sens, plus modeste : elle désigne le modèle proposé tant qu’aucun autre n’a été choisi. Son infobulle a été réécrite, parce qu’elle promettait encore l’ancienne règle. CE QUI RESTE, ET QUI N’EST PAS LA MÊME CHOSE. Un filet subsiste pour le cas où le modèle actif a disparu ou a été fermé depuis un autre appareil : le desk retombe alors sur un modèle visible plutôt que de s’ouvrir sur une grille vide. Une réparation ne s’applique que lorsqu’il y a quelque chose à réparer ; elle ne remplace jamais un choix valide. Un contrôle automatique rejoue désormais votre scénario exact dans un vrai navigateur, deux allers-retours d’onglets compris, et vérifie que le modèle actif n’a pas bougé. Nous l’avons éprouvé en remettant l’ancien comportement : il devient rouge.' },
  { id: 'dtpu-20260904-couleurs-etiquettes', ts: Date.UTC(2026, 8, 4, 8, 0), title: 'Les chiffres publiés se colorent, et la Force des Devises affiche ses valeurs', desc: 'Trois corrections demandées à partir de vos captures. LES CHIFFRES PUBLIÉS DU RÉCAP QUOTIDIEN PRENNENT ENFIN LEURS COULEURS À L’ÉCRAN. Nous avions annoncé cette couleur le 2 septembre, et le calcul était bien en place : le desk marquait correctement chaque donnée en vert au-dessus du consensus, en rouge en dessous, en ambre quand elle sort conforme. Mais la feuille de style peignait par-dessus : la règle générique qui met en blanc le gras d’une puce était plus forte que la couleur de la donnée. Le chiffre était donc coloré dans le document et blanc sur votre écran. Nous l’avons vérifié cette fois en lisant la couleur RÉELLEMENT peinte, et non la balise posée dans le code : c’est très exactement la différence qui a laissé le défaut vivre deux jours. Au passage, un montant en milliards se colorait à moitié, « 1,923 M » teinté et le « d » resté blanc juste derrière : Md est désormais reconnu comme une unité entière. LA FORCE DES DEVISES AFFICHE LE NOMBRE AU BOUT DE CHAQUE COURBE. L’étiquette portait le code de la devise, information déjà donnée par la légende du haut, en permanence et avec la même teinte. Elle porte désormais la valeur, comme sur le terminal de référence que vous nous avez montré : la colonne de droite dit maintenant où en est chaque devise au lieu de répéter son nom. Le réglage « Valeur sur les étiquettes » existe toujours et le décocher rend la pastille au code. ET LES DEVISES QUE VOUS DÉCOCHEZ RESTENT DÉCOCHÉES. Masquer trois courbes pour n’en comparer que cinq était un réglage à refaire à chaque changement d’onglet, de période ou de rechargement. Ce choix est maintenant mémorisé sur votre compte, comme les autres réglages d’affichage : il vous suit d’un appareil à l’autre et vous reprenez le travail où vous l’aviez laissé. Un rapport ou un courriel, eux, montrent toujours les huit devises : leur contenu ne peut pas dépendre de qui les lit.' },
  { id: 'dtpu-20260904-lecteur-fin', ts: Date.UTC(2026, 8, 4, 6, 0), title: 'Un rapport se lit maintenant jusqu’à sa dernière ligne sur téléphone', desc: 'Vous nous avez ecrit, capture à l’appui, que vous ne parveniez pas à descendre plus bas dans un Récap Quotidien ouvert sur téléphone et que la fin restait illisible. Ce n’était pas une impression : trois défauts se superposaient, et ils sont tous les trois corrigés. LE PREMIER EXPLIQUE TOUT LE RESTE. Sur Mon Desk, en colonne unique, les blocs pouvaient se RECOUVRIR : chacun garde la hauteur de rangée choisie sur grand écran, mais reçoit sur téléphone une hauteur minimale bien supérieure. Le bloc débordait donc de son emplacement, et le bloc suivant se dessinait par-dessus la fin du précédent. Mesuré : 123 pixels du lecteur de rapports cachés sous le bloc voisin. La fin du rapport existait bien, elle défilait bien, mais elle vivait sous un autre bloc, et un doigt posé dans cette bande touchait ce bloc-là, donc faisait défiler la page au lieu du rapport. Désormais chaque bloc occupe sa propre rangée : plus aucun recouvrement possible, à aucune largeur d’écran. LE DEUXIÈME EST LA RUBRIQUE « À SURVEILLER », qui était un tableau de huit colonnes. Sur un téléphone, ses colonnes de chiffres, le réel, la prévision et le précédent, tombaient hors de l’écran à droite : l’en-tête s’arrêtait sur un « RÉ » coupé net, et rien ne signalait qu’il manquait quelque chose. Pire, ce tableau glissait latéralement, ce qui capturait le geste vertical du pouce posé dessus. Le calendrier d’un rapport se replie donc en fiches, exactement comme le calendrier économique du desk le fait déjà : heure, drapeau, devise et impact en tête, intitulé sur toute la largeur, puis les trois chiffres nommés un par un. Rien n’est tronqué, rien n’est réduit, et plus rien ne retient le doigt. LE TROISIÈME est une marge : le lecteur gardait sur téléphone les marges latérales prévues pour un grand écran, soit 64 des 390 pixels de largeur perdus, un sixième de l’écran. Le texte d’un rapport occupe maintenant la largeur du téléphone. Et pour ceux qui ont installé le desk sur leur écran d’accueil, la dernière ligne d’un rapport passe désormais au-dessus de la barre d’accueil de l’iPhone au lieu de finir dessous.' },
  { id: 'dtpu-20260904-api-recaps', ts: Date.UTC(2026, 8, 4, 5, 0), title: 'L’interface de programmation donne enfin accès aux récaps de séance', desc: 'Notre interface de programmation, celle qui permet de récupérer les données du terminal depuis un outil extérieur avec une clé, donnait accès aux rapports du desk. Mais elle en connaissait cinq types sur huit : les trois RÉCAPS DE SÉANCE, Asie-Pacifique, Londres et New York, étaient tout simplement absents. Un développeur qui interrogeait la liste des rapports en recevait donc une partie, sans que rien ne lui signale les trois manquants. Ils sont désormais accessibles, avec leur texte complet et leurs données structurées, exactement comme les autres. LA MANIÈRE DONT C’EST CORRIGÉ COMPTE AUTANT QUE LA CORRECTION. La liste des types était recopiée à la main dans l’interface, à côté de l’endroit qui décide réellement quels récaps de séance existent. Deux listes qui disent la même chose finissent toujours par diverger, et c’est ce qui s’était produit. Elle est maintenant DÉRIVÉE de cette source unique : le jour où une quatrième séance serait ajoutée, elle sera disponible sans que personne n’ait à y penser. Quinze contrôles automatiques comparent désormais les deux côtés avant chaque mise en ligne, et vérifient aussi que chaque route de l’interface reste protégée par une clé, sans exception.' },
  { id: 'dtpu-20260904-barre-aeree', ts: Date.UTC(2026, 8, 4, 4, 0), title: 'La barre du haut et les onglets gagnent en aération', desc: 'Vous nous avez envoyé la capture d’un terminal de référence en nous disant que son espacement était meilleur que le nôtre. Vous aviez raison, et la comparaison a porté sur quatre mesures. LA BARRE D’ONGLETS PASSE DE 30 À 36 PIXELS. Les intitulés touchaient presque le filet du bas : ils ont maintenant la place de respirer. Une note pour la mémoire du produit : cette même barre était passée de 28 à 30 pixels en août, à votre demande d’alors, formulée comme « un peu plus large, légèrement ». Deux pixels répondaient à la lettre de cette demande. Celle d’aujourd’hui porte sur l’aération, pas sur la largeur : elle remplace la précédente, et c’est écrit dans le code pour que personne ne croie plus tard à un réglage perdu. LES ONGLETS SONT PLUS ESPACÉS, de quatorze à dix-huit pixels de chaque côté. C’est ce qui permet de lire la rangée d’un coup d’œil au lieu de la parcourir mot à mot. LA RECHERCHE DE SYMBOLE GAGNE EN PRÉSENCE : plus longue, un peu plus haute, et des coins plus doux. C’est l’élément central de la barre ; sur la référence il occupe visiblement plus de place que le nôtre, et c’est ce qui donne son aplomb à l’ensemble. Les fenêtres étroites ne changent pas : la compression y reste exactement la même, et un contrôle automatique vérifie qu’aucun bloc n’en recouvre un autre entre 640 et 1920 pixels. ENFIN LA BARRE DU HAUT S’ÉCARTE DES BORDS, de dix-huit à vingt-deux pixels. Sur la référence, aucun bloc ne touche le cadre. Quatre pixels de chaque côté suffisent à lever cette impression de contenu collé, sans rien retirer à la place disponible au centre.' },
  { id: 'dtpu-20260904-directs-widgets', ts: Date.UTC(2026, 8, 4, 3, 0), title: 'Bloomberg Live et Yahoo Finance Live rejoignent la bibliothèque', desc: 'Trois ajouts et une correction d’affichage. DEUX NOUVEAUX BLOCS DANS LA BIBLIOTHÈQUE : BLOOMBERG LIVE ET YAHOO FINANCE LIVE. Vous les trouverez dans la catégorie Marchés. Chacun ouvre le direct de l’éditeur dans un nouvel onglet, avec un mot sur ce qu’on y trouve et à quel moment de la séance il sert. POURQUOI UN LIEN ET NON UNE VIDÉO ENCADRÉE DANS LE DESK, car la question se pose. Deux raisons indépendantes. La première est technique : ces éditeurs interdisent à un autre site d’encadrer leur page, et le résultat serait un rectangle vide chez vous. La seconde est la vraie : rediffuser un flux vidéo de presse à l’intérieur d’un terminal payant relève des droits de diffusion de son propriétaire, pas d’un réglage d’affichage. Nous préférons vous emmener chez l’éditeur, sous ses conditions, plutôt que de recopier ce qui ne nous appartient pas. Le raccourci depuis votre desk, lui, reste entier. LE LECTEUR DE RAPPORTS RETROUVE SA BARRE HORIZONTALE. Dans l’onglet Institutions, une page de rapport plus large que le volet était coupée à droite, en silence : impossible de la voir, et rien n’indiquait qu’il manquait quelque chose. C’est le pire des comportements, celui qui masque sans le dire. La barre apparaît maintenant quand, et seulement quand, la page dépasse. Le reste du temps rien ne change. DEUX VIGNETTES RETIRÉES DU SITE PUBLIC. Les encarts Mon Desk et Vue d’ensemble montraient une capture du terminal datée du 6 août. Le desk a beaucoup évolué depuis : la capture ne montrait donc plus le produit, et une image périmée est pire qu’une absence d’image, parce qu’elle promet un écran qui n’existe plus. Les deux fonctionnalités restent décrites ailleurs sur la page.' },
  { id: 'dtpu-20260904-bases-debloquees', ts: Date.UTC(2026, 8, 4, 2, 0), title: 'Les quatre bases restaient bloquées en resynchronisation : corrigé', desc: 'Quatre corrections, dont une qui bloquait silencieusement toute lecture de comptes en base. LES QUATRE BASES RESTAIENT EN RESYNCHRONISATION, INDÉFINIMENT. Le panneau d’administration les affichait toutes les quatre en orange, ce qui signifie qu’aucune d’elles ne servait de lecture de compte : tout le terminal fonctionnait sur sa copie locale. La cause est une seule ligne. Nos comptes les plus anciens portent un identifiant hérité, et la synchronisation les envoyait sans cet identifiant, volontairement, pour ne pas écraser celui d’une autre base. Or la colonne identifiant n’accepte pas d’être vide : l’écriture échouait donc à chaque passage, sur chaque base, y compris quand la ligne existait déjà et qu’il n’y avait qu’à la mettre à jour. Et comme la levée de la resynchronisation exige que l’écriture ait réussi, elle n’arrivait jamais. Vérifié sur la vraie base, par un essai qui s’annule lui-même. Les comptes hérités sont désormais mis à jour par leur adresse e-mail, ce qui n’exige aucun identifiant et préserve celui déjà en place ; ceux qu’aucune base ne portait sont créés avec le leur. Trois conséquences se débloquent d’un coup : la resynchronisation se lève, les comptes historiques se propagent enfin sur les quatre bases, et les corrections d’échéance les concernant peuvent enfin les atteindre. LA BOÎTE DE RÉCEPTION SE TRIE VRAIMENT DU PLUS RÉCENT AU PLUS ANCIEN. Elle n’avait aucun tri : l’ordre n’était qu’un effet de bord de la construction de la liste. Il paraissait juste, mais un fil dont le dernier message dépasse la fenêtre des quatre cents messages récents se retrouvait collé en fin de liste quelle que soit sa date : un client qui vous écrit aujourd’hui après des mois de silence tombait tout en bas. Le tri est maintenant explicite, et les fils sans date connue ferment la marche au lieu de s’intercaler n’importe où. UNE PHOTO DE PROFIL PAR DÉFAUT. Un compte sans photo affichait son initiale sur un fond coloré. C’était joli, et c’était le problème : une initiale colorée ressemble à un choix, donc personne n’avait de raison de la remplacer. Elle laisse place à une silhouette sourde, qui se lit comme un emplacement vide et invite à poser sa vraie photo. L’image est dessinée pour le desk, comme l’avatar du Copilote Macro : aucune image empruntée ailleurs. Rien ne change pour un compte qui a déjà sa photo.' },
  { id: 'dtpu-20260904-durabilite', ts: Date.UTC(2026, 8, 4, 1, 0), title: 'La sauvegarde nocturne ne produisait aucune archive : corrigé, et élargie', desc: 'Trois protections ajoutées, et l’une d’elles répare une tâche qui ne fonctionnait pas du tout. LA SAUVEGARDE NOCTURNE N’AVAIT JAMAIS PRODUIT UNE SEULE ARCHIVE. En vérifiant ce qui vous protégerait d’une prochaine mise en pause, nous avons trouvé une erreur d’une ligne : l’export demandait à la base une table dont le nom était vide. La requête échouait, et comme la table des comptes est déclarée indispensable, tout l’export s’arrêtait, donc la sauvegarde entière avec lui. Le minuteur passait chaque nuit et ne laissait rien derrière lui. C’est la même forme de panne que le maintien en éveil des bases resté vert deux mois et demi en ne faisant rien : une tâche qui a l’air installée. Un contrôle automatique joue désormais cette fonction pour de vrai et regarde quel nom de table part réellement, parce qu’une relecture ne voit pas ce genre d’erreur. LA SAUVEGARDE NE COUVRAIT PAS CE QUE VOUS PRODUISEZ. Elle emportait les comptes, les envois de courriels et les récaps hebdomadaires. Elle n’emportait ni vos conversations avec le support, ni le magasin qui contient vos MODÈLES DE JOURNAL DE BORD, vos avatars et vos recherches récentes. Autrement dit, précisément ce que vous avez cru perdre. Les deux tables sont ajoutées. DEUX RÉGLAGES NE VIVAIENT QUE DANS UN FICHIER. La liste des comptes écartés et la trace des comptes supprimés étaient les deux seules données de tout le système à n’exister qu’à un seul endroit, sur un seul disque : tout le reste est déjà recopié sur quatre bases. Un disque remis à zéro et ces deux listes repartaient vides, sans que rien ne le signale, puisque le fichier repartait valide. Elles sont désormais enregistrées sur les quatre bases et entrent dans l’archive nocturne. En cas de désaccord entre le fichier et la base, nous gardons l’écartement : le coût d’une erreur dans ce sens est un message de support, le coût de l’erreur inverse est la raison même pour laquelle cette liste existe. LA SYNCHRONISATION DES ABONNEMENTS S’AFFICHE ENFIN. Une tâche compare toutes les dix minutes les abonnements de la plateforme de paiement avec ceux du terminal, et prolonge ce qui est en retard. Elle tournait depuis toujours sans qu’aucun écran ne la montre : impossible de savoir si les deux disent la même chose, ni depuis quand. Son état apparaît maintenant à côté de celui des bases. À noter, et c’est important : cette tâche ne fait que PROLONGER, jamais raccourcir. Un abonnement réglé par virement n’a donc aucune source extérieure pour le réparer, contrairement à un abonnement souscrit sur la plateforme, qui se rétablit tout seul.' },
  { id: 'dtpu-20260903-recap-profondeur', ts: Date.UTC(2026, 8, 4, 0, 0), title: 'Récap Quotidien : les décisions de taux et les publications se lisent en entier', desc: 'Le Récap Quotidien gagne deux niveaux de détail, sur deux points où il s’arrêtait trop tôt. UNE DÉCISION DE TAUX SE LIT DÉSORMAIS EN ENTIER. Le desk annonçait la décision et le taux atteint. Il annonce maintenant aussi l’AMPLEUR du geste : « relève de 25 points de base à 2,75% » plutôt que « relève à 2,75% ». L’ampleur seule ne dit pas où l’on en est, le niveau seul ne dit pas ce qui vient de se passer : il faut les deux. S’y ajoutent trois choses quand elles existent vraiment. La SÉRIE, d’abord : « 2e hausse consécutive ». Un geste isolé et un troisième d’affilée ne racontent pas la même politique, et c’est la série qui dit laquelle. L’HORIZON que la banque se donne ensuite : quand elle date elle-même son retour à la cible, cette date est reprise telle quelle. C’est ce que le marché price, et cela ne se déduit d’aucun chiffre du jour. Enfin le STATUT DE VOTE de l’intervenant, votant ou non votant : deux membres de la même banque ne pèsent pas pareil sur la prochaine réunion, et l’un des deux n’a pas de voix. Et lorsqu’un intervenant s’écarte de sa ligne habituelle, le desk le dit : c’est souvent l’information la plus utile de la journée. UNE PUBLICATION MAJEURE NE SE RÉSUME PLUS À SON CHIFFRE DE UNE. Le tableau des chiffres du jour donne déjà le résultat, l’attendu et le précédent. Les puces macro apportent maintenant ce que ce chiffre CACHE : la composante qui l’a fait, dont le sens est parfois l’inverse du total ; la série ou le record que la publication annonce elle-même, du type « nouvelles commandes en hausse pour le 26e mois consécutif » ou « plus forte expansion en six mois » ; et la lecture de l’organisme qui publie, attribuée à lui et jamais présentée comme la nôtre. Un chiffre situé dans sa série vaut dix chiffres nus, parce qu’il dit la tendance et non l’instant. Rien de tout cela ne s’invente : quand l’information n’existe pas, la puce s’en tient au fait et à son effet. Un record fabriqué est un mensonge qui a l’air d’une expertise. CE QUI N’A PAS CHANGÉ, VOLONTAIREMENT. Les chiffres du jour restent rangés par famille, inflation, emploi, croissance, parce que vous nous l’aviez demandé ainsi. Et une puce continue de ne parler que d’une seule banque centrale à la fois. Vingt-sept contrôles automatiques protègent désormais ces acquis : ces consignes vivent dans de longs textes où une reformulation peut en emporter une sans que personne ne le voie, et le rapport redeviendrait alors silencieusement ce qu’il était.' },
  { id: 'dtpu-20260903-abonnement-chaine', ts: Date.UTC(2026, 8, 3, 23, 0), title: 'Abonnements : trois défauts fermés de la saisie jusqu’à l’échéance', desc: 'Après le défaut corrigé ce matin, nous avons repris toute la chaîne des abonnements, du sélecteur du panneau d’administration jusqu’à la date inscrite sur votre compte. Deux autres défauts y dormaient. Aucun des deux ne se voyait à l’écran, et c’est précisément ce qui les rendait coûteux. UNE DURÉE NON RECONNUE OFFRAIT UN ABONNEMENT À VIE. Quand une durée d’abonnement n’était pas comprise, le desk ne renvoyait pas d’erreur : il renvoyait « pas de date de fin », ce qui signifie accès illimité. Un contrôle posé fin juillet avait déjà fermé ce piège pour les dates saisies à la main, en notant noir sur blanc qu’une valeur vide accordait un accès illimité par accident. Le même piège était resté quinze lignes plus bas, sur le cas général. Le sélecteur ne propose que des durées connues, donc rien n’était cassé pour vous ; mais l’interface de programmation acceptait le champ tel quel. Désormais une durée non comprise est refusée avec un message clair. On échoue du côté qui ne coûte rien. Au passage, la durée doit s’écrire en chiffres seuls : « 12mois » était accepté et valait douze mois, par chance, mais « 3jours » aurait valu trois MOIS et « 2semaines » deux mois. Une approximation qui tombe juste par hasard est plus dangereuse qu’une erreur. UN MOIS PLUS TARD, C’EST LE MÊME JOUR DU MOIS. Un abonnement d’un mois souscrit un 31 se terminait le 3 du mois suivant, parce que le calendrier n’a pas de 31 février. Trois jours offerts, donc personne ne s’en plaignait, mais l’échéance affichée devenait inexplicable. Elle est maintenant ramenée au dernier jour du mois d’arrivée : le 31 janvier donne le 28 février, le 31 août donne le 30 septembre. Les cas ordinaires ne bougent pas. UNE MODIFICATION D’ABONNEMENT ATTEINT TOUJOURS SA CIBLE. Nos quatre bases sont resynchronisées depuis une copie de référence. Une modification faite depuis le panneau qui réussissait en base mais n’atteignait pas cette copie était donc défaite au passage de synchronisation suivant, sans que rien ne le signale. La recherche se faisait sur un seul identifiant ; elle se fait maintenant aussi sur l’adresse e-mail, exactement comme l’écriture en base le faisait déjà, et l’absence des deux est consignée au lieu d’être avalée. Trente-cinq contrôles automatiques éprouvent maintenant cette chaîne avant chaque mise en ligne, en relisant les durées réellement proposées par le panneau plutôt qu’une liste recopiée à côté.' },
  { id: 'dtpu-20260903-abonnement-lecture', ts: Date.UTC(2026, 8, 3, 22, 0), title: 'Une lecture ne peut plus révoquer un abonnement payé', desc: 'Un membre nous a signalé ce matin être bloqué à la connexion avec « Abonnement expiré », alors qu’il avait réglé son abonnement par virement le 30 août et que son échéance avait été prolongée à la main le jour même. Nous avons remonté la chaîne complète, et voici ce qui s’est passé. LE DÉROULÉ, RECONSTITUÉ ET VÉRIFIÉ. Vos comptes vivent sur quatre bases en parallèle, plus une copie locale qui sert de référence. Le 30 août, la prolongation a été enregistrée correctement : la base principale étant alors arrêtée, elle est partie sur une base secondaire et sur la copie locale. Le 2 septembre, la base principale est revenue avec ses données figées à la mi-juin. L’ouverture du panneau d’administration a suffi : la lecture de la liste des membres est allée chercher la première base disponible, c’était celle qui venait de revenir, et ses échéances de juin ont remplacé les bonnes dans la copie locale. Cette copie a ensuite été recopiée vers les quatre bases. Une prolongation payée trois semaines plus tôt a donc été annulée par une simple lecture, sans qu’aucun message ne le signale. CE QUI CHANGE, ET POURQUOI CELA NE PEUT PLUS ARRIVER. Une règle simple a été posée : une LECTURE ne peut plus jamais raccourcir un abonnement ni désactiver un compte. Elle peut prolonger, jamais retirer. Seule une action d’administration explicite peut réduire une échéance, et celle-ci n’emprunte pas le même chemin. Concrètement, une base en retard peut désormais dire ce qu’elle veut : elle sera écoutée pour ce qu’elle ajoute, ignorée pour ce qu’elle enlève, et le refus est consigné pour que nous sachions qu’une base a pris du retard. Quatorze contrôles automatiques rejouent ce scénario exact avant chaque mise en ligne, avec la date du 30 septembre face à celle du 11 juin. Ils comportent aussi les cas inverses, tout aussi importants : un vrai renouvellement doit continuer de passer, un compte réactivé doit le rester, et une copie locale reconstruite doit pouvoir tout réapprendre. SI VOUS AVEZ ÉTÉ TOUCHÉ. Le désagrément ne concerne que des comptes ouverts avant la mi-juin et dont l’échéance a été modifiée à la main pendant l’été. Nous les reprenons un par un avec nos relevés de paiement. Si vous voyez « Abonnement expiré » alors que vous êtes à jour, écrivez-nous par la bulle de support : la correction prend quelques secondes et elle est désormais définitive.' },
  { id: 'dtpu-20260903-bases-reunion', ts: Date.UTC(2026, 8, 3, 21, 0), title: 'Vos conversations et votre modèle de journal étaient masqués, pas perdus', desc: 'Vous nous avez signalé que votre modèle de journal de bord semblait perdu, et que la liste de vos conversations avec le support paraissait amputée. Rien n’était perdu : tout était CACHÉ, ce qui du point de vue de l’écran revient exactement au même. Voici ce que nous avons mesuré, et ce que nous avons corrigé. CE QUI SE PASSAIT. Vos données vivent sur quatre bases en parallèle. L’une d’elles est restée arrêtée du 14 juin au 2 septembre, et les trois autres ont fait leur travail pendant ce temps : tout ce que vous avez écrit depuis le 14 juin est parti sur elles. Vos messages de support, eux, ne sont pas recopiés sur les quatre bases : chaque message vit sur une seule. Les messages d’avant le 14 juin sont donc sur la base arrêtée, et tous ceux d’après sur une autre. Deux moitiés d’un même historique, dont aucune n’est complète. Or, pour répondre, le desk interrogeait les bases l’une après l’autre et s’arrêtait à la première qui avait quelque chose à dire. À son réveil, la base revenue répondait la première, avec ses 26 conversations arrêtées au 14 juin, et les autres n’étaient jamais consultées. D’où votre impression d’un historique effacé. CE QUI CHANGE. Le desk RÉUNIT désormais les réponses de toutes les bases au lieu d’en retenir une. Votre historique de conversation redevient complet, des deux côtés du 14 juin, et le compteur de messages non lus additionne les deux moitiés au lieu d’en compter une seule. Marquer une conversation comme lue, en supprimer un message ou effacer les messages d’un compte atteint maintenant les quatre bases, alors qu’une seule était touchée jusqu’ici. VOTRE MODÈLE DE JOURNAL DE BORD, DEUXIÈME CAS. Celui-là est bien recopié sur les quatre bases, mais seulement au moment où vous l’enregistrez. Un modèle que vous ne modifiez plus restait donc figé au 14 juin sur la base revenue, pendant que les autres portaient votre version à jour, et le desk vous rendait tantôt l’une tantôt l’autre selon la base interrogée. Il compare désormais les dates et vous rend toujours la version la plus récente. La date d’enregistrement était pourtant conservée depuis le premier jour ; simplement, personne ne la relisait. Vingt-six contrôles automatiques rejouent maintenant ce scénario exact avant chaque mise en ligne, avec une base figée en juin face à une base à jour.' },
  { id: 'dtpu-20260903-pastille-au-bord', ts: Date.UTC(2026, 8, 3, 20, 0), title: 'Force des Devises : la devise ramenée au bord du cadre garde son étiquette', desc: 'Sur Force des Devises, quand le cadre se resserre sur le gros du peloton, la devise laissée au bord perdait son étiquette : sept pastilles s’affichaient au lieu de huit. La devise concernée gardait sa courbe et sa place dans la légende, mais plus son nom ni sa valeur au bout du tracé. LE FAIT, MESURÉ. L’étiquette était bien construite, avec la bonne valeur, et marquée visible. C’est son conteneur qui était masqué par la bibliothèque de graphiques. La raison est une question de quelques pixels : la marge qui ramène une étiquette hors cadre jusqu’au bord valait 1,2 pour cent de l’échelle, soit trois pixels sur un tracé de deux cent cinquante-cinq. Une pastille en fait quinze. Ramenée à trois pixels du bord, elle en dépassait sept vers le haut, et la bibliothèque escamotait alors tout le bloc. La marge se compte désormais en demi-pastille plus trois pixels de garde, convertis à l’échelle du graphique : l’étiquette tient entièrement dans le cadre, quelle que soit la hauteur du bloc. CE DÉFAUT NE SE VOYAIT QUE DANS UN CAS PRÉCIS : une devise qui reste dans le peloton puis s’en va en fin de période. C’est la seule situation où une étiquette est posée à un cheveu de la limite. Ce cas de figure ne faisait pas partie de nos contrôles ; il y est entré ce matin, et il a trouvé le défaut le jour même. Le message du contrôle nomme maintenant la devise absente au lieu de répéter le nombre attendu, ce qui aurait fait gagner un aller-retour.' },
  { id: 'dtpu-20260903-bloc-muet', ts: Date.UTC(2026, 8, 3, 19, 0), title: 'Un bloc qui n’affiche rien le dit désormais, au lieu de rester noir', desc: 'Signalement : dans un panneau à onglets, sur téléphone, le bloc Compte à rebours apparaissait entièrement vide. Ni chiffre, ni intitulé, ni même un message. CE QUE J’AI CHERCHÉ, ET CE QUE JE N’AI PAS TROUVÉ. Le squelette du widget est posé au montage, avant tout appel réseau : même sans données, il devrait rester un grand tiret à l’écran. Un blanc total signifie donc que le contenu existe et n’est pas peint. J’ai éprouvé huit configurations dans un vrai navigateur mobile : onglet simple, onglet composite à deux puis à quatre cases, sept tailles de téléphone, bloc à hauteur de contenu, bloc écrasé à deux cents pixels, calendrier renvoyant une liste vide, calendrier en erreur, calendrier qui ne répond jamais. Le widget s’affiche dans toutes. La cause reste inconnue, et je préfère le dire plutôt que de livrer une correction qui n’en serait pas une. CE QUI EST LIVRÉ EST UN FILET DE SÉCURITÉ, PAS LA CORRECTION. Un bloc qui n’a rien peint au bout de trois secondes et demie affiche désormais le message d’indisponibilité commun, avec son bouton Réessayer. Vous récupérez une action au lieu d’un rectangle noir, et le prochain signalement arrivera avec un message plutôt qu’avec un vide, c’est-à-dire avec de quoi chercher. Trois gardes évitent les fausses alertes : on ne regarde que si le bloc a lui-même de la place à l’écran, on ne touche pas à un bloc qui affiche déjà un message, et on attend trois secondes et demie parce que plusieurs widgets remplissent leur corps en différé. Vérifié sur les quarante widgets de la bibliothèque : aucun ne déclenche le filet à tort.' },
  { id: 'dtpu-20260903-etiquette-valeur', ts: Date.UTC(2026, 8, 3, 18, 0), title: 'Force des Devises : l’option « Valeur sur les étiquettes » affiche enfin la valeur seule', desc: 'Dans les réglages du widget Force des Devises, l’option « Valeur sur les étiquettes » fait désormais ce qu’elle annonce. Cochée, l’étiquette au bout de chaque courbe porte la VALEUR seule, dans la couleur pleine de la devise, exactement comme sur le terminal de référence fourni. C’est alors la couleur qui désigne la devise, la légende du haut restant la table de correspondance. Décochée, on retrouve la pastille au code, inchangée. CE QUI SE PASSAIT : l’étiquette affichait le code PUIS la valeur, deux pavés accolés. Le point gênant n’est pas l’erreur elle-même mais qu’elle contredisait trois écrits d’accord entre eux : le libellé du réglage, le commentaire qui l’accompagne dans le code, et une règle de style écrite depuis des semaines pour la pastille réduite à sa valeur, qui n’était produite nulle part. Le code faisait autre chose que ce que le produit disait de lui, et rien ne le vérifiait. DEUX GAINS AU PASSAGE. Les huit pastilles ont désormais la même largeur : un nombre n’en a pas de fixe, et sans plancher la colonne partait en escalier, de 30 pixels pour « 0,00 » à 44 pour « -100,37 ». Elles sortent maintenant toutes à la même largeur, mesurée au rendu et non calculée. Et la colonne de droite se resserre de 70 à 58 pixels, puisqu’un seul pavé y tient au lieu de deux : douze pixels rendus au tracé, ce que le libellé du réglage promettait déjà. Un contrôle automatique regarde maintenant l’étiquette produite dans les deux positions du réglage, ainsi que son plancher de largeur.' },
  { id: 'dtpu-20260903-force-fluidite', ts: Date.UTC(2026, 8, 3, 17, 0), title: 'Force des Devises : des courbes plus fluides et plus lisibles, sans toucher à la donnée', desc: 'Le graphique Force des Devises se lit beaucoup plus facilement : les courbes sont plus fluides, moins hachées, et les huit devises se distinguent mieux les unes des autres. CE QUI CLOCHAIT, ET CE N’ÉTAIT PAS LA DONNÉE. Comparé à un terminal de référence fourni par l’utilisateur, notre tracé paraissait brouillon. La cause est arithmétique : la référence affiche environ un demi point de donnée par pixel de largeur, notre widget en affichait un par pixel en séance et jusqu’à un et demi sur la semaine. Au-delà d’un point par colonne de pixels, chaque colonne reçoit deux valeurs et le trait ne dessine plus une courbe : il dessine une bande de bruit. La même donnée, deux fois plus serrée, ne peut pas avoir l’air de la même courbe. CE QU’ON A FAIT, ET SURTOUT CE QU’ON N’A PAS FAIT. Aucune moyenne, aucune courbe de lissage, aucune spline : la consigne était explicite, et elle est juste. Le desk choisit désormais, dans chaque tranche de la période, le point qui porte le plus de forme, avec l’algorithme employé par les terminaux de marché pour l’affichage. Chaque point tracé est un point réellement servi par la source, à sa date et à sa valeur. Les sommets et les creux sont conservés, la première et la dernière valeur sont rigoureusement intactes, et la dernière est celle que lit l’étiquette de droite. Mesuré sur une semaine type : les changements de direction passent de 59 à 20 pour cent pixels de largeur, sans qu’un seul point soit calculé. Sur un grand écran, où la densité était déjà bonne, rien n’est retiré du tout. DEUX AUTRES RÉGLAGES SUIVENT. Le trait est plus fin : sur une courbe dense, un trait large empâte les huit devises en une seule masse. Et la marge verticale, qui était comptée deux fois, ne l’est plus qu’une : jusqu’à un quart de la hauteur revenait à du vide, hauteur prise aux courbes, qui se tassaient et dont les étiquettes de droite finissaient alignées à espacement régulier au lieu de pointer chacune sa courbe. Un contrôle automatique mesure maintenant les deux choses qui comptent : que le rendu soit devenu lisible, et que la donnée soit restée intacte. Le second est le plus important, c’est lui qui distingue ce travail d’un lissage.' },
  { id: 'dtpu-20260903-jauge-hauteur-mobile', ts: Date.UTC(2026, 8, 3, 15, 0), title: 'Sur téléphone, le bloc Sentiment de Risque ne coupe plus son contenu', desc: 'Sur téléphone, le bloc Sentiment de Risque coupait environ vingt-cinq pixels de son contenu. Il recevait une hauteur plus basse que les autres blocs, une exception écrite à l’origine pour l’Horloge mondiale et à laquelle la jauge avait été rattachée par association, sans mesure qui la concerne. Elle rejoint le plancher commun, qui lui laisse la place qui manquait ; l’Horloge, elle, garde sa hauteur propre, mesurée sur ses cinq lignes. CE DÉFAUT A ÉTÉ TROUVÉ PAR LE CONTRÔLE POSÉ CE MATIN, et il vaut d’être raconté. Ce contrôle monte les quarante widgets de la bibliothèque au format téléphone et refuse qu’un seul soit coupé. Il était vert sur notre poste de développement, et rouge à la livraison : sans accès au réseau, la jauge n’affiche pas son graphique mais une ligne « indisponible », et il n’y a alors plus rien à couper. Un contrôle écrit sans réseau ne voit qu’une partie du produit. Le contrôle nomme désormais l’élément coupé et non plus seulement le widget, pour qu’un échec dise où regarder.' },
  { id: 'dtpu-20260903-force-toutes-courbes', ts: Date.UTC(2026, 8, 3, 14, 0), title: 'Force des Devises : les huit courbes sont visibles, aucune ne disparaît du cadre', desc: 'Sur le graphique Force des Devises, une devise pouvait disparaître complètement du cadre. Signalé capture à l’appui : « on ne voit pas la courbe NZD, il faut que toutes les courbes apparaissent ». POURQUOI ELLE DISPARAISSAIT. Le graphique resserre son cadre sur le gros du peloton quand une devise s’en éloigne beaucoup. C’est utile : l’indicateur est à somme quasi nulle, donc dès qu’une devise s’échappe, les sept autres se resserrent mécaniquement et deviennent illisibles si l’échelle suit la fuyarde. Mais la devise laissée dehors était rognée par le cadre : sa pastille restait, avec son chevron, et son tracé n’apparaissait nulle part. Sur une devise qui s’éloigne dès le début de la période, cela revenait à annoncer huit devises dans la légende et à n’en montrer que sept. CE QUI CHANGE. Le resserrement n’est plus autorisé qu’à cacher une EXCURSION, jamais une COURBE : une devise doit passer plus de la moitié de la période dans le cadre pour qu’on accepte de la voir en sortir le reste du temps. Une devise qui vit franchement ailleurs fait donc renoncer le resserrement, et le cadre redevient plein : les huit tracés sont visibles. Le seuil suit ce principe et n’est pas ajusté au cas du jour : j’avais d’abord posé un quart de la période, calé entre deux jeux d’essai, et il laissait passer une devise visible 23% du temps, c’est-à-dire absente des trois quarts du graphique. CE QUE ÇA COÛTE, ET C’EST ASSUMÉ. Quand une devise vit vraiment à l’écart, le peloton est plus tassé qu’avant, c’est la situation que le réglage d’août cherchait à éviter. C’est un arbitrage, et il penche du côté de la visibilité : c’est le troisième signalement de suite allant dans ce sens, après le yen le 12 août et les pastilles manquantes le 29. Le double-clic sur la marge de droite bascule toujours entre les deux cadrages. Un contrôle automatique éprouve maintenant les quatre situations que le graphique rencontre et refuse qu’un resserrement cache une courbe plus de la moitié du temps.' },
  { id: 'dtpu-20260903-defilement-mobile', ts: Date.UTC(2026, 8, 3, 12, 0), title: 'Sur téléphone, le doigt n’est plus enfermé dans le fil d’actualité', desc: 'Sur téléphone, arrivé au bas du fil d’actualité, le doigt ne pouvait plus rien faire : la page ne descendait pas plus loin. Signalé capture à l’appui, « ça me bloque ». RELEVÉ : le véritable ascenseur de la page est la grille du desk, avec près de quatre cents pixels à parcourir. Entre elle et le fil, quatre conteneurs qui n’ont rien à défiler. Et le fil portait une consigne de confinement qui COUPE la chaîne : arrivé au bout de ses deux mille pixels, le geste ne passait pas au conteneur suivant. Sur un téléphone, la carte occupe presque tout l’écran, et il ne restait, pour atteindre le reste du desk, que deux minces bandeaux de quelques pixels. L’Accueil avait déjà tranché cette question en juillet, et pour la même raison ; Mon Desk n’avait pas suivi. C’est désormais aligné, sur téléphone uniquement : sur un grand écran plusieurs ascenseurs cohabitent côte à côte et le confinement garde tout son sens. Le volet d’aide, lui, reste confiné : c’est un panneau posé PAR-DESSUS le desk, laisser le geste s’en échapper ferait défiler ce qu’on ne voit pas. Mesuré dans un vrai navigateur mobile : la grille avance désormais de la totalité de sa course pendant que le geste reste sur le fil ; avec l’ancien réglage elle n’avançait pas d’un pixel. ET LA QUESTION DE FOND A ÉTÉ REPRISE. La demande était « que les blocs s’adaptent en fonction du widget ». Première piste : tirer la hauteur du bloc de la taille que chaque widget déclare. La mesure l’a écartée : cette taille ne prédit rien. Le Compte à rebours en déclare 186 et le Sentiment de risque 460, alors que sur téléphone ils se comportent pareil ; les écarts entre taille déclarée et besoin réel vont de moins deux cent vingt à plus cent soixante-seize pixels. Une formule fondée là-dessus aurait rétréci des blocs qui n’en avaient pas besoin. Ce que la mesure dit vraiment : à la hauteur en production, AUCUN des quarante widgets de la bibliothèque ne perd d’information : les trois plus gourmands demandent 280, 300 et 340 pixels, les trente-sept autres tiennent en 240. Le manque de hauteur n’était donc pas le problème ; c’était l’excès, et une hauteur mal transmise aux widgets. Les deux sont corrigés par ailleurs. Reste à ce que cela dure : un nouveau contrôle monte toute la bibliothèque au format téléphone et refuse qu’un seul widget soit coupé. Le prochain widget trop gourmand sera arrêté là, et non par la capture d’écran d’un client.' },
  { id: 'dtpu-20260903-onglets-hauteur-vue', ts: Date.UTC(2026, 8, 3, 11, 0), title: 'Sur téléphone, les widgets d’un panneau à onglets retrouvent les lignes qu’ils s’effaçaient', desc: 'Sur téléphone, un widget placé dans un panneau à onglets se privait tout seul d’une partie de son affichage. Le Compte à rebours perdait sa ligne de lecture (« Attendu 0,3% après 0,2% : consensus en hausse ») et sa ligne « Ensuite », qui annonce la publication suivante. Le même widget posé dans un bloc ordinaire, sur le même écran, les affichait toutes les deux. L’EXPLICATION, mesurée et non supposée. Dix-neuf widgets du desk règlent ce qu’ils montrent sur la hauteur qu’on leur donne : dans un bloc écrasé, le pied et la ligne de lecture s’effacent plutôt que de se chevaucher. C’est voulu. Mais dans un onglet, sur téléphone, le widget se voyait attribuer une hauteur de ZÉRO alors que son bloc en mesurait près de quatre cents : toutes ces règles d’effacement se déclenchaient donc en permanence, y compris dans un grand bloc. Aucune erreur, aucun texte coupé, rien dans la console : l’information disparaissait en silence, ce qui explique qu’aucun de nos contrôles ne l’ait vu : ils mesuraient tous des blocs, jamais ce que le widget CROIT avoir comme place. La cause tient à la façon dont le montage d’un onglet était construit ; il adopte désormais exactement la même forme que celle d’un bloc ordinaire, qui n’a jamais eu ce défaut. Rien ne bouge à l’écran par ailleurs : les quarante widgets de la bibliothèque ont été remontés un par un, même hauteur, même débordement, avant et après. Sur grand écran rien ne change non plus, le défaut n’existait que sur téléphone. Un nouveau contrôle automatique demande maintenant au widget lui-même quelle hauteur il croit avoir, et non plus quelle hauteur son bloc mesure.' },
  { id: 'dtpu-20260903-mobile-hauteur-onglets', ts: Date.UTC(2026, 8, 3, 10, 0), title: 'Sur téléphone, un bloc à onglets prend la hauteur de ce qu’il affiche', desc: 'Sur téléphone, une carte à onglets de Mon Desk mesurait toujours la même chose, quel que soit ce qu’elle affichait. Ce plancher avait été taillé le 2 septembre pour les VUES du desk (Calendrier, Liste FX, Biais, Taux, Banques, Semaine à venir), qui réclament jusqu’à sept cents pixels et se retrouvaient coupées. La correction marchait, mais elle s’appliquait à TOUTES les cartes à onglets, y compris celles qui ne portent que de petits widgets. Résultat, signale capture à l’appui : un Compte à rebours, qui tient nativement en cent quatre-vingts pixels et ne porte qu’une seule information, se retrouvait centré au milieu de sept cents pixels de vide, à côté d’un Sentiment de risque de la même taille démesurée. Deux blocs identiques, dont l’un paraissait vide. Le desk lit maintenant la hauteur sur CE QUI EST MONTÉ, onglet par onglet. Un onglet qui adopte une vue complète du desk garde ses sept cent soixante pixels, inchangés. Un onglet qui affiche un petit widget reçoit la place exacte qu’il aurait dans une carte ordinaire, plus la piste d’onglets que le panneau ajoute au-dessus : quatre cent quatre-vingt-dix pixels, ni plus ni moins. La hauteur suit donc l’onglet actif et change quand vous changez d’onglet. Vérifié dans un vrai navigateur mobile, les neuf petits widgets passés en revue un par un : aucun contenu coupé. Cette double règle est désormais tenue par deux contrôles automatiques et non plus un seul : l’ancien vérifiait qu’une vue est assez haute, il ne pouvait pas voir qu’un petit widget était trop haut, et c’est précisément ce qui est passé.' },
  { id: 'dtpu-20260903-propos-majuscules', ts: Date.UTC(2026, 8, 3, 8, 0), title: 'Fil d’actualité : chaque propos commence par une majuscule', desc: 'Les fils de dépêches écrivent les propos de banquiers centraux tout en minuscules, sans majuscule initiale. Empilées dans le panneau d’une actualité, dix lignes rendues ainsi donnaient une impression de brouillon, alors que le reste du desk affiche des phrases ponctuées. Chaque propos commence désormais par une majuscule. Trois précautions, parce qu’une correction typographique appliquée sans discernement abîme plus qu’elle ne répare. La citation elle-même n’est pas modifiée : la majuscule est posée à l’affichage, le texte d’origine reste exactement ce que la source a écrit. La correction se fait en un seul endroit, celui par lequel passent tous les propos, qu’ils soient groupés ou isolés. Et seule une minuscule en tout début de ligne est touchée : une phrase qui s’ouvre sur un nom propre, un sigle comme RBNZ, un chiffre ou un guillemet est laissée telle quelle, puisqu’elle est déjà correcte.' },
  { id: 'dtpu-20260903-analyse-encre', ts: Date.UTC(2026, 8, 3, 6, 0), title: 'Fil d’actualité : l’Analyse s’écrit dans la même encre que les autres lectures', desc: 'Quand vous dépliez une actualité, le texte qui s’affiche sous les étiquettes change selon la lecture choisie. Info et Impact marché écrivaient le leur dans l’encre principale du desk, un blanc franc, tandis que l’Analyse rédigée sortait dans un gris secondaire. Le même bloc dépliant changeait donc de teinte selon l’onglet ouvert, et l’Analyse était la seule à paraître éteinte, alors que c’est souvent le texte le plus long et le plus lu. Elle prend désormais la même encre que les autres. Le gras à l’intérieur continue de ressortir, mais par son épaisseur plutôt que par sa couleur, puisque celle-ci est maintenant commune au reste du paragraphe. Détail qui compte pour le mode clair : cette encre suit désormais le thème toute seule, là où deux réglages figeaient auparavant un gris qui ne s’adaptait pas.' },
  { id: 'dtpu-20260903-decision-taux-couleur', ts: Date.UTC(2026, 8, 3, 8, 0), title: 'Une hausse de taux ne s’affiche plus en rouge', desc: 'Quand vous dépliez une décision de banque centrale, le desk annonce le geste : maintien, hausse ou baisse. La hausse sortait en ROUGE et la baisse en VERT. C’était l’inverse de ce que la ligne raconte : sur un desk de devises, une hausse de taux rend la devise plus attractive, donc elle la soutient. La couleur disait donc le contraire du texte juste à côté, à chaque publication. Elle est remise dans le bon sens : hausse en vert, baisse en rouge, maintien en gris. C’est déjà la règle qu’appliquait le tableau macro du Radar de Biais et la lecture du niveau d’inflation ; cet écran était le seul à dire l’inverse. UN SECOND DÉFAUT, SUR LE CHIFFRE CETTE FOIS. Sur la même décision, vous avez pu lire « relève ses taux à 25% (+22,5 pt) » face à un précédent de 2,50%. La source publiait le MOUVEMENT en points de base là où les autres colonnes donnaient le NIVEAU en pourcentage : le desk comparait deux unités différentes et en tirait une phrase absurde, écrite avec le même aplomb qu’une phrase juste. Il refuse désormais de conclure quand les unités ne concordent pas : il affiche la valeur publiée telle quelle, sans inventer ni écart ni surprise. Mieux vaut une ligne sobre qu’une ligne fausse. DEUX RETOUCHES D’AFFICHAGE AU PASSAGE. Le libellé « Analyse » d’une actualité s’écrit maintenant dans le bleu de son propre contour, comme Info s’écrit en turquoise et Réaction en violet : il était le seul des quatre à rester blanc. Et le sélecteur de période des graphiques de force des devises (TD, TW, 8H, 1D, 7D, 1M) affiche la période active avec le même coin carré dans le desk et dans vos courriels ; le mail était resté sur une forme arrondie, ce qui ne se remarquait pas tant qu’on ne mettait pas les deux côte à côte.' },
  { id: 'dtpu-20260902-bases-resynchro', ts: Date.UTC(2026, 8, 2, 23, 50), title: 'Vos accès sont protégés quand une de nos bases revient après une absence', desc: 'Vos comptes vivent sur quatre bases de données en parallèle : si l’une s’arrête, les trois autres prennent le relais et vous ne voyez rien. C’est ce qui s’est passé, et c’est ce pour quoi cette redondance existe. Restait un angle mort, que nous avons trouvé et fermé. Une base absente RATE les changements qui tombent pendant son absence : un mot de passe modifié, un abonnement renouvelé, un compte créé. À son retour, elle était réintégrée immédiatement et redevenait la première interrogée. Elle aurait donc répondu avec sa version, celle d’avant son absence, et elle aurait écrasé la bonne au passage. Concrètement : un mot de passe changé entre-temps refusé, un abonnement pourtant renouvelé annoncé comme expiré. Rien ne l’aurait signalé, ni à vous, ni à nous. Désormais, une base qui revient reçoit les mises à jour mais ne répond plus à aucune question sur les comptes tant qu’elle n’a pas été remise à niveau. Le temps que ça prend, ce sont les autres bases qui répondent, et si aucune n’est prête nous servons notre copie locale, qui est la plus à jour de toutes. Autrement dit, le pire cas de cette protection est aussi le plus sûr. Deux automatismes accompagnent ce changement, côté coulisses : nos bases sont maintenues éveillées depuis notre propre serveur plutôt que depuis un service tiers dont la configuration pouvait rester incomplète sans que personne ne s’en aperçoive, une base mise en pause est désormais relancée toute seule, et une sauvegarde chiffrée de vos comptes est prise chaque nuit, avec les trois dernières conservées.' },
  { id: 'dtpu-20260902-fxlist-icones', ts: Date.UTC(2026, 8, 2, 23, 30), title: 'Liste FX : le bandeau se range, l’en-tête se calme', desc: 'Deux retouches d’affichage sur l’onglet Liste FX, toutes deux venues de vos captures. L’ICÔNE DE RÉGLAGES DEVIENT CELLE DU DESK. Le bandeau portait une roue dentée écrite comme un caractère de texte : c’est votre appareil qui la dessinait, chacun à sa manière, et elle ne ressemblait à aucune autre commande du desk, qui sont toutes des dessins faits maison. Elle prend l’icône de réglages commune à tout le desk, les trois curseurs. Même place, même geste, même volet de colonnes : seule la forme change. LES DOUBLES CHEVRONS DISPARAISSENT DE L’EN-TÊTE. Deux petits chevrons gris se posaient en permanence sur les colonnes Symbole et Force. Ils étaient là pour dire que ces colonnes se trient, mais ils le disaient tout le temps, y compris quand le tableau était trié ailleurs, et n’apprenaient donc rien : le tri en cours, lui, se lit d’un coup d’œil à sa flèche pleine. Seule cette flèche reste, sur la colonne réellement triée. Rien ne se perd côté usage : toutes les colonnes qui se triaient se trient encore, d’un clic sur leur titre, exactement comme avant.' },
  { id: 'dtpu-20260902-tag-analyse-blanc', ts: Date.UTC(2026, 8, 2, 23, 0), title: 'Fil d’actualité : le libellé « Analyse » s’écrit en blanc', desc: 'Dans le fil d’actualité, chaque lecture d’une dépêche écrivait son libellé dans sa propre teinte : Info en turquoise, Analyse en bleu, Réaction en violet, Impact marché en vert. Au milieu d’une rangée où voisinent la paire de devises en or et les étiquettes de thème en blanc, le bleu d’Analyse était le seul à trancher, et cela se remarquait davantage que ce qu’il désignait. Son libellé s’écrit désormais dans le même blanc que les autres étiquettes du fil, exactement la teinte déjà utilisée partout ailleurs, et il passe au blanc franc lorsque la lecture est ouverte. Ce qui ne change pas, volontairement : le contour reste bleu. C’est lui qui distingue Analyse d’Info, de Réaction et d’Impact marché ; seule la couleur du texte devait s’aligner. La lisibilité y gagne au passage, le contraste du libellé passant de 6,5 à plus de 11 sur le fond du desk.' },
  { id: 'dtpu-20260902-ouverture-generale', ts: Date.UTC(2026, 8, 2, 21, 0), title: 'Mon Desk et l’Accueil ouverts à tous les membres', desc: 'Mon Desk et le nouvel Accueil sont désormais accessibles à tous les membres, sans exception. Ces deux nouveautés avaient été ouvertes à tout le monde début août, mais un réglage de sécurité posé en base pouvait encore les tenir fermées, et ce réglage était invisible depuis notre propre compte, qui garde l’accès en toutes circonstances pour pouvoir diagnostiquer. Autrement dit, une fermeture temporaire oubliée ne se voyait pas. Elle est levée pour de bon, une fois, et la trace de cette ouverture est conservée pour qu’elle ne se rejoue jamais : si nous devons un jour refermer une fonctionnalité en urgence, cette décision-là sera respectée. Trois mentions dans notre code affirmaient encore que Mon Desk était réservé à l’administrateur, près d’un mois après que la règle avait changé. Elles ont trompé une relecture récente, qui a conclu que la fonctionnalité était fermée alors qu’elle était livrée. Elles sont corrigées, et un contrôle de livraison interdit désormais leur retour. Ce que vous y gagnez concrètement : la composition de votre propre espace de travail, la bibliothèque de widgets, les dispositions enregistrées et l’écran d’accueil, pour tous les comptes, dès la prochaine connexion.' },
  { id: 'dtpu-20260902-quotidien-couleurs-datas', ts: Date.UTC(2026, 8, 2, 19, 0), title: 'Récap Quotidien : les chiffres publiés prennent leurs couleurs', desc: 'Dans le Récap Hebdo, un chiffre publié se lit d’un coup d’œil : il est vert quand il dépasse le consensus, rouge quand il passe dessous, ambre quand il sort conforme. Le Récap Quotidien, lui, affichait tout en blanc. Deux récaps du même desk, deux lectures du même chiffre. C’est corrigé : les rubriques du quotidien colorent désormais leurs données exactement comme l’hebdo, avec la même règle et les mêmes teintes. Les indicateurs dont la lecture s’inverse gardent leur traitement particulier : pour le chômage, les inscriptions ou les stocks, un chiffre au-dessus des attentes est une mauvaise nouvelle et sort donc en rouge, jamais en vert. Une nuance importante au passage : une puce du quotidien porte souvent deux ou trois publications d’affilée, par exemple l’inflation d’ensemble suivie de l’inflation sous-jacente dans la même phrase. Le desk n’en colorait qu’une, ce qui donnait un chiffre en couleur et le suivant en blanc juste à côté, et se lisait comme un oubli. Toutes les publications d’une même phrase sont maintenant traitées. Et lorsqu’une donnée n’a pas de référence comparable, elle reste blanche : mieux vaut pas de couleur qu’une couleur fausse.' },
  { id: 'dtpu-20260902-mobile-widgets-hauteur', ts: Date.UTC(2026, 8, 2, 17, 0), title: 'Sur téléphone, les widgets montrent enfin tout leur contenu', desc: 'Vous nous avez écrit que sur téléphone les widgets de Mon Desk ne montraient pas toutes leurs informations. Nous avons mesuré, dans un vrai navigateur de téléphone, ce que chaque vue réclame et ce qu’on lui donnait. Une carte à onglets porte deux barres avant son contenu : la rangée d’onglets et l’en-tête de la vue. Restaient 542 pixels utiles pour des vues qui en demandent 610, et jusqu’à 684 pour la Semaine à venir. Autrement dit il manquait entre 70 et 155 pixels, et c’est exactement ce qui ne s’affichait pas : l’onglet Institutions perdait 81 pixels de cartes, Analystes 63, la Semaine à venir 155. Les cartes à onglets sont donc nettement plus hautes sur téléphone, calées sur la vue la plus gourmande. Plus rien n’est coupé, à l’exception du fil d’actualité, qui défile par nature puisqu’il porte des dizaines de dépêches. L’horloge mondiale gagne elle aussi de la hauteur : il lui manquait quatorze pixels, soit une place tronquée en permanence. Sur un téléphone, en colonne unique, une carte plus haute ne coûte rien puisque la page défile de toute façon ; c’est le manque de hauteur qui cachait l’information. Rien ne change sur ordinateur ni sur tablette. Un contrôle de livraison ouvre désormais Mon Desk dans un téléphone simulé et refuse la mise en ligne si un widget se retrouve amputé.' },
  { id: 'dtpu-20260902-banques-graphique', ts: Date.UTC(2026, 8, 2, 15, 0), title: 'Onglet Banques : le graphique remonte, et il se lit', desc: 'Vous nous avez écrit que le graphique de l’onglet Banques donnait l’impression d’un faux graphique, et que le vide au-dessus de lui était trop grand. Deux corrections, mesurées l’une et l’autre. LE GRAPHIQUE REMONTE. Le tableau des positions prenait toute la hauteur disponible même avec cinq lignes, ce qui repoussait le graphique derrière plus de deux cents pixels de rien. Il se dimensionne désormais sur son contenu : le graphique vient se placer juste sous la dernière position, avec un espacement franc, et il gagne au passage deux cents pixels de hauteur. Quand les positions sont nombreuses, le tableau reprend la main jusqu’à la moitié de l’écran puis défile, pour que le graphique garde toujours sa place. ET IL RESSEMBLE ENFIN À UN GRAPHIQUE DE MARCHÉ. Une précision d’abord : c’est bien la bibliothèque de TradingView qui dessine ce graphique depuis le premier jour, et les trois lignes Entrée, Objectif et Stop y sont posées depuis le premier jour aussi. Ce qui n’allait pas, c’était le cadrage. Le desk affichait toutes les bougies reçues, soit plus de quatre cents : une échelle allant de 129 à 173 pour un trade dont les trois niveaux tiennent dans cinq unités de prix. Résultat, ces niveaux occupaient douze pour cent de la hauteur et deux d’entre eux se retrouvaient à quinze pixels l’un de l’autre, étiquettes collées, pendant que les bougies se réduisaient à des traits. Le cadrage se règle maintenant sur le trade lui-même : le desk remonte le temps depuis la dernière bougie tant que le marché reste dans une plage raisonnable autour des niveaux, puis s’arrête. Sur le même jeu de données, les niveaux passent de douze à quarante-six pour cent de la hauteur et l’écart entre les deux plus proches passe de quinze à cinquante-neuf pixels. Rien n’est perdu : tout l’historique reste chargé, un simple glissement vers la gauche le retrouve.' },
  { id: 'dtpu-20260902-fxview-rapide-et-mail-agenda', ts: Date.UTC(2026, 8, 2, 11, 0), title: 'FX View s’ouvre sans attente, et le mail Semaine à venir retrouve son agenda', desc: 'Deux corrections sur des choses qui vous faisaient attendre ou qui manquaient. L’ONGLET FX VIEW S’OUVRE MAINTENANT INSTANTANÉMENT. Le tableau ne demandait ses données qu’au moment précis où vous cliquiez sur l’onglet : vous regardiez donc l’animation de chargement à chaque fois, même quand tout était prêt côté serveur. Les données sont désormais préparées en arrière-plan pendant que vous lisez le fil, sans jamais retarder son affichage. Mesuré avec une connexion volontairement ralentie d’une seconde et deux dixièmes : l’animation de chargement restait visible un peu plus d’une seconde, elle ne s’affiche plus du tout, et les lignes sont là dès l’ouverture. Côté serveur, une seconde cause était plus sournoise : quand l’instantané avait dépassé ses quatre heures, votre requête attendait le recalcul complet, soit vingt-huit paires sur cinq ans d’historique, alors qu’un instantané parfaitement lisible dormait en mémoire. Le desk vous sert maintenant celui-là tout de suite et recalcule derrière. LE MAIL SEMAINE À VENIR RETROUVE SON AGENDA. Vous nous avez montré que le widget n’apparaissait pas dans ce mail. La cause tenait en trois maillons : quand l’image ne peut pas être fabriquée, l’adresse de secours pointait vers le même fabricant, lequel renvoie en dernier recours un pixel transparent, et ce pixel étiré sur toute la largeur se réduisait au trait fin que vous avez vu. Le mail perdait alors tout son agenda, puisque le texte par journée avait justement été retiré au profit de l’image. Un repli en tableau prend désormais le relais avec les mêmes journées : il ne demande aucune fabrication d’image, donc il ne peut pas échouer. Et quand une image manque, notre journal le dit franchement au lieu de laisser passer un mail troué.' },
  { id: 'dtpu-20260901-barres-et-curseur', ts: Date.UTC(2026, 8, 1, 14, 0), title: 'Lecteur de rapport, curseur et engrenage : les moitiés oubliées', desc: 'Quatre corrections d’affichage, toutes venues de vos captures. LE LECTEUR DE RAPPORT DE L’ONGLET INSTITUTIONS. Vous nous aviez signalé que la barre du lecteur ne faisait pas professionnelle, et nous avions réparé… celle de l’onglet Analystes. Les deux barres font exactement le même travail mais sont écrites deux fois dans notre feuille de style, et une seule avait été corrigée : voilà pourquoi il a fallu le signaler une seconde fois. Celle des Institutions porte maintenant le fond, le filet et la hauteur communs à tous les bandeaux du desk, et elle réserve la place des commandes qui flottent en haut à droite, pour que le bouton des éclairages ne passe plus dessous. LE CURSEUR MAIN, ENCORE. Là aussi le correctif précédent n’avait fait que la moitié du chemin, pour deux raisons. La règle qui donnait la main au titre d’une actualité s’appliquait sans condition, y compris aux titres qui ne déplient rien. Et surtout, la main couvrait la ligne entière et pas le texte : mesuré dans un vrai navigateur sur huit titres, entre 68 et 79 pour cent de la surface qui affichait la main ne portait aucune lettre. Elle suit désormais les mots. UN RÉGLAGE INATTEIGNABLE. L’engrenage des colonnes de la Liste FX, posé aujourd’hui, tombait exactement sous la plaque de commandes lorsque la vue est affichée en onglet dans Mon Desk : visible, mais impossible à cliquer. Une vérification automatique ouvre maintenant le desk, vise l’engrenage et refuse la livraison s’il ne répond pas au clic. Nous en avons profité pour passer en revue les neuf onglets : aucun autre n’est concerné. ENFIN, UNE PHRASE EN TROP. La mention « pricing indisponible » qui suivait les probabilités de réunion disparaît : dire qu’une donnée qu’on n’affiche pas est indisponible n’apprend rien. La provenance, elle, reste écrite, parce qu’une estimation du desk ne doit jamais pouvoir se lire comme un pricing de marché.' },
  { id: 'dtpu-20260901-fxlist-colonnes', ts: Date.UTC(2026, 8, 1, 12, 0), title: 'Liste FX : vous choisissez les colonnes que vous affichez', desc: 'Vous nous avez demandé de pouvoir masquer ou afficher les colonnes de l’onglet Liste FX comme vous le souhaitez. Une icône en forme de roue dentée apparaît maintenant à droite du bandeau de cet onglet : elle ouvre un petit volet où chacune des douze colonnes se coupe et se rallume d’un geste. Var. %, Saisonnalité, DMX, Fondamental, Recherche, Biais, les trois rendements 1M, 3M et 12M, Tendance, Force, et le dernier prix. Votre choix est retenu par compte, pas par navigateur : vous retrouvez votre tableau tel que vous l’avez laissé, y compris sur un autre appareil. La colonne Symbole reste toujours là, volontairement : sans elle, il resterait une rangée de chiffres sans savoir de quelle paire il s’agit. Et si vous masquez la colonne sur laquelle le tableau était trié, le tri revient de lui-même sur le symbole, plutôt que de rester classé selon une donnée devenue invisible. Le volet se referme au clic ailleurs ou avec la touche Échap, comme celui du calendrier. Au passage, une fragilité a été corrigée dans ce même tableau : lorsque la réponse du serveur arrivait incomplète, sans la liste des paires, l’affichage s’interrompait en silence au milieu du dessin. La barre de colonnes se redessinait, le corps du tableau restait figé sur son animation de chargement, et rien n’indiquait qu’il y avait un problème. Le tableau annonce désormais franchement qu’il n’a pas de données, ce qui est la vérité.' },
  { id: 'dtpu-20260902-icones-onglets', ts: Date.UTC(2026, 8, 2, 10, 0), title: 'Icônes d’onglet : plus lisibles, et bien plus nombreuses', desc: 'Deux choses sur le sélecteur d’icônes des onglets de Mon Desk. ELLES SE VOIENT MIEUX. Les dessins faisaient treize pixels avec un trait très fin : pas assez de matière pour reconnaître une forme d’un coup d’œil. Ils passent à quinze pixels avec un trait légèrement plus appuyé. Ce n’était pas une question de couleur, contrairement à ce qu’on aurait pu croire : la teinte au repos ressort déjà largement au-dessus du seuil de lisibilité, c’est la taille qui manquait, et c’est donc elle qui a été corrigée. IL Y EN A DEUX FOIS PLUS. Dix-huit icônes couvraient mal la variété des widgets du desk. La palette en compte désormais trente-deux, choisies pour ressembler à ce que vos onglets contiennent vraiment : égaliseur pour le baromètre, camembert pour le positionnement, balance pour le radar de biais, sablier pour le compte à rebours, cycle pour la saisonnalité, onde pour le direct, bulle pour l’assistant, bloc-notes, loupe, carte, bouclier, goutte, lingot. Elles sont rangées par famille (marchés, mesures, temps, lieux, contenus et signaux) pour qu’une palette deux fois plus grande reste parcourable au lieu de devenir un mur.' },
  { id: 'dtpu-20260902-lecteur-rapport-bandeau', ts: Date.UTC(2026, 8, 2, 10, 30), title: 'Ouvrir un rapport : la barre du lecteur redevient une vraie barre', desc: 'Vous nous avez signalé qu’ouvrir un rapport dans l’onglet Institutions ne faisait pas professionnel. La barre qui porte le retour, le titre du rapport et le bouton des éclairages était la seule du desk à ne pas suivre la règle commune. Son fond était exactement la couleur du contenu qu’elle surmonte, elle n’avait donc aucune existence visuelle, et sa ligne de séparation était tracée dans cette même couleur : une bordure invisible, qui occupait un pixel sans jamais rien séparer. Collée sous une barre d’onglets, le bouton finissait par se lire comme s’il appartenait à la barre du dessus. Elle porte maintenant le fond et le filet de tous les autres bandeaux du desk. Et lorsqu’elle vit dans une carte à onglets, elle réserve la place des commandes qui flottent en haut à droite, pour que le bouton et le badge ne passent plus dessous.' },
  { id: 'dtpu-20260902-curseur-classique', ts: Date.UTC(2026, 8, 2, 9, 0), title: 'Le curseur main ne s’affiche plus que sur ce qui répond au clic', desc: 'En promenant la souris sur le desk, le curseur passait en main sur presque toute la surface du fil d’actualité. Chaque ligne portait ce curseur sur toute sa largeur, soixante fois de suite, ce qui revenait à l’afficher partout. Et c’était une promesse fausse : la ligne elle-même n’est pas cliquable, c’est le titre qui déplie l’actualité. Le curseur annonçait donc un clic qui ne répondait nulle part ailleurs. La ligne rend maintenant la flèche classique, comme sur un terminal, et la main reste exactement là où quelque chose se passe : le titre de l’actualité, les étiquettes et les boutons. Un contrôle de livraison mesure désormais les trois cas dans un vrai navigateur, pour que la main ne se répande pas à nouveau et ne disparaisse pas non plus là où elle informe.' },
  { id: 'dtpu-20260902-force-pastilles-alignees', ts: Date.UTC(2026, 8, 2, 8, 0), title: 'Force des Devises : les pastilles se recollent à leurs courbes', desc: 'Vous nous avez montré une référence où chaque étiquette est posée à la hauteur exacte de la fin de sa courbe, en disant que la nôtre ne faisait pas professionnelle. Vous aviez raison, et la cause était dans notre propre réglage. Quand plusieurs devises finissent au même niveau, le desk écarte les pastilles pour qu’elles ne se recouvrent pas : c’est nécessaire. Mais il ajoutait en plus un écart de confort, au motif que huit pastilles collées se liraient comme un seul bloc. Sur le cas réel, celui de votre capture, cela faisait vingt-cinq pixels d’écart là où dix-neuf suffisent : six pixels d’éloignement artificiel par étiquette, et plus de quarante pixels de dérive entre la première et la dernière. Chaque pastille s’éloignait donc de sa courbe pour une raison qui n’était pas la donnée, et la colonne bien régulière qui en résultait ne montrait plus rien. L’écart est désormais réduit au strict minimum qui évite le recouvrement, jamais plus : la position d’une pastille redevient une information. La lisibilité d’un groupe serré est assurée autrement, par le fin trait et le point de couleur posés à la fin réelle de chaque courbe.' },
  { id: 'dtpu-20260902-taux-pied-retire', ts: Date.UTC(2026, 8, 2, 7, 0), title: 'Onglet Taux : la ligne de sources disparaît du bas des cartes', desc: 'La ligne posée hier au pied de chaque carte pour citer la provenance du taux et du pricing est retirée. Elle partait d’une bonne intention, mais elle finissait par écrire du diagnostic technique sur la carte d’un client : un code d’erreur HTTP et le nom d’un abonnement manquant chez un fournisseur n’ont rien à faire dans un produit, et sur deux lignes minuscules elle pesait plus lourd que les chiffres qu’elle accompagnait. Ce qui reste, et qui compte : le badge en tête de carte continue d’indiquer quand un pricing vient du modèle du desk plutôt que du marché. C’est lui la vraie garantie, la ligne du bas n’en était que la version longue : une carte sans pricing de marché ne peut toujours pas se lire comme un pricing de marché. La provenance du taux, elle, reste calculée et disponible côté serveur ; c’est seulement son affichage sur la carte qui disparaît.' },
  { id: 'dtpu-20260902-bandeaux-harmonises', ts: Date.UTC(2026, 8, 2, 6, 0), title: 'Les bandeaux de panneaux retrouvent tous le même fond', desc: 'Sur le desk, le bandeau de titre du fil d’actualité s’affichait sans fond, laissant voir le corps du panneau derrière lui, pendant que tous les bandeaux de la colonne de droite portaient bien leur teinte. Les deux sont pourtant définis avec exactement la même couleur : un effet de lumière ajouté plus tard sur les cartes remplaçait cette couleur au lieu de se poser dessus. La séparation entre l’en-tête et le contenu revient donc à gauche comme à droite, à la même hauteur et avec la même teinte. Un contrôle de livraison mesure désormais les deux familles de bandeaux dans un vrai navigateur et refuse un écart entre elles : c’est la cascade des styles qui tranche à l’écran, pas la déclaration qu’on lit dans le fichier.' },
  { id: 'dtpu-20260902-quotidien-cb-forme', ts: Date.UTC(2026, 8, 2, 5, 0), title: 'Récap Quotidien : les propos de banquiers centraux se lisent enfin comme de vraies notes de desk', desc: 'Vous nous avez fourni un extrait frais et récent du rapport de votre mentor pour préciser votre demande : le manque ne portait pas sur la structure, déjà proche, mais sur la manière dont c’est écrit. Comparaison ligne à ligne sur cinq interventions de banquiers centraux de cet extrait : aucune ne suit le schéma en trois temps que le desk imposait à chaque puce, fait, puis interprétation détachée, puis réaction de marché chiffrée. La vraie forme est plus proche d’une note prise en direct pendant un discours : l’intervenant d’abord, une seule flèche d’ouverture, puis ce qu’il a dit en plusieurs phrases courtes séparées par des points-virgules, l’interprétation déjà contenue dans le fait rapporté plutôt que redite à part. La réaction de marché, quand il y en a vraiment une de chiffrée, rejoint cette même liste au lieu d’ouvrir une seconde flèche, et la plupart des interventions n’en ont simplement aucune : ce n’est plus un manque. Rien ne change sur le fond déjà établi : une seule institution par puce, la fonction de l’intervenant précisée dès qu’il n’est pas le gouverneur en exercice, une décision annoncée en premier, et le mode du verbe qui distingue toujours ce qui est confirmé de ce qui est seulement rapporté.' },
  { id: 'dtpu-20260902-fil-propos-titre-fr', ts: Date.UTC(2026, 8, 2, 4, 0), title: 'Fil d’actualités : les dépêches de propos s’affichent enfin en français dans la liste', desc: 'Vous nous avez montré une ligne restée en anglais dans le fil, avec ses « +4 propos ». La dépêche était pourtant bien traduite : mais dans le mauvais champ. Une dépêche de propos possède deux textes. Celui du panneau, débarrassé du nom de celui qui parle, parce qu’une fois la fiche ouverte le locuteur est déjà annoncé. Et celui de la liste, entier, qui doit garder ce nom. Le desk ne remplissait que le premier. Résultat : du français dès qu’on ouvrait la dépêche, et de l’anglais tant qu’on ne l’ouvrait pas, c’est-à-dire dans le fil, qui est justement ce qu’on regarde le plus. Et c’était définitif : le cycle de traduction considère une dépêche comme traitée dès que le premier champ est rempli, il ne repassait donc jamais. Les deux textes sont désormais posés ensemble, sans payer de traduction supplémentaire : le nom du locuteur est simplement recollé devant la phrase traduite. Les dépêches déjà traduites avant ce correctif récupèrent leur ligne de la même façon, sans nouvel appel.' },
  { id: 'dtpu-20260902-widget-mail-cache', ts: Date.UTC(2026, 8, 2, 3, 30), title: 'Les images des courriels suivent enfin les changements d’apparence', desc: 'Vous avez signalé deux fois que la nouvelle pastille dorée des périodes n’apparaissait pas sur le graphique de la force des devises envoyé par courriel. Le desk était pourtant à jour. La cause : les images des courriels sont fabriquées une fois puis conservées, et leur identifiant décrit ce qu’on demande (le type de graphique, la période, la devise) sans jamais dire comment on le dessine. Une image déjà fabriquée restait donc valable après un changement d’apparence. Et pas seulement quelques minutes : la dernière bonne image est gardée sur disque, elle survit aux mises en ligne, et elle peut être servie jusqu’à trois jours. Un correctif visuel pouvait donc mettre trois jours à vous parvenir, sans que rien ne le signale. La version du dessin fait maintenant partie de l’identifiant : dès qu’on touche à l’apparence d’un widget, toutes ses images sont refaites. Et pour que personne n’oublie de le déclarer, un contrôle de livraison prend l’empreinte des gabarits et refuse de passer si elle change sans que la version bouge.' },
  { id: 'dtpu-20260902-hebdo-force-remplace-vix', ts: Date.UTC(2026, 8, 2, 3, 0), title: 'Récap Hebdo : la force des devises de la semaine remplace le VIX, sur le desk comme par courriel', desc: 'Sous la partie Géopolitique, le graphique du VIX cède sa place à celui de la force des devises, réglé sur la semaine. L’intention de l’emplacement ne change pas : la semaine géopolitique vient d’être racontée, une image dit ce que le marché en a fait. Mais là où le VIX donnait la prime de risque sans nommer aucune devise, la force des huit dit qui a profité de la semaine et qui l’a subie, ce qui enchaîne directement sur les blocs par devise juste en dessous. Le graphique du VIX n’est pas supprimé du desk : il reste disponible, c’est ce rapport qui ne l’affiche plus. Au passage, le titre de rubrique « Force des Devises » disparaît au-dessus de l’image, dans le Récap Hebdo comme dans le Récap Quotidien : l’image porte déjà son propre bandeau avec ses périodes, l’intertitre écrivait le même mot deux fois à vingt pixels d’écart.' },
  { id: 'dtpu-20260902-force-pastille-point', ts: Date.UTC(2026, 8, 2, 2, 0), title: 'Force des Devises : chaque pastille montre désormais où sa courbe se termine', desc: 'Quand les huit devises finissent dans un mouchoir, les pastilles ne peuvent pas rester chacune au bout de sa courbe : elles se recouvriraient. Le desk les écarte donc juste ce qu’il faut, et les relie à leur courbe par un fin trait de rappel. Ce trait s’arrêtait dans le vide, au milieu de sept autres de la même épaisseur : impossible de savoir sur quelle courbe il atterrit. Chaque trait porte maintenant un point à son extrémité, dans la couleur de la devise, posé exactement à la fin de sa courbe, avec un liseré sombre qui le détache de ses voisins quand deux devises terminent collées. Le trait, lui, s’affine et s’efface : c’est le point qui désigne, la ligne ne fait que conduire l’œil. Aucune pastille n’a bougé d’un pixel, aucun écart n’a changé, la gouttière garde sa largeur : seule la lecture du lien change.' },
  { id: 'dtpu-20260902-analyse-sans-cadre', ts: Date.UTC(2026, 8, 2, 1, 30), title: 'Le bouton Analyse : plus de cadre ni d’en-tête, juste le texte', desc: 'Suite de la simplification du tag Analyse. La synthèse était posée dans un encadré au fond plus clair, ouvert par une pastille dorée, le mot « Analyse » et l’heure. Trois couches d’habillage autour de quelques phrases, dans un panneau qui est déjà lui-même un cadre. L’en-tête ne disait d’ailleurs rien de neuf : le bouton qu’on vient de cliquer s’appelle « Analyse », et l’heure est déjà portée par la ligne du fil juste au-dessus. Il ne reste que le texte, sur le fond du panneau, comme les autres lectures du desk. Une analyse ancienne, produite avant l’existence de la synthèse, continue de s’ouvrir sur son contenu habituel plutôt que sur un panneau vide.' },
  { id: 'dtpu-20260902-periode-active-teintee', ts: Date.UTC(2026, 8, 2, 1, 0), title: 'Période active : la pastille dorée s’affine', desc: 'Ajustement de la pastille posée un peu plus tôt sur les barres de périodes (TD, TW, 8H, 1D, 5D, 7D, 1M). L’aplat doré plein cédait la place : il criait plus fort que les titres de la barre qu’il côtoie. La période active porte désormais un fond sourd dans la teinte, un cadre fin dans la teinte, et son texte en doré. L’or désigne au lieu de recouvrir, et la lecture y gagne. Les dimensions ne bougent toujours pas d’un pixel : le cadre est dessiné à l’intérieur du bouton plutôt qu’ajouté autour, sinon la barre entière se décalerait à chaque changement de période. Même pastille sur le desk et dans les graphiques envoyés par courriel.' },
  { id: 'dtpu-20260902-propos-traduction-retard', ts: Date.UTC(2026, 8, 2, 0, 40), title: 'Fil d’actualités : une traduction qui arrive en retard s’affiche quand même', desc: 'Vous nous avez montré un panneau de propos dont la première ligne était en français et les six suivantes en anglais. La première tenait sa traduction du desk, préparée à l’avance ; les autres passaient par la traduction à l’ouverture, et c’est là que le défaut se cachait. Cette traduction laisse deux secondes et demie au serveur, puis réaffiche le texte d’origine pour ne pas laisser le lecteur devant un vide. Jusqu’ici, elle marquait aussi la ligne comme définitive. Or la réponse arrivait souvent juste après ce délai : elle était bien reçue, bien mise en mémoire, et jamais affichée, la ligne ayant été déclarée close. L’anglais restait alors pour toute la session, sans le moindre signe d’erreur. Le réaffichage de secours ne ferme plus la ligne : elle redevient lisible tout de suite, puis se corrige d’elle-même dès que sa traduction arrive, même en retard. Seule la fin réelle du cycle, quand plus rien n’est en attente, fige ce qui n’a pas pu être traduit.' },
  { id: 'dtpu-20260901-mails-couleurs-datas', ts: Date.UTC(2026, 8, 2, 0, 20), title: 'Les courriels colorent enfin leurs chiffres, comme le desk', desc: 'Vous avez mis les deux côte à côte : la même publication, colorée sur le desk, blanche dans le courriel. La cause était simple et elle ne tenait qu’à une ligne : le chiffre publié était peint en gris clair en dur dans les mails, quel que soit son écart au consensus. Le calcul, lui, existait déjà dans le fichier des courriels, à l’identique de celui du desk, polarité inversée du chômage comprise ; il n’était simplement pas appelé à cet endroit. Il l’est désormais, dans le Récap Hebdo comme dans le Récap Quotidien : vert au-dessus du consensus, rouge en dessous, blanc quand la donnée sort pile dessus ou qu’il n’y a pas de consensus à comparer. La lecture qui suit la flèche, « au-dessus des attentes », prend la même couleur que le chiffre qu’elle commente.' },
  { id: 'dtpu-20260901-seance-couleurs-datas', ts: Date.UTC(2026, 8, 2, 0, 10), title: 'Récaps de séance : les chiffres publiés se colorent aussi', desc: 'Dans les récaps de séance, les lignes de données restaient blanches alors que, quelques lignes plus haut, d’autres sortaient en couleur. La couleur ne dépendait pas de la donnée mais de la TOURNURE de la phrase. Le desk reconnaissait la comparaison écrite « 51,7 vs 51,5 attendu », c’est-à-dire le mot de comparaison AVANT la référence. Or les lignes de données du desk s’écrivent dans l’autre sens, séparées par un point médian : « ISM Manufacturing PMI : 48,7 · attendu 49,0 · préc. 50,1 ». Ces lignes-là n’étaient rattrapées que lorsqu’elles énonçaient en plus leur verdict, ce que les récaps de séance ne font pas : ils listent les chiffres. Les deux écritures sont désormais lues de la même façon. Une règle ne change pas : seul le consensus sert de référence. Une ligne sans prévision reste blanche, on ne déduit jamais un signal du chiffre précédent.' },
  { id: 'dtpu-20260901-hebdo-force-sous-geo', ts: Date.UTC(2026, 8, 2, 0, 0), title: 'Récap Hebdo par courriel : la force des devises rejoint le VIX sous la géopolitique, et le VIX retrouve sa place', desc: 'La vue d’ensemble de la force des devises sur la semaine s’ajoute juste sous la partie Géopolitique, à côté du VIX. Les deux se complètent au même endroit et pour la même raison : la semaine géopolitique vient d’être racontée, le VIX dit la prime de risque qu’elle a produite, la force des devises dit qui en a profité et qui en a souffert. Aucune image supplémentaire n’est fabriquée, c’est celle que le courriel embarquait déjà. EN LA POSANT, UN DÉCALAGE A ÉTÉ TROUVÉ. Le graphique du VIX n’était pas là où il devait être. Il est bien produit juste après la géopolitique, mais l’assemblage final du courriel suit une liste d’ordre, et tout ce qui n’y figure pas est recollé à la fin : le VIX ne figurait pas dans cette liste, il s’affichait donc après les huit blocs de devises, tout en bas. Sur le desk, au même moment, il était à sa place. Les deux graphiques sont désormais inscrits dans cette liste, entre la géopolitique et la macro, et les deux surfaces montrent enfin le même rapport.' },
  { id: 'dtpu-20260901-point-marche-sans-tags', ts: Date.UTC(2026, 8, 1, 23, 55), title: 'Votre Récap Quotidien par courriel : les étiquettes de thèmes disparaissent', desc: 'La rangée d’étiquettes de thèmes qui s’intercalait entre le titre daté et l’ouverture du courriel est retirée. Elle avait été ajoutée pour donner les sujets du jour d’un coup d’œil, mais dans un message qui se lit de haut en bas, elle redisait en mots-clés ce que la Synthèse dit juste après en phrases : deux lectures du même contenu, à trois lignes d’écart. Les étiquettes restent sur le desk, où elles servent vraiment : y repérer un rapport dans une liste.' },
  { id: 'dtpu-20260901-calendrier-archive-futur', ts: Date.UTC(2026, 8, 1, 23, 50), title: 'Calendrier : le résultat d’hier ne peut plus ressurgir sur l’échéance de ce soir', desc: 'Vous nous avez remontré la même ligne quelques heures après notre correctif : le JOLTS de 20h était bien redevenu vide, mais l’ISM Manufacturing PMI de 20h affichait toujours un résultat alors qu’il était 16h45. Le correctif marchait, mais il ne fermait qu’une porte sur deux. Le desk garde six mois de publications en mémoire, pour rappeler les chiffres qui sortent de la fenêtre servie par le fournisseur. Cette mémoire avait enregistré la valeur fautive AVANT le correctif, et elle est conservée durablement : elle survivait donc aux redémarrages, et elle était réinjectée après le nettoyage, sur la ligne fraîchement nettoyée. Pire, cette mémoire ne remplace une valeur que si la nouvelle est plus récente : le vrai chiffre de 20h portant exactement le même horaire que la valeur fautive, il n’aurait jamais pu la corriger. Trois verrous sont posés. Un résultat daté du futur n’entre plus en mémoire. Une valeur déjà enregistrée est remplacée quand le vrai chiffre tombe au même horaire, ce qui couvre aussi les révisions. Et la mémoire se répare d’elle-même : une entrée fautive est ramenée à la dernière valeur réellement publiée, sans attendre que l’heure fautive finisse par passer.' },
  { id: 'dtpu-20260901-rebours-premier-calendrier', ts: Date.UTC(2026, 8, 1, 23, 40), title: 'Compte à rebours : la carte annonce bien la première échéance du calendrier', desc: 'Vous l’avez repéré sur une heure où deux publications fortes tombaient ensemble : le calendrier listait le JOLTS puis l’ISM, et la carte du compte à rebours annonçait l’ISM. Deux surfaces branchées sur la même réponse donnaient deux réponses. La cause tient à une différence de lecture : le tableau du calendrier trie sur le seul horaire, quand la carte ajoutait un départage sur le niveau d’impact, comparé de façon sensible à la casse. Une ligne servie « high » plutôt que « High » affichait donc trois points pleins dans le tableau tout en passant pour non-forte dans la carte : elle reculait derrière sa voisine, et le filtre « impact fort uniquement » l’aurait même fait disparaître. La carte reprend désormais exactement l’ordre du calendrier, et le niveau d’impact se lit partout de la même façon. Les autres publications de la même heure restent signalées sous le titre.' },
  { id: 'dtpu-20260901-force-sans-rechargement', ts: Date.UTC(2026, 8, 1, 23, 30), title: 'Force des Devises : la carte se met à jour sans que les courbes disparaissent', desc: 'Vous nous l’avez signalé : de temps en temps, la carte Force des Devises se vidait, affichait « Chargement… », puis redessinait ses courbes. Ce n’était pas occasionnel, c’était toutes les minutes. À chaque tour, la carte détruisait son graphique et le reconstruisait entièrement au lieu de simplement prolonger ses courbes avec les nouvelles données. Le mécanisme de mise à jour discrète existait pourtant déjà, et servait sur l’onglet FORCE du desk. La carte l’utilise désormais aussi : les courbes restent à l’écran pendant tout l’aller-retour, et se prolongent sans rupture. La reconstruction complète reste réservée à ce qui la justifie, un changement de période ou une reprise après incident. Et si la réponse n’arrive pas, plus rien ne bouge : la dernière courbe valable reste affichée plutôt que d’être remplacée par un message.' },
  { id: 'dtpu-20260901-periode-active-or', ts: Date.UTC(2026, 8, 1, 23, 20), title: 'La période affichée se repère d’un coup d’œil : pastille dorée sur TD, TW, 8H, 1D, 7D, 1M', desc: 'Dans une barre de sept périodes, un simple soulignement de deux pixels sous la période active se lit de près et se perd de loin. La période sélectionnée porte désormais une pastille dans le doré DTP : un fond sourd dans la teinte, un cadre fin, et le texte lui-même en doré. Le soulignement disparaît, la pastille le remplace au lieu de s’y ajouter. Tailles, espacements et alignements de la barre sont strictement inchangés, seul le marquage de l’état actif change. Même pastille et mêmes valeurs sur le desk et dans les graphiques envoyés par courriel, pour que les deux montrent la même chose.' },
  { id: 'dtpu-20260901-programme-temoignage-ligne', ts: Date.UTC(2026, 8, 1, 23, 10), title: 'Programme des envois : le témoignage membre a sa propre ligne, comme les autres envois', desc: 'Le témoignage mensuel s’affichait en petite étiquette accrochée à la ligne d’une autre semaine. C’était le seul envoi du programme à ne pas se lire comme les autres, alors qu’il en est un à part entière, avec son gabarit, son objet et ses cinq présentations. Sur l’écran qui sert justement à savoir ce qui part et quand, il était facile à manquer. Il a désormais sa ligne, au même format que ses voisines : sa date, son jour, son heure, et la présentation qui partira. Ce qui ne change pas : il reste hors rotation, puisqu’il s’ajoute au contenu de la semaine au lieu de le remplacer. Sa ligne le dit en toutes lettres, et ne propose donc pas le sélecteur de contenu des autres lignes, qui n’aurait rien à changer. Le jour affiché reste calculé sur la date réelle d’envoi, décalage de deux jours compris quand le mardi est déjà pris.' },
  { id: 'dtpu-20260901-analyse-synthese-seule', ts: Date.UTC(2026, 8, 1, 23, 0), title: 'Le bouton Analyse ouvre sur la synthèse, et rien derrière', desc: 'Vous nous avez mis deux captures côte à côte : d’un côté la carte de synthèse seule, de l’autre la même carte suivie d’un dossier en six rubriques. C’est la première que vous voulez. Le bouton Analyse déroulait la synthèse PUIS le détail complet, chiffres clés, ce qui a surpris, réaction de marché, implications banque centrale. La synthèse dit déjà tout cela, en quelques lignes écrites simplement : le résultat, la surprise réelle, le ton, la réaction. Le dossier ne fait que le répéter en plus long. Le bouton ne montre donc plus que la carte. Rien n’est supprimé côté desk : les analyses continuent d’être produites en entier, c’est l’affichage qui va à l’essentiel. Une analyse ancienne, produite avant l’existence de la synthèse, continue de s’ouvrir sur son contenu habituel plutôt que sur un panneau vide.' },
  { id: 'dtpu-20260901-calendrier-resultat-futur', ts: Date.UTC(2026, 8, 1, 22, 0), title: 'Calendrier : un événement encore à venir ne peut plus afficher un résultat déjà publié', desc: 'Vous nous avez montré une ligne « ISM Manufacturing PMI » prévue à 20h, encore marquée comme le prochain rendez-vous de la journée, qui affichait déjà un résultat réel. La cause : deux lignes du même jour et du même intitulé peuvent partager la même case de mémoire des résultats, sans distinction d’heure, si un fournisseur déclare deux fois le même indicateur à des horaires différents. La ligne réellement publiée y dépose son résultat, et la seconde, pas encore survenue, le récupérait par erreur au tour suivant. Un verrou final ferme désormais la porte, quelle que soit l’origine du résultat mal daté : aucune ligne dont l’horaire est encore à venir ne peut plus porter de résultat publié. Elle garde sa prévision et son précédent, comme toute échéance qui n’a pas encore eu lieu.' },
  { id: 'dtpu-20260901-quotidien-force-devises', ts: Date.UTC(2026, 8, 1, 21, 0), title: 'Récap Quotidien : la Force des Devises de la journée s’affiche après la Synthèse', desc: 'Sur le modèle du rapport de votre mentor, le Récap Quotidien montre désormais un graphique de la Force des Devises juste après la Synthèse, réglé sur la journée en cours plutôt que sur la semaine : c’est la même image que celle déjà posée sous chaque devise du Récap Hebdo et dans le mail hebdomadaire. Deux finitions demandées sur ce même graphique, appliquées partout où il apparaît : la période active de la barre TD TW 8H 1D 7D 1M se voit désormais en pastille dorée, plutôt qu’en simple soulignement, et la grille légère derrière les courbes, déjà posée fin août, reste bien active sur cette image.' },
  { id: 'dtpu-20260901-puces-couleur-courtes', ts: Date.UTC(2026, 8, 1, 20, 0), title: 'Les puces de données courtes se colorent aussi, et trois défauts d’écriture disparaissent au passage', desc: 'Vous nous avez montré deux rapports côte à côte : une même ligne de donnée, colorée vert, rouge ou or dans l’un, blanche dans l’autre. La couleur ne dépendait pas du récap mais de la longueur du paragraphe qui la portait : seuls les textes assez longs pour être découpés en plusieurs puces passaient par le contrôle qui compare le chiffre publié à ce qui était attendu. Or une ligne de donnée tient presque toujours sur une seule puce, courte, c’est justement le cas qui ne recevait jamais la couleur, sur tous les rapports. Elle la reçoit désormais partout. Trois défauts d’écriture ont été trouvés en vérifiant ce correctif sur des cas réels, et corrigés avec lui. Une heure au format 03:30 se scindait en deux, une moitié grasse et l’autre non, comme cela avait déjà été corrigé pour l’écriture 14h30 mais pas pour celle-ci. Un nombre sans unité suivi d’une espace traînait cette espace dans son habillage. Et un montant en milliards, écrit 4,29B, ne gardait que son premier chiffre en gras, le reste ressortant nu.' },
  { id: 'dtpu-20260901-vix-fond-blanc', ts: Date.UTC(2026, 8, 1, 19, 0), title: 'Récap Hebdo : le graphique du VIX passe en fond blanc, sans bandeau de titre', desc: 'Sur sa propre lecture TradingView du VIX, vous nous avez montré ce que vous vouliez : le même type de vue, sans le bandeau de titre et de valeur au-dessus du graphique, et avec un fond blanc plutôt que sombre. Les trois sont faits. Le bandeau disparaît : le titre « Volatilité · VIX » reste au-dessus de l’image, comme pour les autres graphiques du rapport, rien n’est perdu. L’axe du temps ne laisse plus de blancs pendant les heures où le VIX ne cote pas (nuit américaine, week-end) : les bougies s’enchaînent en continu, comme sur votre capture. Même image utilisée par le desk et par le mail, ils restent identiques.' },
  { id: 'dtpu-20260901-hebdo-vix-desk-jours-gras', ts: Date.UTC(2026, 8, 1, 18, 0), title: 'Récap Hebdo : le VIX arrive sur le desk, et les jours de la chronologie repassent en gras', desc: 'Le graphique du VIX (bougies 2 heures, traits rouges à chaque lundi) vivait déjà dans le mail hebdomadaire depuis quelques jours, juste après la partie Géopolitique : la semaine géopolitique vient d’être racontée, ce graphique dit ce que le marché en a fait avant d’entrer dans la partie Macro. Il n’avait pas encore rejoint le desk, c’est fait désormais, au même endroit, avec la même image. Et dans la chronologie géopolitique jour par jour, le nom du jour (« Mardi », « Mercredi »…) repasse en gras, sur le desk comme dans le mail : il sert de repère pour parcourir rapidement la semaine.' },
  { id: 'dtpu-20260901-taux-sources', ts: Date.UTC(2026, 8, 1, 17, 0), title: 'Onglet Taux : chaque carte cite la source de son taux, et le texte ne passe plus sur la courbe', desc: 'Trois corrections d’un coup sur l’onglet TAUX, toutes venues de votre relecture. LE TAUX N’EST PLUS UNE ESTIMATION, ET IL NE L’ÉTAIT PAS. Deux banques sur huit n’ont pas de pricing de marché chez notre fournisseur, et leur carte portait pour cela un badge « estimation DTP ». Placé seul en tête de carte, il se lisait comme un verdict sur tout ce qu’elle affiche, taux directeur compris. Le badge dit désormais ce qu’il qualifie vraiment, « pricing modélisé », et il reste là parce qu’une carte sans pricing de marché ne doit jamais pouvoir se lire comme un pricing de marché. LES SOURCES SONT ÉCRITES. Chaque carte porte en pied la provenance de son taux directeur et celle de son pricing, séparément : la décision qui a écrit le taux avec sa date et son intitulé de calendrier, ou la mention honnête d’un relevé fait à la main sur le communiqué de la banque quand aucune décision récente ne porte ce chiffre. ET UNE PANNE DE FOND, TROUVÉE EN CHERCHANT CES SOURCES. La voie qui recale le taux sur la dernière décision publiée lisait une liste qui ne contient pas les champs qu’elle cherchait : elle n’avait donc jamais rien écrit, et les huit cartes affichaient toujours la valeur relevée à la main. Elle lit maintenant les listes qui portent réellement ces chiffres, sur six mois d’historique, et le cas particulier de la BCE, qui publie deux taux le même jour, est tranché sur la facilité de dépôt, celle que suit le marché. ENFIN, LE TEXTE SUR LA COURBE. Sous 560 pixels de large, les valeurs Prochain mouvement, Probabilité et Δ attendu s’écrivaient par-dessus la petite courbe de fond, sur quinze pixels. La place réservée à la courbe et la hauteur de la courbe étaient deux réglages séparés qui avaient fini par diverger : ils n’en font plus qu’un, et sur mobile c’est la courbe, décorative, qui se réduit.' },
  { id: 'dtpu-20260901-calendrier-source-ff', ts: Date.UTC(2026, 8, 1, 12, 0), title: 'Calendrier économique : c’est ForexFactory qui dit ce qui est au programme', desc: 'Vous nous l’avez demandé après avoir cherché une publication sur forexfactory.com sans la retrouver chez nous : « la source du calendrier éco doit être celle de ForexFactory ». Jusqu’ici elle ne l’était qu’à moitié. ForexFactory donnait les NOMS des lignes, mais c’est notre autre fournisseur qui décidait lesquelles existent. Deux écarts en découlaient. Une ligne pouvait s’afficher chez nous sans figurer sur ForexFactory, et vous n’aviez alors aucun moyen de la recouper. Et l’inverse, plus discret : une publication annoncée par ForexFactory et ignorée par l’autre fournisseur n’apparaissait jamais, puisque renommer des lignes ne sait pas en ajouter. Désormais, sur la semaine que ForexFactory couvre, c’est lui qui fait foi : ses publications manquantes sont ajoutées, ses intitulés, ses horaires et ses niveaux d’importance l’emportent, et une ligne qu’il ne liste pas est retirée. Chaque ligne venue de ForexFactory porte aussi le lien vers sa fiche, avec le détail de l’indicateur et son historique au clic. Ce qui ne change pas : les résultats publiés continuent d’être collectés partout où ils se trouvent, et l’historique des mois passés reste servi comme avant, ForexFactory ne diffusant que la semaine en cours. Trois sécurités encadrent le retrait de lignes, pour qu’un flux momentanément indisponible ou incomplet ne puisse jamais vider une journée du calendrier : les grands rendez-vous que ForexFactory classe hors calendrier, comme un symposium de banquiers centraux ou une réunion de l’OPEP, restent affichés en toutes circonstances.' },
  { id: 'dtpu-20260901-rebours-pied', ts: Date.UTC(2026, 8, 1, 9, 0), title: 'Compte à rebours : la prévision et le précédent ne disparaissent plus sur les cartes courtes', desc: 'Vous nous l’avez signalé : toutes les informations du compte à rebours n’étaient pas visibles. La carte effaçait purement et simplement sa dernière ligne, celle qui porte la prévision et le précédent, dès que sa hauteur descendait sous un certain seuil. C’était volontaire au départ, pour garder le chronomètre lisible sur une carte volontairement courte, mais la mesure a montré deux choses : le seuil visait la hauteur de la CARTE alors qu’il s’applique au cadre intérieur, plus court d’une trentaine de pixels, si bien que la ligne disparaissait même à la taille par défaut de la carte ; et dans un panneau à onglets, la barre d’onglets prend sa part de hauteur, ce qui faisait passer sous le seuil sans que la carte paraisse petite. Or ce sont ces deux chiffres qui donnent son sens au décompte : sans eux il ne reste qu’une horloge. La ligne est désormais conservée et resserrée, et si elle ne tient vraiment pas, le corps de la carte défile : l’information reste atteignable, jamais supprimée.' },
  { id: 'dtpu-20260901-fil-francais-seulement', ts: Date.UTC(2026, 8, 1, 8, 0), title: 'Le fil ne peut plus afficher une actualité dans une autre langue', desc: 'Vous nous l’avez montré : cinq lignes du fil s’affichaient EN ITALIEN. La cause n’était pas la source mais le contrôle de ce que rend le traducteur. Avant d’enregistrer une traduction, le desk vérifiait deux choses seulement : que la réponse ne soit pas vide, et qu’elle soit différente du texte d’origine. Une réponse italienne passe ces deux tests sans difficulté : elle n’est ni vide, ni identique à l’anglais de départ. Elle était donc écrite dans le champ d’affichage de la ligne, et y restait pour toujours, puisqu’un champ déjà rempli n’est jamais retraduit. Le desk vérifie désormais que ce qu’il reçoit est bien du français avant de l’enregistrer : dans le cas contraire rien n’est posé, la ligne garde son titre d’origine et repasse au cycle suivant. Les traductions déjà enregistrées dans une autre langue sont retirées automatiquement et retraduites. Un contrôle de livraison rejoue les cinq lignes de votre capture à chaque version, avec des pièges volontaires (« Los Angeles », « Las Vegas », et le mot « mais ») pour qu’aucun titre français correct ne soit refusé au passage.' },
  { id: 'dtpu-20260901-hebdo-chronologie', ts: Date.UTC(2026, 8, 1, 7, 30), title: 'Récap Hebdo : les chiffres de la semaine se lisent enfin dans l’ordre des jours', desc: 'Sous chaque devise, les publications de la semaine se suivaient dans le désordre : mercredi, mercredi, vendredi, puis de nouveau mercredi. Elles héritaient de l’ordre du calendrier après renommage et dédoublonnage, c’est-à-dire d’aucun ordre lisible. Elles sont désormais triées par date, du lundi au vendredi, pour les huit devises et dans les trois rubriques (inflation, emploi, croissance), sur le desk comme dans le mail.' },
  { id: 'dtpu-20260901-hebdo-vix-gras', ts: Date.UTC(2026, 8, 1, 0, 30), title: 'Récap Hebdo : le VIX de la semaine en graphique, et le gras retrouve sa place dans le mail', desc: 'Deux ajouts au Récap Hebdo. LE VIX EN IMAGE, juste après la Géopolitique : la semaine vient d’être racontée, ce graphique dit ce que le marché en a fait. Bougies de 2 heures, avec un trait rouge à chaque lundi minuit pour séparer les semaines d’un coup d’œil. L’image est fabriquée à chaque envoi sur les vraies bougies, comme les courbes de force des devises, et embarquée dans le message pour s’afficher même quand la messagerie bloque les images distantes. LE GRAS REVIENT DANS LE MAIL. Les intitulés que le desk met en gras blanc en tête de chaque puce (« Fed : », « CPI zone euro : ») arrivaient à plat dans le courriel : la mise en forme était retirée en même temps que la syntaxe qui la porte. Elle est désormais rendue, dans la même couleur et la même graisse que sur le desk.' },
  { id: 'dtpu-20260901-lecture-hebdo', ts: Date.UTC(2026, 7, 31, 23, 58), title: 'Récap Hebdo : le jour de la chronologie passe en blanc, et les hebdos importants ne crient plus en rouge', desc: 'Deux retouches de lecture. Dans la chronologie géopolitique, le nom du jour s’affichait en or et en gras : il passait devant le fait qu’il introduit alors qu’il ne fait que le situer. Il est désormais en blanc, sans gras, sur le desk comme dans le mail. Et dans la liste INSTITUTIONS, FX Weekly et Asia FX Weekly portaient un titre écrit en rouge : ils adoptent la grammaire exacte des actualités majeures du fil — une teinte de fond rouge qui se renforce au survol, et un titre qui reste blanc. Deux surfaces du desk disaient « important » de deux façons différentes.' },
  { id: 'dtpu-20260831-temoignage-decale', ts: Date.UTC(2026, 7, 31, 23, 55), title: 'Plus jamais deux e-mails le même jour : le témoignage mensuel se décale de 2 jours si besoin', desc: 'Le témoignage mensuel part toujours le premier mardi du mois — mais certaines semaines, le contenu hebdomadaire de la rotation tombe lui aussi le mardi. Les deux e-mails partaient alors le même jour, à quelques heures d’écart. Quand ce chevauchement se produit, le témoignage glisse désormais au jeudi suivant : deux jours d’écart garantis entre les deux envois.' },
  { id: 'dtpu-20260831-recaps-sans-puces', ts: Date.UTC(2026, 7, 31, 23, 50), title: 'Récap Quotidien, récaps de séance, Récap Hebdo et Récap Économique perdent leur point doré', desc: 'Chaque ligne de ces quatre rapports s’ouvrait sur une petite pastille dorée. Elle est retirée : le texte garde son retrait, plus rien ne le précède. Même geste sur le desk et dans les mails.' },
  { id: 'dtpu-20260831-poignee-contour', ts: Date.UTC(2026, 7, 31, 23, 45), title: 'Mon Desk : la poignée d’élargissement allume le contour de la carte, sans plus rien ajouter', desc: 'Une première correction avait déjà rendu le rail de la poignée plus discret, mais il restait un second trait fin, distinct de la vraie bordure de la carte : deux lignes proches, encore un peu de confusion. La poignée surligne désormais la bordure DROITE existante de la carte elle-même, rien de plus — un seul trait, celui qui délimitait déjà la carte, qui s’allume au moment précis où on peut tirer le bord pour l’élargir.' },
  { id: 'dtpu-20260831-onglet-icone-chevron', ts: Date.UTC(2026, 7, 31, 23, 0), title: 'Panneau à onglets : l’icône remplace le chevron générique au lieu de s’y ajouter', desc: 'Choisir une icône pour un onglet du panneau à onglets faisait apparaître icône ET chevron « › » côte à côte, alors que l’icône dit déjà « ceci est un onglet » — le chevron générique ne servait plus qu’à répéter la même chose une deuxième fois, plus petit et plus pâle. Il ne s’affiche désormais que sur les onglets sans icône ; un onglet illustré affiche uniquement son icône, comme sur la barre de navigation du desk.' },
  { id: 'dtpu-20260831-recap-quotidien-autres-retire', ts: Date.UTC(2026, 7, 31, 22, 0), title: 'Récap Quotidien : la rubrique Autres éléments notables est retirée', desc: 'Même retrait que « Commerce International & Tarifs » avant elle : la rubrique disparaît du Récap Quotidien, desk et mail. Les faits qu’elle portait ne sont pas perdus pour autant — ils rejoignent la Géopolitique ou la rubrique de leur donnée chiffrée, selon leur nature.' },
  { id: 'dtpu-20260831-carte-poignee-rail', ts: Date.UTC(2026, 7, 31, 21, 0), title: 'Mon Desk : la poignée d’élargissement ne se lit plus comme un second ascenseur', desc: 'Sur une carte au contenu long, un rail doré discret longeait la vraie barre de défilement pendant toute la lecture — pas seulement au moment de tirer le bord pour élargir la carte, mais dès que la souris passait n’importe où dessus. Deux traits verticaux collés se lisaient comme deux ascenseurs. Le rail ne s’allume désormais qu’au survol PRÉCIS de la poignée elle-même, à l’instant où le curseur propose réellement d’élargir : en lecture normale, une seule barre reste visible. La poignée reste saisissable exactement comme avant.' },
  { id: 'dtpu-20260918-calendrier-pays-euro', ts: Date.UTC(2026, 8, 18, 16, 0), title: 'Calendrier : les publications de la zone euro portent enfin leur pays', desc: 'Une publication allemande s’affichait « CPI y/y », exactement comme l’agrégat de toute la zone euro publié le même mois : rien ne les distinguait à l’écran alors que ce sont deux chiffres différents, publiés par deux instituts différents. La donnée du desk savait déjà lequel des dix-sept pays avait publié (c’est elle qui évite de confondre l’inflation allemande et l’inflation française tombées le même jour), mais cette information s’arrêtait avant l’affichage. Les publications nationales portent désormais leur pays en tête du libellé, comme sur forexfactory.com : « German CPI m/m », « French Prelim GDP q/q »… L’agrégat de la zone euro entière, lui, garde son nom sans préfixe : c’est aussi la convention de forexfactory.com, et c’est la bonne, puisqu’il ne vient d’aucun pays en particulier.' },
  { id: 'dtpu-20260918-calendrier-panneau-a-onglets', ts: Date.UTC(2026, 8, 18, 15, 0), title: 'Calendrier en panneau à onglets : le décalage au déroulé d’un événement est corrigé', desc: 'Une correction publiée plus tôt visait le mauvais rendu. Le déroulé d’un événement du calendrier partage son code entre deux affichages qui ne comptent pas les colonnes de la même façon : la vue plein écran de l’onglet CALENDRIER lit le réglage global de l’onglet, le panneau à onglets (celui de la capture) lit un réglage propre à la carte. Masquer les colonnes Haut et Bas dans les réglages de la carte ne change rien au réglage global : le panneau annonçait alors deux colonnes de plus qu’il n’en existe, et le tableau réel s’effondrait de 150 pixels le temps que le déroulé reste sur toute la largeur (le bandeau de la journée et les colonnes RÉEL/PRÉVISION/PRÉCÉDENT glissaient visiblement vers la gauche). Le calcul lit désormais directement le nombre de colonnes de la ligne cliquée, quel que soit l’affichage qui l’a produite : plus de dépendance à un réglage qu’il ne consultait pas. Vérifié aux six largeurs d’écran du desk, colonnes affichées ou masquées.' },
  { id: 'dtpu-20260918-calendrier-cadre-et-bande', ts: Date.UTC(2026, 8, 18, 14, 0), title: 'Calendrier : un seul cadre doré, et plus de bande sombre quand on déroule un événement', desc: 'Deux défauts d’affichage de l’onglet CALENDRIER, tous deux visibles sur la ligne de l’événement en cours. D’abord le cadre doré qui la signale : il était peint DEUX FOIS, par deux mécanismes posés à des dates différentes, chacun installé en croyant être le seul. Au grossissement, on lisait deux liserés dorés parallèles séparés par un creux sombre au lieu d’un trait net. Il n’en reste qu’un, et le repère redevient franc, sur ordinateur comme sur téléphone : chacun garde le mécanisme qui fonctionne chez lui. Ensuite, ouvrir le décryptage d’un événement faisait apparaître une bande sombre le long du bord droit, juste à côté de la barre de défilement : le panneau semblait s’arrêter avant la fin du tableau. La place de la barre de défilement est réservée en permanence depuis une correction précédente, pour que dérouler une ligne ne décale plus tout le tableau vers la gauche. Cette réserve passait inaperçue tant que les lignes partageaient le fond du tableau ; le panneau déroulé, lui, peignait un fond légèrement plus clair, et la réserve se lisait alors comme un vide à sa droite. Le panneau reprend le fond du tableau : la bande disparaît, et le tableau continue de ne plus bouger à l’ouverture. Au passage, ce même panneau annonçait deux colonnes de plus que le tableau n’en compte lorsque vous masquez Haut et Bas dans les réglages de l’onglet.' },
  { id: 'dtpu-20260918-rail-dore-tactile', ts: Date.UTC(2026, 8, 18, 12, 0), title: 'Plus de trait doré parasite le long des cartes sur téléphone', desc: 'Un fin trait doré vertical apparaissait au bord droit des cartes, juste à gauche de la barre de défilement, au point de se lire comme un second ascenseur. Ce n’était pas une barre de défilement mais le repère de la poignée qui sert à élargir une carte : il s’allume au survol de la souris, et un téléphone garde cet état de survol accroché après le premier appui, sans jamais le retirer. Le repère ne s’affiche donc plus sur les écrans tactiles, où rien ne survole. La poignée reste saisissable et l’élargissement fonctionne comme avant ; sur ordinateur, le repère répond au survol comme toujours.' },
  { id: 'dtpu-20260918-impact-survol', ts: Date.UTC(2026, 8, 18, 10, 0), title: 'Le tag Impact marché suit enfin la même grammaire que ses voisins', desc: 'La pastille « Impact marché » se remplissait de vert dès le survol, quand les pastilles Info, Analyse et Réaction se contentent d’y changer leur couleur et leur contour. Sur téléphone, cet état de survol reste accroché après un appui : la pastille gardait donc son fond vert une fois le panneau refermé, seule de sa rangée. Elle rejoint la règle commune : contour et couleur au survol, fond teinté seulement quand son panneau est ouvert, et la même intensité de teinte que les trois autres lectures.' },
  { id: 'dtpu-20260918-fx-weekly-important', ts: Date.UTC(2026, 8, 18, 8, 0), title: 'FX Weekly et Asia FX Weekly signalés en important', desc: 'Les deux rendez-vous hebdomadaires de la recherche bancaire, FX Weekly et Asia FX Weekly, ressortent désormais en rouge dans la liste de l’onglet INSTITUTIONS, à chaque nouvelle sortie, comme les actualités majeures du fil. Une ligne déjà lue s’assagit mais garde sa couleur : vos hebdos de référence se retrouvent d’un coup d’œil, même au milieu de centaines de documents.' },
  { id: 'dtpu-20260917-boutons-incrustes', ts: Date.UTC(2026, 8, 17, 22, 0), title: 'Des boutons enfin incrustés dans leur panneau', desc: 'Les boutons de commande d’un panneau à onglets, réglages, tri, aide, fermeture, reposaient sur une petite plaque plus sombre que la barre qui les porte : un rectangle visible, comme posé après coup. La plaque devient transparente, les icônes reposent directement sur le panneau, et l’ensemble retrouve l’unité visuelle du desk. Ce nettoyage était rendu possible par une amélioration précédente : la rangée d’onglets s’arrête désormais avant la zone des boutons, plus rien ne défile dessous.' },
  { id: 'dtpu-20260917-recherche-mobile', ts: Date.UTC(2026, 8, 17, 20, 0), title: 'La recherche de symboles arrive sur téléphone', desc: 'Sur mobile, la case de recherche de la barre supérieure était réduite à une simple loupe : la liste des résultats s’ouvrait, mais le champ de saisie restait invisible, écrasé par le manque de place. Désormais, touchez la loupe et la recherche se déploie en barre pleine largeur par-dessus la barre supérieure : vous voyez ce que vous tapez, les résultats s’affichent dessous, et tout se replie dès que vous quittez le champ. Retrouvez vos paires, métaux et indices du bout du doigt, comme sur ordinateur.' },
  { id: 'dtpu-20260917-impact-pastille', ts: Date.UTC(2026, 8, 17, 18, 0), title: 'Le tag Impact marché s’habille comme ses voisins', desc: 'Sur une actualité du fil, la pastille « Impact marché » portait un fond rempli plus sombre que les pastilles Info, Analyse et Réaction, seules de leur rangée à jouer contour sur fond transparent. Elle adopte désormais la même structure : un contour coloré, un fond transparent, et seule la couleur distingue chaque lecture. Une rangée de tags enfin homogène, fidèle à la charte du desk.' },
  { id: 'dtpu-20260917-institutions-boutons', ts: Date.UTC(2026, 8, 17, 16, 0), title: 'Institutions en panneau : les boutons remontent à leur place', desc: 'Dans un panneau à onglets, l’onglet Institutions présentait ses boutons de commande, tri, aide, fermeture, relégués tout en bas de la carte, sous la ligne « Affichage de N sur N documents ». Ils retrouvent désormais leur emplacement légitime : en haut à droite du panneau, alignés sur la ligne du titre, comme partout ailleurs dans le desk. La correction bénéficie à toute vue accueillie dans un panneau à onglets dépourvue de barre d’outils dédiée.' },
  { id: 'dtpu-20260917-onglets-doigt', ts: Date.UTC(2026, 8, 17, 14, 0), title: 'Sur téléphone, la barre d’onglets ne s’emporte plus avec le doigt', desc: 'Balayer la barre d’un panneau à onglets pour parcourir ses onglets pouvait, au bout d’une demi-seconde, saisir toute la carte : elle partait alors sous le doigt, onglets chevauchés, et l’écran ne défilait plus. Le geste de balayage est désormais reconnu dans les deux sens : la rangée d’onglets défile, la carte reste en place. Pour réorganiser votre desk au doigt, rien ne change : maintenez la carte un instant sans bouger, puis déplacez-la.' },
  { id: 'dtpu-20260917-calendrier-cadre-mobile', ts: Date.UTC(2026, 8, 17, 12, 0), title: 'Calendrier sur téléphone : un seul cadre autour de la publication en cours', desc: 'Sur mobile, la prochaine publication du calendrier s’encadrait mal : chaque champ de la carte, l’heure, la devise, les valeurs, portait son propre trait doré, un quadrillage au lieu d’un repère. La carte de l’événement en cours porte désormais un seul cadre doré, autour d’elle et rien qu’elle, comme sur ordinateur. Le repère redevient ce qu’il doit être : un coup d’œil suffit pour voir ce qui arrive.' },
  { id: 'dtpu-20260917-mobile-un-ascenseur', ts: Date.UTC(2026, 8, 17, 10, 0), title: 'Sur téléphone, une seule barre de défilement le long du fil', desc: 'Sur mobile, deux barres fines pouvaient apparaître côte à côte le long du fil d’actualité : celle du fil lui-même et celle de la page de widgets qui le porte. La seconde est désormais invisible, le geste de défilement reste exactement le même, et seule la barre du fil, celle que vous connaissez, marque votre position dans les actualités. Un écran plus net, rien à réapprendre.' },
  { id: 'dtpu-20260917-graphique-unites', ts: Date.UTC(2026, 8, 17, 8, 0), title: 'Widget Graphique : drapeaux, paire et unités de temps dans la barre de la carte', desc: 'Le widget Graphique adopte l’en-tête des salles de marché, à la façon des terminaux de référence et aux couleurs du desk. À gauche, les drapeaux de la paire et son sélecteur ; à droite, les unités de temps en boutons : 5m, 15m, 30m, 1H, 4H, 1D, 1W et 1M, l’unité active à l’or. Un clic change l’unité et elle est mémorisée par compte, comme la paire. La barre d’outils que TradingView affichait en haut du graphique disparaît : elle faisait double emploi avec la nôtre ; les outils de dessin du bord gauche, eux, restent, pour poser niveaux et lignes de tendance directement sur les cours. Trois unités s’ajoutent au passage : 5 minutes, 30 minutes et le mensuel. Les minutes s’écrivent en minuscules (5m) et le mois en capitale (1M), pour qu’un coup d’œil suffise à les distinguer.' },
  { id: 'dtpu-20260916-jumelles-variantes', ts: Date.UTC(2026, 8, 16, 22, 0), title: 'Doublons du fil : les variantes du même événement fusionnent aussi', desc: 'Suite directe de la correction des dépêches en double, sur votre nouvelle capture : il restait le cas de la VARIANTE : « Communiqué sur les taux du FOMC » et « Communiqué sur les taux et prévisions économiques (SEP) du FOMC » à la même minute : la même échéance, annoncée deux fois par des libellés presque identiques. La déduplication reconnaît désormais ces annonces jumelles : deux titres quasi simultanés (moins de dix minutes d’écart) dont l’un est l’autre plus un complément fusionnent en une seule ligne, qui garde le libellé le plus précis, toutes les sources et le niveau d’importance. La règle est volontairement étroite : il faut un vrai tronc commun d’au moins trois mots pleins, si bien que deux dépêches courtes et distinctes (« Oil rises » et sa suite) ne fusionnent jamais, et au-delà de dix minutes rien ne change. Les paires de ce type déjà stockées sont retirées au démarrage, et votre capture exacte est rejouée par les contrôles automatiques à chaque livraison.' },
  { id: 'dtpu-20260916-rouge-deplie', ts: Date.UTC(2026, 8, 16, 20, 0), title: 'Une news importante dépliée reste rouge de haut en bas', desc: 'Vous l’avez pointé, référence à l’appui : quand on dépliait une news importante, la ligne gardait son fond rouge sombre mais la description en dessous repassait sur le gris des news ordinaires : le bloc se cassait en deux, et l’œil perdait le lien entre le titre et son détail. Le déplié d’une news rouge porte désormais exactement le même fond que sa ligne : le rouge descend d’un seul tenant sur le titre, la description, les puces et la réaction, au repos comme au survol, et la même correction s’applique au thème clair. Les news ordinaires ne changent pas. Un contrôle automatique déplie désormais une vraie news rouge dans un navigateur à chaque livraison et mesure que le fond du détail est bien celui de la ligne.' },
  { id: 'dtpu-20260916-fil-jumelles', ts: Date.UTC(2026, 8, 16, 18, 0), title: 'Fini les dépêches en double dans le fil', desc: 'Vous l’avez capturé : la conférence de presse du FOMC, le communiqué sur les taux et le rapport mensuel de l’AIE apparaissaient chacun deux fois, à la même minute. La cause était un angle mort de la déduplication : quand deux sources livrent la même dépêche dans le même lot d’arrivée, chaque copie n’était comparée qu’aux actualités déjà stockées, jamais à celles acceptées juste avant elle dans le lot : les deux entraient. Le lot se compare désormais aussi à lui-même : la seconde copie fusionne avec la première (ses sources s’ajoutent, son niveau d’importance est conservé), exactement comme si elle était arrivée plus tard. Les doublons déjà présents dans le fil sont retirés au passage, prudemment : seules deux dépêches au même titre à moins de trois heures d’écart sont considérées jumelles : une conférence du FOMC qui revient six semaines plus tard est une nouvelle édition, pas un doublon. Le lot exact de votre capture est rejoué à chaque livraison par les contrôles automatiques.' },
  { id: 'dtpu-20260916-semaine-deux-tetes', ts: Date.UTC(2026, 8, 16, 16, 0), title: 'Semaine à venir : quand deux décisions de taux tombent le même jour, les deux parlent', desc: 'Vous l’avez relevé sur la semaine du 31 août : le mercredi portait la décision de la Banque du Canada ET celle de la RBNZ, mais la carte titrait « BoC » et sa description ne parlait que d’elle : la RBNZ, pourtant présente dans la liste sous la carte, n’apparaissait ni dans le titre ni dans le texte. La règle en cause donnait tout le titre au rendez-vous majeur du jour pour qu’un chiffre secondaire ne le dilue pas ; elle n’avait pas prévu deux majeurs. C’est corrigé : deux têtes d’affiche partagent désormais le titre (« RBNZ + BoC », dans l’ordre de la journée), et la description change de forme ces jours-là, comme demandé : une clause courte par rendez-vous majeur avec son heure de Paris et ses chiffres, un seul « pourquoi ça compte », puis le reste du programme en une ligne : simple et court, fini le paragraphe sur une seule décision qui taisait l’autre. Les journées à un seul grand rendez-vous ne changent pas d’un mot, et le cas exact du mercredi 2 septembre est rejoué à chaque livraison par un contrôle automatique.' },
  { id: 'dtpu-20260916-lecteur-sombre', ts: Date.UTC(2026, 8, 16, 14, 0), title: 'Rapports d’institutions : fini le grand flash blanc au chargement d’un PDF', desc: 'Vous l’avez capturé : ouvrir un rapport d’institution affichait une grande zone blanche le temps du « Chargement du PDF… », étrangère au desk, avec un ascenseur peint en clair sur le côté. La cause : le fond blanc du papier était posé en permanence sur toute la zone de lecture, même quand aucun document n’y était encore. Le blanc n’appartient désormais qu’au document lui-même : pendant un chargement, sur un état d’attente ou dans la visionneuse PDF, la zone reste sur le fond sombre du desk et son ascenseur reste noir ; dès qu’un article s’affiche, son papier blanc revient, identique à avant. Le cas a été rejoué dans un vrai navigateur (rapport MUFG, chargement PDF maintenu ouvert) et un contrôle automatique bascule désormais la vraie règle à chaque livraison : sombre sans document, papier blanc avec.' },
  { id: 'dtpu-20260916-tag-info-propos', ts: Date.UTC(2026, 8, 16, 12, 0), title: 'Les tags du fil rentrent dans le rang : Info, Réaction, Analyse, Impact marché', desc: 'Vous l’avez relevé sur une news de propos rapportés : son bouton affichait « Contexte », un tag qui n’existe pas dans le vocabulaire du desk. Les tags du fil sont au nombre de quatre, et quatre seulement : Info, Réaction, Analyse et Impact marché (plus Décryptage, réservé aux données du calendrier). Une news qui reprend les propos d’un responsable porte donc désormais le tag Info, comme toutes les autres ; ce qui la distingue reste en place au bon endroit : le titre explicatif, la note « Propos personnels repris tels quels, sans portée directe sur les marchés » dans le panneau, et la citation d’origine lisible au déplié. Un contrôle automatique rend désormais une news de propos dans un vrai navigateur à chaque livraison et vérifie que son tag dit Info, et que « Contexte » ne revient jamais, ni en libellé ni en habillage.' },
  { id: 'dtpu-20260916-fil-sans-valeur', ts: Date.UTC(2026, 8, 16, 10, 0), title: 'Le fil refuse les communiqués promotionnels sans lecture marché', desc: 'Vous nous l’avez montré : une ligne « Comment la ligne directrice 12345 de la Chine réinvente les services aux citoyens » s’était glissée dans le fil, taguée Géopolitique. Ce genre de texte est de la communication d’action publique : un État y raconte comment son programme améliore la vie civique, sans un chiffre de marché, sans un actif, sans une décision. Le fil les refuse désormais à l’entrée, sur une règle volontairement étroite : il faut à la fois la forme du publireportage (« Comment… », « réinvente », « transforme »…) et le sujet civico-administratif (services aux citoyens, hotline, gouvernance…) pour qu’une ligne soit écartée, et tout titre qui parle réellement marché est épargné d’office : la géopolitique chinoise, les tarifs douaniers, une réforme à portée budgétaire restent. Les lignes de ce type déjà présentes dans le fil sont retirées au passage, et une batterie de contrôles automatiques rejoue à chaque livraison ce qui doit partir comme ce qui doit rester.' },
  { id: 'dtpu-20260916-stats-particuliers', ts: Date.UTC(2026, 8, 16, 8, 0), title: 'Nouveau widget : Statistiques DMX, la table complète du positionnement', desc: 'La bibliothèque de widgets accueille la table statistique du sentiment particuliers, avec sa vignette d’aperçu. Jusqu’ici le desk lisait ce positionnement en pourcentages : l’Aperçu DMX en barres, le widget par paire en anneau. La nouvelle table va au bout de la donnée : pour chaque paire, deux lignes (vendeurs et acheteurs) portent le pourcentage, le volume en lots, le nombre de positions, le prix moyen d’entrée du camp et son écart au prix actuel, en pips : vert quand le camp gagne, rouge quand il perd, et le pourcentage du camp majoritaire ressort à l’or. La lecture reste contrarienne : une foule majoritaire ET perdante devra racheter ses positions, et le tri « Foule la plus piégée » fait remonter ces paires d’un geste. Les métaux, sans cotation attachée, montrent leurs prix moyens mais laissent l’écart vide plutôt que d’inventer un chiffre.' },
  { id: 'dtpu-20260915-rebours-visible', ts: Date.UTC(2026, 8, 15, 22, 0), title: 'Compte à rebours : le chrono reste visible, même dans un panneau à onglets', desc: 'Votre capture montrait un Compte à rebours invisible dans un panneau à onglets : un grand vide, et la première ligne coupée au bord bas de la carte. La cause est un piège de géométrie : le corps de cette carte est centré verticalement, et quand sa boîte se croit plus haute que la carte réellement affichée (un contexte d’onglet ou une carte compressée peut tromper le calcul), le centre de la boîte tombe sous le bord : on ne voit que du vide. Le cas a été rejoué dans un vrai navigateur en doublant artificiellement la boîte, puis fermé par deux gardes : le centrage de toutes les cartes passe en centrage SÛR (centré quand ça tient, calé en haut dès que ça déborde : l’information d’abord), et la boîte du chrono est bornée à son hôte, en carte comme en onglet : elle ne peut plus dépasser. Les états de repli (« Aucune donnée », erreurs, onglets vides) profitent du même centrage sûr. Et l’attaque fait partie des contrôles de livraison : à chaque version, un navigateur monte le vrai widget, double sa boîte, et vérifie que le contenu reste dans la carte.' },
  { id: 'dtpu-20260915-calendrier-pleine-largeur', ts: Date.UTC(2026, 8, 15, 20, 0), title: 'Calendrier : plus de bande noire à droite quand une ligne est déroulée', desc: 'Votre capture le montrait bien : dans un panneau large, les lignes du calendrier s’arrêtaient avant le bord droit pendant que le décryptage déroulé, lui, courait sur toute la largeur : une bande noire vide longeait toutes les lignes. Le cas a été rejoué dans un vrai navigateur, pleine largeur, semaine courante et semaine d’archive, ligne déroulée, largeurs mesurées au pixel. La table du calendrier porte désormais un plancher structurel : elle épouse AU MOINS son panneau, dans tous les modes d’affichage et sur les trois surfaces qui la rendent (la vue Calendrier, le widget de Mon Desk et la page Semaine à venir), sans rien changer au comportement des petits écrans, où la table garde sa tenue. Et ce n’est pas une promesse : à chaque livraison, un contrôle automatique ouvre la vraie vue dans un navigateur, déroule une ligne et mesure que la table touche son panneau et que le déroulé n’en déborde jamais.' },
  { id: 'dtpu-20260915-stabilites', ts: Date.UTC(2026, 8, 15, 18, 0), title: 'Deux stabilités : le calendrier ne bouge plus au déroulé, la Force ne clignote plus au retour', desc: 'Deux agacements visuels fermés. LE CALENDRIER ÉCONOMIQUE d’abord : dérouler le décryptage d’une ligne faisait apparaître l’ascenseur vertical, et tout le tableau glissait vers la gauche en laissant un vide à droite. La place de l’ascenseur est désormais réservée en permanence : ouvrir ou refermer une ligne ne déplace plus rien à l’écran. LA FORCE DES DEVISES ensuite : revenir sur l’onglet FORCE reconstruisait les deux graphiques de zéro, courbes effacées puis redessinées, comme si le desk venait de démarrer. Quand les graphes sont vivants, plus rien ne se détruit : le retour ré-arme seulement la mise à jour silencieuse, les nouvelles valeurs se peignent en place et les courbes ne quittent plus l’écran. Une actualisation ne doit jamais se voir.' },
  { id: 'dtpu-20260915-widgets-refonte', ts: Date.UTC(2026, 8, 15, 16, 0), title: 'Nouveaux widgets : plus lisibles, plus DTP, et l’aperçu manquant retrouvé', desc: 'Vos retours en rafale sur les widgets récents, traités ensemble. LA SAISONNALITÉ d’abord : les chiffres se détachent désormais sur toute intensité de fond (texte posé sur une fine ombre), les flèches redondantes disparaissent (le signe et la couleur disent déjà le sens), la colonne Moy. se détache à l’or, les cellules pas encore cotées se hachurent au lieu de rester noires, et la ligne survolée s’éclaire. LES CARTES À BARRES (Indices & Matières et leur famille) gagnent une pointe dégradée au halo doux, un axe central net, des lignes séparées d’un filet fin et des chiffres alignés façon terminal. LE VERDICT de chaque carte récente prend l’encadré or du desk, la même écriture que la synthèse des récaps : la lecture principale se voit enfin comme telle. Et la carte « Indices & Matières » de la bibliothèque, seule du catalogue sans aperçu, a désormais sa vignette ; un contrôle automatique interdit qu’une carte ressorte un jour sans la sienne. Les anciens widgets n’ont pas bougé.' },
  { id: 'dtpu-20260915-ordre-importance', ts: Date.UTC(2026, 8, 15, 14, 0), title: 'Les catégories se lisent par importance : banque centrale d’abord, partout', desc: 'Vous avez fixé l’ordre : banque centrale, inflation, emploi, puis croissance économique, de la plus importante à la moins importante pour une devise. Il est appliqué partout où ces familles se lisent. Chaque bloc devise du Récap Hebdo (le desk comme le mail) ouvre désormais sur la banque centrale, sa décision et ses propos, puis l’inflation, l’emploi, et la croissance en dernier ; les Points Macro Clés suivent le même ordre, l’emploi passant devant la croissance ; et le Récap Quotidien comme les récaps de séance rangent leur rubrique Macro et leurs chiffres du jour à l’identique. Les rapports déjà archivés se réordonnent aussi, puisque l’ordre s’applique au moment d’afficher. Deux retouches de plume au passage, à votre demande : la ligne « Biais / Scénario » s’appelle sobrement « Biais », et les prochains rapports tiendront « Biais » comme « Semaine à venir » en une phrase courte qui nomme du concret : les rendez-vous et les chiffres, pas « l’attention se portera sur ».' },
  { id: 'dtpu-20260915-biais-audite', ts: Date.UTC(2026, 8, 15, 12, 0), title: 'Radar de Biais : audit complet de la chaîne, un défaut fermé, une garde permanente', desc: 'Vous nous avez demandé de vérifier que les biais des devises collent bien aux données : audit complet effectué, de la publication du calendrier jusqu’au verdict affiché. LE CONSTAT D’ENSEMBLE EST BON : le verdict découle à 100% des cellules affichées (politique monétaire, inflation, croissance, emploi), toutes nourries par les publications réelles du calendrier ; le chômage est bien inversé partout (un chômage qui monte pèse sur la devise) ; le niveau d’inflation ne se compare qu’en glissement annuel, à la cible de SA banque centrale ; le différentiel de taux suit sa courbe graduée au millième près ; et le classement est relatif entre les huit devises, comme sur un vrai desk. UN DÉFAUT RÉEL A ÉTÉ TROUVÉ ET FERMÉ : la mémoire du « Prochain mouvement » (l’hystérésis qui évite qu’un pricing hésitant fasse clignoter la direction) ne vivait qu’en mémoire vive. Au pricing actuel de la Fed (57,6% de hausse), un serveur en marche affichait « Hausse » quand un serveur fraîchement redéployé affichait « Maintien » : même donnée, deux affichages, sur le Radar comme sur l’onglet TAUX. Cette mémoire est désormais rechargée au démarrage depuis le dernier état publié. ET LA CHAÎNE A SA GARDE PERMANENTE : cinquante-six contrôles automatiques rejouent désormais à chaque livraison la surprise d’une publication (négatifs compris), l’inversion du chômage à ses trois étages, les valeurs exactes du différentiel de taux, le classement relatif et le défaut du redéploiement, fermé.' },
  { id: 'dtpu-20260915-hebdo-toutes-puces', ts: Date.UTC(2026, 8, 15, 10, 0), title: 'Le prochain Récap Hebdo gardera toutes ses puces, rubrique par rubrique', desc: 'Une vérification de fond menée avant l’édition de samedi a mis au jour deux restes de l’ancienne fabrique du Récap Hebdo, hérités d’avant la séparation des catégories. Le premier supprimait la rubrique « Banque centrale » au moment d’écrire le rapport : elle était ensuite reconstituée à l’affichage depuis les données des banques, mais dans une version plus pauvre que celle rédigée pour l’occasion. Le second reclassait les rubriques fraîchement séparées avec les règles d’AVANT la séparation : Inflation, Croissance économique et Emploi se refusionnaient en un seul bloc, plafonné à six puces, alors que trois rubriques de deux à trois puces en font jusqu’à neuf. Des puces pouvaient donc disparaître du rapport enregistré, sans trace, et l’affichage ne peut pas ressusciter ce qui n’a jamais été écrit. Les deux mécanismes sont retirés : le rapport s’enregistre désormais tel que rédigé, rubriques séparées, rubrique Banque centrale comprise, chaque rubrique gardant jusqu’à six puces. Le scénario exact (trois rubriques de trois puces, neuf puces attendues à l’arrivée) est rejoué à chaque livraison par un contrôle automatique.' },
  { id: 'dtpu-20260915-commerce-partout', ts: Date.UTC(2026, 8, 15, 8, 0), title: 'Le retrait de la rubrique Commerce s’applique à tout le desk', desc: 'Dans la foulée du Récap Hebdo, la catégorie Commerce disparaît partout où elle rangeait encore : la rubrique Macro et les Chiffres du jour du Récap Quotidien, les récaps de séance (Macro et Analyse de séance) et la Synthèse du Global Economic Weekly (« Commerce International »). Une balance commerciale ou une mesure tarifaire rejoint « Autres », qui porte toujours son intitulé : rien ne se perd, rien ne sort sans catégorie. Un soin particulier a été apporté au classement : une puce comme « Canada : contre-tarifs de 20 milliards de dollars » aurait pu glisser dans la rubrique Devises sur le seul mot « dollars » ; elle est retenue dans « Autres » exprès. Les rapports déjà archivés suivent, le mail comme le desk, et plus de six cents contrôles automatiques rejouent le nouveau rangement à chaque livraison.' },
  { id: 'dtpu-20260914-commerce-retire', ts: Date.UTC(2026, 8, 14, 22, 0), title: 'Points Macro Clés : la rubrique Commerce International & Tarifs est retirée', desc: 'Vous nous l’avez demandé : la rubrique « Commerce International & Tarifs » disparaît des Points Macro Clés du Récap Hebdo. Le retrait est appliqué au moment d’afficher, comme pour « Performance Cross-Asset » avant elle : les rapports déjà archivés perdent donc la rubrique eux aussi, sans être réécrits. Les faits de commerce ne sont pas perdus pour autant : les prochains rapports rangent un bras de fer tarifaire entre États dans « Géopolitique », là où vivent les autres rapports de force, et une retombée chiffrée (exportations, PIB, prix) dans la rubrique de sa donnée. La grammaire macro du Hebdo se resserre donc à six familles : Géopolitique, Banque centrale, Inflation, Croissance économique, Emploi, Technologie & Innovation, dans cet ordre.' },
  { id: 'dtpu-20260914-chiffres-anglais-classes', ts: Date.UTC(2026, 8, 14, 20, 0), title: 'Récap Hebdo : les chiffres au nom anglais retrouvent leur catégorie', desc: 'Vous nous l’avez montré, capture à l’appui : dans le Récap Hebdo, plusieurs chiffres de la semaine se retrouvaient relégués dans « Autres chiffres de la semaine » alors qu’ils ont une famille toute désignée : le taux de chômage japonais et européen (« Unemployment Rate »), le climat des affaires allemand (« Ifo Business Climate ») et les revenus des ménages américains (« Personal Income »). La cause : le calendrier économique livre les noms d’indicateurs en anglais, et le rangement du Hebdo ne reconnaissait que les mots français. Chaque catégorie comprend désormais les deux langues. « Unemployment » et les chiffres du marché du travail rejoignent « Emploi » ; le climat des affaires (Ifo, ZEW, Tankan), la confiance des consommateurs, les revenus et dépenses des ménages, les commandes de biens durables et l’immobilier rejoignent « Croissance économique » ; les salaires (wages, earnings) rejoignent « Inflation », au même titre que leur version française. Les archives en profitent immédiatement, puisque le rangement s’applique au moment d’afficher, et les quatre cas exacts de votre capture sont rejoués à chaque livraison par un contrôle automatique.' },
  { id: 'dtpu-20260914-graphique-splitters', ts: Date.UTC(2026, 8, 14, 18, 0), title: 'Vue graphique : les poignées de redimensionnement se font discrètes et précises', desc: 'Sur la vue graphique d’une paire, les deux poignées qui redimensionnent les panneaux passaient à l’or au survol : le trait vertical pleine hauteur au bord du graphique se lisait comme un second ascenseur doré. Elles deviennent neutres et quasi invisibles au repos, s’éclaircissent pendant le geste, et leur zone de prise s’élargit côté volet (jamais côté graphique : un clic ou un glissement sur le graphe ne peut plus les attraper par accident). Le glissement est aussi corrigé en profondeur : la poignée suivait la position absolue du curseur en oubliant la marge de la grille, ce qui la faisait sauter sous la souris au premier mouvement ; elle suit désormais le déplacement exact, un pixel de souris pour un pixel de poignée. Les dimensions du graphique, son échelle et son fonctionnement ne changent pas.' },
  { id: 'dtpu-20260914-taux-conforme', ts: Date.UTC(2026, 8, 14, 16, 0), title: 'Onglet TAUX passé au peigne contre la référence professionnelle', desc: 'Vérification demandée, carte par carte : notre Probabilité de taux d’intérêt affiche les mêmes données que l’outil professionnel de référence (taux actuel, date de réunion, probabilités, delta attendu, distribution des scénarios, tableau des réunions) avec la même grille visuelle : probabilité en or, distribution triée sans lignes vides, deltas en pastilles, scénario central en badge. Les chiffres de la Fed peuvent différer de quelques dixièmes selon la méthode de calcul (contrats à terme ou taux au jour le jour) : les deux lectures sont de vraies données de marché, et la carte Fed porte déjà la seconde en recoupement. Un libellé s’aligne au passage : la colonne Jours.' },
  { id: 'dtpu-20260914-splitter-titres', ts: Date.UTC(2026, 8, 14, 14, 0), title: 'La barre de redimensionnement ne se déguise plus en ascenseur, et les titres des mails s’allègent', desc: 'Sur le desk, la barre qui sépare le flux du panneau droit passait à l’or au survol : pleine hauteur, collée au vrai ascenseur du panneau, elle se lisait comme un second ascenseur doré. Son retour visuel devient neutre (la ligne s’éclaircit et s’épaissit légèrement pendant le glissement) et sa zone de prise s’élargit de moitié : le curseur attrape la barre du premier coup, sans gêner l’ascenseur voisin. La règle qui dorait tous les ascenseurs au survol est retirée avec elle. Et dans les e-mails, les titres de rubrique perdent leur petit trait vertical à gauche, comme sur le desk : titre doré, filet dessous, rien devant.' },
  { id: 'dtpu-20260914-mails-jamais-perimes', ts: Date.UTC(2026, 8, 14, 12, 0), title: 'Les e-mails ne peuvent plus montrer une semaine passée', desc: 'Repéré sur l’aperçu du mail Semaine à venir : le texte annonçait la bonne semaine pendant que l’image du calendrier montrait celle d’il y a deux semaines. En cause, le filet anti-image-cassée des e-mails : quand le rendu d’une image échoue, il sert la dernière image réussie ; sans date de péremption, il a resservi une image figée pendant deux semaines, en silence. Le filet est désormais borné : une image qui porte des dates (Semaine à venir, calendrier) périme en 24 heures, les autres en 3 jours ; au-delà, le mail préfère ne rien afficher plutôt qu’afficher faux, et la panne de rendu s’écrit dans le journal au lieu de se taire. La même règle vaut pour les données : le mail Semaine à venir n’embarque l’agenda que s’il couvre bien la semaine cible, et un Récap Hebdo de plus de neuf jours ne part plus jamais comme s’il était neuf. Au passage, chaque courbe de devise garde désormais sa propre image de secours : celle d’une devise ne peut plus remplacer celle d’une autre.' },
  { id: 'dtpu-20260914-taux-calibres', ts: Date.UTC(2026, 8, 14, 9, 0), title: 'Onglet TAUX : les huit banques vérifiées une par une, biais recalés sur le pricing réel', desc: 'Suite de l’audit des taux, chaque devise a été vérifiée sur pièces. Les huit taux directeurs affichés sont confirmés exacts : fourchette Fed 3,50-3,75, dépôt BCE 2,25, BoE 3,75, BoJ 1,00, BoC 2,25, RBA 4,35, RBNZ 2,50, BNS 0,00. En revanche, les biais de secours dataient de juin et disaient « pause, penchant baisse » sur quatre banques alors que le marché price aujourd’hui la hausse : environ 58% pour la Fed, 90% pour la BCE, 74% pour la BoJ et 58% pour la RBA à leur prochaine réunion. Ils sont recalés sur ce pricing réel. Surtout, les deux banques sans flux de marché s’alignent enfin sur les vrais niveaux : la carte RBNZ affiche environ 93% de hausse, comme le marché (93,3%), et la carte BNS environ 95% de maintien, au plus près du marché (99,5%), au lieu des 60% et 65% génériques d’avant.' },
  { id: 'dtpu-20260913-hebdo-force-mail', ts: Date.UTC(2026, 8, 13, 23, 0), title: 'Le mail Récap Hebdo retrouve la force des devises, courbe par courbe', desc: 'Repéré sur l’aperçu du mail Votre Récap Hebdo : les blocs devise n’affichaient plus la force de la devise, alors que le rapport du desk montre une courbe sous chaque bloc. Lors d’une refonte récente, l’image d’ensemble avait été retirée au motif que chaque devise garderait sa propre courbe ; cette courbe n’avait en réalité jamais été posée dans le mail, et la force avait disparu tout court. C’est corrigé : chaque bloc devise porte désormais la courbe de force de SA devise sur la semaine, la même que sur le desk, placée au même endroit (après le résumé, avant les chiffres). Les images sont embarquées dans le mail pour s’afficher partout, y compris dans les messageries qui bloquent les images distantes, et une devise sans publication cette semaine ne reçoit pas de courbe orpheline.' },
  { id: 'dtpu-20260913-rapports-taux', ts: Date.UTC(2026, 8, 13, 22, 0), title: 'Les rapports parlent taux avec les mêmes chiffres que l’onglet TAUX', desc: 'Dans la foulée de la remise à plat de l’onglet TAUX, les trois grands rendez-vous écrits du desk s’alignent sur les mêmes chiffres. Le Récap Hebdo ancrait déjà sa section Banques centrales sur le pricing du desk : chaque banque y porte désormais aussi sa source (pricing de marché ou estimation du desk), et la puce Pricing de chaque devise commence par le taux directeur en vigueur, recalé sur la dernière décision réelle. Le Point Marché de midi reçoit le même bloc de taux et de probabilités : sa section Banques centrales cite des niveaux réels au lieu de broder sur la seule actualité. Et dans la Semaine à Venir, la carte d’un jour de décision de taux annonce maintenant le scénario pricé de la réunion (maintien, hausse, baisse) et le taux actuel, avec sa source. Une règle commune verrouille le tout : une estimation du desk ne peut plus jamais s’écrire comme du pricing de marché.' },
  { id: 'dtpu-20260913-taux-en-direct', ts: Date.UTC(2026, 8, 13, 20, 0), title: 'Onglet TAUX : le taux affiché suit la dernière décision réelle, et chaque carte dit sa source', desc: 'Un abonné nous l’a signalé, données de marché en main : la carte RBNZ affichait un taux actuel de 2,2500% alors que la banque l’a porté à 2,50% début juillet. L’audit complet du circuit des taux qui a suivi corrige la valeur, et surtout le mécanisme : le taux affiché de chaque banque centrale est désormais recalé automatiquement, plusieurs fois par heure, sur la dernière décision réellement publiée au calendrier économique. Une valeur qui ne coïncide pas avec cette dernière décision est refusée, y compris quand elle sort de nos propres mémoires internes. Le badge de chaque carte devient aussi plus bavard au survol : côté pricing de marché, il donne l’heure de la dernière donnée reçue ; côté estimation du desk, il explique pourquoi le marché n’est pas disponible pour cette banque. Pour la RBNZ et la BNS, la raison est simple et vérifiée : notre fournisseur réserve ces deux banques à son offre payante. Le desk est techniquement prêt si nous choisissons de nous y abonner ; en attendant, leur estimation reste calée sur les décisions officielles.' },
  { id: 'dtpu-20260913-macro-separee', ts: Date.UTC(2026, 8, 13, 18, 0), title: 'Le Récap Hebdo sépare ses catégories macro partout, anciens rapports compris', desc: 'Vous nous l’avez signalé, capture à l’appui : malgré la nouvelle grammaire, un rapport hebdo affichait encore le bloc fusionné « Inflation & Croissance ». La première livraison séparait bien les rubriques des NOUVEAUX rapports, mais laissait aux rapports déjà écrits leur ancien bloc, simplement remis en ordre. C’est corrigé, et plus profondément : le desk ÉCLATE désormais ce bloc au moment d’afficher, puce par puce. Une décision de banque centrale rejoint « Banque centrale », le PCE rejoint « Inflation », le PIB rejoint « Croissance économique », les chiffres de payrolls rejoignent « Emploi » ; une puce vraiment inclassable rejoint « Autres chiffres de la semaine », en fin de section, plutôt que d’être perdue ; et une rubrique recréée fusionne avec l’existante (jamais deux « Inflation » l’une sous l’autre). Aucun rapport n’est réécrit : c’est l’affichage qui range, donc les archives comme l’édition de la semaine en cours en profitent immédiatement, et le cas exact de votre capture est rejoué à chaque livraison par un contrôle automatique. DEUX RUBRIQUES QUI MANQUAIENT ENTIÈREMENT reviennent aussi : « Emploi » ressort de l’éclatement, et « Banque centrale » est RECONSTITUÉE sur les anciens rapports : leur matière (postures, propos et décisions des banques) existait mais ne s’affichait nulle part dans la macro ; elle revient en tête de section, une puce par banque intervenue, sans jamais faire doublon avec les nouveaux rapports qui la portent nativement.' },
  { id: 'dtpu-20260913-molette-retour', ts: Date.UTC(2026, 8, 13, 16, 0), title: 'La molette revient en arrière sur la barre d’onglets, même sur les Chrome les plus récents', desc: 'Attrapé par notre nouvelle garde de déploiement, avant que quiconque ne le vive : sur les versions les plus récentes de Chrome, une fois la barre d’onglets de Mon Desk parcourue jusqu’au bout à la molette, impossible de revenir en arrière : la rangée restait collée à sa butée, chaque cran arrière tombait dans le vide. La cause est un détail d’arithmétique de navigateur : les Chrome récents mesurent la position de défilement au centième de pixel, et le calcul du desk, en comparant cette position fractionnaire à des largeurs entières, visait un « onglet précédent » situé à un dixième de pixel de là où il se trouvait déjà. Le calcul tolère désormais l’écart et vise toujours un vrai bord d’onglet, dans les deux sens, sur les anciens navigateurs comme sur les nouveaux. Le cas exact, chiffres du diagnostic compris, est rejoué à chaque livraison, et la garde qui l’a trouvé fait maintenant partie du chemin de mise en production : chaque version passe l’intégralité des contrôles du desk, sur un navigateur indépendant, avant d’avoir le droit de partir.' },
  { id: 'dtpu-20260913-archives-3-mois', ts: Date.UTC(2026, 8, 13, 14, 0), title: 'L’onglet Analystes garde trois mois d’archives, et c’est désormais garanti', desc: 'Vous nous l’avez demandé : tous les récaps de l’onglet Analystes doivent rester consultables pendant trois mois. Vérification faite de bout en bout, la promesse tenait déjà presque partout : récaps de séance, Récap Quotidien, Récap Hebdo, Global Economic Weekly et notes d’institutions sont conservés quatre-vingt-dix jours, redémarrages du serveur compris. Deux maillons, en revanche, coupaient plus court. La liste des notes « FX Daily » s’arrêtait à trente entrées, environ six semaines, alors que la réserve en garde bien trois mois : elle affiche désormais toute la fenêtre. Et la fenêtre de rechargement après un redémarrage était calculée trop juste pour trois mois pleins de rapports quotidiens : elle a pris de la marge. LE POINT IMPORTANT : la rétention est une chaîne (la collecte, la mémoire, la sauvegarde, le service, l’affichage) et c’est toujours le maillon le plus court qui décide de ce que vous voyez. Ce défaut-là a déjà mordu par le passé : un plafond oublié écrêtait des rapports que le stockage conservait pourtant. Un contrôle automatique mesure donc désormais CHAQUE maillon de la chaîne à chaque livraison : en resserrer un seul fait échouer la vérification, l’élargir passe. Trois mois, c’est trois mois.' },
  { id: 'dtpu-20260913-cibles-mortes', ts: Date.UTC(2026, 8, 13, 12, 0), title: 'Trois zones qui ignoraient le clic répondent enfin : la case de recherche, les champs, la croix', desc: 'Un audit complet du desk, mené dans un vrai navigateur en mesurant chaque clic, a relevé trois endroits où l’écran promettait plus que la souris n’obtenait. LA CASE « RECHERCHER DES SYMBOLES » de la barre du haut ne répondait que sur une mince bande médiane : un clic sur la loupe (le geste le plus naturel) ou près des bords ne posait pas le curseur, et rien ne signalait pourquoi. La zone de saisie épouse désormais toute la case, loupe comprise ; les cases de recherche du calendrier, des analystes et des institutions reçoivent la même correction. LES CHAMPS DE RECHERCHE des onglets INSTITUTIONS et ANALYSTES pouvaient se faire écraser par leurs propres filtres : sur un écran de portable, celui d’INSTITUTIONS tombait à zéro pixel (le cadre et la loupe restaient visibles, mais on ne pouvait ni cliquer ni taper) ; dans une carte étroite, celui d’ANALYSTES se réduisait à un moignon dont la zone de saisie débordait hors de la carte. Les filtres cèdent maintenant l’espace avant d’étouffer la recherche, qui garde toujours une taille utilisable ou descend sur sa propre ligne. ET LA CROIX « RETIRER » d’un sous-widget de panneau à onglets était recouverte à moitié par la zone invisible qui sert à élargir la carte : un clic au centre ne faisait rien, il fallait viser le bord gauche sans le savoir. Un bouton visible passe désormais toujours devant une zone de saisie invisible. Chacune des trois réparations est éprouvée à chaque livraison, au clic, dans un vrai navigateur.' },
  { id: 'dtpu-20260913-tout-francais', ts: Date.UTC(2026, 8, 13, 10, 0), title: 'La chasse aux derniers mots anglais : page publique, tags, menus et badges', desc: 'Le même audit a passé le desk au peigne fin sur la langue, et six restes d’anglais sont tombés d’un coup. LA PAGE PUBLIQUE « SEMAINE À VENIR » (celle que vous pouvez partager sans compte) affichait ses titres de panneaux, ses jours, ses mois, ses badges d’impact et ses boutons en anglais, alors que le desk rend exactement les mêmes cartes en français : elle parle désormais la même langue que le terminal, jusqu’au calendrier (« LUN 24 AOÛT, IMPACT ÉLEVÉ, Lire la suite »). LES TAGS D’UN RAPPORT ouvert dans l’onglet ANALYSTES restaient en anglais (« Geopolitical », « Oil ») quand le fil traduit les mêmes notions deux clics plus haut : ils sont maintenant traduits par la même table, et un tag inconnu reste tel quel plutôt que d’être mal traduit. LE MENU DE RECHERCHE DE SYMBOLE titrait « Recent Searches » et « Foreign Exchange » : il dit « Recherches récentes » et « Paires de devises », et chaque paire s’écrit par ses codes (EUR / USD), la règle que vous nous avez demandée. La colonne « Seasonal » de LISTE FX devient « Saisonnalité », comme partout ailleurs. Le bouton « Masquer Insights » du lecteur de rapport parlait anglais du bloc qu’il commande, « Éclairages desk » : il dit désormais « Masquer les éclairages ». Et le badge de ton d’une banque centrale dans le Décryptage du calendrier disait « Hawkish / Dovish » quand le Radar de Biais dit « Restrictive / Accommodante » pour la même banque : il dit maintenant « Restrictif / Accommodant ».' },
  { id: 'dtpu-20260913-typo-reglee', ts: Date.UTC(2026, 8, 13, 8, 0), title: 'Typographie : le pourcent colle à son chiffre partout, le tiret long disparaît pour de bon', desc: 'Deux règles que vous avez fixées, appliquées jusque dans les recoins que l’audit a débusqués. LE POURCENT D’ABORD : dix widgets de la bibliothèque (Différentiel de taux, Variations quotidiennes, Fréquence d’amplitude, Statistiques de volatilité et six autres) glissaient encore une espace entre le chiffre et son signe pourcent, quand tout le reste du desk les colle. La faute était invisible aux contrôles habituels : le chiffre n’existe qu’au moment de l’affichage, pas dans le texte du code. Les trente-neuf points d’écriture sont collés, et un contrôle automatique interdit désormais la forme elle-même, celle qui fabriquait l’espace à l’exécution. LE TIRET LONG ENSUITE : le caractère « cadratin », que vous avez banni du desk, vivait encore à deux endroits. Dans le panneau Parrainages, sur un libellé de bouton. Et surtout dans ce fil Nouveautés lui-même : plus de cent trente annonces déjà publiées en portaient, le chemin qui les sert étant le seul à ne pas appliquer le nettoyage. C’est corrigé à la sortie : toutes les annonces, y compris les anciennes, s’affichent désormais nettoyées, et une annonce neuve qui tenterait d’en glisser un est refusée avant même d’être publiée.' },
  { id: 'dtpu-20260912-discours-apres', ts: Date.UTC(2026, 8, 12, 20, 0), title: 'La fiche d’un discours vit aussi APRÈS : le ton et les propos, dès qu’ils tombent', desc: 'Demande d’un membre, exemple à l’appui, un discours de la Fed : la fiche du calendrier préparait bien le terrain AVANT une prise de parole, avec les derniers propos de l’intervenant et leur ton mesuré. Mais une fois le discours tenu, elle continuait de montrer… l’avant. Ce que l’intervenant venait de dire, c’est-à-dire la seule chose qui compte alors, celle qui oriente la devise et la prochaine réunion, restait à chercher soi-même dans le fil. DÉSORMAIS LA FICHE BASCULE D’ELLE-MÊME. Le discours passé, elle partage les propos autour de son heure, exactement comme la fiche d’une réunion s’organise autour de la décision : « Ton du discours » (restrictif, accommodant ou neutre), lu sur les citations du discours lui-même ; « Propos du discours », les déclarations les plus fortes relayées par les agences ; et « Avant ce discours », gardé en une ligne pour mesurer le chemin parcouru. Si rien n’a encore été relayé, la fiche le dit en toutes lettres et se met à jour d’elle-même dès les premières citations : généralement dans l’heure qui suit la prise de parole. Rien n’est généré ni deviné : uniquement des propos réellement relayés, datés et attribués.' },
  { id: 'dtpu-20260912-hebdo-grammaire', ts: Date.UTC(2026, 8, 12, 18, 0), title: 'Le Récap Hebdo range sa macro comme les récaps quotidiens', desc: 'Deux demandes, une même idée : le desk doit parler UNE seule grammaire. La section « Points Macro Clés » du Récap Hebdo rangeait avec des thèmes à elle (un bloc fusionné « Inflation & Croissance », une rubrique « Performance Cross-Asset ») quand les récaps quotidiens classent depuis toujours par « Banque centrale », « Inflation », « Croissance économique », « Emploi ». C’est désormais le même rangement, dans le même ordre : Banque centrale d’abord (les décisions de taux et les propos d’officiels, qui manquaient à l’appel), puis Inflation, Croissance économique, Emploi, et enfin Commerce International & Tarifs puis Technologie & Innovation. « Performance Cross-Asset » disparaît : les mouvements de pur marché (actions, rendements, or, pétrole) vivent déjà dans la synthèse et dans les blocs devises, pas besoin de les lire deux fois. LE POINT QUI CHANGE TOUT : le rangement est appliqué au moment d’AFFICHER, pas seulement demandé au rédacteur. Les rapports déjà archivés, écrits avec l’ancienne grammaire, profitent donc du même ordre et du même ménage, sans être réécrits. Et un thème que le desk ne reconnaît pas passe en fin de section, jamais à la poubelle : le doute profite toujours au contenu.' },
  { id: 'dtpu-20260912-force-discrete', ts: Date.UTC(2026, 8, 12, 16, 0), title: 'Force des Devises se met à jour sans se faire remarquer', desc: 'Vous nous l’avez signalé : régulièrement, le widget Force des Devises rejouait son ouverture (voile de chargement, huit courbes qui repoussent depuis zéro) comme si le desk venait de démarrer. Rien n’était cassé : le widget se reconstruit souvent pour rester frais (relevé toutes les cinq minutes, retour sur l’onglet, période recalée sur le compte), et chaque reconstruction déclenchait l’animation prévue pour la PREMIÈRE apparition. Une simple remise à jour se transformait en spectacle, et un spectacle répété devient un clignotement. L’animation d’entrée ne joue plus qu’une fois, à la première construction du graphique. Ensuite, les reconstructions peignent directement les nouvelles valeurs : les chiffres bougent, le widget, lui, ne bronche plus.' },
  { id: 'dtpu-20260912-panneau-retouches', ts: Date.UTC(2026, 8, 12, 14, 0), title: 'Série de retouches : tags accordés, panneau allégé, cadre complet, un seul ascenseur', desc: 'Cinq finitions demandées captures à l’appui, livrées ensemble. LE TAG DE L’INDICATEUR (« PIB », « IPC »…) prend le même fond que les autres tags de sa ligne : sur une publication majeure, son fond sombre se lisait comme une pastille d’une autre famille. Et le tag de la devise disparaît quand la paire l’annonce déjà : « USDCAD » porte CAD dans son nom, inutile de le répéter juste à côté. LE PANNEAU D’UNE DONNÉE dépliée perd sa section « Banque centrale » : propos, tons et réunion y faisaient double emploi avec la fiche du calendrier, qui reste l’endroit du décryptage complet. LA LIGNE EN COURS DU CALENDRIER retrouve son cadre doré COMPLET : le trait du haut perdait systématiquement contre le séparateur de la ligne précédente, et les côtés n’existaient pas ; le cadre se peint désormais d’une façon qui s’affiche toujours, sur les quatre bords. « INDICES & MATIÈRES » ne montre plus qu’UN ascenseur : le corps de la carte défilait en même temps que la liste interne, deux barres côte à côte pour le même contenu ; seule la liste garde la sienne. Dernier détail, au Récap Hebdo : « Chronologie rapide » s’appelle sobrement « Chronologie », et le sujet affiché à sa droite reprend la même taille que le titre qu’il complète.' },
  { id: 'dtpu-20260912-traductions-fil', ts: Date.UTC(2026, 8, 12, 12, 0), title: 'Traduction du fil : le rythme suit enfin le volume des dépêches', desc: 'Signalé capture à l’appui : quelques lignes du fil s’affichaient encore en anglais. La chaîne de traduction a été vérifiée maillon par maillon (détection, traduction, mise en cache, affichage), et elle fait son travail ; mais son débit était plafonné à trois cents titres par jour, un réglage taillé pour un fil plus calme. Une journée chargée pouvait donc finir en langue source, le temps que les cycles suivants rattrapent. Le débit est TRIPLÉ : neuf cents titres par jour, par lots plus larges, de quoi absorber les journées les plus denses avec de la marge. Et la dépense reste tenue : un titre coûte une poignée de jetons, la tâche tourne en fond et se coupe d’office bien avant d’entamer le budget des analyses du desk. Les lignes restées en anglais se rattrapent d’elles-mêmes au fil des cycles suivants.' },
  { id: 'dtpu-20260911-fil-perimetre', ts: Date.UTC(2026, 8, 11, 10, 0), title: 'Le fil reste sur les devises tradées, et le NFP retrouve son rang', desc: 'Deux corrections signalées par le desk. D’abord, une statistique d’un pays hors de nos devises — un taux de chômage chilien, une inflation turque — pouvait occuper une ligne du fil : ces publications sont désormais écartées à l’entrée. La règle est étroite exprès : elle exige un pays identifié en tête de titre ET la forme d’une publication chiffrée, si bien que la géopolitique de ces mêmes pays (une frappe, des sanctions, les céréales ukrainiennes) reste dans le fil — c’est la statistique qui part, jamais l’événement. Ensuite, la révision annuelle des payrolls américains est sortie en simple « commentaire économique », sans rouge ni tags : les indicateurs au nom proprement américain — NFP, ISM, JOLTS, ADP — sont maintenant reconnus comme données US même quand le titre n’écrit pas « US », et la révision des payrolls rejoint le premier rang, celui qui colore la ligne en rouge et ouvre l’analyse. Au passage, un défaut ancien : « Nonfarm Payrolls » au pluriel n’était jamais reconnu comme majeur — une frontière de mot refusait le « s » final.' },
  { id: 'dtpu-20260911-pricing-source', ts: Date.UTC(2026, 8, 11, 8, 0), title: 'Pricing de taux : chaque carte dit sa source, et la RBNZ retrouve ses vrais chiffres', desc: 'Un membre nous a signalé, preuves en main, que la carte RBNZ contredisait le marché — et il avait raison, merci à lui. Sur huit banques centrales, six affichent un vrai pricing de marché (probabilités implicites des instruments de taux) ; pour la RBNZ et la BNS, notre fournisseur ne le publie pas, et le desk affichait à la place une estimation interne SANS le dire. Pire : une mise à jour automatique avait inversé le sens de cette estimation et abaissé le taux affiché, si bien que la carte montrait une baisse probable là où le marché price une hausse. Quatre corrections. Chaque carte de l’onglet TAUX porte désormais sa source, écrite dessus : « pricing marché » ou « estimation DTP » — même chose dans le Radar de Biais et les récaps, qui ne disent plus « le marché price » quand c’est le modèle. L’estimation ne peut plus contredire la configuration vérifiée à la main sur les communiqués des banques. Un taux mis à jour automatiquement doit désormais coïncider avec une décision réelle du calendrier avant d’être affiché. Et la probabilité en tête de carte est celle du mouvement affiché — fini le « Hausse · 50% » où 50% était en réalité la probabilité du maintien.' },
  { id: 'dtpu-20260910-onglets-parcours', ts: Date.UTC(2026, 8, 10, 23, 45), title: 'La barre d’onglets de Mon Desk se parcourt enfin en entier', desc: 'Sur le modèle par défaut, le panneau à onglets en porte neuf — ACTUS, CALENDRIER, LISTE FX, INSTITUTIONS… — qui réclament deux fois la largeur de la carte. Six restaient hors champ, deux se cachaient sous les boutons de la carte (invisibles, et surtout impossibles à cliquer), et la rangée s’arrêtait en plein mot : on lisait « TUTIONS » à la place d’« INSTITUTIONS ». Trois changements : la place des boutons est désormais mesurée sur les boutons eux-mêmes, si bien qu’aucun onglet ne passe plus dessous ; la molette parcourt la rangée d’un onglet à la fois, en s’arrêtant toujours sur un nom entier ; et un dégradé, à gauche comme à droite, signale qu’il reste des onglets de ce côté. Tous les onglets sont donc atteignables à la souris, ce qui n’était pas le cas.' },
  { id: 'dtpu-20260910-barre-fantome', ts: Date.UTC(2026, 8, 10, 21, 45), title: 'La barre de défilement qui ne menait nulle part a disparu', desc: 'Signalé sur capture : sous la carte « Semaine à Venir » de Mon Desk, une barre de défilement horizontale ne servait à rien — tirée à fond, elle ne découvrait que du vide, et elle rognait au passage le bas de la carte. La cause ne venait pas du widget : un halo doré décoratif, posé derrière chaque vue pour lui donner de la profondeur, avait une largeur figée de 820 pixels. Sur le desk en plein écran il ne se voit ni ne gêne ; dans une carte de 460 pixels, il agrandissait la zone défilable de près de 400 pixels de vide. Le halo s’ajuste désormais à son panneau, et garde exactement sa taille d’avant partout où il se voit. La barre disparaît sur toutes les vues et à toutes les largeurs, sur ordinateur comme sur téléphone.' },
  { id: 'dtpu-20260910-pourcent-partout', ts: Date.UTC(2026, 8, 10, 19, 45), title: 'Le pourcent colle à son chiffre, sur le desk comme sur le site', desc: 'Vous nous l’aviez signalé : le desk glissait une espace entre le chiffre et son signe pourcent, là où vous voulez lire « 2,4% » d’un bloc. Cette espace vient de la typographie française, que les modèles appliquent à la lettre — d’où ce petit air de texte de machine à chaque chiffre. Elle disparaît partout d’un coup : aides des widgets, réglages de la calculatrice, récaps de séance, Quotidien et Hebdo, chat macro, e-mails, pages de documentation et démonstration du site. Et elle ne reviendra pas : tout texte écrit par l’IA passe désormais par un filtre commun à tous nos moteurs, et un contrôle relit l’ensemble du produit avant chaque livraison.' },
  { id: 'dtpu-20260910-devises-en-codes', ts: Date.UTC(2026, 8, 10, 17, 45), title: 'Les devises s’écrivent par leur code : USD, CAD, NZD', desc: 'Demande du desk : dans les récaps de séance et les rapports Quotidien / Hebdo, « le dollar américain » occupait la place d’un simple USD. Les noms de devises sont désormais rendus par leur code, article compris — « l’USD », « de l’USD », « le CAD », « du JPY », « au CHF ». Un « dollar » seul, sans pays, reste écrit en toutes lettres : sur un desk il désigne presque toujours l’USD, mais presque ne suffit pas pour afficher un code faux.' },
  { id: 'dtpu-20260910-synthese-sans-couleur', ts: Date.UTC(2026, 8, 10, 15, 45), title: 'La synthèse d’un récap ne se colorie plus', desc: 'Signalé sur capture : dans la synthèse d’un récap de séance, le 10 de « rendements à 10 ans » ressortait en rouge, comme s’il s’agissait d’un verdict de marché. La coloration est faite pour une puce de donnée, où le chiffre coloré EST la valeur publiée ; appliquée à un paragraphe de prose, elle attrape n’importe quel nombre. Les synthèses n’ont plus de couleur. Les puces gardent la leur.' },
  { id: 'dtpu-20260910-sources-titres', ts: Date.UTC(2026, 8, 10, 13, 45), title: 'Le nom du média disparaît de la fin des titres', desc: 'Signalé sur capture : « … plusieurs explosions dans la capitale syrienne - Tasnim News. » Le desk retirait déjà ces attributions, mais à partir d’une liste de noms exacts — et l’agence y figurait sous « Tasnim », pas « Tasnim News ». Une liste est toujours en retard d’un média. Le desk reconnaît désormais une attribution à sa forme, pas à son nom.' },
  { id: 'dtpu-20260910-bruit-nominations', ts: Date.UTC(2026, 8, 10, 11, 45), title: 'Les nominations d’état-major quittent le fil', desc: 'Signalé sur capture : une annonce de nomination à la Maison Blanche — secrétaire général, conseiller — occupait une ligne du fil, à la première personne et sans qu’on sache de qui elle était. Aucune portée sur une paire de devises. Ces lignes sont désormais écartées à l’arrivée. Les nominations qui COMPTENT restent, elles : présidence de la Fed, Trésor, gouverneur de banque centrale, ministre des Finances.' },
  { id: 'dtpu-20260910-audit-traductions', ts: Date.UTC(2026, 8, 10, 9, 45), title: 'Six traductions mortes réparées, dont le titre du fil', desc: 'Pour nos lecteurs en anglais, allemand et espagnol : six libellés étaient restés en français, dont « Fil d’actualité », le titre du panneau des actualités. Le desk était passé du tutoiement au vouvoiement sans que les dictionnaires suivent. C’est réparé, et un contrôle automatique empêche désormais qu’une traduction meure en silence.' },
  { id: 'dtpu-20260910-apercu-alertes', ts: Date.UTC(2026, 8, 10, 23, 0), title: 'Les alertes ne se coupent plus au milieu d’un mot', desc: 'Dans le panneau ALERTES, les aperçus s’arrêtaient net : « Pas de mess », « Vérification f ». Ils s’arrêtent désormais sur une phrase entière quand il y en a une, sinon sur le dernier mot complet, suivi de points de suspension. Une citation ouverte par la coupe est refermée.' },
  { id: 'dtpu-20260910-pourcent-colle', ts: Date.UTC(2026, 8, 10, 23, 30), title: 'Le pourcent est collé à son nombre', desc: 'L’espace qui séparait un nombre du signe pourcent disparaît : le chiffre et son unité se lisent désormais d’un bloc, partout sur le desk. C’est un écart assumé à la typographie française, qui veut cette espace. La règle vaut pour les chiffres calculés comme pour les textes rédigés par le desk.' },
  { id: 'dtpu-20260910-propos-bc-fr', ts: Date.UTC(2026, 8, 10, 22, 0), title: 'Les propos des banquiers centraux s’affichent enfin en français', desc: 'Signalé sur capture : dans la fiche d’une banque centrale, la rubrique DERNIERS PROPOS listait les déclarations en anglais. « No central bank would seek to adjust degree of financial accommodation by shocking markets » — au milieu d’un panneau en français. LA TRADUCTION ÉTAIT DÉJÀ BRANCHÉE, ELLE PERDAIT LA COURSE. La fiche demandait la traduction au moment où vous l’ouvriez : les lignes sont masquées, et si la réponse tarde de plus de deux secondes et demie, le desk renonce, révèle l’anglais et le FIGE. La traduction revenue ensuite était reçue et jetée en silence. C’est exactement le défaut déjà corrigé sur le panneau Info d’une actualité, et la réponse est la même : ne plus rien demander à l’ouverture, servir ce qui est déjà prêt. CES PROPOS SONT DÉJÀ TRADUITS EN TÂCHE DE FOND, bien avant que vous n’ouvriez la fiche — ils le sont pour le panneau Info depuis plusieurs jours. La fiche ne les recevait tout simplement pas : elle demandait la déclaration d’origine et rien d’autre. Elle reçoit maintenant les deux, et affiche le français dès la première milliseconde. Si un propos vient d’arriver et n’a pas encore été préparé, la traduction à la volée reste là en dernier recours : rien n’est perdu, on a simplement cessé de compter dessus. UN DÉTAIL QUI AURAIT COÛTÉ CHER. Le ton d’un discours — le badge HAWKISH, DOVISH ou NEUTRE, et la ligne de lecture qui l’accompagne — est reconnu par des mots-clés ANGLAIS dans la déclaration. Remplacer purement et simplement le texte par sa traduction aurait rendu ce badge muet : le panneau aurait gagné des propos lisibles et perdu sa lecture de posture. Le desk analyse donc la version d’origine et n’affiche que le français. Un contrôle automatique le vérifie dans les deux sens à chaque livraison — la version anglaise doit déclencher la détection, sa traduction ne doit pas. AU PASSAGE, UN COMMENTAIRE QUI MENTAIT. Le code portait encore, à cet endroit, la mention « propos jamais traduits » alors que leur traduction avait été demandée et branchée trois mois plus tôt. Un commentaire périmé a l’autorité du code sans en avoir la vérité : celui-ci a bien failli faire refuser une demande parfaitement légitime. Il est corrigé, et un contrôle interdit qu’il revienne.' },
  { id: 'dtpu-20260910-titres-francais', ts: Date.UTC(2026, 8, 10, 20, 0), title: 'Les titres du fil passent en français', desc: 'Signalé sur capture : une dépêche géopolitique s’affichait EN ANGLAIS dans le fil — « Chinese executives may join Xi’s US trip… » — au milieu d’un desk qui est en français partout ailleurs. LE MÉCANISME EXISTAIT, IL ÉTAIT SIMPLEMENT TROP ÉTROIT. Le desk prépare déjà ses traductions en tâche de fond, pour ne rien vous faire attendre à l’ouverture. Deux cycles tournaient : l’un traduit la DESCRIPTION d’une actualité — ce que vous lisez quand vous la dépliez — l’autre traduit les TITRES, mais uniquement ceux des prises de parole des responsables. Le titre d’une dépêche ordinaire n’était traduit NULLE PART. Résultat : du français dès que vous ouvriez une actualité, et de l’anglais tant que vous ne l’ouvriez pas — c’est-à-dire dans le fil, qui est précisément ce qu’on regarde le plus. LES TITRES DU FIL SONT DÉSORMAIS PRÉPARÉS EUX AUSSI. Le budget ne bouge pas d’un pouce : même plafond quotidien, même débit, même priorité de fond qui cède devant tout le reste, même cache. Un titre est court, un lot en coûte une fraction de ce que coûte le même nombre de descriptions. Ce qui change, c’est l’ORDRE : les actualités importantes passent en premier, comme pour les descriptions. Si le quota d’une journée s’épuise en route, ce sont les dépêches qui comptent qui auront été traduites, pas celles qui se trouvaient en tête de liste. TROIS PRÉCAUTIONS, parce qu’une traduction mal posée est pire qu’un texte en anglais. Les prises de parole gardent leur propre traitement : leur titre est débarrassé du nom du locuteur pour le panneau, et ce texte-là ne doit surtout pas remplacer la ligne du fil — sans quoi « BoE’s Mann : » disparaîtrait. Les rapports écrits par le desk sont écartés : ils sont déjà en français, les traduire reviendrait à payer pour les abîmer. Et une traduction qui ÉCHOUE n’est jamais enregistrée : notre outil renvoie le texte d’origine quand il n’a pas pu traduire, et le retenir figerait l’anglais pour toujours sur cette ligne, qui ne serait plus jamais retentée. ENFIN, RIEN NE BOUGE SOUS VOS YEUX. Une traduction qui arrive pendant que vous lisez une actualité ouverte est mise en réserve et n’est posée qu’à la fermeture du dernier panneau. Tant qu’elle n’est pas là, le titre d’origine reste affiché : jamais de ligne vide, jamais d’attente.' },
  { id: 'dtpu-20260910-impact-clic-mort', ts: Date.UTC(2026, 8, 10, 18, 0), title: 'Le bouton « Impact marché » qui ne s’ouvrait pas est réparé', desc: 'Signalé capture à l’appui : sur une dépêche géopolitique, le bouton « Impact marché » était bien là, et le clic ne faisait RIEN. Pas de message, pas d’erreur, pas de panneau — rien. Le défaut est reproduit, compris et corrigé. LA CAUSE TIENT EN UNE CONDITION. Le panneau qui se déplie sous une actualité — celui que partagent Info, Analyse, Réaction et Impact marché — n’était fabriqué que si l’actualité portait une description, une analyse ou une donnée économique. « Impact marché » ne figurait pas dans cette liste. Or une dépêche géopolitique porte souvent une lecture d’impact ET RIEN D’AUTRE : elle recevait donc un bouton parfaitement cliquable, et aucun panneau derrière pour l’accueillir. Le clic était avalé en silence. CE QUI REND CE DÉFAUT PARTICULIÈREMENT DÉSAGRÉABLE, c’est qu’il ne ressemble pas à une panne : rien ne clignote, rien ne s’affiche en rouge, la console reste muette. Le lecteur clique deux fois, trois fois, et finit par se dire que le desk ne marche pas. C’est exactement ce qu’un client a vécu. ET IL ÉTAIT DÉJÀ CONNU — RÉPARÉ À UN SEUL ENDROIT. Le bouton « Réaction » portait depuis longtemps son propre rattrapage pour ce même cas. Un rattrapage écrit dans un bouton ne protège que ce bouton : le suivant retombe dans le trou, et c’est précisément ce qui est arrivé. La fabrication du panneau passe désormais par UN seul point que tous les boutons appellent — un bouton ajouté demain ne pourra plus oublier son panneau. Un contrôle automatique refuse d’ailleurs qu’on en fabrique un ailleurs. LE CHEVRON AUSSI. Ouvrir le panneau à ces actualités fait apparaître le petit chevron à leur gauche : il vise maintenant la lecture d’impact. Sans cette précision, il aurait visé un onglet inexistant et on aurait simplement déplacé le clic mort au lieu de le supprimer. Les deux chemins — le bouton et le chevron — sont désormais éprouvés à chaque livraison, sur une dépêche géopolitique dépouillée, celle-là même de la capture.' },
  { id: 'dtpu-20260910-indices-matieres', ts: Date.UTC(2026, 8, 10, 16, 0), title: 'Le desk sort du forex : un nouveau widget « Indices & Matières »', desc: 'Retour d’un client, transmis tel quel : « rajoute les indices et plus de marché avant, que le forex c’est frustrant de ouf ». Vérification faite avant d’écrire la moindre ligne, et il avait raison au pied de la lettre : LES QUINZE WIDGETS des rubriques Marchés et Devises parlaient de change, et uniquement de change — Carte de chaleur FX, Taux croisés, Corrélations des sept majeures, Performance hebdo des huit devises. Le desk balayait l’intégralité du forex et rien d’autre. UN NOUVEAU WIDGET, dans la rubrique Marchés : quatre indices actions — DAX 40, S&P 500, FTSE 100, CAC 40 — et trois matières premières — Or, Argent, Pétrole WTI. Pour chacun, DEUX horizons côte à côte : la variation de sa dernière séance cotée, et celle de la semaine depuis lundi. Les deux ensemble, parce qu’une séance isolée est du bruit et qu’une semaine seule rate le retournement du jour. La barre reprend exactement la grammaire de Performance hebdo : axe au centre, vert à droite, rouge à gauche. Rien de nouveau à apprendre pour la lire. CES PLACES N’OUVRENT PAS AUX MÊMES HEURES, et la carte en tient compte : quand New York cote, Francfort et Paris sont fermés depuis des heures, et le week-end aucune ne cote. Chaque ligne se compare donc à SA propre clôture précédente, jamais à une heure d’horloge commune — une place fermée garde la variation de sa dernière séance, ce qui reste l’information juste. Prendre « la bougie d’aujourd’hui » aurait vidé la moitié de la carte selon l’heure à laquelle on la regarde. L’ÉCHELLE DES BARRES EST COMMUNE à toute la carte : le pétrole bouge structurellement plus qu’un indice, et c’est précisément ce que la carte doit montrer. Une barre normalisée ligne par ligne aurait donné sept barres pleines et n’aurait rien appris. CE QUE ÇA OUVRE COMME LECTURE : un dollar qui monte pendant que l’or monte AUSSI ne raconte pas la même histoire qu’un dollar qui monte pendant que l’or baisse. Le premier sent la fuite vers la qualité, le second le simple différentiel de taux. C’est exactement ce qui manquait au change lu seul. AUCUNE SOURCE NOUVELLE : ces sept instruments alimentaient déjà le sélecteur du widget Graphique, par la même route que les paires de devises. Il ne manquait pas de données, il manquait un endroit pour les lire ensemble. La semaine est calculée par le MÊME code que Performance hebdo, jamais par une seconde copie : les deux cartes ne peuvent pas afficher deux chiffres différents pour la même chose. Sur une carte étroite, c’est la colonne de la semaine qui s’efface — la moins urgente — et jamais le nom, la barre ou la variation du jour.' },
  { id: 'dtpu-20260910-poignee-elargir', ts: Date.UTC(2026, 8, 10, 14, 0), title: 'Élargir un widget : le repère se voit enfin là où le curseur le promet', desc: 'Retour d’un client, capture à l’appui : « regarde moi ce curseur n’est pas précis, je comprends pas ». Il avait raison, et voici ce qui se passait. Le bord droit d’un widget se tire pour l’élargir : en approchant le pointeur, il devient une double flèche. CETTE ZONE COURT SUR TOUTE LA HAUTEUR DE LA CARTE — trois cent six pixels mesurés sur une carte ordinaire. Le petit repère doré qui la signalait, lui, ne faisait que vingt-six pixels, ET IL ÉTAIT CENTRÉ. Autrement dit : huit et demi pour cent de ce qu’on pouvait attraper était dessiné, et cent quarante pixels restaient aveugles au-dessus comme en dessous. On survolait le bord, le curseur annonçait « redimensionner », et la seule marque visible s’allumait jusqu’à cent quarante pixels plus loin. Rien n’était cassé — c’est précisément ce qui rendait le défaut déroutant : le geste fonctionnait là où l’œil ne voyait rien, et l’œil fixait une marque qui n’était pas sous la main. LE REPÈRE ÉPOUSE DÉSORMAIS LA ZONE, exactement : ce que vous voyez est ce que vous pouvez prendre. Il se lit en deux temps, parce que les deux moments n’ont pas le même sens — quand votre souris entre dans la carte, un rail discret le long du bord dit que ce bord se tire ; quand vous arrivez dessus, c’est-à-dire au moment même où la double flèche apparaît, le rail passe en or plein sur toute sa hauteur, sous votre pointeur. L’intensité du rail discret n’a pas été choisie au jugé : quatre valeurs ont été peintes côte à côte pour retenir celle qui se voit sans dessiner une seconde bordure le long de chaque carte. Au repos, rien n’est peint : le desk reste aussi net qu’avant. Et un contrôle automatique mesure désormais ce recouvrement à chaque livraison, sur une carte haute et sur une carte basse — le repère ne pourra plus se désolidariser de sa zone sans que ça se voie.' },
  { id: 'dtpu-20260910-impact-evenements', ts: Date.UTC(2026, 8, 10, 12, 0), title: 'Impact marché s’ouvre aux événements : décisions de banques centrales et géopolitique de premier rang', desc: 'Retour d’un client, transmis tel quel : « c’est un outil qui spot l’entièreté du forex c’est cool, mais les drivers sur marché ce n’est pas ça, et c’est dommage ». Il avait raison, et le défaut tenait à une seule condition. LA LECTURE « IMPACT MARCHÉ » N’ÉTAIT SERVIE QU’AUX STATISTIQUES CHIFFRÉES. Pour y avoir droit, une actualité devait porter dans son titre un chiffre ET son consensus — le format « 3,2% contre 3,1% attendu ». Autrement dit : une décision de taux, un compte rendu de banque centrale, une menace sur le détroit d’Ormuz, un embargo pétrolier — c’est-à-dire ce qui déplace réellement les marchés — n’en recevaient AUCUNE. Le desk savait lire la surprise d’un chiffre, pas l’événement qui fait le marché. UNE SECONDE PORTE S’OUVRE. Les décisions et communications des neuf grandes banques centrales, et la géopolitique de premier rang, reçoivent désormais leur lecture : le verdict, le canal par lequel l’événement atteint les marchés, et les actifs exposés avec leur direction. ET LA PREMIÈRE GARDE N’A PAS ÉTÉ SUPPRIMÉE POUR AUTANT — c’est le point important. L’exigence du consensus n’était pas une lubie : elle garantit que le desk a de quoi comparer et ne peut pas broder. La supprimer aurait rendu éligible n’importe quelle dépêche du fil, qui en compte plus de mille par jour. La seconde porte a donc sa propre garantie — un événement de premier rang, reconnu par les mêmes règles qui classent déjà les actualités en rouge — et surtout SA PROPRE CONSIGNE : elle dit au desk, en toutes lettres, qu’il n’a AUCUN chiffre, aucun consensus, aucune surprise à mesurer, et qu’il doit décrire le mécanisme à la place. Réclamer un écart à qui n’en a pas, c’est l’inviter à en inventer un. Un fait géopolitique est par ailleurs orienté vers l’énergie et les valeurs refuge plutôt que vers une paire de devises prise au hasard. Les plafonds de dépense, eux, ne bougent pas d’un pouce.' },
  { id: 'dtpu-20260910-orientation', ts: Date.UTC(2026, 8, 10, 10, 0), title: 'Politique monétaire : « Stance » devient « Orientation »', desc: 'Dans le panneau d’une devise, la ligne de politique monétaire s’intitulait « Stance actuelle ». Retour d’un lecteur : « j’comprends pas le terme Stance ». Il a raison — c’est de l’anglais. Le mot est courant dans les salles de marché anglophones, il ne l’est pas en français, et le terminal est en français partout ailleurs. Elle s’appelle désormais « Orientation actuelle », qui est le terme officiel employé par la Banque de France et par la BCE — « l’orientation de la politique monétaire ». Il a aussi l’avantage de s’accorder avec les valeurs déjà affichées : Accommodante, Restrictive, Neutre. « Ton » aurait été plus court, mais masculin : il aurait fallu réécrire les trois valeurs pour gagner deux lettres. La fiche détaillée d’une banque centrale suit le même changement, et les traductions anglaise, allemande et espagnole sont posées dans la foulée.' },
  { id: 'dtpu-20260910-topbar-mobile', ts: Date.UTC(2026, 8, 10, 8, 0), title: 'Sur téléphone, la barre du haut tient enfin sur une seule ligne', desc: 'Sous 400 pixels de large — c’est-à-dire sur la plupart des téléphones — la barre du haut se coupait en DEUX rangées : le logo et vos icônes personnelles en haut, les outils et la recherche en dessous. À l’écran, une première ligne avec un vide de cent soixante pixels au milieu, une seconde qui commençait ailleurs, et deux hauteurs différentes. Rien ne s’alignait avec rien, et la barre mangeait quatre-vingt-quatre pixels de hauteur sur un écran qui n’en a pas de trop. TOUT TIENT SUR UNE LIGNE, ET C’EST MESURÉ : sur un écran de 390 pixels, le logo, les trois outils, la recherche et les cinq icônes de droite occupent trois cent quarante-neuf pixels. Il en restait quarante de libres, et on dépensait une rangée entière. La barre passe de quatre-vingt-quatre à cinquante-deux pixels : trente-deux pixels rendus au terminal, sur chaque écran. CE QUI RENDAIT LA LIGNE IMPOSSIBLE : une règle d’affichage donnait à la recherche toute la largeur disponible, ce qui annulait la case compacte prévue pour le mobile. La recherche s’étalait sur près de trois cents pixels et poussait tout le reste à la ligne. Elle redevient une case-icône — et ne perd rien au passage, puisqu’elle se déplie déjà en pleine largeur au moment où vous la touchez. SUR LES ÉCRANS LES PLUS ÉTROITS, les outils et les icônes de droite se chevauchaient carrément — vingt-cinq pixels de recouvrement mesurés sous 360 pixels. Les deux groupes se resserrent ensemble, sans qu’aucune icône ne disparaisse ni ne passe sous le seuil de ce qu’un pouce peut viser. Un contrôle automatique ouvre désormais la VRAIE barre du haut dans un navigateur, à 390 et 360 pixels, et vérifie qu’elle tient sur une ligne, qu’elle ne se replie pas, que rien ne se chevauche, que la recherche reste compacte et que les icônes partagent la même ligne d’horizon.' },
  { id: 'dtpu-20260909-noms-widgets', ts: Date.UTC(2026, 8, 9, 23, 30), title: 'Les noms de widgets sont raccourcis : douze intitulés cessent de passer à la ligne', desc: 'Les noms s’affichent dans les cartes de la bibliothèque et en tête de chaque widget posé sur votre desk. Au-delà d’une vingtaine de caractères ils passaient sur deux lignes ou se faisaient couper — dix d’entre eux allaient de vingt-quatre à vingt-huit caractères. DOUZE INTITULÉS SONT RESSERRÉS, sans rien perdre de leur sens : « Compte à rebours d’événement » devient « Compte à rebours », « Corrélations entre paires » devient « Corrélations », « Calculatrice de position » devient « Calculatrice », « Performance de la semaine » devient « Performance hebdo », « Rendement moyen par mois » devient « Rendement mensuel », « Matrice de taux croisés » devient « Taux croisés ». Le plus long du catalogue passe de vingt-huit à vingt-trois caractères, et la moyenne de dix-neuf virgule sept à dix-sept virgule deux. DEUX NOMS EN PROFITENT POUR DEVENIR PLUS JUSTES : « Historique du Sentiment » devient « Historique du risque », qui dit ce qu’il montre et se lit en paire avec « Sentiment de Risque » ; « Probabilité de mouvement » devient « Atteinte d’un seuil », qui est exactement ce que la carte calcule. VOS DESKS NE BOUGENT PAS : les dispositions enregistrées désignent chaque widget par son identifiant, jamais par son nom. Rien à refaire, rien à replacer. Et un contrôle automatique mesure désormais TOUS les noms du catalogue à chaque livraison — pas seulement les douze corrigés : le treizième, ajouté plus tard, ne pourra pas rallonger la liste sans que ce soit un choix.' },
  { id: 'dtpu-20260909-rebours-lisible', ts: Date.UTC(2026, 8, 9, 23, 0), title: 'Compte à rebours d’événement : le nom de la publication se lit enfin, et les mentions grises passent le seuil', desc: 'Retour sur la carte du compte à rebours, capture à l’appui. Le chiffre du décompte était parfaitement visible ; tout le reste l’était beaucoup moins. TROIS TEXTES ÉTAIENT SOUS LE SEUIL DE LISIBILITÉ, et ce n’est pas une impression : mesuré, le gris employé donnait un contraste de 3,96 pour 1 sur le fond du desk, là où la norme demande 4,5 pour 1 sur du petit texte — et deux de ces trois textes étaient en 9,5 pixels. Ils passent sur le gris secondaire, à 7,35 pour 1, et gagnent un point de taille. Même correction en thème clair, qui était lui aussi juste en dessous. ET LE NOM DE LA PUBLICATION CESSE D’ÊTRE UNE LÉGENDE. C’est le sujet de la carte — ce qu’on attend, la raison du décompte — et il s’affichait en gris, plus petit que le reste. Il est désormais en blanc, à la taille du texte courant. CE QUI N’A PAS ÉTÉ TOUCHÉ : le gris éteint du desk lui-même. Il habille des centaines d’éléments, et le remonter pour régler une carte aurait déplacé la hiérarchie visuelle de tout le terminal. La correction reste là où était le problème.' },
  { id: 'dtpu-20260909-espacement-layout', ts: Date.UTC(2026, 8, 9, 22, 0), title: 'L’espacement du desk se règle là où vous choisissez votre disposition', desc: 'Le réglage « Espacés / Collés » décide de la respiration ENTRE vos widgets une fois posés : c’est une propriété de la DISPOSITION. Il vivait pourtant dans la bibliothèque de widgets, l’écran où l’on choisit QUELS widgets ajouter, coincé à côté des filtres par catégorie. On le trouve désormais dans « Mes layouts », au-dessus de la liste de vos dispositions, là où on le cherche. ET IL SE COMPORTE ENFIN CORRECTEMENT QUAND ON RESTE DEVANT. Basculer l’espacement resserrait bien le desk, mais ne rafraîchissait pas son propre bouton : « Espacés » restait allumé alors que « Collés » venait d’être appliqué. Le défaut ne se voyait pas tant que le réglage vivait dans la bibliothèque, qui recalculait cet état à chaque ouverture ; il devenait visible dès qu’on reste sur le panneau. Le bouton suit maintenant le clic. Un contrôle automatique garde les deux moitiés ensemble : déplacer le bloc sans déplacer le calcul de son état actif aurait ouvert le panneau avec deux boutons éteints — le réglage en place, et l’écran affirmant le contraire.' },
  { id: 'dtpu-20260909-programme-envois', ts: Date.UTC(2026, 8, 9, 20, 0), title: 'Programme des envois : un seul « prochain », et le témoignage annonce enfin lequel part', desc: 'Le panneau qui dit ce qui part et quand. Trois corrections, toutes venues de la même capture. DEUX « PROCHAINS » À L’ÉCRAN, DONT UN FAUX. La ligne du parrainage portait le mot « Prochain » et la mise en avant dorée SANS AUCUNE CONDITION — alors que sa date tombait dix-huit mois plus tard, juste au-dessus du vrai prochain envoi, doré lui aussi. Sur le seul écran qui sert à savoir ce qui part, deux lignes se déclaraient premières. La règle est maintenant celle que le mot veut dire : premier DANS LE TEMPS. Quand ce n’est pas pour tout de suite, la colonne dit l’attente — « dans 18 mois » — ce qui est justement l’information qu’on cherche à ce moment-là. Un envoi en retard, lui, reste mis en avant : là, c’est actionnable. LE TÉMOIGNAGE NE DISAIT PAS LEQUEL PARTAIT. Les lignes annonçaient « + Témoignage membre » sans plus, pendant que l’en-tête affirmait « Aucun témoignage programmé » — alors qu’il part tout seul le premier mardi de chaque mois. Deux affirmations fausses sur le même bloc. Les cinq présentations tournent depuis fin août, jamais deux fois la même de suite : c’est cette rotation qui était invisible. Le programme annonce désormais la présentation qui partira, avec son objet réel, exactement comme le fait déjà le parrainage. ET IL L’ANNONCE JUSTE. Le panneau lit la MÊME mémoire que l’expéditeur et appelle la MÊME fonction de choix : il ne devine pas, il lit. Deux chemins qui choisiraient chacun de leur côté finiraient par diverger, et l’écran annoncerait un courriel pendant qu’un autre partirait — un mensonge silencieux, invisible jusqu’à ce qu’un client reçoive autre chose. La variante n’est affichée que sur le PROCHAIN témoignage : le programme couvre huit semaines, donc deux premiers mardis, et la rotation aura tourné entre les deux. UN RÉGLAGE EN DOUBLE A ÉTÉ RETIRÉ. Le programmateur de date manuel du témoignage vivait juste sous le programme qui affiche désormais cet envoi, son jour, son heure et sa présentation. Deux réglages pour la même chose, côte à côte, sans qu’on sache lequel fait foi.' },
  { id: 'dtpu-20260909-verrou-mobile', ts: Date.UTC(2026, 8, 9, 18, 0), title: 'App mobile : le déverrouillage par empreinte ou visage devient activable, et la fiche des magasins est prête', desc: 'DEUXIÈME CAPACITÉ MORTE, TROUVÉE COMME LA PREMIÈRE. L’application savait verrouiller le desk par empreinte ou reconnaissance faciale depuis le premier jour : elle attendait qu’on le lui demande. Le desk ne le lui demandait JAMAIS — aucune ligne, nulle part. Le verrou ne pouvait donc être activé par personne. Exactement le même défaut que les notifications la veille : une capacité présente, annoncée, et injoignable. L’INTERRUPTEUR EXISTE MAINTENANT, dans « Mot de passe et sécurité ». Il n’apparaît que dans l’application — au navigateur il ne mènerait à rien. Et c’est l’application qui dit la vérité, pas le desk : elle seule sait si un visage ou une empreinte est enregistré sur l’appareil. Sur un téléphone qui n’en a aucun, l’interrupteur ne s’allume pas et explique pourquoi, au lieu d’accepter un réglage qui ne verrouillerait rien. Après une réinstallation, il retrouve tout seul le bon état. POURQUOI DEUX FOIS LE MÊME DÉFAUT. Parce que le contrôle automatique ne regardait qu’UN BOUT du fil : il vérifiait que la capacité existait bien dans l’application, et elle y était. Il vérifie désormais que le desk peut l’ATTEINDRE et que l’application RÉPOND — l’aller-retour complet, pour les trois capacités. UN AVERTISSEMENT DE COMPILATION CORRIGÉ AU PASSAGE : un réglage d’affichage Android n’existe pas dans la version des outils que nous utilisons. Il était ignoré en silence — nous croyions configurer quelque chose que rien n’appliquait. Un contrôle lit désormais le schéma officiel des outils installés et refuse toute clé qu’ils n’acceptent pas. ENFIN, LES FICHES DES MAGASINS SONT ÉCRITES : descriptions, mots-clés, classifications, et les formulaires de confidentialité d’Apple et de Google remplis à partir de ce que le produit fait réellement — chaque ligne vérifiée dans le code, pas déduite.' },
  { id: 'dtpu-20260909-push-mobile', ts: Date.UTC(2026, 8, 9, 16, 0), title: 'App mobile : les alertes de marché arrivent enfin écran verrouillé', desc: 'LA MOITIÉ QUI MANQUAIT. L’application savait déjà demander l’autorisation de notifier et produire son identifiant d’appareil — mais PERSONNE ne le ramassait : ni le desk, ni le serveur. L’identifiant naissait et mourait dans l’application. Autrement dit : la capacité était annoncée, la chaîne n’existait pas. Elle existe maintenant de bout en bout. L’INTERRUPTEUR « PUSH » DU PANNEAU ALERTES NE FAISAIT RIEN DANS L’APPLICATION, et ne le disait pas. Le desk passait par l’interface de notification des navigateurs — qui n’existe tout simplement pas à l’intérieur d’une application mobile. On appuyait, il ne se passait rien : pas d’erreur, pas de refus, rien. Il parle désormais à la coquille native, qui, elle, sait faire. Au navigateur, rien ne change. CE QUI VOUS RÉVEILLE, ET CE QUI NE VOUS RÉVEILLE PAS. Seules les publications de premier rang partent : la donnée macro majeure avec son chiffre, la géopolitique de premier rang. Une notification qui réveille un téléphone la nuit n’a pas le même coût qu’une ligne de plus dans un panneau. Vos réglages sont respectés à l’identique : le même interrupteur que la cloche du desk, les mêmes catégories coupées dans le panneau Filtre. Six par heure au maximum — un matin de réunion de la Fed, d’emploi américain et d’inflation, on se tait plutôt que de vider votre batterie, et c’est aussi le meilleur moyen de ne pas se faire couper les notifications pour de bon. Une même publication ne vous réveille jamais deux fois, même quand le desk l’enrichit ensuite. ET ON NE VOUS DEMANDE PAS L’AUTORISATION AU LANCEMENT. Un refus, sur téléphone, est DÉFINITIF : il faut ensuite aller le retrouver dans les réglages du système. La demande passe donc par l’interrupteur du panneau d’alertes, là où vous savez ce que vous acceptez. Désactivé, l’appareil se retire immédiatement au lieu d’attendre une désinstallation ; réinstallé ailleurs, il se réenregistre tout seul à l’ouverture.' },
  { id: 'dtpu-20260909-propos-panneau', ts: Date.UTC(2026, 8, 9, 9, 0), title: 'Prise de parole : la note du desk est retirée, et les propos s’affichent enfin en français', desc: 'Le panneau qui s’ouvre sous le bouton Info quand un responsable prend la parole. Deux changements, tous deux demandés. LA NOTE DU DESK EST RETIRÉE. Sous la liste des propos, nous ajoutions une note de cadrage — « Contexte DTP : … ». Elle ÉTIQUETAIT le sujet au lieu de le dire : « Le dossier concerne les déclarations de X sur la persistance de l’inflation. Le sujet touche les marchés par la politique monétaire. » Deux phrases sous dix propos de la même intervention, et rien dedans que vous n’ayez déjà sous les yeux. Verdict : « ça je comprends pas, enlève ». Elle part. ET ELLE PART VRAIMENT. Le texte n’est pas simplement caché : la fabrication qui le produisait — un cycle d’intelligence artificielle tournant en fond, avec ses consignes, ses garde-fous, ses compteurs et sa mémoire — est supprimée en même temps. Laisser tourner une fabrication pour un texte que plus personne n’affiche aurait consommé du quota chaque minute sans que rien ne le signale. Le précédent du desk est clair : déplacer ce dont personne ne veut, ce n’est pas le retirer. LES PROPOS SONT TRADUITS. Ils restaient en anglais alors que la traduction était pourtant bien branchée sur eux : elle PERDAIT LA COURSE. Le panneau masque les lignes en attente puis, au bout de deux secondes et demie, renonce, affiche l’anglais et le FIGE ; la traduction qui revenait à quatre secondes était bien reçue, et jamais peinte. Elle est donc préparée EN FOND, avant que vous n’ouvriez le panneau : le français est là dès l’ouverture, sans attente et sans bascule sous vos yeux. NOUS N’AVONS PAS CHOISI D’ALLONGER LE DÉLAI D’ATTENTE : cela vous aurait fait patienter plus longtemps devant un écran gris pour recevoir, les jours de quota serré, exactement le même anglais. Si la préparation n’a pas eu lieu, l’affichage d’avant reste : rien n’est retiré, un chemin rapide est ajouté. La dépense est plafonnée, ne paie jamais deux fois le même propos ni un texte déjà français, ne remonte pas au-delà de six heures, et cède la place aux autres travaux du desk avant eux. Elle est mesurée dans le moniteur.' },
  { id: 'dtpu-20260908-synthese-hebdo', ts: Date.UTC(2026, 8, 8, 9, 0), title: 'La synthèse des rapports est réduite à l’essentiel, et les récaps hebdo s’affichent enfin sans attendre', desc: 'TROIS RETOURS DANS LA MÊME JOURNÉE, même sujet. L’encadre doré qui ouvre chaque rapport rendait trois choses de nature différente à la suite : le paragraphe qui raconte la séance, un décompte (« 2 publications, dont 1 hors consensus »), puis la liste des performances. Le Récap Quotidien, qui sert de référence, n’y met que le paragraphe. Le décompte et la photo de séance sont donc SUPPRIMÉS — pas déplacés ailleurs. Ils ne reviendront nulle part : un contrôle automatique le vérifie, parce que deplacer ce dont personne ne veut, ce n’est pas le retirer. ET PLUS DE GRAS DANS LA SYNTHÈSE. C’est de la prose. Un paragraphe où la Fed, la BCE et le dollar australien ressortent tous en gras se lit comme une liste de mots-clés, pas comme un récit — et le gras y perdait tout pouvoir de signaler, puisque tout le vocabulaire du desk y passait. Il reste partout ailleurs, où il distingue vraiment quelque chose. LES RÉCAPS HEBDO N’ATTENDENT PLUS. Signalement : « je les vois pas quand j’actualise, ils prennent du temps à charger ». Deux causes, toutes deux dans la mémoire locale du navigateur. La première : quand le serveur est en train de fabriquer le rapport, celui-ci n’arrive pas par la première lecture mais par les re-tentatives — et celles-ci ne rangeaient jamais le résultat. La réserve locale restait donc vide à chaque fois, et chaque rechargement de page repartait du réseau. La seconde : cette réserve se périmait en vingt-quatre heures, pour un rapport qui ne change QU’UNE FOIS PAR SEMAINE — passe un jour, elle était jetée alors que son contenu était encore le bon. Elle vit maintenant huit jours, et les deux chemins rangent au même endroit. LE RÉCAP HEBDO adopte aussi la mise en page du Quotidien : sa synthèse porte le même encadre doré, et ses sous-titres, qui sortaient en blanc et plus gros, sont ramenés au même rang que partout ailleurs. Les trois rapports se lisent à la suite : ils rangent pareil, ils doivent en avoir l’air.' },
  { id: 'dtpu-20260907-syntheses-epurees', ts: Date.UTC(2026, 8, 7, 19, 0), title: 'Les synthèses de rapports ne portent plus que la lecture, et le récap hebdo adopte la mise en page du quotidien', desc: 'Deux captures à l’appui. La SYNTHÈSE d’un récap de séance mélangeait trois choses de nature différente dans le même encadré doré : le paragraphe qui raconte la séance, un décompte (« 2 publications, dont 1 hors consensus »), puis la liste des performances. Le Récap Quotidien, lui, n’y met que le paragraphe — et c’est lui qui a raison. LE DECOMPTE DISPARAÎT. Il avait déjà été refuse une fois, avec le même mot : un décompte n’est pas une lecture. Il n’avait survécu que parce qu’on l’avait déplacé derrière le paragraphe au lieu de le retirer. LA PHOTO DE SÉANCE RESTE : c’est une donnée de marché, pas du remplissage. Elle prend simplement sa propre rubrique juste après la synthèse, au même rang que Géopolitique ou Macro, et elle y perd son préfixe puisque l’intitulé le porte déjà. Une synthèse sans paragraphe ne se remplit plus avec les performances : mieux vaut pas de synthèse qu’une synthèse qui n’en’est pas une. Tous les récaps de séance sont régénérés. LE RÉCAP HEBDO SE CALE SUR LE QUOTIDIEN. Il ouvrait sur du texte nu, sans intitulé ni encadré, là où les deux autres rapports encadrent leur synthèse d’un liseré doré. Il l’à maintenant, et c’est le MÊME élément, pas une troisième copie. Ses sous-titres et ses puces suivent aussi : mesuré dans un vrai navigateur avant correction, ses sous-titres sortaient en blanc et plus gros, au même rang visuel que ses titres de rubrique — c’est exactement ce qui faisait paraître le rapport chargé. Ils sont désormais petits et gris, comme partout ailleurs. Les trois rapports se lisent à la suite : ils rangent pareil, ils doivent en avoir l’air.' },
  { id: 'dtpu-20260907-app-mobile', ts: Date.UTC(2026, 8, 7, 17, 0), title: 'L’app mobile DataTradingPro existe : une coquille native qui affiche le desk, prête pour les deux magasins', desc: 'Le desk devient une application, pour l’App Store et Google Play. Le choix de fond, d’abord, parce qu’il explique tout le reste : le desk n’est PAS réécrit. L’application l’affiche. POURQUOI. Le desk représente cinquante-six mille lignes de code d’interface et vingt et un mille lignes de mise en forme, dont rien ne s’exécute dans le langage des applications natives. Le réécrire aurait produit un second produit, à faire évoluer deux fois, pour toujours. CE QUE ÇA VOUS DONNE. Chaque mise à jour du desk est en ligne sur les deux applications INSTANTANÉMENT. Pas de nouvelle version à publier, pas de revue de magasin à attendre, pas de client resté sur une ancienne version. Ce que vous voyez le matin sur le site, vous l’avez le matin sur le téléphone. MAIS UNE APPLICATION DOIT ÊTRE PLUS QU’UN SITE EMBALLE, et Apple refuse celles qui n’en sont qu’un. Trois capacités que le web n’a pas sur téléphone ont donc été ajoutées, et elles ne sont pas décoratives : les notifications, pour qu’une alerte de marché arrive écran verrouillé ; le déverrouillage par empreinte ou reconnaissance faciale, la session gardée dans le coffre du système ; et un mode hors ligne qui affiche le dernier état connu au lieu d’un écran blanc. LA FRONTIÈRE EST GARDée. Tout ce qui n’est pas le desk s’ouvre dans le navigateur, jamais dans l’application : un paiement, un article, une page tierce. La vérification se fait sur le nom de domaine exact, pas sur le début de l’adresse — une adresse qui COMMENCE comme la notre mais appartient à quelqu un d’autre est rejetée, et c’est vérifie par un contrôle automatique. Les visuels sont produits à partir du logo vectoriel, jamais agrandis depuis une petite image. Il reste à compiler et à déposer sur les magasins.' },
  { id: 'dtpu-20260907-parrainage-existant', ts: Date.UTC(2026, 8, 7, 15, 0), title: 'Parrainage : le filleul qui avait déjà un compte est enfin rattaché à son parrain', desc: 'Audit complet de la chaîne de parrainage, demandé avant toute certification. Un défaut de fond en est sorti, et il touchait le cas le PLUS COURANT. L’ATTRIBUTION NE MARCHAIT QUE POUR LES COMPTES NEUFS. Quand Whop nous signale un abonnement, notre serveur se sépare en deux chemins : soit la personne a déjà un compte chez nous, soit il faut le créer. Le rattachement du filleul à son parrain ne vivait que dans le SECOND. Conséquence : quelqu’un qui avait déjà un compte — offre gratuite, essai, ancien abonnement expiré — et qui souscrivait ENSUITE par le lien d’un parrain n’était rattaché à personne. Whop versait bien la commission, elle ne dépend pas de nous ; mais notre compteur restait à zero, donc le mois offert tous les trois filleuls ne se déclenchait jamais pour ce filleul-la, et rien ne le signalait ni au parrain ni à l’administration. Sur un produit qui propose une offre gratuite, c’est le chemin normal, pas le cas rare. Le rattachement tourne désormais sur LES DEUX chemins. SANS CRÉDITER LE PASSE PAR ERREUR. Tous les renouvellements passent par ce même endroit, y compris ceux d’abonnés de deux ans souscrits jadis via un lien. Sans précaution, chacun aurait déclenché une récompense rétroactive — des mois d’accès offerts que personne n’avait gagnés cette fois-ci. Le rattachement ne vaut donc, sur ce second chemin, que pour une adhésion récente, et l’adhésion porte maintenant sa date de création pour qu’on puisse en juger. Un verrou garantissait déjà qu’un filleul ne compte qu’une seule fois, quel que soit le nombre de renouvellements. CE QUI A ÉTÉ VÉRIFIE AU PASSAGE, et qui va bien : les données de parrainage ne sont jamais effacées par le ménage automatique du cache — seules les entrées d’intelligence artificielle le sont. On ne peut pas se parrainer soi-même. Et le compteur, la récompense au troisième filleul, les jours ajoutés et les deux mails partent correctement.' },
  { id: 'dtpu-20260907-parrainage-audit', ts: Date.UTC(2026, 8, 7, 11, 0), title: 'Parrainage : un audit qui repond pour TOUS les comptes, plus un seul à la fois', desc: 'Question posée : est-ce que chacun a bien son lien d’affiliation, et est-ce que l’affiliation fonctionne vraiment quand on transmet son lien à un nouvel inscrit. Le panneau d’administration savait déjà repondre, mais POUR UNE ADRESSE À LA FOIS : pour savoir si tout le monde était servi, il fallait le rejouer compte par compte. Une nouvelle vue balaie désormais l’annuaire entier et ne rend que ce qui compte : qui à un lien, qui n’en à pas, et pourquoi — aucune adhésion Whop, membre Whop sans pseudo exploitable, ou Whop injoignable. DEUX CHOSES SONT RAPPORTéeS SÉPARÉMENT, ET C’EST LE POINT IMPORTANT. La COMMISSION est l’affaire de Whop : elle est suivie et versée par eux, à partir du lien partage, sans que notre serveur intervienne. Le COMPTEUR DE FILLEULS, lui — celui qui declenche un mois offert tous les trois filleuls — à besoin que nous sachions relier le pseudo du parrain à son compte. Les confondre ferait annoncer une perte d’argent là où il n’y en a aucune : un lien manquant n’enleve rien aux commissions déjà dues, il empeche seulement CE compte-la d’en partager un. La vue le dit noir sur blanc, et signale à part un index qui pointerait vers le mauvais compte. C’EST UN AUDIT, DONC IL N’ÉCRIT RIEN. Ni index, ni compteur, aucun appel à l’IA. Un contrôle qui repare en passant ne dit plus ce qu’il à trouve : il dit ce qu’il à laisse. Les appels sont espaces les uns après les autres plutôt que lances tous ensemble, et le balayage est plafonne — sur notre hébergement, interroger tout l’annuaire d’un bloc est exactement ce qui coupe le service au milieu du travail de quelqu’un d’autre. Si l’annuaire dépassé le plafond, c’est écrit.' },
  { id: 'dtpu-20260907-analyse-carte', ts: Date.UTC(2026, 8, 7, 9, 0), title: 'Le tag Analyse s’ouvre sur une synthèse lisible, et le détail passe derrière', desc: 'Retour client, capture de référence à l’appui. Sur une analyse d’événement - décision de banque centrale, inflation, emploi -, le bouton ANALYSE déroulait le rapport ENTIER : six intertitres, une quinzaine de lignes, avant même de savoir ce qui s’était passe. Il fallait tout lire pour trouver l’essentiel. IL S’OUVRE MAINTENANT SUR UNE CARTE. Une pastille, le mot Analyse, l’heure à laquelle le desk a écrit sa lecture, et un paragraphe de prose : ce qui a été decide, si c’était attendu, le ton employé, ce qui a changé depuis la fois précédente. C’est l’accroche que le desk rédigeait déjà avant chaque rapport - elle n’avait simplement jamais été montrée à cet endroit. RIEN N’EST PERDU. Les rubriques détaillées suivent la carte, sous leur propre intitulé. Vous lisez l’essentiel en quelques secondes, et le détail reste à portée de regard pour qui veut le fond. Un ancien rapport sans accroche garde exactement son affichage précédent : aucune analyse déjà publiée ne perd quoi que ce soit. ET LE BOUTON INFO NE RÉPÈTE PLUS LA MÊME CHOSE. Sur ces analyses, il montrait ce paragraphe, et l’Analyse montrait le reste : le même texte se lisait sur deux surfaces selon le bouton cliqué. Il disparaît donc de ces analyses-là, où il n’avait plus rien qui lui soit propre. Toutes les autres news gardent leur bouton Info intact. L’habillage reste celui du desk : bordure fine, coins doux, pastille OR. La forme vient de la référence, la couleur reste la notre.' },
  { id: 'dtpu-20260906-discours-preserves', ts: Date.UTC(2026, 8, 6, 22, 0), title: 'Les discours et bulletins gardent ce qu’ils disent, et la phrase de tête ne compte plus un congrès comme un chiffre', desc: 'Correction de deux défauts que j’ai introduits ce matin même, en ouvrant les récaps de séance aux rendez-vous sans chiffre. Les deux ont été pris par un contrôle rejoué contre le calendrier réel, pas en relecture. LE PROPOS DES DISCOURS ÉTAIT EFFACÉ. Quand notre calendrier et la rédaction parlaient du même rendez-vous, le desk gardait NOTRE ligne - nom exact, heure exacte - et n’en retenait que la lecture, ce qui suit la fleche. C’est juste pour une publication chiffrée : le calendrier redit les nombres mieux que la rédaction. C’est destructeur pour un DISCOURS, où tout le contenu est AVANT la fleche. Un discours de la Banque du Japon annonçant une sortie graduelle et aucune hausse avant décembre se réduisait à une ligne de programme : l’heure, la devise, le titre. La séance portait ses rendez-vous et avait perdu ce qu’elle en disait. La règle tient maintenant en une phrase : le calendrier possède TOUJOURS l’identité - le nom et l’heure -, il ne possède les FAITS que lorsqu’il en a. Sans chiffre, c’est le corps de la ligne qui est conservé. LA PHRASE DE TÊTE ANNONCAIT DES CHIFFRES QUI N’EXISTAIENT PAS. Un jour où aucune donnée chiffrée n’est sortie en Asie, le récap s’ouvrait sur « 3 publications sur la séance, toutes conformes aux attentes ». Un congrès, un discours et un bulletin ne sont conformes à aucune attente : ils n’en ont pas. Les rendez-vous étaient comptes comme des publications, et faute de chiffre à comparer, la mention « toutes conformes » tombait toute seule. Les deux comptes sont désormais séparés, et le jugement de conformité ne porte que sur ce qui a réellement publié un chiffre. Cette phrase ouvre aussi les récaps qui ne passent pas par l’IA : elle était servie immédiatement. ET LA CONSIGNE DE RÉDACTION NE CONTIENT PLUS DE RAPPORT TOUT FAIT. La correction d’hier n’avait nettoyé que le squelette ; le corps des consignes gardait encore une ligne d’inflation américaine complète avec ses chiffres, et un paragraphe d’analyse entier sur un dossier géopolitique. De quoi recopier un rapport crédible sans aucune matière - c’est exactement ce qui s’était produit. Remplacés par des emplacements vides. La forme reste enseignée, les faits ne sont plus fournis. Tous les récaps de séance sont régénérés.' },
  { id: 'dtpu-20260906-recap-relu', ts: Date.UTC(2026, 8, 6, 20, 0), title: 'Les récaps de séance sont relus automatiquement, et toute incohérence servie est nommée', desc: 'Suite du signalement sur le CPI américain. Les verrous posés la veille écartent la puce fautive AU MOMENT DU RENDU, mais sans rien dire : le jour où une nouvelle tournure passe entre les mailles - il y en a déjà eu deux vagues - plus rien ne le signale, et c’est un client qui le découvre, capture à l’appui. C’était le vrai problème : non pas qu’un défaut existe, mais que personne ne le voie avant vous. LE DESK SE RELIT MAINTENANT LUI-MÊME. À chaque récap fabriqué, le desk repasse sur ce qu’il vient d’écrire - toutes les rubriques, pas seulement la Macro - et consigne ce qui cloche. Le contrôle travaille dans le SENS INVERSE de la complétion : au lieu de partir du calendrier et de chercher dans le rapport, il part du RAPPORT et cherche dans le calendrier. C’est ce sens-là qui voit une invention - une ligne inventée ne MANQUE à aucun rendez-vous, elle n’est RATTACHÉE à aucun, et l’anti-doublon, qui ne sait que comparer, ne pouvait pas la voir. QUATRE CHOSES SONT RELUES. Un chiffre dont le pays n’est pas celui de la séance - un indice américain dans un récap de Londres. Une échéance que personne ne peut vérifier : le mot « demain », celui-là même qui rendait la ligne inventée crédible. Un enchaînement qui rattacherait un chiffre d’un pays à la banque centrale d’un autre. Et les fragments de gabarit de rédaction, qui sortaient aussi dans la synthèse d’ouverture et l’analyse de séance. PRÉCISION AVANT COUVERTURE. Un contrôle qui crie à tort est un contrôle qu’on cesse de lire, et le jour où il a raison personne ne l’ouvre. Chacun des quatre est donc borné à la rubrique où il ne peut pas se tromper, et chacun est éprouvé DANS LES DEUX SENS : qu’il attrape le défaut, et qu’il reste muet sur du bon travail. Une séance propre ne produit aucun signalement. ET VOUS POUVEZ LE CONSULTER. Le panneau d’administration met désormais un verdict en tête de la comparaison au calendrier : les trois séances du jour, ce qui est grave et ce qui est simplement à lire, séance par séance.' },
  { id: 'dtpu-20260906-seance-ses-news', ts: Date.UTC(2026, 8, 6, 18, 0), title: 'Récaps de séance : chaque séance porte enfin SES propres rendez-vous, et les intitulés sont ceux du calendrier', desc: 'Retour client, deux captures. Le récap de la séance Asie-Pacifique annonçait un chiffre d’inflation américain — alors qu’aucun n’était publié ce jour-là, et que la séance asiatique n’avait rien à voir avec lui. POURQUOI LA SÉANCE NE PORTAIT PAS SES PROPRES NEWS. Le desk complète chaque récap avec ce que notre calendrier a enregistré pendant la fenêtre horaire de la séance. Mais il ne retenait que les rendez-vous PORTANT UN CHIFFRE. Or une séance asiatique est faite de discours, de bulletins et de réunions : ce jour-là, le congrès chinois, le discours de la Banque du Japon et le bulletin de la Banque de réserve d’Australie. Trois rendez-vous, aucun chiffre — la complétion n’ajoutait donc rien, et la rubrique restait seule avec ce que la rédaction automatique avait écrit. Ces rendez-vous entrent désormais, avec leur heure et leur intitulé, et sans colonnes vides puisqu’ils n’ont pas de chiffres à montrer. Une publication chiffrée qui n’est pas encore tombée, elle, reste où elle doit être : dans À surveiller, pas dans le récit de ce qui s’est passé. LES INTITULÉS SONT CEUX DU CALENDRIER. Une ligne annonçait « Dépenses des ménages australiens » ; vous cherchez ce rendez-vous sous son nom de calendrier, pas sous une traduction thématique. Quand la rédaction et le calendrier parlent de la même publication, c’est désormais NOTRE ligne qui est gardée — nom exact, heure exacte, chiffres exacts — et de la sienne on ne retient que la lecture, ce qui suit la flèche. Les faits viennent du calendrier, l’interprétation de l’analyse. ET LA LECTURE GREFFÉE EST VÉRIFIÉE. Une conséquence qui rattacherait un chiffre d’un pays à la banque centrale d’un autre est écartée, et les faits restent seuls : mieux vaut une ligne sans lecture qu’une lecture fausse. Le contrôle posé la veille ne reconnaissait qu’une seule tournure ; huit reformulations de la même absurdité passaient encore. Il raisonne maintenant sur ce que la phrase affirme, plus sur les mots qu’elle emploie — et il a cessé d’écarter deux lectures justes qu’il supprimait à tort. Il s’applique enfin aux récaps servis quand le tableau du calendrier n’est pas disponible, ce qui n’était pas le cas : c’était le trou le plus grave. Tous les récaps de séance sont régénérés pour en bénéficier immédiatement.' },
  { id: 'dtpu-20260906-surveiller-coherence', ts: Date.UTC(2026, 8, 6, 14, 0), title: 'Récaps de séance : « À surveiller » ne peut plus annoncer qu’un chiffre américain price une réunion australienne', desc: 'Signalé par un client, capture à l’appui. Sous le calendrier d’une séance de Londres — trois publications de la zone euro — s’affichait la ligne « CPI US demain → catalyseur du pricing de la réunion RBA ». Un chiffre d’inflation américain ne price pas une réunion de la banque centrale australienne, et la ligne revenait d’un récap à l’autre. DEUX CAUSES, ET IL FALLAIT LES DEUX. La première : la consigne de rédaction donnée à notre assistant se terminait par un exemple de réponse qui contenait cette phrase, avec la Fed. Quand une séance ne laisse rien de prospectif à annoncer, un modèle recopie ce qu’il à sous les yeux — en remplaçant au passage la banque centrale par celle qu’il vient de croiser. L’exemple ne porte plus aucun fait, seulement des emplacements à remplir, et la consigne dit maintenant en toutes lettres qu’un indicateur ne price que la banque centrale de sa propre devise, et qu’une rubrique sans matière s’omet plutôt que se remplit. La seconde : rien ne relisait le texte produit. Le contrôle posé fin août ne comparait la rubrique qu’au tableau du calendrier juste au-dessus ; aucun chiffre américain n’y figurant ce jour-là, la ligne n’était pas vue comme une répétition et passait. Le desk vérifie désormais lui-même, sans assistant : une ligne qui affirme qu’un sujet d’une devise price la réunion d’une banque d’une autre devise est écartée avant d’arriver sous vos yeux. CE QU’ON A REFUSÉ DE FAIRE. Corriger le nom de la banque plutôt que retirer la ligne aurait été plus élégant à l’écran, et malhonnête : quand la ligne est une recopie d’exemple, le rendez-vous lui-même n’existe pas, et lui remettre la bonne banque rendrait crédible une échéance inventée. On retire ce qu’on sait faux plutôt que d’affirmer ce qu’on ne peut pas vérifier. ET CE QUI RESTE. Trois garde-fous protègent les lignes légitimes : le discours à Jackson Hole, les résultats d’une grande valeur, une banque centrale simplement mentionnée sans affirmation — tout cela reste affiché, comme avant. Les récaps de séance déjà produits sont régénérés pour en bénéficier immédiatement.' },
  { id: 'dtpu-20260906-cache-images', ts: Date.UTC(2026, 8, 6, 9, 0), title: 'Application installée : les images du desk se mettent de nouveau à jour, et l’écran hors ligne s’affiche même déconnecté', desc: 'UN DÉFAUT DE LA SEMAINE DERNIÈRE, CORRIGÉ AVANT QU’IL NE FASSE DES DÉGÂTS. En posant l’installation sur téléphone, le desk a reçu un composant qui répond aux demandes du navigateur AVANT le réseau. Il avait consigne de ne mémoriser que les fichiers qui portent un numéro de version — mais il décidait en réalité sur l’extension du fichier. Les logos de banques et les illustrations, qui n’en portent pas, se retrouvaient mémorisés DÉFINITIVEMENT : remplacer un logo sur nos serveurs n’atteignait plus jamais un appareil ayant ouvert le desk une fois, et aucun rechargement, pas même Ctrl+F5, n’y pouvait rien — ce composant répond avant que la demande ne parte. La règle annoncée devient celle qui s’applique : pas de numéro de version, pas de mémorisation. LE RITUEL DE MISE À JOUR COUVRE MAINTENANT CE COMPOSANT. Il gardait son propre numéro, mis à jour à la main, donc oublié tôt ou tard. Il suit désormais celui des pages, automatiquement, et un contrôle refuse un décalage entre les deux. L’ÉCRAN HORS LIGNE S’AFFICHE AUSSI QUAND VOUS N’ÊTES PAS CONNECTÉ. Lui et le composant d’installation étaient servis derrière la session : en pratique, l’installation ne pouvait pas se faire depuis la page de connexion. Ils sont désormais accessibles à tous, comme le doivent des fichiers qui servent précisément quand le reste ne répond pas.' },
  { id: 'dtpu-20260905-apparence-panneau', ts: Date.UTC(2026, 8, 5, 15, 0), title: 'Réglages : le panneau Apparence se range en deux blocs, et les icônes de thème disent enfin lequel elles choisissent', desc: 'UN RÉGLAGE QUI NE FAISAIT RIEN A ÉTÉ RETIRÉ. « Couleur des bougies » proposait quatre palettes et n’en appliquait aucune : les graphiques du desk sont dessinés par TradingView et par notre moteur de cartes, qui ont chacun la leur. Un bouton qui ne change rien est une promesse que le produit ne tient pas — mieux vaut pas de bouton du tout. LE PANNEAU SE LIT EN DEUX BLOCS. C’était une liste de six réglages à la suite, sans hiérarchie, où la couleur des bougies s’intercalait entre le zoom et les formats sans qu’on sache pourquoi. Il y a maintenant ce qui touche à l’œil — thème et zoom — puis ce qui touche à l’écriture des valeurs : nombres, dates, heures, repère de survol. Deux intitulés, un filet, et l’ordre devient évident. LES ICÔNES DISENT LE THÈME. « Mode Sombre » portait une flamme : une flamme n’est ni sombre ni claire, et à côté d’un soleil elle se lisait comme un troisième réglage. Un soleil, une lune, un écran — le jour, la nuit, et « comme mon appareil ». LE MODE CLAIR EST ENFIN CLAIR JUSQU’AU BOUT. Les trois boutons de thème, les pas de zoom et « Réinitialiser » gardaient un fond noir écrit en dur : sur le panneau crème du mode clair, ils formaient des pastilles sombres, et le comble était que le bouton « Mode Clair », une fois choisi, se retrouvait entouré de deux d’entre elles. Personne ne l’avait vu parce que personne n’avait ouvert ce panneau en mode clair : c’est désormais fait à chaque contrôle, dans les deux thèmes.' },
  { id: 'dtpu-20260905-app-telephone', ts: Date.UTC(2026, 8, 5, 9, 0), title: 'Le desk s’installe sur le téléphone, garde sa barre lisible et vous dit quand la navigation continue', desc: 'DTP S’INSTALLE COMME UNE APPLICATION. Sur Android comme sur iPhone, votre navigateur vous propose désormais d’ajouter DataTradingPro à l’écran d’accueil : icône, ouverture en plein écran, sans barre d’adresse. Rien à télécharger, aucun magasin d’applications. QUAND LE RÉSEAU TOMBE, VOUS RESTEZ CHEZ VOUS. Dans un métro ou un ascenseur, la coupure d’une seconde donnait la page d’erreur du navigateur ; un écran DTP prend sa place, et le desk se recharge tout seul dès que le réseau revient. Volontairement, aucun chiffre de marché n’y est affiché de mémoire : un cours périmé serait plus trompeur qu’un écran vide. LA BARRE DU HAUT NE MORD PLUS SUR LES ONGLETS. Sur les téléphones étroits, elle passe sur deux rangées — et la seconde recouvrait le début de la rangée d’onglets : « ACTUS » était à moitié caché derrière la recherche de symbole. Les deux rangées tiennent désormais chacune leur place. LA NAVIGATION DIT QU’ELLE CONTINUE. Elle est plus large que l’écran d’un téléphone : plus de la moitié des onglets se trouve hors champ, à droite, et rien ne l’indiquait — le dernier onglet lisible était tranché en plein mot et ressemblait à un défaut d’affichage. Un fondu marque maintenant le bord, et il s’efface quand vous êtes arrivé au bout. « CHARGER PLUS » NE SAUTE PLUS LA FIN DE LA JOURNÉE. Quand le fil affichait ses cent premières dépêches et que la journée en comptait davantage, le bouton proposait déjà la veille et déroulait deux journées d’un seul coup. Il termine maintenant la journée en cours, et son étiquette annonce ce qu’il va faire. Enfin, une alerte importante ne fige plus le fil sur les téléphones dont les notifications ne sont pas autorisées.' },
  { id: 'dtpu-20260904-recaps-titres', ts: Date.UTC(2026, 8, 4, 23, 30), title: 'Le Récap Hebdo retrouve sa partie Macro, et les trois récaps portent enfin les mêmes titres', desc: 'LA MACRO REVIENT À SA PLACE, entre la géopolitique et les devises. Elle avait été retirée du rendu en août au motif qu’elle répétait les blocs devises. Le motif était vrai pour certains thèmes et faux pour le reste : la semaine macro d’ensemble — inflation, croissance, banques centrales vues de haut, commerce — ne se reconstitue pas en lisant huit blocs devises l’un après l’autre, elle se lit d’un coup ou pas du tout. Le rapport passait donc de la géopolitique aux devises sans jamais dire ce qu’avait fait l’économie. Les rapports déjà archives en profitent aussi : c’est le rendu qui change, pas les données. UN SEUL TRAIT SOUS LE TITRE DES DEVISES. Il y en avait deux, colles. La règle censée retirer celui du premier bloc visait le premier élément DU MÊME TYPE parmi ses frères, c’est-a-dire le premier bloc de la page — qui est le titre, pas le premier bloc devise. Elle ne s’appliquait donc à personne. LES TITRES DE RUBRIQUE SONT LES MÊMES PARTOUT. Le Récap Quotidien et les récaps de séance portaient un petit trait vertical doré devant chaque titre, que le Récap Hebdo n’a jamais eu, et leurs corps de texte différaient de quelques pixels. La même information prenait donc deux formes selon le rapport ouvert, alors que c’est le même desk qui parle. Le trait vertical disparaît, les trois s’alignent sur le Hebdo. Au passage : la poignée qui élargit une carte est plus facile à attraper, les noms de la bibliothèque de widgets ne sont plus en gras — dans une galerie ou chaque carte porte un nom, tout mettre en gras revient à ne rien mettre en avant — et la Table des probabilités quitte le catalogue.' },
  { id: 'dtpu-20260904-desk-finitions', ts: Date.UTC(2026, 8, 4, 22, 0), title: 'Le curseur attrape la barre de défilement, la séance en cours s’allume, et le fil ne se fige plus sur Android', desc: 'Trois corrections signalées par des captures. LA BARRE DE DÉFILEMENT. Viser la barre d’un widget et attraper la poignée qui élargit le bloc : le défaut avait été corrigé fin août, mais la mesure ne regardait que le corps de la carte. Or le desk empile une douzaine de conteneurs défilants À L’INTÉRIEUR du corps, et dans un panneau à onglets ce n’est jamais le corps qui défile, c’est le contenu de l’onglet. Le défaut n’avait donc pas disparu : il s’était réduit aux widgets simples, ceux sur lesquels on l’avait eprouve. La detection cherche désormais partout dans la carte. LA SÉANCE EN COURS S’ALLUME. L’état ouvert ne se disait que par un aplat un peu plus dense que les autres : juste, et plat, sur une frise ou quatre plages se suivent. La plage ouverte prend maintenant du volume par une lumière rasante, un halo de sa propre couleur, et un souffle très lent sur ce halo seul — la matière ne bouge pas, l’horaire écrit dedans ne clignote pas. Rien n’emprunte le vert ni le rouge, réserves aux signaux de marché. Le souffle s’arrêté pour qui a demande moins d’animations dans son système. LE TRAIT DORÉ DE L’ONGLET ACTIF passait derrière les commandes de la carte et semblait les traverser : la barre d’onglets réserve maintenant leur place à toutes les tailles d’écran, et leur fond occupe toute la hauteur. ET SUR ANDROID, une correction qu’aucune capture ne pouvait montrer : le navigateur y refuse la création directe d’une notification système. L’appel n’était protégé par rien, et il se trouve juste avant le rafraichissement du fil : l’exception remontait, et le fil restait fige. Le détail qui rendait la panne introuvable : ce chemin ne s’execute que si le lot contient une dépêche PRIORITAIRE. Le fil se figeait donc précisément sur la news attendue, et jamais sur les autres.' },
  { id: 'dtpu-20260904-parrainage-taux', ts: Date.UTC(2026, 8, 4, 20, 0), title: 'Parrainage : la commission annoncée est désormais la commission réelle, partout', desc: 'Le taux de commission du parrainage était le seul chiffre du produit à vivre à la fois chez notre opérateur de paiement et dans nos propres textes. Il avait donc deux valeurs, sans que rien ne le signale : l’opérateur versait trente pour cent quand nos mails et le desk annonçaient quinze. Personne n’a été lésé — l’écart jouait en faveur des parrains, qui touchaient plus que promis — mais c’est l’inverse qui aurait pu se produire, et la promesse venait de partir à toute la liste. Un chiffre écrit en dur à vingt-six endroits ne se vérifie jamais : il se contredit. Le taux se pose maintenant en UN seul endroit. Les quatre mails de campagne, le mail d’invitation, l’aperçu du panneau et le panneau Parrainages du desk le lisent tous à la même source : le desk le reçoit par le serveur au lieu de le porter dans son code. Le changer demande une ligne, plus une relecture de vingt-six phrases. Un banc l’eprouve en changeant le taux pour de vrai et en vérifiant que les six mails suivent d’un coup — sans quoi le contrôle ne prouverait que la fidélite d’un copier-coller. Au passage, deux faits confirmés : la commission porte bien sur les revenus RÉCURRENTS, pas sur la seule première échéance, et le programme est ouvert sans condition d’abonnement payant.' },
  { id: 'dtpu-20260904-parrainage-semestriel', ts: Date.UTC(2026, 8, 4, 14, 0), title: 'Le parrainage vous est rappelé deux fois par an, et jamais avec le même mail', desc: 'Le programme de parrainage existait, mais rien n’allait le dire à ceux qui ne descendent jamais dans Profil puis Parrainages. Un mail part désormais tous les six mois pour le rappeler : quinze pour cent à vie sur chaque abonne que vous amenez, une commission qui revient chaque mois et non une prime unique, et un mois d’accès ajoute tous les trois filleuls. Le compte à rebours repart du dernier envoi, pas d’une date du calendrier : deux mails ne peuvent pas se retrouver dans le même trimestre. Et le texte CHANGE à chaque fois. Pas une reformulation : quatre angles différents, qui se succèdent dans l’ordre. Le premier parle du revenu, le deuxième de l’abonnement qui finit par se payer seul, le troisième des recommandations que vous faites déjà gratuitement, le quatrième est un rappel court pour les liens jamais ouverts. À deux envois par an, il faut donc deux ans avant de relire le même. Le bouton du mail ne vous depose plus sur le desk en vous laissant chercher : il ouvre directement la section Parrainages, ou votre lien s’affiche à jour. Un point de détail qui n’en est pas un : le mail est le même pour tout le monde, abonne ou non, parce que parrainer ne demande pas d’être abonne au produit payant.' },
  { id: 'dtpu-20260904-frise-note-lisible', ts: Date.UTC(2026, 8, 4, 12, 0), title: 'Sessions de marché : la note du bas était écrite, elle n’était pas lisible', desc: 'La ligne qui explique le chevauchement des séances et le suivi de l’heure d’été se lisait mal, et la mesure sur le desk réel dit pourquoi. Le gris employé donnait un contraste de 1,98 pour 1 sur le fond de la carte, quand le minimum admis pour un texte de cette taille est de 4,5. Et les 9,5 pixels de la feuille de style tombaient à 8,55 pixels réellement peints, le desk s’affichant à 90 pour cent. Deux défauts qui se multiplient : un gris très sombre à une taille très petite ne se lit pas, il se devine. La note passe à 6,92 pour 1 de contraste et gagne un cinquième en taille, avec un filet qui la detache de la frise pour qu’elle se lise comme une légende et non comme une ligne de donnée oubliee. Le banc de la frise mesure désormais les deux valeurs à chaque passage.' },
  { id: 'dtpu-20260904-parrainage-mail', ts: Date.UTC(2026, 8, 4, 10, 0), title: 'Parrainage : un e-mail pret à envoyer, qui porte votre lien quand on le connait', desc: 'Le programme de parrainage existait sur le desk, mais rien ne le disait à ceux qui ne sont jamais allés dans Profil. Un e-mail d’invitation rejoint donc la série : quinze pour cent à vie sur chaque abonne que vous amenez, une commission récurrente et non une prime unique, et un mois d’accès ajoute tous les trois filleuls. Il existe en deux formes, et c’est la seule différence entre les deux. Quand votre lien d’affiliation est déjà connu, le mail le porte, en clair, pret à copier. Quand il ne l’est pas, le mail donne les deux étapes pour l’obtenir en deux minutes — ouvrir Profil puis Parrainages, ou sinon creer un compte Whop et rejoindre l’espace JustOneTrader, ou l’offre gratuite suffit. Un encadre insiste sur le seul point ou la chaîne peut casser : utiliser sur Whop la MÊME adresse e-mail que celle du compte DataTradingPro, sans quoi les deux ne se reconnaissent pas et le lien ne s’affiche jamais. Le mail dit aussi qui paie quoi : les commissions sont suivies et versées par Whop, dans votre espace Whop ; le compteur de filleuls, lui, s’affiche en direct dans le panneau Parrainages. Il est repondable, et il figure dans la galerie d’aperçu des e-mails avec ses deux variantes.' },
  { id: 'dtpu-20260903-onglets-sources', ts: Date.UTC(2026, 8, 4, 8, 0), title: 'Un onglet porte le nom de son widget, et les récaps d’analystes ne citent plus leurs sources', desc: 'Deux corrections signalées capture à l’appui. UN ONGLET PORTE LE NOM DE SON WIDGET. Un onglet intitulé MONDE s’ouvrait sur un panneau intitulé SESSIONS DE MARCHE. Le libelle par défaut d’un onglet retombait sur le SIGLE du widget — un code court conçu pour les vignettes de disposition, ou un nom entier ne tiendrait pas — avant son nom. Sur les quarante et un widgets du catalogue, vingt-sept ont un sigle différent de leur nom, et plusieurs le PARTAGENT : cinq portent VOLATILITÉ, trois FX, deux TAUX. Deux onglets voisins pouvaient donc s’appeler pareil, ce qui retire à un onglet sa seule fonction : dire ce qu’il ouvre. Le nom du widget est désormais le libelle par défaut, partout et pour tout le monde — un onglet renomme à la main garde évidemment son nom. Le sigle reste employé là où il à un sens, sur la vignette de disposition et la fiche d’aide. LES RÉCAPS DE SÉANCE NE CITENT PLUS LEURS SOURCES. Une puce se terminait par : en septembre, point median, Sondage Reuters, fleche, renforcement du yen. Le lecteur paie une lecture, pas un annuaire de dépêches, et une attribution au milieu d’une phrase ne lui apprend qu’ou aller lire ailleurs. Toute attribution à un media est retirée du corps des puces — après un séparateur, entre parentheses, ou en toutes lettres avec selon et d’après. Une précision : un media SUJET de la phrase reste en place. Reuters rapporte que la BoJ hésite garde son sujet, sans quoi la phrase deviendrait bancale. C’est la même prudence que pour source proche de la BCE, ou le mot porte l’information. La règle est appliquee au rendu, donc les rapports déjà publiés en bénéficient aussi.' },
  { id: 'dtpu-20260903-frise-epaisseur', ts: Date.UTC(2026, 8, 3, 23, 30), title: 'Sessions de marché : plages plus épaisses, plus de quadrillage, et tout tient sans barre de défilement', desc: 'Trois retours utilisateur, captures à l’appui, sur le même widget. LES PLAGES SE VOIENT. Sur une carte écrasée, elles devenaient des filets de la hauteur d’un trait et l’horaire écrit dedans passait à cheval sur ses propres bordures. Une plage qu’on distingue à peine ne dit plus ni sa durée ni son chevauchement, c’est-a-dire plus rien de ce pour quoi elle existe. La hauteur minimale passe de 7 à 12 pixels, chaque palier de densite est relevé d’autant, et le remplissage remonte : allégé la veille pour que des plages épaisses cessent d’ecraser la carte, il devenait trop pale dès qu’une plage s’amincit. PLUS DE QUADRILLAGE. Une trame de colonnes avait été posée la veille pour relier 15 h de Londres à 15 h de New York. Arbitrage de l’utilisateur : la grille est la signature de FORCE DES DEVISES, pas de cette frise, dont la référence ne montre que les intitulés d’heures en tête et des rails nus. Deux widgets cote à côté, deux grammaires : un quadrillage partout ne signale plus rien nulle part. Les rails restent à peine teintes, pour dire jusqu ou va la journée sans concurrencer la plage qu’ils encadrent. ET TOUT S’AFFICHE, SANS BARRE DE DÉFILEMENT. Le défilement de dernier recours pose le 26 août est remplace par une compaction qui va jusqu au bout : sur une carte très basse, la note de pied puis le résume d’en-tête cedent AVANT les places — la note explique la frise, l’en-tête la résume, les places SONT la frise, et chaque ligne porte déjà son badge ouvert ou ferme au bout. Vérifie à sept hauteurs de carte : les quatre places tiennent entièrement, rien n’est cache.' },
  { id: 'dtpu-20260903-fil-sans-regroupement', ts: Date.UTC(2026, 8, 3, 22, 0), title: 'Le fil garde une ligne par publication : le regroupement essayé aujourd’hui est retiré', desc: 'Une publication économique arrive souvent en plusieurs intitulés à la même heure : le PIB et le PCE americains de 14 h 30, par exemple, produisent sept lignes dans le fil. Un regroupement a été essayé aujourd’hui pour n’en faire qu’une, avec les sept valeurs en pastilles sous le titre. Après l’avoir vu à l’écran, la décision a été prise de revenir à l’affichage précédent : chaque publication garde sa ligne, avec son intitulé complet, ses chiffres et ses boutons. Rien d’autre ne change. Le classement des rubriques, les couleurs des chiffres et les tags restent ceux d’aujourd’hui.' },
  { id: 'dtpu-20260903-grille-controles', ts: Date.UTC(2026, 8, 3, 17, 0), title: 'Audit au millimètre : les commandes des volets tiennent désormais sur une seule grille', desc: 'Demande faite référence de terminal à l’appui : vérifier les incohérences de branding et d’interface, largeur des boutons comprise, au millimètre près. Un audit de ce genre ne peut pas être une opinion sur le goût — celui-là se règle par des captures. Il peut être une MESURE : deux commandes de la même famille, cote à côté dans le même panneau, doivent faire la même hauteur. Ce n’est pas une préférence, c’est ce qui distingue une grille d’un empilement. MESURE SUR LE DESK RÉEL, avant correctif : trois boutons de 33, 34 et 36,6 pixels DANS LE MÊME PANNEAU, et trois champs de saisie de 28,4, 31,2 et 35,1 pixels d’un volet à l’autre. Aucune de ces valeurs n’avait été choisie : elles tombaient d’une marge intérieure et d’une interligne écrites à des dates différentes. Le bouton Copier du lien de parrainage, lui, heritait de 42 pixels — le champ d’à côté gardait sa marge basse à l’intérieur d’une rangée ou les éléments s’etirent, et le bouton suivait. Les boutons et les champs des volets — profil, parrainage, assistant IA, support — partagent maintenant UNE hauteur, pilotée par un token, comme le bouton-icone des en-têtes l’avait été le 22 août. La largeur, elle, reste libre : un bouton principal à le droit d’être plus large que son voisin secondaire, c’est une hiérarchie. Deux hauteurs différentes n’en sont pas une. Un banc de contrôle ouvre le desk et relit les hauteurs peintes, pour que le prochain padding écrit ailleurs ne recasse pas l’alignement en silence.' },
  { id: 'dtpu-20260903-parrainage-retour', ts: Date.UTC(2026, 8, 3, 9, 0), title: 'Parrainage : le lien d’affiliation arrive même sans abonnement payant, et un mot de retour pour qui se réabonne', desc: 'PARRAINAGE — AUDIT ET CORRECTIF. Le panneau Parrainages n’affiche un lien que si Whop connait le client : on demande à Whop l’adhésion portant l’adresse du compte, on en tire le nom d’utilisateur, et le lien d’affiliation se construit avec. L’audit à trouve un défaut : cette recherche était filtrée sur le PRODUIT payant. Un compte AMI, OFFERT ou créé à la main n’a pas d’adhésion payante — il ne pouvait donc JAMAIS obtenir de lien, quoi qu’il fasse. Et le panneau lui demandait pourtant de rejoindre le Whop, ce qui ne changeait rien : rejoindre l’offre gratuite créé une adhésion à un AUTRE produit, invisible pour une requête filtrée. La promesse affichée était fausse pour ces comptes. Le serveur cherche désormais l’adhésion dans TOUT l’espace JustOneTrader quand le produit payant ne donne rien. RÉPONSE PRÉCISE À LA QUESTION POSÉE : quel Whop faut-il rejoindre ? PEU IMPORTE, et c’est maintenant écrit noir sur blanc dans le panneau — l’OFFRE GRATUITE SUFFIT. Le lien d’affiliation ne demande pas d’être abonne au produit vendu, il demande un compte Whop rattache à l’espace. Un bouton J’AI REJOINT — VÉRIFIER a été ajoute : le lien apparaissait jusqu ici au prochain rechargement de page, sans que rien ne le dise. Une adresse masquee par Apple est également reconnue, comme elle l’est déjà pour l’abonnement lui-même. Ce qui NE CHANGE PAS, et c’est volontaire : sans compte Whop, aucun lien n’est fabrique. Un lien interne ne verse aucune commission ; mieux vaut afficher les deux étapes d’inscription qu’un lien qui ne paiera jamais. UN MOT DE RETOUR POUR QUI SE RÉABONNE. Une reprise d’abonnement ne produisait aucun message dans le chat : le client rouvrait le desk sur son message de bienvenue d’inscription, un texte qui lui explique ce qu’il sait déjà. Il reçoit maintenant un mot de retour, et ce mot n’est pas le même au deuxième qu’au premier — le choix se fait sur un compteur de reprises, jamais au hasard, sinon deux reprises tireraient le même texte une fois sur quatre. Il part sur les DEUX chemins de réactivation, le webhook Whop et le panneau d’administration. Un renouvellement mensuel de routine, lui, ne declenche rien : écrire tous les mois à quelqu un qui n’a rien demande, ce n’est pas de l’attention, c’est du bruit.' },
  { id: 'dtpu-20260902-trait-horloge', ts: Date.UTC(2026, 8, 2, 23, 0), title: 'Le trait doré devant les titres de blocs est retiré, et l’Horloge mondiale montre enfin tout', desc: 'Deux corrections signalées capture à l’appui. LE TRAIT DORÉ DEVANT LES TITRES DE BLOCS DISPARAÎT — POUR LA SECONDE FOIS. Il avait été retiré sur demande le 19 août. Une règle d’extinction avait bien été posée, mais elle ne visait pas les titres des cartes du desk ; et surtout un bloc de finition écrit deux jours plus tard l’à REDESSINE pour toutes les familles de titres, plus bas dans la feuille de style. Le trait est donc revenu partout, y compris là où il n’avait jamais été demande. Cette fois la declaration est SUPPRIMée et non eteinte par-dessus : une extinction empilée se fait rallumer par le prochain bloc de finition, une declaration absente non. Un contrôle mesure désormais la position du texte dans son titre : un repère de deux pixels suivi de sa marge decalerait le texte de dix pixels, et cela se verrait immédiatement. L’HORLOGE MONDIALE MONTRE TOUT CE QU’ELLE AFFICHE. Troisième signalement du même défaut, et la cause était une contradiction interne : le widget à deux dispositifs d’adaptation posés à des dates différentes. Des requêtes de conteneur compactent le contenu quand la carte devient basse ; un plancher de rangée, ajoute plus tard, garantissait qu’une grille repliée n’ecrase pas ses cellules. Le plancher ne connaissait pas les paliers : sur une carte basse le contenu se compactait pendant que la rangée restait bloquee à 136 pixels. Mesure au banc : jusqu’à 72 pixels de contenu hors cadre, donc le pays, la météo et le vent de chaque place inatteignables autrement qu’en défilant. Le plancher suit maintenant la hauteur du cadre quand les places tiennent sur une seule rangée — rien ne dépasse — et reprend ses 136 pixels quand la grille se replie, ou le défilement reste le dernier recours voulu. Deux paliers de compaction manquaient entre les existants : ils sont ajoutes, et la dégradation est graduée — d’abord la typo, puis le vent, puis la météo, puis la date ; l’heure et la ville ne cedent jamais. Enfin, sur le modèle par défaut, l’horloge prend une rangée de plus (prise sur le panneau à onglets qui en a vingt-deux) : elle s’affiche entière, sans rien compacter, pour tout le monde.' },
  { id: 'dtpu-20260902-paire-recherche', ts: Date.UTC(2026, 8, 2, 21, 0), title: 'Le selecteur de paire du graphique se cherche : recherche, classes d’actif et drapeaux', desc: 'Le widget Graphique laisse choisir parmi trente-cinq symboles : les vingt-huit croisements des majeures, quatre indices, trois matières premières. Ils arrivaient dans une liste deroulante d’un seul tenant, sans regroupement ni recherche — trouver CAD/CHF s’y faisait à l’œil, ligne par ligne, et rien ne distinguait un indice d’une paire. Le menu reprend désormais ce que montre la référence fournie. UN CHAMP DE RECHERCHE, qui prend le focus des l’ouverture : trois lettres suffisent. Il ignore accents et majuscules. DES PUCES DE CLASSE D’ACTIF — Forex, Indices, Matières premières — qui se combinent à la recherche au lieu de l’annuler. ET UN DRAPEAU PAR DEVISE : une paire porte les deux drapeaux de ses devises, légèrement chevauchés comme sur le bandeau d’accueil ; un indice ou une matière première n’en porte aucun, il n’a pas de pays. Au clavier : Entrée prend la première entrée encore visible — après trois lettres il n’en reste souvent qu’une, exiger un clic serait absurde — et Echap referme sans rien choisir. UNE PRÉCISION SUR CE CORRECTIF. Un champ de recherche avait déjà été pose la veille sur les longues listes du panneau de réglages. Il ne couvrait pas celui-ci : la paire du graphique n’est pas rendue par le panneau mais par la barre du widget, une surface différente. L’écart a été relevé à l’audit et comble ici, avec son propre banc de contrôle pour qu’il ne se rouvre pas.' },
  { id: 'dtpu-20260902-donnees-autres', ts: Date.UTC(2026, 8, 2, 18, 0), title: 'Une neuvième rubrique de données : les publications des pays hors des huit ont enfin leur place', desc: 'Le desk classe les sorties de calendrier dans huit rubriques pays : Données US, EU, UK, Suisse, Japon, Canada, Australie, Chine. Une publication venue d’ailleurs — Suède, Norvège, Brésil, Mexique, Inde — n’avait aucune rubrique et tombait en Actualités mondiales. C’était le dernier trou du correctif du 31 août : depuis, une sortie de calendrier se reconnait à sa FORME et non à son vocabulaire, mais un garde-fou laissait repartir au fourre-tout toute ligne dont le pays n’était pas nommable. Le raisonnement tenait pour le PAYS — on ne le devine pas — mais pas pour la NATURE : que Swedish CPI Actual 2.1% Forecast 2.0% soit une publication est etabli par la signature elle-même. L’envoyer en Actualités mondiales était une erreur de classement, pas une prudence. Une neuvième rubrique est donc ajoutée : Données autres pays. POURQUOI AJOUTER PLUTÔT QUE FUSIONNER. L’autre solution était de remplacer les huit rubriques pays par une seule Calendrier économique. Elle bouchait le trou elle aussi, mais au prix du filtrage par pays — couper Données Chine en gardant Données US, ce que des clients font. Ajouter une rubrique ne change le sens d’aucun réglage déjà enregistre. Elle arrive ACTIVE pour tout le monde, y compris sur les comptes existants : la préférence est stockée en négatif côté serveur, et un rattrapage a été pose pour le cache local, qui garde lui la liste des rubriques actives et aurait lu l’absence de la neuvième comme un choix de l’utilisateur. Enfin, elle ne devient pas le nouveau fourre-tout : elle est posée APRÈS le test de signature, donc une dépêche sans chiffre n’y tombe jamais.' },
  { id: 'dtpu-20260902-frise-lisible', ts: Date.UTC(2026, 8, 2, 15, 0), title: 'Sessions de marché : la colonnade des heures traverse les quatre places, et les plages redeviennent des intervalles', desc: 'Suite de la refonte de la veille, sur retour utilisateur capture à l’appui : « amélioré la lisibilite et la visibilite ». Le widget remplissait bien son bloc, mais il le remplissait MAL — les plages horaires étaient devenues des dalles de 85 pixels de haut, l’horaire flottait au milieu d’un rectangle plein, et quatre aplats de couleur ecrasaient tout le reste de la carte. Trois corrections. LA TRAME DES 3 HEURES PASSE DU RAIL AU CORPS. Chaque piste portait sa propre trame verticale, qui s’arretait à son bord : quatre grilles indépendantes, et rien ne reliait 15 h de Londres à 15 h de New York — alors que lire un CHEVAUCHEMENT est la raison d’être de ce widget. C’est désormais une seule colonnade continue qui traverse les quatre places de haut en bas. Les rails deviennent transparents et la laissent passer : seule la PLAGE est peinte, parce que seule la plage est l’information. UNE PLAGE EST UN INTERVALLE, PAS UN APLAT. Moins de matière dans le remplissage, et un contour de la couleur de la place. Les BORNES — l’heure d’ouverture, l’heure de fermeture — redeviennent nettes, ce qui est justement ce qu’on vient chercher. La séance ouverte garde plus de matière que les fermées : c’est le seul contraste qui dise l’état sans emprunter le vert ni le rouge, réserves par la charte aux signaux de marché. L’ESPACE SE RÉPARTIT AU LIEU DE GONFLER LES BARRES. Les plages sont plafonnées à une hauteur lisible et le contenu de chaque ligne est centre : ce qui reste se partage moitié au-dessus, moitié au-dessous. La carte reste occupée d’un bord à l’autre, sans dalle et sans vide accumule en bas. Remplir n’est pas gonfler : les deux premières versions avaient chacune manque ce point d’un cote. Enfin, l’étiquette de l’heure courante ne se pose plus PAR-DESSUS la dernière plage : une bande lui est réservée en bas du cadre.' },
  { id: 'dtpu-20260902-alertes-chiffres', ts: Date.UTC(2026, 8, 2, 10, 0), title: 'Les alertes de calendrier montrent leurs trois chiffres, et chaque carte du desk dit sur quoi elle porte', desc: 'Deux améliorations de lecture, reprises de références fournies. UNE ALERTE DE CALENDRIER SE LIT EN TROIS CHIFFRES. Dans le volet Alertes, la sortie d’une donnée économique arrivait sous forme de phrase : Actual: 207K Forecast: 215K Previous: 219K, en gris, sur deux lignes tronquées. Trois nombres qu’il fallait aller chercher dans un texte, alors que la seule question posée par une publication est : au-dessus ou en dessous du consensus ? Ces trois valeurs s’affichent désormais en cases, sous le titre : RÉEL, PRÉVU, PRÉCÉDENT. Le réel prend la couleur du calendrier, et c’est la MÊME fonction qui la calcule — pas une seconde règle écrite pour le volet. Elle sait que pour les inscriptions au chômage un chiffre plus BAS que prévu est une bonne surprise, et qu’un chiffre sorti PILE au consensus est un troisième état, distinct d’une donnée qu’on ne peut pas juger faute de prévision. Deux règles de couleur pour la même donnée auraient fini par se contredire : le volet aurait dit l’inverse du calendrier sur le même chiffre. La prévision et le précédent restent neutres : ce sont des repères, pas des résultats. Et le tableau REMPLACE la description au lieu de s’y ajouter — cette description n’était que ces trois chiffres écrits en phrase. UNE ALERTE NON LUE SE VOIT SANS ÊTRE LUE. Le seul signe de non-lu était la teinte d’une pastille de 22 pixels à gauche, invisible dans une liste de trente lignes. La ligne porte maintenant un liseré à gauche et un point en haut à droite, là où l’œil arrive en fin de titre. Le point est OR et non rouge : la charte réserve le rouge au baissier et à l’alerte, et pas encore ouvert n’est ni l’un ni l’autre. CHAQUE CARTE DU DESK DIT SUR QUOI ELLE PORTE. L’en-tête d’une carte n’affichait que le nom du widget. Sur un desk qui accepte le même widget plusieurs fois — deux graphiques, deux tables de probabilités, deux horloges — deux cartes voisines portaient donc exactement le même titre, et il fallait ouvrir les réglages de chacune pour savoir laquelle montrait quoi. Le contexte s’écrit désormais à côté du nom, en or et entre crochets : GRAPHIQUE [EUR/USD - 1 h], SESSIONS [Horaires des places]. Au plus deux réglages, et seulement ceux qui IDENTIFIENT la carte : une bascule oui/non ou un nombre de lignes ne dit pas de quoi elle parle. Sur une carte étroite, c’est le contexte qui se tronque en premier, jamais le titre.' },
  { id: 'dtpu-20260901-frise-remplit', ts: Date.UTC(2026, 8, 1, 23, 30), title: 'Sessions de marché remplit désormais tout son bloc, et les longues listes de réglages se cherchent', desc: 'Deux améliorations d’ergonomie sur le desk personnalisable. SESSIONS DE MARCHE OCCUPE TOUT L’ESPACE QU’ON LUI DONNE. Le widget, vue Horaires des places, se dessinait à taille fixe : agrandir sa carte n’agrandissait rien du tout. Les quatre places restaient tassées en haut et la moitie basse du bloc restait vide — mesure au banc, une carte de 900 pixels laissait près de cinq cents pixels de vide sous New York. Les lignes se partagent maintenant la hauteur disponible, et c’est la PLAGE HORAIRE elle-même qui s’epaissit, pas l’écart entre les lignes. La différence n’est pas cosmétique : le nom d’une place reste colle à sa propre plage, ce qui n’était pas le cas d’une répartition qui aurait simplement écarté les lignes — on avait essayé, on ne savait plus quel bloc appartenait à qui. Une plage épaisse porte aussi son horaire écrit dedans lisiblement, et rend le chevauchement Londres-New York — la fenêtre de plus forte liquidité de la journée — visible d’un coup d’œil. En largeur, rien ne change de principe : la piste couvre toute la largeur utile et l’axe des heures reste aligne dessus au pixel, faute de quoi les plages mentiraient. Et le comportement inverse est preserve : sur une carte basse, un téléphone, un bloc réduit, les lignes ne s’ecrasent pas jusqu’à l’illisible — elles gardent une hauteur minimale et ce qui ne tient pas reste atteignable par un défilement, jamais coupe sans trace. UNE LONGUE LISTE DE RÉGLAGES SE CHERCHE AU LIEU DE SE PARCOURIR. Le selecteur de paire du widget graphique compte quarante-deux entrées, présentées en deux colonnes de pastilles qu’il fallait balayer à l’œil pour trouver CAD/CHF. Un champ Rechercher coiffe désormais ces listes, et il filtre à la frappe. Il n’apparaît qu’au-dela de quatorze entrées : trois unités de temps sous un champ de recherche seraient du bruit. La recherche ignore accents et majuscules — taper zurich trouve Zurich — sans quoi le champ punirait exactement la frappe rapide qu’il promet. Et une recherche sans résultat le DIT, au lieu de laisser un panneau vide sans explication.' },
  { id: 'dtpu-20260901-banques-noms', ts: Date.UTC(2026, 8, 1, 21, 0), title: 'Les banques centrales sont nommées en entier dans les réglages des widgets', desc: 'Les trois widgets qui laissent choisir une banque centrale — Taux directeurs, Prochaine réunion BC et la nouvelle Table des probabilités — ne proposaient que des sigles : Fed, BCE, BoE, BoJ, SNB, BoC, RBA, RBNZ. Il faut déjà les connaître pour choisir, et SNB était même reste en anglais dans un desk qui parle français. Les noms complets existaient pourtant depuis toujours du côté du serveur, et en français : Réserve fédérale, Banque centrale européenne, Banque d’Angleterre, Banque du Japon, Banque nationale suisse, Banque du Canada, Banque de réserve d’Australie, Banque de réserve de Nouvelle-Zélande. Ce sont eux qui s’affichent désormais, avec le sigle entre parentheses pour qui lit vite. Aucune donnée nouvelle, la même liste partout : trois sélecteurs dans le même desk ne peuvent pas nommer les mêmes banques de trois façons. Au passage, le dictionnaire de la version anglaise a été remis à jour : six entrées mortes ont été retirées — elles traduisaient les boutons de sortie vers les sites des banques, supprimes le 30/08 — et vingt-deux entrées ajoutées pour les textes neufs.' },
  { id: 'dtpu-20260901-frise-sessions', ts: Date.UTC(2026, 8, 1, 18, 0), title: 'Sessions de marché : l’état de chaque place se lit au bout de la ligne, et les plages ont pris de l’epaisseur', desc: 'Le widget Sessions de marché, vue Horaires des places, est repris sur une référence fournie. L’ÉTAT PASSE AU BOUT DE LA LIGNE. Le badge OUVERT ou FERME était colle au nom de la place, en petit texte gris. Les noms n’ayant pas la même longueur — Sydney, Tokyo, Londres, New York — le badge se retrouvait à quatre abscisses différentes, et il fallait le chercher ligne par ligne. Il se place désormais tout à droite, ou il forme une COLONNE : les quatre états se lisent d’un seul balayage vertical. Il redevient une pastille encadrée, comme les autres états du desk. Une précision assumée : la référence affiche le FERME en rouge ; notre charte réserve le rouge au baissier et à l’alerte, et un marché ferme n’est ni l’un ni l’autre. On prend le placement de la référence, pas sa couleur — le ferme reste neutre, l’ouvert garde son vert puisque lui est un état actif. LES PLAGES HORAIRES ONT PRIS DE L’EPAISSEUR. La piste faisait douze pixels : une reglette. Ce n’est pas une question de decoration — c’est la hauteur qui laisse l’horaire s’écrire DEDANS lisiblement au lieu de flotter sur un filet, et c’est elle qui rend le chevauchement Londres-New York, c’est-a-dire la fenêtre de plus forte liquidité de la journée, visible d’un coup d’œil. Les cartes basses et les téléphones gardent leurs hauteurs réduites : rien ne déborde sur un petit format.' },
  { id: 'dtpu-20260901-table-probabilites', ts: Date.UTC(2026, 8, 1, 15, 0), title: 'Nouveau widget Table des probabilités, et la grille de fond de Force des Devises se voit enfin', desc: 'UN NOUVEAU WIDGET : LA TABLE DES PROBABILITÉS. Le desk montrait jusqu ici ce que le marché price pour la PROCHAINE réunion d’une banque centrale — dans Taux directeurs et dans Prochaine réunion BC. La TRAJECTOIRE, elle, n’était visible nulle part : à partir de quelle réunion le marché cesse-t-il de croire au statu quo ? Le nouveau widget repond, banque par banque. Chaque ligne est une réunion à venir avec la probabilite d’une baisse, d’un maintien, d’une hausse, le mouvement implicite en points de base et le scénario de base. En tête, cinq repères : la banque, son taux en vigueur, la date de la prochaine réunion et le nombre de jours qui en séparent, le scénario de base avec sa probabilité, et le delta implicite. Juste en dessous, une barre montre la répartition des trois issues de cette prochaine réunion, à l’échelle. Sur chaque ligne, l’issue la plus probable est mise en avant : sur sept colonnes de chiffres, l’œil doit trouver l’issue dominante sans les comparer une à une. Les couleurs sont celles de la charte du desk, sans exception : hausse en vert, baisse en rouge, maintien en jaune-orange — les mêmes trois encres que les badges ACHAT VENTE NEUTRE et la matrice de biais. Ces chiffres ne disent pas ce qui VA arriver : ils disent ce qui est déjà dans les prix. Une hausse pricée à 95 pour cent ne fera pas bouger la devise le jour venu ; c’est l’écart entre la décision et ce qui était attendu qui la déplace. Une précision honnete : la donnée de notre fournisseur donne la répartition entre baisse, maintien et hausse pour chaque réunion, mais pas la distribution complète par NIVEAU de taux. Le widget rend donc la forme qu’il peut honorer entièrement plutôt qu’une matrice à trous. LA GRILLE DE FOND DE FORCE DES DEVISES SE VOIT. Elle existait, à une intensite si faible qu’elle était présente dans le code et invisible à l’écran. Sur huit courbes qui se croisent, une grille sert à SITUER — à quelle heure, à quel niveau — et une grille qu’on ne voit pas ne situe rien. Elle est désormais lisible d’un coup d’œil, tout en restant derrière le trace. Au passage, un défaut plus discret est corrigé : la grille verticale était figée en gris sombre pendant que l’horizontale suivait le thème. Sur le thème clair, l’une s’effaçait et l’autre non — un quadrillage à moitié peint, ce qui est pire que pas de quadrillage. Les deux partagent maintenant exactement le même style.' },
  { id: 'dtpu-20260901-tags-roles', ts: Date.UTC(2026, 8, 1, 9, 0), title: 'Chaque bouton d’une analyse à retrouve son role, et la poignée d’élargissement laisse la barre de défilement tranquille', desc: 'Deux corrections d’usage, signalées captures à l’appui. LE BOUTON INFO NE DÉROULE PLUS LE RAPPORT ENTIER. Sur une analyse d’événement — analyse PCE, analyse PIB — le panneau Info affichait les six sections du rapport : l’accroche, les chiffres cles, ce qui a surpris, la réaction de marché, les implications pour la banque centrale et l’impact marche. Six sections sous un bouton qui en promet une, pendant que les boutons Analyse et Impact marche, juste à côté, en repetaient des morceaux. Chaque bouton à désormais son role, exactement comme sur la référence fournie : INFO dit ce qui s’est passe — le fait, deux à quatre phrases, l’accroche que le desk écrit avant toute section. ANALYSE porte le dossier : chiffres cles, ce qui a surpris, réaction de marché, implications banque centrale. IMPACT MARCHE garde sa lecture prospective, et il est retiré du dossier pour ne pas être lu deux fois. Rien n’est perdu : ce qu’Info ne porte plus à simplement change de porte. Le decoupage est fait par le desk sur le texte DÉJÀ publié : aucune régénération, les analyses déjà en ligne se répartissent dès le premier affichage. Au passage, les intertitres de rubrique ne portent plus leur deux-points à l’affichage — le deux-points sert à les RECONNAÎTRE, pas à être lu, et la description d’une news le retirait déjà de son cote : le même texte se rendait donc de deux façons selon le panneau. LA POIGNÉE D’ÉLARGISSEMENT NE VOLE PLUS LA BARRE DE DÉFILEMENT. Sur une carte de widget dont le contenu défile, viser la barre de défilement attrapait la poignée Élargir. Ce n’était pas une impression : mesure, la poignée occupe les 9 pixels les plus à droite de la carte, la barre les 8 pixels les plus à droite du même bord — elles se recouvrent, et la poignée gagne puisqu elle se pose par-dessus. La sortir de la carte était impossible, le cadre etant en decoupe stricte : elle y serait rognée, donc inatteignable. Elle se décale donc vers l’intérieur de la largeur exacte de la barre, mais UNIQUEMENT sur une carte qui défile : une carte sans barre garde sa poignée au bord, là où la main la cherche.' },
  { id: 'dtpu-20260831-calendrier-categorie', ts: Date.UTC(2026, 7, 31, 23, 0), title: 'Les sorties du calendrier tombent dans leur rubrique, et l’analyse d’un chiffre porte le nom de son indicateur', desc: 'Deux correctifs sur les lignes de données économiques, signalés captures à l’appui. UNE PUBLICATION SE RECONNAIT À SA FORME, PLUS À SON VOCABULAIRE. La ligne US Core PCE Price Index MoM Actual 0.2% s’affichait en Actualités mondiales. La rubrique Données US existe pourtant depuis toujours : ce n’est pas une catégorie qui manquait, c’est le classement qui l’a ratée. Il travaillait sur une liste de mots écrite à la main — PIB, inflation, CPI, PPI, PMI, NFP, chômage, ventes au détail — ou le PCE ne figure pas, ni le terme indice des prix. La ligne traversait les quarante règles et tombait dans le fourre-tout. Le même trou valait pour l’ISM, le JOLTS, l’Ifo allemand, le ZEW, le Tankan japonais — et pour l’indicateur qu’on ajoutera demain : une liste de mots est toujours en retard d’une publication. Le desk ne cherche plus un mot mais une PROPRIÉTÉ : ces lignes portent toutes leur résultat face au consensus, Actual suivi de Forecast et Previous, une signature qu’aucune dépêche rédactionnelle ne porte. Le pays se lit en tête de l’intitulé, là où le fournisseur le met. Trois garde-fous : une décision de taux garde sa banque centrale plutôt que de basculer en données pays, un pays hors des huit rubriques existantes ne prend pas une rubrique au hasard, et un recit de marché — Euro surges as traders ignore soft German data — n’est jamais pris pour une publication. Aucune nouvelle catégorie n’a été créée. L’ANALYSE D’UN CHIFFRE PORTE DÉSORMAIS LE NOM DE SON INDICATEUR. Une ligne de calendrier affiche un tag drapeau plus nom de l’indicateur, dont le survol donne la definition. L’ANALYSE DTP de ce même chiffre ne l’avait pas : le lecteur voyait le tag sur la donnée brute, et plus rien sur le texte qui l’explique. Les rapports maison en étaient exclus en bloc, au motif que leur titre dit déjà tout — vrai d’un récap de séance, faux d’une analyse d’événement, dont le sujet EST un indicateur. Le nom est désormais pose par le desk et non devine du titre : celui-ci est en français, ANALYSE PIB US, alors que la table de reconnaissance lit l’anglais du calendrier. Le drapeau est celui de la devise de l’ÉVÉNEMENT et non de la paire exposée : la paire d’un chiffre americain etant EUR/USD, en deduire le drapeau aurait affiche celui de la zone euro. Les analyses de banque centrale n’en portent pas : leur sujet est une décision, pas un indicateur. Les analyses du jour sont régénérées pour en bénéficier immédiatement.' },
  { id: 'dtpu-20260831-semaine-description', ts: Date.UTC(2026, 7, 31, 20, 0), title: 'Semaine à Venir : la description de chaque journée se lit seule, et la ligne du calendrier ressort', desc: 'Deux améliorations de la page Semaine à Venir, demandées captures à l’appui. LA DESCRIPTION DE CHAQUE JOURNÉE CHANGE DE FORME. Elle était rédigée en télégramme — deux ou trois phrases courtes, denses, sans liant : correct, mais il fallait avoir le calendrier sous les yeux pour comprendre à quoi ressemblait la journée. Elle devient un paragraphe suivi qui SITUE d’abord la séance — ce qu’elle met en jeu, dans quel contexte elle tombe, une réunion de banque centrale, un sommet, le retour d’un chiffre attendu, ou simplement une séance plus calme — puis NOMME les publications au fil de la phrase, en clair et en français, et termine par ce qui ferait réagir les marchés, prévision face au précédent. Plus d’enumeration sèche de sigles : on lit la journée comme on lirait la note d’un stratégiste. Le TITRE, lui, ne change pas : il continue de nommer les événements concrets plutôt que de servir une formule d’ambiance. Les textes de la semaine en cours sont régénérés immédiatement, sans attendre la semaine suivante. LA LIGNE DU CALENDRIER RESSORT. Le calendrier de cette page est un fichier à part, avec sa propre feuille de style : il n’avait jamais reçu la grammaire de lignes du calendrier du desk et se contentait d’un survol plat, ce qui rend un tableau dense difficile à suivre sur huit colonnes. Trois crans, et pas un de plus — un tableau ou tout ressort est un tableau ou rien ne ressort. Au survol, la ligne s’allume et prend un liseré doré à gauche : on suit une ligne d’un bout à l’autre sans perdre le fil. Les événements à FORT impact portent un liseré rouge permanent : ce sont eux qui déplacent une séance, l’œil doit les trouver sans avoir à lire la colonne des points. Et la prochaine échéance porte l’or du desk — filets haut et bas, heure en or et en gras — exactement comme dans l’onglet Calendrier. Une seule ligne le porte : un repère qui se répète ne repère plus rien.' },
  { id: 'dtpu-20260831-reaction-repere', ts: Date.UTC(2026, 7, 31, 16, 0), title: 'Graphique de Réaction : le repère de publication se met à la taille de la bougie', desc: 'Retour client sur le graphique de Réaction d’une publication, capture à l’appui : le cercle rouge était trop petit par rapport à la bougie, et le trait vertical mal rendu. Trois corrections. LE CERCLE SUIT DÉSORMAIS LA BOUGIE. Il mesurait 46 pixels, fixes. Or la bougie de publication est justement celle qui decroche — c’est tout l’objet du panneau : le repère se retrouvait DEDANS, comme une pastille posée au hasard sur une barre au lieu de la désigner. Son diamètre suit maintenant l’amplitude haut/bas de la bougie, avec de l’air autour : la barre tient dans le cercle, elle ne le remplit pas. Deux bornes l’encadrent — un plancher, sans quoi une bougie plate n’aurait plus de repère du tout, et un plafond en fraction de la hauteur du cadre, sans quoi une mèche démesurée ferait un cercle plus grand que le graphique. Le fond du cercle a été allégé : c’est la bougie qu’on vient lire, le repère ne doit pas la teinter. LE TRAIT VERTICAL EST REFAIT. Il était declare en bordure pointillée d’un pixel — or les navigateurs dimensionnent les tirets sur l’epaisseur du trait : à un pixel, on obtient des tirets d’un pixel séparés d’un pixel, soit un pointille grésillant plutôt qu’un trait. Le motif est désormais écrit au pixel près, cinq pleins cinq vides. Et il n’est plus rouge : le rouge est la couleur du REPÈRE, deux rouges dans le même cadre dont un qui court sur toute la hauteur se disputent l’œil au lieu de désigner. Le trait redevient un guide neutre, le cercle garde l’accent. UN TROISIÈME TRAIT ROUGE A DISPARU, celui-là n’était même pas le notre : par défaut, la bibliothèque de graphiques trace un trait horizontal au cours de la dernière bougie, avec une étiquette sur l’axe, dans la couleur de cette bougie. Sur un graphique de réaction, cette dernière bougie est la fin d’une fenêtre de deux heures autour d’une publication passée : ce prix ne veut rien dire, et quand la bougie est baissiere le trait est rouge, sur toute la largeur. Il est retiré. Un contrôle automatique ouvre désormais le vrai graphique dans un vrai navigateur et RELIT LES PIXELS PEINTS — pas les propriétés de la feuille de style : il vérifie que le trait est bien peint, bien tireté et bien neutre, et que le cercle grandit avec la bougie au lieu d’être simplement plus gros qu’avant.' },
  { id: 'dtpu-20260831-surveiller-autres', ts: Date.UTC(2026, 7, 31, 10, 0), title: 'Récaps de séance : sous le calendrier, les autres échéances ont enfin leur intitulé', desc: 'Retour client, capture à l’appui. Dans la rubrique À surveiller d’un récap de séance, le calendrier de la séance suivante s’affiche en tableau — heure, devise, impact, attentes chiffrées. Juste en dessous venaient les fils encore ouverts relevés par la rédaction : résultats trimestriels d’une grande valeur, discours attendu d’un banquier central, indicateur d’inflation à venir. Ces lignes arrivaient NUES et COLLÉES à la dernière ligne du tableau, sans intitulé et sans le moindre espace. Deux défauts, et le second est le vrai : rien ne disait au lecteur si ces lignes commentaient le tableau ou parlaient d’autre chose. Elles portent désormais leur intitulé, Autres, séparé du tableau par un filet et par de l’air — exactement la grammaire que suivent déjà les rubriques Macro et Analyse de séance de ce même rapport : aucune puce sans son intitulé. Et avant de les intituler, le desk les DÉDOUBLONNE. Une ligne qui annonce un rendez-vous déjà liste dans le tableau juste au-dessus n’est pas un autre sujet, c’est une répétition. Sur la capture, la ligne qui annoncait l’indicateur d’inflation préfère de la Fed doublait la ligne du calendrier : elle disparaît, tandis que les résultats trimestriels et le discours à Jackson Hole — que le calendrier économique ne porte pas — restent. Le rapprochement est fait par le desk, jamais demande à la rédaction automatique, et il utilise l’anti-doublon déjà en place pour la rubrique Macro : le pays tranche d’abord, puis un sigle distinctif (PCE, CPI, ISM), puis les mots utiles en commun — le calendrier etant en anglais et les puces en français, la comparaison passe par un vocabulaire commun. Si tout ce que la rédaction a relevé figure déjà au calendrier, aucun intitulé Autres n’apparaît : la rubrique s’arrêté sur le tableau, ce qui vaut mieux qu’un titre qui répète la ligne du dessus. Tous les récaps de séance sont régénérés pour en bénéficier immédiatement.' },
  { id: 'dtpu-20260830-force-survol-retire', ts: Date.UTC(2026, 7, 30, 23, 0), title: 'Force des Devises : le survol ne masque plus les autres courbes', desc: 'La mise en avant au survol, ajoutée hier, est retirée. Passer la souris sur une devise gardait sa courbe pleine et estompait les sept autres, pour aider à suivre un trace au milieu des croisements. À l’usage, c’était une gêne et non une aide : dans ce panneau on ne suit pas UNE devise, on compare les huit — et le curseur se promène en permanence sur le graphique, donc l’effacement se declenchait tout le temps, sans avoir été demande. Une mise en avant permanente n’est plus une mise en avant. Les huit courbes gardent désormais leur intensite pleine, quoi que fasse la souris, sur la légende comme sur le trace. Ce qui reste : le croisillon et son point d’accroche colore, qui désignent la courbe visée sans rien effacer, et le mode focus — une seule devise en avant, les autres grisées — qui fait ce travail quand on le DEMANDE. Le contrôle automatique qui surveillait cette fonction n’a pas été supprime, il a été retourne : il glisse un vrai curseur sur une courbe, dans un vrai navigateur, et refuse la livraison si une seule des huit perd de son intensite.' },
  { id: 'dtpu-20260830-institutions-sans-source', ts: Date.UTC(2026, 7, 30, 21, 0), title: 'Plus aucun chemin vers la source dans les rapports d’institution', desc: 'Retour client, capture à l’appui : en tête d’un rapport KBC, la ligne Please click here to read the PDF version, le here en bleu souligne. Le nettoyage pose le 28/08 était pourtant bien en place — mais il nettoyait le TEXTE des rapports, celui que le desk affiche quand il reconstruit l’article. Or dès qu’une banque fournit un PDF, ou dès que sa page peut être rendue en PDF, le lecteur n’affiche PAS ce texte : il affiche le document. Le nettoyage était au bon endroit pour la mauvaise moitié du produit, et c’est la moitie que vous avez sous les yeux. Le rendu d’une page en PDF passe désormais par le même principe que le texte : aucune adresse n’y subsiste. Les phrases de renvoi vers le document d’origine sont retirées — cliquez ici, version PDF, télécharger, lire le rapport complet, et les lignes de desabonnement des lettres d’information. Tous les liens perdent leur adresse ET leur apparence de lien : la phrase reste lisible, le chemin disparaît, et il ne reste pas un bleu souligne qui ne mene nulle part. Les adresses écrites en clair dans le texte, typiquement en pied de page, partent aussi. Deux garde-fous : un paragraphe qui contient une image, un tableau ou un graphique n’est jamais retiré, et seuls les blocs COURTS qui portent une adresse sont considérés comme des renvois — un vrai paragraphe de rapport est plus long et ne porte presque jamais de lien. Tous les rapports déjà rendus sont régénérés : le correctif vaut immédiatement, y compris sur ce que vous avez déjà ouvert. LE PLUS DIRECT DE CES CHEMINS N’ÉTAIT PAS UNE TRACE OUBLIEE, C’ÉTAIENT NOS PROPRES BOUTONS. Un pied de page Lire l’original renvoyait au site de la banque sous chaque rapport reconstruit. Un bouton Ouvrir le rapport original, en or plein, s’affichait dès que notre chaîne d’affichage echouait. Et le PDF que le desk fabrique lui-même imprimait Source suivi du domaine de la banque en pied de CHAQUE page — celui-là survivait au desk, dans un fichier telecharge, indéfiniment. Les trois sont retirés. Une précision honnete sur ce qui change en echange : ce bouton servait à quelque chose, c’était la seule reprise possible quand un rapport ne s’affiche pas. La carte propose désormais de REESSAYER l’affichage sur place, et rappelle que les Éclairages, juste au-dessus, donnent la substance du rapport. Le contrôle automatique qui surveille tout ceci a été étendu : il ouvre maintenant une page dans un vrai navigateur, y execute le vrai nettoyage, relit le PDF produit, et vérifie qu’aucun bouton de sortie ne subsiste dans le lecteur.' },
  { id: 'dtpu-20260830-pictos-au-doigt', ts: Date.UTC(2026, 7, 30, 17, 0), title: 'Les pictogrammes du desk disent enfin ce qu’ils veulent dire sur téléphone, et le graphique de Réaction retrouve ses cotations', desc: 'Trois correctifs sortis du même audit tactile. D’ABORD LES PICTOGRAMMES MUETS. Plusieurs symboles du desk portent TOUTE leur explication dans une infobulle qui ne s’affiche qu’au survol de la souris : la double fleche de divergence du Radar de Biais, qui signale qu’une banque centrale est structurellement dans un sens quand le marché price l’inverse pour la prochaine réunion ; l’eclair du calendrier, qui dit qu’un chiffre est sorti SOUS l’estimation basse ; le Neutre par défaut d’un sous-indicateur, celui qui distingue un vrai Neutre d’une ABSENCE de publication ; et la ligne d’un sous-indicateur, dont l’infobulle portait la seule trace du chiffre qui fonde son badge — l’intitulé de l’événement, le réalise et l’attendu, dont rien n’est affiche. Ni iPhone ni Android n’affichent ce genre d’infobulle : sur téléphone le symbole restait, son sens disparaissait, et il n’existait nulle part ailleurs dans l’écran. Un appui sur le symbole ouvre désormais la même phrase dans une petite bulle, qui se referme au second appui, au défilement, ou d’elle-même. Elle se place sous le symbole, bascule au-dessus quand on est en bas de l’écran, reste entièrement visible près d’un bord, et sa pointe vise toujours le symbole concerne. Ces symboles sont minuscules — l’eclair fait neuf pixels de large : leur zone sensible est légèrement élargie au doigt sans que le dessin bouge. Sur ordinateur, rien ne change : l’infobulle du navigateur fait déjà le travail. ENSUITE UN SOUS-TITRE ROGNE. Dans une actualité depliee sur téléphone, le sous-titre d’une rubrique se decalait vers la gauche pour se détacher des puces — un décalage taille pour un grand écran, ou il puise dans une large marge. Sur téléphone cette marge n’existe plus, et le sous-titre sortait du cadre : on lisait npact marche, le I mange par le bord. Le décalage est désormais borne à la place réellement disponible. Sur grand écran il ne bouge pas d’un pixel. ENFIN LE GRAPHIQUE DE RÉACTION. Le panneau Réaction d’une publication affichait parfois Réaction indisponible, les cotations à la minute ne couvrent plus l’heure de cette publication — sur un chiffre de la matinée, soit quelques heures, là où ce message est censé signaler une publication trop ancienne. Le desk vérifiait que la série reçue contenait ASSEZ de bougies, pas qu’elle couvrait bien l’heure demandée : notre fournisseur pouvait rendre une séance entière, des centaines de bougies, qui commençait APRÈS cette heure-la. Le compte était largement atteint, le rattrapage prévu n’était donc jamais tente, et le lecteur voyait un message d’indisponibilité alors que la donnée existait à une requête de la. Le desk mesure désormais la COUVERTURE — une bougie avant, une bougie après — et ne va rechercher une plage plus large que lorsque cela sert vraiment.' },
  { id: 'dtpu-20260830-poignees-defilement', ts: Date.UTC(2026, 7, 30, 14, 0), title: 'Faire defiler la liste des onglets ne déplace plus un onglet par accident', desc: 'Correctif d’un défaut introduit ce matin en rendant le reordonnancement possible au doigt, et trouve par un audit tactile. Les poignées de déplacement forment une colonne presque continue sur le bord GAUCHE du volet des réglages : 37 pixels de large sur les trois quarts de la hauteur de la liste, avec à peine douze pixels libres entre deux. Un pouce qui descend ce bord pour faire DEFILER la liste ne peut pas la manquer — et le glissement partait immédiatement : la liste ne bougeait pas d’un pixel et un onglet changeait de place. Le geste le plus banal cassait l’ordre des onglets. Sur écran tactile, il faut désormais MAINTENIR la poignée une demi-seconde avant qu’elle se saisisse : la liste défile normalement, et seul un appui qui insiste soulevé la ligne. À la souris rien ne change, le glissement reste immédiat — on ne pose pas un curseur sur une poignée par hasard. La même correction s’applique à la liste des desks, qui à la même colonne de poignées. Deuxième correctif du même audit : lâcher un onglet AU-DESSUS de la liste, sur le titre du volet, ne faisait rien du tout. Or c’est exactement le geste de quelqu un qui veut remonter un onglet tout en haut : il y a 128 pixels sans aucune ligne au-dessus de la première, et le déplacement était abandonne sans le moindre signe. Lâcher au-dessus place maintenant l’onglet en premier, lâcher en dessous le place en dernier. Et comme relacher hors de la liste était jusqu ici la seule façon de renoncer à un déplacement commence, la touche Echap le fait désormais.' },
  { id: 'dtpu-20260830-commandes-visibles', ts: Date.UTC(2026, 7, 30, 11, 0), title: 'Des commandes qui n’apparaissaient jamais sur téléphone sont enfin visibles', desc: 'Plusieurs boutons du desk ne se montrent qu’au survol de la souris : ils restent invisibles au repos et apparaissent quand le curseur passe dessus. C’est confortable sur ordinateur, ça garde les listes calmes. Sur téléphone il n’y à pas de survol, et ces commandes produisaient deux défauts opposés — les deux sérieux. Certaines étaient INATTEIGNABLES : le bouton qui ouvre la fiche détaillée d’un trade dans le Journal — notes, captures d’écran, tous les champs — était rendu invisible ET traversant, si bien que la fiche entière était inaccessible depuis un téléphone. D’autres étaient INVISIBLES MAIS ACTIVES, ce qui est pire qu’une fonction manquante : la croix Supprimer ce trade repondait au doigt sans qu’on puisse la voir. Une suppression qu’on ne pouvait pas anticiper. Cinq commandes sont concernées et deviennent visibles en permanence sur écran tactile, à une intensite qui les montre sans les faire crier : ouvrir la fiche d’un trade, supprimer un trade, selectionner des lignes, retirer une capture d’écran d’une fiche, et le menu d’un message dans la messagerie — sans lui, on ne pouvait ni corriger ni retirer ce qu’on venait d’envoyer depuis un téléphone. Sur ordinateur, rien ne change : les listes gardent leur calme. Un contrôle automatique mesure désormais, sur un écran tactile simule, que plus aucune commande n’est invisible sous le doigt — ni inatteignable, ni piégeuse.' },
  { id: 'dtpu-20260830-desk-au-doigt', ts: Date.UTC(2026, 7, 30, 9, 0), title: 'Le desk se manipule au doigt : redimensionner, séparer, réordonner', desc: 'Après le correctif des onglets, un audit complet à passe au doigt tout ce que le desk laisse deplacer. Quatre gestes ne répondaient qu’à la souris, et cela ne se voyait pas : ils sont bien la, visibles, ils ne font simplement rien sous un doigt. REDIMENSIONNER UNE CARTE. Le coin et le bord droit d’une carte ne répondaient pas au toucher. Une règle avait été posée pour rendre le défilement à ces poignées, en supposant qu’elles n’avaient aucun gestionnaire tactile — elles en ont un, et cette règle supprimait donc le geste au lieu de le libérer. La gêne qui l’avait motivée était pourtant réelle : la poignée du bord droit courait sur toute la hauteur de la carte, soit une colonne de 500 pixels ou la page ne defilait plus. Ce n’était pas le geste qu’il fallait retirer mais la bande qu’il fallait raccourcir : elle devient un segment centre, le redimensionnement revient et les trois quarts de la hauteur redeviennent defilables. LA BARRE DE SÉPARATION du desk, et celle qui règle la hauteur des horloges, n’ecoutaient que la souris : sur tablette tactile elles étaient visibles et immobiles. Elles ecoutent désormais le pointeur, qui couvre la souris, le doigt et le stylet. LA BARRE D’ONGLETS du haut : l’appui long armait bien l’onglet, puis le navigateur reprenait le geste et rien ne bougeait. La barre continue de defiler normalement, mais refuse le défilement le temps d’un déplacement engage. LES COLONNES DU JOURNAL annonçaient un glisser qui ne peut pas aboutir au doigt : l’invitation est retirée sur écran tactile et l’infobulle renvoie au menu de chaque colonne, qui fait déjà le travail. DEPLACER UNE CARTE DU DESK. C’est le geste qui manquait le plus, et le moins visible : sous 560 pixels de large la grille passe à UNE colonne, donc l’ordre des cartes EST toute la disposition — et il n’existait aucun repli, ni monter ni descendre dans les réglages. Sur téléphone, on ne pouvait tout simplement pas rearranger son desk. On maintient désormais l’en-tête d’une carte une demi-seconde : elle se souleve, on la fait glisser ou l’on veut, on releve. L’appui est volontairement insistant parce que cet en-tête sert AUSSI à faire defiler le desk : un glissement franc fait defiler comme avant, seule une pression qui insiste soulevé la carte. AU PASSAGE, un décalage de 11 pour cent entre le curseur et le bord d’une carte pendant un redimensionnement a été corrigé : la carte était mesurée dans une unité et le geste dans une autre. Et toutes les cibles du volet des onglets sont passées au gabarit du doigt. Un contrôle automatique ouvre désormais le desk sur un écran tactile simule et y conduit de VRAIS gestes du doigt. C’est le point important : le contrôle précédent fabriquait les événements de glissement, ce qui réussit toujours — même quand un vrai doigt n’en produirait aucun.' },
  { id: 'dtpu-20260829-onglets-au-doigt', ts: Date.UTC(2026, 7, 29, 23, 0), title: 'Réordonner ses onglets et ses desks fonctionne enfin au doigt', desc: 'Sur téléphone, la poignée de déplacement des onglets d’un panneau ne repondait pas : on pouvait la toucher, la maintenir, glisser vers le haut, rien ne bougeait. La cause est technique mais nette : le déplacement reposait sur le glisser-deposer natif des navigateurs, un mecanisme qui n’existe tout simplement pas au toucher — sur iPhone comme sur Android, un doigt pose sur un élément deplacable ne declenche jamais le debut du glissement. Le geste n’atteignait donc jamais le code de reordonnancement, qui était par ailleurs correct. Sans clavier physique pour utiliser les fleches haut et bas, il n’y avait aucun moyen de réordonner ses onglets depuis un téléphone. Le déplacement passe désormais par les événements de pointeur, qui couvrent la souris et le doigt d’un seul mecanisme : on pose le doigt sur la poignée, on glisse, la ligne visée s’eclaire, on releve. La ligne qu’on déplacé s’estompe pendant le geste pour qu’on voie ce qu’on tient — à la souris, le navigateur dessinait ce repérage lui-même, il fallait le refaire. Un simple appui reste un appui : il faut bouger de quelques pixels pour que le glissement commence. Et tout le volet passe au gabarit du doigt sur écran tactile, sans rien changer au bureau : la zone de prise de la poignée passe de 10x15 à 27x33 pixels sans que le symbole grossisse, les lignes de la liste de 27 à 36 pixels de haut, et la croix de suppression de 22 à 31. La poignée et cette croix se touchaient à quatre pixels près : de quoi supprimer un onglet en croyant le deplacer. Au passage, un défaut plus ancien a été trouve : la liste des desks du gestionnaire ne se reordonnait plus DU TOUT, ni au doigt ni à la souris. Le code y cherchait un nom de ligne qui avait été renomme ailleurs, et cherchait donc dans le vide depuis ce renommage. Les deux listes partagent maintenant la même mecanique. Enfin le contrôle automatique qui surveillait ce geste a été refait : il ouvrait bien un vrai navigateur, mais il FABRIQUAIT les événements de glissement au lieu de les laisser naître d’un vrai geste — un événement fabrique arrive toujours, même quand le navigateur ne l’emettrait jamais. Il conduit désormais un vrai doigt sur un écran tactile simule, et un vrai pointeur de souris, sur les mêmes gestes.' },
  { id: 'dtpu-20260829-force-lisibilite', ts: Date.UTC(2026, 7, 29, 20, 0), title: 'Force des Devises : les huit courbes, et les huit devises, se voient enfin d’un coup d’œil', desc: 'Le panneau Force des Devises a été repris après un retour client : on n’y distinguait ni toutes les courbes ni toutes les devises. Le défaut principal était invisible à la lecture du code. Quand une devise decroche nettement, le graphique resserre son cadre sur les autres pour qu’elles restent lisibles — et la devise partie loin perdait alors NON SEULEMENT sa courbe mais son étiquette : plus de nom, plus de valeur, elle disparaissait du panneau. Mesure au banc : sept étiquettes sur huit, parfois six. L’étiquette est désormais ramenée au bord du cadre et porte un petit chevron qui indique que la courbe continue au-dela ; sa valeur réelle reste affichée. Les huit devises sont nommées quel que soit le cadrage. Ensuite, la place. Quand le cadre ne se resserre pas, il était laisse à l’ajustement automatique, qui arrondit à des bornes rondes : les courbes tenaient dans 40% de la hauteur, le reste était du vide. Le cadre epouse maintenant les données et rend près de la moitie de la hauteur au trace. La légende du haut, qui passait à deux lignes sur un panneau étroit, tient sur une ligne des 380 px de large. Sur les cartes courtes, les huit étiquettes se recouvraient et la dernière sortait du cadre : elles se placent désormais d’après leur taille réelle et passent en mode compact quand la carte est trop basse. Nouveau geste, le plus utile au quotidien : survoler une devise dans la légende, ou simplement promener la souris sur le graphique, met la courbe visée en avant et estompe les sept autres. Huit courbes qui se croisent trente fois ne se demelent pas par la couleur seule ; on suit maintenant une devise du regard sans perdre le contexte. Le mode clair avait un défaut sérieux : six couleurs sur huit passaient sous le seuil de lisibilité sur fond blanc, et le Dollar americain, blanc casse, y était invisible. Le mode clair à désormais sa propre palette, plus foncée, avec la même identité de couleur par devise, et le texte des étiquettes se calcule sur la couleur de chacune. Enfin, plusieurs détails qui genaient sans qu’on sache dire quoi : les chiffres de l’échelle qui depassaient de derrière les étiquettes sont franchement masques au lieu d’être coupes en deux ; l’axe des heures gagne un pas de 2 heures — sur un panneau étroit il ne restait que deux heures lisibles — et son premier libellé n’est plus rogne par le bord ; et la bande invisible qui sert à étirer l’échelle à la souris epouse enfin la largeur réelle de la colonne de droite au lieu de mordre sur le graphique.' },
  { id: 'dtpu-20260828-seance-classes', ts: Date.UTC(2026, 7, 28, 19, 0), title: 'Analyse de séance : chaque ligne rangée dans sa classe d’actif', desc: 'La rubrique Analyse de séance d’un récap alignait le Dollar, le Kiwi, le Franc suisse, une mesure commerciale canadienne, les matières premières, les obligations et les actions dans une seule liste : sept sujets sans rapport à la suite, qu’il fallait trier à l’œil. Elle se range désormais comme la rubrique Macro, sous ses propres intitulés — Devises, Obligations, Matières premières, Actions, Crypto, Commerce. Le classement est fait par le desk sur ce que la rédaction a écrit, jamais demande à la rédaction automatique : elle ne peut donc ni inventer une catégorie ni en oublier une. C’est le SUJET de la ligne qui decide, pas ce qu’elle mentionne au passage — une annonce de contre-tarifs chiffrée en milliards de dollars est une ligne Commerce, pas une ligne Devises. Et quand toute la rubrique tient dans une seule classe, aucun sous-titre n’apparaît : il n’apprendrait rien.' },
  { id: 'dtpu-20260828-rapports-sans-liens', ts: Date.UTC(2026, 7, 28, 23, 0), title: 'Les rapports d’institution ne renvoient plus vers l’exterieur', desc: 'Au milieu du corps de certains rapports subsistaient des renvois vers le document d’origine — Please click here to read the PDF version, une adresse écrite en clair, un lien sur un nom de domaine. Le desk retirait déjà les formules connues, une par une, mais une liste de formules ne couvre jamais la banque suivante ni la prochaine refonte d’une page. La règle est désormais une propriété, pas une formule : dans le corps d’un rapport d’institution, il ne reste aucune adresse. Un lien devient son propre texte — la phrase reste lisible, le chemin disparaît — et un lien dont le texte EST l’adresse s’efface entièrement, comme les adresses écrites en clair ; le paragraphe que le retrait à vide part avec elles. Le nettoyage s’applique à la lecture, donc il vaut aussi pour tous les rapports déjà en ligne, sans rien avoir à régénérer. Les récaps de séance, eux, gardent leurs liens : la liste des sources d’un récap est une fonction du produit.' },
  { id: 'dtpu-20260828-dates-rapports', ts: Date.UTC(2026, 7, 28, 22, 0), title: 'Les rapports affichés n.d. vont chercher leur date dans trois endroits de plus', desc: 'Certaines banques ne datent pas les publications de leur liste. Le desk allait alors chercher la date sur la page du rapport, et quand elle n’y figurait pas non plus, la colonne Date affichait n.d. — definitivement : plus rien ne reexaminait la question. Trois lectures sont ajoutées. La date écrite dans l’adresse du document, quand elle y est : elle y est mise par l’éditeur, elle ne bouge plus, et la lire ne coute aucune requête. La date imprimée EN TÊTE du document lui-même, lue au moment ou vous ouvrez le rapport, sur le texte déjà extrait — une note institutionnelle porte presque toujours sa date sous son titre, en anglais comme en français. Et la date affichée sur une page dont la source n’est pas encore étudiée, acceptée uniquement si toute la page s’accorde sur une seule date : plusieurs dates à l’écran, ce sont les vignettes des publications liées, et le desk s’abstient plutôt que d’en choisir une au hasard. La règle de fond ne change pas — mieux vaut n.d. qu’une date inventée — mais elle ne s’applique plus qu’après avoir vraiment cherche. Toutes les publications actuellement sans date sont reexaminées automatiquement, et le journal du desk nomme désormais les institutions qui restent muettes.' },
  { id: 'dtpu-20260828-synthese-recit', ts: Date.UTC(2026, 7, 28, 21, 0), title: 'Les récaps de séance s’ouvrent sur le même paragraphe de synthèse que le Récap Quotidien', desc: 'Un récap de séance commençait par une accroche en puces, en texte nu, puis par le decompte des publications de la séance. Le Récap Quotidien, lui, ouvre sur un vrai paragraphe : le dossier qui a domine la journée, ce que les banques centrales et les chiffres ont dit, quelles devises en sortent gagnantes ou perdantes, et le lien de cause à effet entre les deux. Les récaps de séance ouvrent désormais sur ce même paragraphe, dans le même encadre a liseré doré. Les deux lignes chiffrées — nombre de publications, sorties hors consensus, mouvement le plus marque, photo de séance — restent, mais derrière le recit : elles l’étayent au lieu de le remplacer. Les rapports de la journée sont régénérés pour en bénéficier immédiatement.' },
  { id: 'dtpu-20260828-macro-souspartie', ts: Date.UTC(2026, 7, 28, 20, 0), title: 'Récap Quotidien : plus une seule ligne de la rubrique Macro sans sa catégorie', desc: 'La rubrique Macro du Récap Quotidien s’ouvrait parfois sur deux ou trois puces posées sans intitulé — une mesure commerciale, un prix du brut — avant le premier sous-titre. Ce sont les sujets qui ne relèvent d’aucune des quatre catégories du Radar de Biais : ils n’avaient pas de titre à eux et arrivaient donc nus. Ils ont désormais le leur, Commerce et Autres, en fin de rubrique, après Politique monétaire, Inflation, Croissance économique et Emploi. Chaque ligne de la rubrique dit maintenant de quoi elle parle, exactement comme dans les récaps de séance. Un contrôle automatique ouvre le rapport dans un vrai navigateur avant chaque livraison et refuse une puce posée avant son sous-titre.' },
  { id: 'dtpu-20260828-recap-autres', ts: Date.UTC(2026, 7, 28, 18, 0), title: 'Récap Quotidien : une rubrique Autres éléments notables, et le conditionnel pour ce qui '+ 'n est pas confirme', desc: 'Deux améliorations du Récap Quotidien, tirées d’une comparaison ligne à ligne avec un récap de référence. D’abord une nouvelle rubrique, Autres éléments notables, entre Géopolitique et Macro : les faits réels de la journée qui ne relèvent ni du dossier géopolitique ni des chiffres — une mesure commerciale annoncée par un pays, un projet d’infrastructure d’État, une rencontre politique programmée. Ils étaient jusqu ici ecrases dans la géopolitique, ou ils n’avaient rien à faire, ou purement perdus. Ensuite, une règle d’écriture : ce qui est rapporte sans être confirme s’écrit désormais au conditionnel — aurait transmis, poursuivrait, envisageraient — et ce qui est etabli à l’indicatif. Un fait rapporte écrit à l’indicatif devient un fait acquis, et cette confusion-la est invisible à la lecture. Quand deux sources se contredisent, les deux sont écrites et la divergence remonte dans les points cles. Le mail Point Marche suit les mêmes rubriques.' },
  { id: 'dtpu-20260828-lisibilite-aide', ts: Date.UTC(2026, 7, 28, 14, 0), title: 'Volet d’aide des widgets : titres en or, texte en blanc', desc: 'Le volet qui explique un widget — ce qu’il montre, comment le lire, d’où vient la donnée, ce qu’il faut surveiller — s’affichait en gris sur gris : les intertitres se distinguaient à peine du texte et le volet se lisait comme un bloc continu. Les intertitres passent en or et le texte en blanc, la même grammaire que les rubriques de rapport. Le mode clair garde ses propres teintes, l’or vif passant sous le seuil de lisibilité sur fond blanc. Autre réglage : le liseré doré sous l’onglet actif d’un Panneau à onglets est légèrement attenue — il tapait à l’or plein, la même encre que les valeurs de marque, pour ne signaler qu’une position de navigation.' },
  { id: 'dtpu-20260828-support-photo-texte', ts: Date.UTC(2026, 7, 28, 9, 0), title: 'Le support à son visage, et un message d’accueil qui va droit au but', desc: 'La photo affichée à côté des messages du support se change désormais depuis le panneau d’administration, en deux clics : elle s’applique à tous les clients dans la minute, sans mise à jour de la plateforme ni cache à vider. Elle était jusqu ici figée dans le code, et pointait même sur une banque d’images exterieure. Le recadrage carre et la compression sont faits au moment de l’envoi, avec une fenêtre remontée vers le visage — sur une photo de bureau, un cadrage centre coupe la tête. Et le message d’accueil envoye aux nouveaux clients passe de cinq paragraphes à quatre lignes : l’accès est ouvert, trois portes d’entrée concrètes, et la phrase qui compte vraiment — écrivez ici. L’inventaire de neuf fonctionnalités d’une traite ne se lisait pas.' },
  { id: 'dtpu-20260827-surveiller-tableau', ts: Date.UTC(2026, 7, 27, 21, 0), title: 'À surveiller affiche le vrai calendrier du desk', desc: 'Dans les récaps de séance, la rubrique À surveiller listait les prochains rendez-vous sous forme de phrases. Elle affiche désormais LE calendrier lui-même, celui du desk : séparateurs de journées, heure de Paris, drapeau, points d’impact, prévision et précédent — et chaque ligne s’ouvre d’un clic sur son Decryptage DTP, exactement comme dans l’onglet Calendrier et dans le Récap Quotidien. Les deux rapports utilisent maintenant la même fabrique de tableau : ils ne peuvent plus diverger. Les fils encore ouverts relevés par la rédaction restent affichés sous le tableau. Au passage, les colonnes Haut et Bas ont été retirées des tableaux de rapport : elles portent une fourchette d’estimations que notre fournisseur ne remplit pas pour les rendez-vous à venir, et affichaient donc deux colonnes de tirets qui volaient de la place à l’intitulé.' },
  { id: 'dtpu-20260827-avatar-support', ts: Date.UTC(2026, 7, 27, 22, 0), title: 'Le support prend le visage de l’équipe DTP', desc: 'La photo affichée à côté des messages du support était une image de banque d’images, chargée depuis un site tiers à chaque ouverture de la conversation. Elle est remplacée par la photo de l’équipe DTP, hébergée par nos soins : elle s’affiche pour tous les clients, et la remplacer plus tard mettra tout le monde à jour d’un coup. Le cadrage se fait sur le visage et non au centre de l’image, pour que la pastille ronde montre bien la personne. Si la photo ne peut pas être chargée, les initiales DTP s’affichent comme avant.' },
  { id: 'dtpu-20260827-mdp-oublie', ts: Date.UTC(2026, 7, 27, 19, 0), title: 'Mot de passe oublie : plus aucun risque de rester bloque dehors', desc: 'Un défaut vient d’être corrigé sur la réinitialisation du mot de passe. L’ancien fonctionnement changeait le mot de passe en base PUIS tentait d’envoyer l’e-mail — et si cet envoi echouait, rien ne le signalait : l’ancien mot de passe était déjà detruit et le nouveau n’arrivait jamais. L’ordre est désormais inverse. L’e-mail part d’abord ; le mot de passe n’est remplace que si l’envoi a bien été accepté. Un envoi qui echoue ne coute donc plus rien : le compte n’a pas bouge, l’ancien mot de passe fonctionne toujours, et la demande peut être refaite immédiatement — la temporisation de deux minutes est levée dans ce cas au lieu d’ignorer les nouvelles demandes en silence. Le message affiche après la demande a aussi été raccourci de moitié.' },
  { id: 'dtpu-20260827-identite-rapports', ts: Date.UTC(2026, 7, 27, 17, 0), title: 'Les récaps de séance adoptent l’identité visuelle du Récap Quotidien', desc: 'Les deux rapports se lisent souvent à la suite : ils se presentent désormais pareil. La synthèse d’un récap de séance s’affiche dans le même encadre a liseré doré que celle du Récap Quotidien, au lieu d’une simple liste à puces. Les titres de rubrique — Synthèse, Géopolitique, Macro, Analyse de séance, À surveiller — portent le même petit liseré doré vertical, la même taille et les mêmes marges. Et le filet horizontal qui doublait la bordure sous chaque titre a été retiré : il n’existait pas dans le Récap Quotidien et faisait deux traits là où il en faut un. Ces réglages ne sont plus écrits deux fois dans la feuille de style mais une seule, partagée par les deux rapports : ils ne peuvent plus diverger à la prochaine retouche.' },
  { id: 'dtpu-20260827-synthese-seance', ts: Date.UTC(2026, 7, 27, 15, 0), title: 'Chaque récap de séance s’ouvre sur une synthèse chiffrée', desc: 'Le récap de séance commençait directement par le recit : les rumeurs ont pèse sur le dollar, les sources de la banque centrale indiquent... Aucune ligne ne disait ce que la séance avait FAIT. Il s’ouvre désormais sur une Synthèse, comme le Récap Quotidien : combien de publications sont tombées pendant la séance, combien sont sorties hors consensus, et quel a été le mouvement le plus marque. Juste en dessous, la photo de séance donne la performance réelle des marchés de cette séance sur sa fenêtre horaire. Les deux lignes sont calculées à partir de nos propres mesures, jamais rédigées automatiquement, et elles n’apparaissent que si le desk à effectivement mesure quelque chose : sans données, le rapport reste exactement celui d’avant.' },
  { id: 'dtpu-20260827-datas-couleurs', ts: Date.UTC(2026, 7, 27, 12, 0), title: 'Les chiffres publiés prennent la couleur de leur verdict', desc: 'Dans les récaps, une donnée sortie AU-DESSUS de son consensus s’affiche désormais en vert, EN DESSOUS en rouge, et CONFORME aux attentes en jaune-orange — les trois mêmes couleurs que les badges ACHAT VENTE NEUTRE et la matrice de biais, pour n’avoir qu’une seule grammaire de couleur à lire. Une hausse de taux est verte, une baisse rouge, un maintien neutre. Le calcul est fait par nos règles à partir des chiffres écrits dans la puce, jamais laisse à l’appréciation de la rédaction automatique. Les indicateurs INVERSES sont traités comme il se doit : pour le chômage, les inscriptions, les stocks ou un deficit, un chiffre au-dessus du consensus est une mauvaise nouvelle et sort donc en rouge. Une puce qui ne porte ni comparaison ni verdict reste blanche : mieux vaut pas de couleur qu’une couleur fausse. La couleur s’ajoute au gras, elle ne le remplace pas.' },
  { id: 'dtpu-20260827-surveiller-calendrier', ts: Date.UTC(2026, 7, 27, 13, 0), title: 'À surveiller affiche le calendrier de la séance suivante', desc: 'La rubrique À surveiller d’un récap de séance annoncait des choses comme la réaction continue du marché aux rumeurs ou les prochaines declarations de la Fed : du prospectif sans heure ni chiffre, donc inactionnable. Elle ouvre désormais sur LE CALENDRIER de la séance qui vient — Londres après l’Asie, New York après Londres, l’Asie du lendemain après New York — avec pour chaque rendez-vous son heure de Paris, sa devise, son nom exact du calendrier, le consensus et le précédent. Les fils encore ouverts que la rédaction avait relevés restent en dessous : une échéance datée passe avant une attente vague. La rubrique est créée si le récap n’en avait pas, et reste en fin de rapport. Elle n’est posée que sur un récap du jour : annoncer des échéances à venir dans un rapport relu le lendemain n’aurait aucun sens.' },
  { id: 'dtpu-20260827-analystes-rapide', ts: Date.UTC(2026, 7, 27, 10, 0), title: 'L’onglet Analystes s’ouvre immédiatement', desc: 'L’onglet Analystes restait plusieurs secondes sur Chargement des rapports avant d’afficher quoi que ce soit. Deux causes, corrigées ensemble. Le desk attendait ses quatre sources ENSEMBLE avant de dessiner la liste : il suffisait que l’une soit lente pour que tout attende, alors que les trois autres avaient déjà répondu et que le cache de votre navigateur avait de quoi remplir la page dès la première milliseconde. La liste s’affiche désormais tout de suite avec ce qui est déjà connu, puis chaque source la complète des son arrivée. Et la source lente, celle des rapports hebdomadaires et quotidiens, attendait systématiquement un aller-retour avec le stockage distant avant de repondre — elle ne le fait plus que lorsqu elle n’a réellement rien a servir. Les rapports hebdomadaires sont en outre gardes en cache local comme les autres : ils étaient les seuls à n’avoir aucun repli instantane.' },
  { id: 'dtpu-20260827-heures-calendrier', ts: Date.UTC(2026, 7, 27, 8, 0), title: 'Calendrier : les heures passent en blanc', desc: 'La colonne des heures du calendrier s’affichait dans un gris légèrement bleuté, volontairement en retrait pour que l’intitulé de l’événement se lise en premier. Elle passe en blanc, comme demande. La hiérarchie de lecture ne disparaît pas pour autant : elle tenait déjà à la police à chasse fixe, à la taille et à la graisse, et une colonne de chiffres alignes se balaie de toute façon comme une colonne. L’heure de l’événement en cours reste en or et en gras — c’est désormais le seul accent de la colonne, donc il ressort davantage. Les publications déjà tombées gardent leur retrait, mais en blanc attenue plutôt qu’en gris teinte : toute la colonne est de la même teinte. Le mode clair n’est pas concerne.' },
  { id: 'dtpu-20260827-quotidien-lit-seances', ts: Date.UTC(2026, 7, 27, 6, 0), title: 'Le Récap Quotidien lit enfin les récaps de séance de la journée', desc: 'Le Récap Quotidien devait ouvrir sur le fil de la journée séance après séance, en reprenant les récaps Asie, Londres et New York. Il ne les voyait pas : le filtre qui les cherchait reposait sur un marqueur interne que seul un autre rapport porte, si bien que l’introduction se construisait sur cette seule synthèse et que les trois récaps de séance étaient écartés du rapport comme du reste de son corpus. Ils y entrent maintenant, avec la place qu’ils méritent : leur résumé porte la synthèse de séance, la photo des marchés sur la fenêtre horaire et les publications rangées par famille, et il était coupe à trois cents caracteres quand il en avait besoin de neuf cents. Le fil de la journée du Récap Quotidien s’appuie donc désormais sur ce que le desk à réellement publié pendant la journée.' },
  { id: 'dtpu-20260827-coherence-quotidien', ts: Date.UTC(2026, 7, 27, 4, 0), title: 'Le Récap Quotidien et les récaps de séance disent enfin la même chose', desc: 'Les deux rapports lisent le même calendrier, mais quatre détails les faisaient diverger. Les noms : le Récap Quotidien servait les intitulés bruts du fournisseur, quand l’onglet Calendrier, la Semaine à Venir et les récaps de séance affichent tous le nom ForexFactory — un même chiffre pouvait donc porter deux noms selon le rapport ouvert. Le classement par famille : la partie Données du jour utilisait sa propre liste de quatre catégories, sans Politique monétaire, si bien qu’une décision de taux ou les minutes du FOMC tombaient dans Autres, et la catégorie s’appelait Croissance ici et Croissance économique deux blocs plus bas. Le rattachement à une séance : il se faisait sur la seule devise, alors que les récaps de séance travaillent sur des plages horaires — une publication de la zone euro sortie à 22h se lisait sous Londres sans apparaître dans aucun récap de séance. Et les chiffres : point decimal anglais d’un cote, virgule française de l’autre. Les quatre sont alignes, y compris dans l’e-mail Point Marche.' },
  { id: 'dtpu-20260827-style-puces', ts: Date.UTC(2026, 7, 27, 2, 0), title: 'Récaps de séance : le mot Sources disparaît, et le gras ne coupe plus les heures', desc: 'Trois détails de lecture, corriges ensemble. Une puce qui commençait par Sources BCE : commence maintenant directement par BCE : — un desk nomme sa source, il ne l’annonce pas, et c’est le style de toutes les autres puces. La règle ne s’applique que devant un vrai nom d’institution : une formulation comme Source proche de la BCE garde son sens, le mot y porte l’information. Ensuite, la mise en gras automatique des chiffres coupait certains mots en deux : 14h15 sortait avec 14 en gras et h15 en maigre, et un écart comme +0,3 pt voyait son gras s’arrêter juste avant son unité. Le gras s’arrêté désormais au bord du mot. Enfin, les valeurs reprises du calendrier s’ecrivent avec la virgule française : 11,75K et non 11.75K, au milieu de puces qui ecrivent déjà 0,6%.' },
  { id: 'dtpu-20260826-macro-aucune-orpheline', ts: Date.UTC(2026, 7, 27, 0, 0), title: 'Récap de séance : plus aucune publication sans sa catégorie', desc: 'Dans la rubrique Macro d’un récap de séance, les publications qui ne relevaient d’aucune des quatre grandes catégories s’affichaient en tête, sans intitulé. Quand elles étaient les seules de la rubrique — une séance calme avec une seule publication — la rubrique sortait donc avec une ligne nue et aucune catégorie à l’écran. Commerce et Autres portent désormais leur intitulé comme les quatre autres : chaque ligne est rangée, toujours. Le classement lui-même s’élargit : ventes de gros et manufacturières, permis de construire et hypothecaires, bénéfices des entreprises, productivite, cout du travail, agrégats de credit, flux de capitaux. Sur un echantillon de quatre-vingt-cinq intitulés du calendrier, trois seulement restent dans Autres — les stocks de pétrole, de gaz et le solde budgetaire, qui ne relèvent honnetement d’aucune des cinq familles.' },
  { id: 'dtpu-20260826-onglets-deplacer', ts: Date.UTC(2026, 7, 26, 23, 0), title: 'Panneau à onglets : vos onglets se réordonnent à la poignée', desc: 'Chaque ligne de la liste des onglets, dans les réglages du Panneau à onglets, porte désormais une poignée à gauche. Glissez-la pour placer l’onglet ou vous voulez : un trait doré indique ou il va tomber. Au clavier, la poignée repond aux fleches haut et bas, ce qui va plus vite pour réordonner une liste de sept onglets. La barre d’onglets de la carte se met à jour immédiatement, en même temps que la liste. L’onglet que vous regardiez reste affiche : il suit son contenu, pas sa position. Le nom, l’icone, la disposition et les réglages propres à chaque onglet le suivent aussi. Au passage, un défaut est corrigé : retirer un onglet decalait l’icone de tous les suivants d’un cran.' },
  { id: 'dtpu-20260826-seances-toutes', ts: Date.UTC(2026, 7, 26, 22, 0), title: 'Les trois récaps de séance reçoivent bien leurs chiffres, pas seulement certains', desc: 'Un récap de séance recevait les publications du calendrier, le suivant non, sans que rien ne distingue les deux à l’écran. La cause : la séance d’un récap était lue dans une étiquette posée à la récupération, qui retombe sur Global dès que le titre de la dépêche ne nomme pas la séance — et un récap Global n’a aucune fenêtre horaire, donc aucun chiffre. La séance se lit désormais aussi dans l’intitulé affiche et dans l’adresse de l’article, avec les mêmes repères que ceux qui servent déjà à écrire Récap Séance Asie-Pacifique en tête du rapport. Asie, Londres et New York sont traités à l’identique.' },
  { id: 'dtpu-20260826-macro-classification', ts: Date.UTC(2026, 7, 26, 21, 0), title: 'Récap de séance : la rubrique Macro affiche toujours ses catégories', desc: 'La rubrique Macro d’un récap de séance n’affichait ses intitulés de catégorie que si la séance en comptait au moins deux. Un jour ou les trois publications relevaient toutes de la croissance économique, la rubrique retombait donc en liste plate, sans aucune catégorie — juste à côté du Récap Quotidien qui, lui, les affiche toujours. Chaque catégorie présente porte désormais son intitulé, même seule. La rubrique reprend aussi l’ordre exact du Récap Quotidien : politique monétaire, inflation, croissance économique, emploi, avec ce qui n’entre dans aucune des quatre en tête et sans intitulé — sinon ces lignes se lisent comme la suite de la catégorie précédente. Dernière précision : un banquier central qui s’exprime relevé de la politique monétaire même quand il parle d’inflation, alors qu’un chiffre d’inflation qui cite une banque centrale en consequence reste de l’inflation.' },
  { id: 'dtpu-20260826-familles-elargies', ts: Date.UTC(2026, 7, 26, 19, 0), title: 'Le rangement par famille couvre désormais presque tout le calendrier', desc: 'La table qui range les publications par famille — Inflation, Croissance économique, Emploi, Politique monétaire, Commerce — avait été écrite pour la dizaine d’indicateurs que citent les récaps. En y faisant passer tout le calendrier, un intitulé sur quatre tombait dans Autres : ventes de logements anciens, stocks des entreprises, dépenses et revenus des ménages, enquetes Sentix, GfK, ESI, indicateurs avancés, immatriculations, masse monétaire. Ils sont maintenant rangés. Un défaut est corrigé au passage : les enquetes régionales de la Fed — Philly Fed, Dallas Fed, Empire State, Richmond — étaient classées en Politique monétaire à cause du seul mot Fed, alors que ce sont des enquetes d’activité. Elles rejoignent la Croissance économique, sans emporter les discours et décisions des banquiers centraux, qui restent à leur place. Le changement vaut pour le Récap Quotidien, les récaps de séance et l’e-mail hebdomadaire, qui partagent la même table.' },
  { id: 'dtpu-20260826-macro-calendrier-seance', ts: Date.UTC(2026, 7, 26, 18, 0), title: 'Récap de séance : la rubrique Macro reprend TOUTES les publications de la séance', desc: 'La rubrique Macro d’un récap de séance ne reprenait que les chiffres cites dans le récap d’origine : une publication tombée pendant la séance mais passée sous silence n’apparaissait nulle part. Elle est désormais complétée par notre propre calendrier économique, sur la fenêtre horaire exacte de la séance et sur ses devises — Asie, Londres et New York, les trois récaps du jour. Chaque publication ajoutée arrive chiffrée, au même format que les autres : heure de Paris, résultat, consensus, écart et précédent, sous le nom exact du calendrier. Elle se range dans sa famille, avec le reste. Rien n’est répète : une publication déjà racontée dans le récap n’est pas réécrite en dessous, et le pays fait partie de la comparaison — la confiance des ménages américaine et la française ne sont plus confondues. Et si un récap ne parlait d’aucune donnée alors que la séance en comptait, la rubrique Macro est créée pour les accueillir.' },
  { id: 'dtpu-20260826-macro-familles-seance', ts: Date.UTC(2026, 7, 26, 16, 0), title: 'Récap de séance : la rubrique Macro rangée par famille, comme le Récap Quotidien', desc: 'Dans le récap de séance, la rubrique Macro alignait toutes les publications à la suite. Elles sont désormais rangées par famille — Inflation, Croissance économique, Emploi, Politique monétaire, Commerce — avec les mêmes noms et le même ordre que dans le Récap Quotidien, que beaucoup lisent juste avant ou juste après. Le classement est fait par nos règles, pas laisse à l’appréciation de la rédaction automatique : une même publication tombe dans la même famille dans les deux rapports. Les décisions et propos de banques centrales rejoignent la Politique monétaire, et une famille sans publication du jour ne s’affiche pas.' },
  { id: 'dtpu-20260826-expiries-retirees', ts: Date.UTC(2026, 7, 26, 15, 0), title: 'Les échéances d’options de change disparaissent du fil', desc: 'Les dépêches du type Wednesday FX Option Expiries revenaient chaque jour sans chiffre ni consequence lisible. Elles sont désormais écartées à la source : elles ne sont plus récupérées du tout, et celles déjà présentés ont été retirées du fil. Un filtre existait déjà mais il ne s’appliquait que si la dépêche était très courte, si bien qu’il suffisait d’un texte un peu plus long pour la voir repasser.' },
  { id: 'dtpu-20260826-seance-familles', ts: Date.UTC(2026, 7, 26, 14, 0), title: 'Récaps de séance : les chiffres rangés par famille, comme le Récap Quotidien', desc: 'Les publications d’une séance ne sortent plus en liste plate : elles sont rangées par famille — Inflation, Croissance économique, Emploi, Politique monétaire, Commerce — exactement comme dans le Récap Quotidien, avec les mêmes noms et le même ordre. Les deux rapports se lisent souvent à la suite le même jour : ranger pareil évité d’avoir à se réorienter en passant de l’un à l’autre. Une famille sans publication ce jour-la ne s’affiche pas.' },
  { id: 'dtpu-20260826-seance-maj-auto', ts: Date.UTC(2026, 7, 26, 12, 0), title: 'Les récaps de séance du jour se mettent à jour tout seuls', desc: 'Quand nous ameliorons la forme d’un récap de séance, les récaps DÉJÀ publiés de la journée se refont désormais automatiquement au format le plus récent. Auparavant seuls les récaps suivants en profitaient : celui que vous aviez sous les yeux restait dans son ancienne forme jusqu au lendemain. Le desk vérifie au démarrage, refait ce qui doit l’être, et attend d’avoir mesure les marchés avant de le faire — un récap refait trop tôt sortirait sans sa photo de séance, ce qui serait pire que de ne rien changer. Une séance qui n’a pas encore commence n’est évidemment pas touchée.' },
  { id: 'dtpu-20260826-seance-chiffree', ts: Date.UTC(2026, 7, 26, 10, 0), title: 'Récaps de séance : la séance est désormais chiffrée, pas seulement racontée', desc: 'Chaque récap de séance s’ouvre maintenant sur des mesures. Une synthèse qui dit combien de publications sont tombées et combien ont surpris. Une photo de séance : la performance réelle des marchés de CETTE séance sur SA fenêtre horaire — le DAX et le FTSE pour Londres, le Nikkei et le Hang Seng pour l’Asie, le S&P et le rendement dix ans pour New York. Puis les chiffres eux-mêmes, avec le résultat, le consensus et l’écart. Les rendements sont exprimes en points de base, comme sur un desk, et un indicateur ou la hausse est une mauvaise nouvelle — chômage, inscriptions, stocks — est lu dans le bon sens. Rien n’est invente : une donnée absente est omise plutôt que remplie d’un tiret, et sans données le récap reste exactement celui d’avant.' },
  { id: 'dtpu-20260826-charger-journee', ts: Date.UTC(2026, 7, 26, 9, 0), title: 'Charger plus déroule maintenant la journée entière', desc: 'Le bouton Charger plus, en bas du fil d’actualité, avancait par lots de cent : sur une journée chargée il fallait cliquer cinq ou six fois pour la parcourir. Un clic déroule désormais TOUTE la journée affichée, d’un coup, et vous la lisez en scrollant. Le clic suivant déroule la journée précédente. Le bouton annonce ce qu’il va faire : il indique Voir toute la journée tant qu’il reste des actualités du jour, puis nomme la journée qu’il chargera ensuite. Aucun doublon possible : une actualité déjà reçue n’est jamais rajoutée.' },
  { id: 'dtpu-20260826-fil-repare', ts: Date.UTC(2026, 7, 26, 0, 30), title: 'Fil d’actualité : incident corrigé, et un contrôle pose pour qu’il ne revienne pas', desc: 'Le fil d’actualité est reste vide pendant un moment ce soir : une seule ligne de code retirée la veille en cassait l’affichage de chaque actualité. C’est repare. Nous avons surtout ajoute un contrôle automatique qui refuse ce type de modification avant qu’elle parte en ligne : il vérifie que chaque nom utilise dans le code existe réellement, ce que la vérification précédente ne savait pas faire — elle ne regardait que la grammaire, pas le sens. Le défaut qui à cause l’incident est rejoue à chaque fois pour s’assurer que le contrôle le voit toujours.' },
  { id: 'dtpu-20260825-analyse-rouge-2', ts: Date.UTC(2026, 7, 25, 23, 30), title: 'Les analyses du desk s’affichent en rouge, comme les autres news majeures', desc: 'Une analyse publiée par le desk juste après une publication majeure — ADP, NFP, inflation, décision de taux — s’affichait en ligne ordinaire au lieu du rouge réserve aux news importantes. La couleur se décidait à deux endroits différents dans le code, et les deux avaient fini par diverger. Il n’y en a plus qu’un seul, partage par le fil et par le bandeau d’alerte : ce qui est rouge dans l’un l’est dans l’autre. Et une analyse du desk est désormais rouge par definition, parce qu’elle n’existe que lorsqu un chiffre de premier rang vient de tomber.' },
  { id: 'dtpu-20260825-marquants-retires', ts: Date.UTC(2026, 7, 25, 23, 0), title: 'La section Commentaires marquants disparaît des récaps de séance', desc: 'Le bloc Commentaires marquants, qui listait cinq actualités du jour tout en bas du lecteur de récap de séance, est retiré. Il faisait doublon avec le fil d’actualité, ou ces mêmes news sont déjà lisibles avec leur analyse et leur graphique. Retiré pour de bon, avec sa fabrique : c’était une génération automatique quotidienne, qui liberait autant de ressources pour les rapports que vous lisez vraiment.' },
  { id: 'dtpu-20260825-agenda-sigles', ts: Date.UTC(2026, 7, 25, 22, 30), title: 'Semaine à Venir : les titres reprennent les termes du calendrier', desc: 'Le titre de chaque journée affiche désormais le rendez-vous tel que vous le cherchez dans le calendrier : Core PCE USD, CPI USD, PPI USD, GDP USD, Fed, BoE, RBA Minutes, Ifo, Jackson Hole. Les libellés thématiques français expliquaient au mauvais endroit — « Moral des entreprises allemandes » ne se retrouve dans aucun calendrier, alors qu’Ifo se reconnait tout de suite. L’explication en français clair n’a pas disparu : elle est dans la description, juste en dessous, ou elle a sa place. Deux précisions utiles : une publication nationale de la zone euro porte son pays plutôt que la devise, CPI FR et CPI DE plutôt que CPI EUR qui laisse croire au chiffre de toute la zone ; et une révision de chiffres déjà publiés est marquee comme telle.' },
  { id: 'dtpu-20260825-analyse-en-rouge', ts: Date.UTC(2026, 7, 25, 22, 0), title: 'Les analyses du desk ressortent en rouge dans le fil, comme les autres news importantes', desc: 'Une analyse publiée par le desk après une publication majeure — ADP, NFP, inflation, décision de taux — s’affichait parfois en ligne ordinaire au lieu du rouge réserve aux news importantes. La cause : le fil regroupe les rafales de commentaires économiques pour ne pas vous noyer, et ce regroupement ramassait aussi les analyses du desk, qui perdaient leur couleur en y entrant. Une news marquee importante garde maintenant sa propre ligne, et sa couleur avec. Les dépêches de routine, elles, continuent d’être regroupées.' },
  { id: 'dtpu-20260825-agenda-noms-appris', ts: Date.UTC(2026, 7, 25, 21, 30), title: 'Semaine à Venir : plus aucun rendez-vous n’affiche son intitulé anglais', desc: 'Nos règles couvrent les rendez-vous habituels du calendrier, mais un fournisseur en publié des centaines : il arrivait qu’un indicateur rare sorte avec son nom d’origine en anglais dans le titre de la carte. Ces cas-la sont maintenant nommes automatiquement, en français, avec le pays correctement accorde. La méthode est volontairement étroite : le système choisit une catégorie dans une liste fixe de dix-huit — inflation, emploi, consommation, immobilier, énergie, politique monétaire… — et c’est notre code qui écrit le libelle. Il lui est donc impossible d’annoncer un rendez-vous qui n’existe pas, ce qui était la raison pour laquelle nous avions retiré toute rédaction automatique de ces cartes. Chaque nom appris est retenu une fois pour toutes.' },
  { id: 'dtpu-20260825-agenda-couverture', ts: Date.UTC(2026, 7, 25, 20, 0), title: 'Semaine à Venir : chaque rendez-vous porte enfin un nom français et son explication', desc: 'Vérification complète de l’agenda sur 88 intitulés réels du calendrier. Dix-huit d’entre eux n’avaient aucun nom français et ressortaient tels quels en anglais dans le titre des cartes : conference de presse de banque centrale, projections du comité, postes vacants, réunions du G20 et de l’OPEP, adjudications obligataires, enquetes manufacturières régionales, stocks de gaz, solde budgetaire, credit à la consommation. Tous sont désormais nommes et expliques. Deux corrections de précision au passage : un rendez-vous n’est présente comme se poursuivant que s’il s’agit vraiment du même événement d’un jour à l’autre, et sa dernière journée n’est annoncée que lorsqu on peut la constater dans la semaine affichée. Enfin un rendez-vous majeur affiche le même niveau d’impact dans le calendrier et dans l’agenda : les deux vues pouvaient se contredire.' },
  { id: 'dtpu-20260825-agenda-semaine-ouvree', ts: Date.UTC(2026, 7, 25, 18, 0), title: 'Semaine à Venir : du lundi au vendredi, et deux journées ne se ressemblent plus', desc: 'Quatre corrections sur les cartes de l’agenda. Un lundi de la semaine suivante s’invitait au bout de la liste : la journée se compte maintenant à Paris de bout en bout, la semaine va du lundi au vendredi et rien d’autre. Les publications d’impact moyen reapparaissent : un seul rendez-vous majeur dans la journée les faisait toutes disparaitre de la carte. Un rendez-vous qui dure plusieurs jours, comme le symposium de Jackson Hole, ne répète plus le même texte : la carte annonce la deuxième journée, puis la dernière, et quand la journée porte aussi une publication neuve c’est elle qui passe en tête. Enfin les titres sont plus courts, debarrasses des mentions techniques de période, et davantage de rendez-vous portent un nom français au lieu de leur intitulé d’origine.' },
  { id: 'dtpu-20260825-agenda-meme-calendrier', ts: Date.UTC(2026, 7, 25, 16, 30), title: 'Semaine à Venir et Calendrier parlent enfin le même langage', desc: 'Les rendez-vous de la Semaine à Venir portent désormais exactement les mêmes noms que dans votre onglet Calendrier. Jusqu ici l’agenda servait les intitulés bruts de notre fournisseur de données pendant que le calendrier affichait ceux de ForexFactory, notre référence : le même événement apparaissait sous deux noms selon l’endroit ou vous le lisiez. La rubrique À surveiller des récaps de séance suit la même règle. Au passage, la décision de taux porte le nom que chaque banque lui donne — Fédéral Funds Rate pour la Fed, Official Bank Rate pour la Banque d’Angleterre — au lieu d’un libellé unique qui donnait le nom de la Banque d’Angleterre à toutes les banques centrales. Et deux pays de la zone euro qui publient le même indicateur à la même heure ne se remplacent plus l’un l’autre dans la liste.' },
  { id: 'dtpu-20260825-semaine-titres-honnetes', ts: Date.UTC(2026, 7, 25, 15, 0), title: 'Semaine à Venir : le titre d’une journée ne peut plus annoncer un rendez-vous absent', desc: 'Le titre de chaque carte de la Semaine à Venir se calcule désormais À PARTIR de la liste affichée juste en dessous, et de rien d’autre : il lui est impossible d’annoncer un événement qui n’est pas au programme. Trois corrections derrière ce garde-fou. Une RÉVISION n’est plus confondue avec la publication d’origine : une révision annuelle des créations d’emplois corrige des chiffres déjà connus, elle porte maintenant son propre nom et ne prend plus la place du rapport mensuel. Le PAYS est enfin lu : l’inflation de fin de mois est publiée par la France, l’Espagne ou l’Allemagne, elle s’annonce donc ainsi, et le mot zone euro est réserve au chiffre de la zone. Enfin un rendez-vous majeur — décision de taux, Jackson Hole, rapport emploi americain — tient le titre seul au lieu d’être dilue par un second thème. Un contrôle automatique rejoue le cas signale à chaque modification.' },
  { id: 'dtpu-20260825-semaine-descriptions-claires', ts: Date.UTC(2026, 7, 25, 14, 0), title: 'Semaine à Venir : chaque chiffre est désormais explique en français clair', desc: 'Les descriptions des cartes se lisent sans connaître le jargon. Chaque publication est suivie de ce qu’elle mesure, en une formule courte : l’inflation que la Fed regarde en priorité, les commandes de machines qui donnent le thermomètre de l’investissement des entreprises, le barometre des directeurs d’achat ou la barre des 50 séparé croissance et contraction. Vient ensuite ce que le chiffre change concretement pour la devise, et seulement après le reste du programme. La phrase qui explique l’enjeu porte maintenant sur l’événement réellement mis en avant : une journée consacrée à l’inflation et aux dépenses des ménages ne se conclut plus sur une remarque à propos du produit intérieur brut. Les intitulés restent dans leur langue d’origine pour se retrouver dans le calendrier.' },
  { id: 'dtpu-20260825-calendrier-journee-paris', ts: Date.UTC(2026, 7, 25, 13, 30), title: 'Calendrier : une journée commence et finit à Paris, et les grands rendez-vous ne manquent plus', desc: 'Trois corrections sur le calendrier économique. Les événements sont rangés au jour civil de Paris et non plus à l’heure de Greenwich : une publication asiatique de une heure du matin s’affichait la veille, et un chiffre du lundi matin en Asie disparaissait même complètement de la semaine. Les rendez-vous sans chiffre attendu — symposium de Jackson Hole, discours de gouverneur, comptes rendus de comité, réunions de l’OPEP — sont désormais repeches et affichés : notre fournisseur les classe en importance faible faute de consensus à comparer, ils étaient donc écartés alors qu’ils déplacent le marché à eux seuls. Enfin deux pays de la zone euro qui publient le même indicateur au même moment ne se remplacent plus l’un l’autre dans la liste.' },
  { id: 'dtpu-20260830-seance-a-surveiller', ts: Date.UTC(2026, 7, 30, 20, 0), title: 'Récaps de séance : À surveiller annonce désormais la séance suivante', desc: 'La rubrique À surveiller des récaps de séance ne disposait d’aucune source d’événements à venir : elle se remplissait donc en extrapolant les actualités du jour, au point d’annoncer une publication qui n’existait pas. Elle lit maintenant le calendrier économique et vous donne les rendez-vous de la SÉANCE SUIVANTE, avec leur heure exacte, la devise concernée et le consensus attendu. Le récap de la séance asiatique annonce ce qui attend Londres ; celui de Londres annonce New York ; celui de New York annonce l’Asie du lendemain. Seuls passent les événements ENCORE À VENIR au moment de la publication, filtres sur les devises de la séance concernée — un rendez-vous britannique de fin d’après-midi n’est pas présente comme un événement new-yorkais. Et si le calendrier ne porte rien, la rubrique ne s’affiche pas : mieux vaut une rubrique absente qu’une échéance inventée.' },
  { id: 'dtpu-20260830-seance-meme-grammaire', ts: Date.UTC(2026, 7, 30, 16, 0), title: 'Récaps de séance : les mêmes rubriques que le Récap Quotidien', desc: 'Les récaps de séance — Asie-Pacifique, Londres, New York — declinaient leurs propres rubriques : une section Banques centrales autonome, une section Marches, et aucune synthèse. Le Récap Quotidien, lui, ouvre sur une synthèse, traite les banques centrales À L’INTÉRIEUR de Macro et nomme sa lecture de marché Analyse par session. Comme les deux rapports se lisent à la suite dans la même journée, il fallait se réorienter à chaque fois. Les récaps de séance adoptent désormais exactement les mêmes parties, dans le même ordre : Synthèse, Géopolitique, Macro — organisée en Politique monétaire, Inflation, Croissance économique et Emploi, les quatre mêmes rubriques que le Radar de Biais — puis Analyse de séance et À surveiller. Chaque banque garde sa propre puce, avec sa décision ou le ton de son intervenant. Seule la grammaire devient commune : le contenu reste propre à chaque séance.' },
  { id: 'dtpu-20260830-recap-clarte', ts: Date.UTC(2026, 7, 30, 12, 0), title: 'Récap Quotidien : chaque banque sa puce, et les chiffres du jour réunis sous un seul titre', desc: 'Trois corrections de lecture. Une puce pouvait encore melanger deux banques centrales — « ECB et BoJ : les chemins divergents... » — alors que la règle une banque par puce existait déjà : elle ne couvrait pas la rubrique qui alimente Politique monétaire. Chaque banque à désormais sa puce partout, avec sa décision (hausse, baisse ou maintien et le niveau atteint) ou l’intervenant, sa fonction et le ton de son discours ; un écart entre deux banques se raconte depuis chacune, du point de vue de sa devise. Ensuite, les chiffres publiés du jour étaient rangés dans des sections portant les MÊMES noms que les sous-rubriques de Macro : Croissance économique apparaissait à deux niveaux dans le même rapport, sans rien pour distinguer les actualités des chiffres. Ils sont maintenant réunis sous un seul titre, Chiffres du jour, avec les familles en sous-titres. Enfin, dans les récaps de séance, la rubrique À surveiller pouvait annoncer une publication qui n’existait pas — un CPI americain « demain » un jour ou aucun n’était au calendrier : elle ne peut plus écrire une échéance absente du flux, ni recopier un fait déjà raconte ailleurs.' },
  { id: 'dtpu-20260830-temoignage-mention-retiree', ts: Date.UTC(2026, 7, 30, 9, 0), title: 'Témoignage : la mention commerciale sous le bouton disparaît', desc: 'Le courriel de témoignage se terminait par une ligne de réassurance commerciale sous le bouton — accès immédiat, sans engagement, résiliable en un clic. Elle est retirée des cinq présentations : dans un courriel dont tout l’intérêt est de laisser parler un membre, cette phrase de vendeur cassait le ton juste après sa citation. Le bouton, la citation et la signature ne bougent pas.' },
  { id: 'dtpu-20260829-force-cadrage-paquet', ts: Date.UTC(2026, 7, 29, 21, 0), title: 'Force des Devises : le graphique cadre sur le groupe, même quand une devise s’envole', desc: 'Quand une devise s’échappait très loin des autres — un dollar à +35 quand le reste du groupe évolué entre -10 et +15 — le graphique etirait son échelle jusqu’à elle dès lors qu’elle terminait la période sur son extreme. Résultat : les sept autres courbes se retrouvaient tassées sur le fond du cadre, illisibles. Le cadrage se fait désormais sur le GROUPE, dans tous les cas : les courbes que vous comparez occupent l’espace. La devise qui s’envole sort du cadre par le haut, comme elle en sortait déjà en cours de période : son étiquette reste visible au bord avec son filet de rappel, sa valeur exacte reste dans l’infobulle, et un double-clic sur l’échelle de droite rétablit à tout moment la vue complète. Applique à toutes les périodes : TD, TW, 8H, 1D, 7D, 1M.' },
  { id: 'dtpu-20260829-force-desk-fenetre-moyenne', ts: Date.UTC(2026, 7, 29, 18, 0), title: 'Onglet FORCE : les deux graphiques entiers aussi en fenêtre moyenne', desc: 'Le correctif qui donnait aux deux graphiques TD et TW leur pleine hauteur — avec défilement entre les deux — ne s’appliquait que sur téléphone. Or les graphiques s’empilent dès que la fenêtre passe sous 1380 pixels de large : sur une tablette ou une fenêtre de bureau réduite, ils se partageaient encore une hauteur figée et le graphique du bas était coupe sous la barre des 20 — ligne de zero, axe des dates et devises basses (JPY, CHF, CAD, NZD) hors champ, sans défilement. Le remède couvre désormais toute la plage d’empilement : chaque graphique reçoit sa hauteur pleine et le panneau défile si nécessaire. Au-dela, cote à côté, rien ne change.' },
  { id: 'dtpu-20260829-force-devises-jamais-coupe', ts: Date.UTC(2026, 7, 29, 15, 0), title: 'Force des Devises : le graphique retrecit désormais au lieu d’être coupe', desc: 'Le graphique Force des Devises refusait de descendre sous une hauteur minimale élevée. Quand la carte était plus courte que cette hauteur, il ne s’adaptait pas : il debordait, et tout son bas était coupe net — la ligne de zero, l’axe des dates et la moitie des devises disparaissaient sans aucun signe. Sur une capture, l’échelle affichait 40 et 20 et le cadre s’arretait vers 20 : les quatre devises situées en dessous étaient tout simplement invisibles. Le graphique se redimensionne maintenant quand la place manque, au lieu de deborder. Un graphique un peu plus petit se lit ; un graphique coupe en deux, non. La carte continue par ailleurs de réserver la hauteur confortable dès qu’elle le peut.' },
  { id: 'dtpu-20260829-risque-mois-visibles', ts: Date.UTC(2026, 7, 29, 12, 0), title: 'Sentiment de Risque : les mois sous l’historique restent lisibles', desc: 'Sous la bande d’historique du widget Sentiment de Risque, les repères de mois étaient coupes en deux dans une carte un peu courte. La jauge réservait une hauteur minimale heritée de l’onglet RISQUE du desk, bien plus large que ce dont elle a besoin dans une carte : additionnée à celle de l’historique, elle poussait le bas du graphique hors du cadre. Ce minimum est ramene à la place réellement utile — l’arc et le badge ne bougent pas d’un pixel — et l’ensemble tient désormais dans des cartes nettement plus courtes qu’avant, avec la bande d’historique à sa taille pleine plus longtemps.' },
  { id: 'dtpu-20260829-recap-quotidien-effets', ts: Date.UTC(2026, 7, 29, 9, 0), title: 'Récap Quotidien : chaque point dit ce qu’il implique, et une rubrique de fils ouverts apparaît', desc: 'Trois améliorations du Récap Quotidien. D’abord, chaque point porte désormais un EFFET et non plus un simple fait : quand le marché a déjà réagi, vous lisez l’ampleur ; quand il n’a pas encore reagi, vous lisez la consequence conditionnelle et son sens — « le marché price déjà la hausse, donc si la banque ne releve pas, le yen pourrait fortement s’affaiblir ». Ensuite, la QUALITE de chaque intervenant est précisée dès qu’il n’est pas le gouverneur en exercice : « ex-membre du board », « Trésor americain ». Un nom seul ne se situe pas, et c’est souvent la fonction qui donne son poids à la phrase. Enfin, la rubrique À surveiller s’ouvre sur les FILS OUVERTS : les échéances qu’aucun calendrier ne porte — une sanction annoncée pour la fin de semaine, une mediation en cours, une annonce de tarifs — chacune avec son délai et pourquoi elle compte pour les devises. Le tableau des publications, lui, reste juste en dessous, inchangé.' },
  { id: 'dtpu-20260828-temoignage-au-programme', ts: Date.UTC(2026, 7, 28, 23, 0), title: 'Le témoignage mensuel apparaît dans le programme des envois', desc: 'Le témoignage ne fait pas partie de la rotation hebdomadaire : il s’ajoute, une fois par mois. Il n’avait donc aucune ligne dans le programme des envois, ce qui laissait croire qu’il n’était pas programme alors qu’il part tout seul. Il s’affiche désormais sur la semaine qui le porte, avec son jour et son heure. Le rendez-vous est aussi corrigé partout : premier MARDI du mois, et non plus premier lundi comme l’indiquait encore la note du panneau.' },
  { id: 'dtpu-20260828-force-devises-entiere', ts: Date.UTC(2026, 7, 28, 21, 0), title: 'Force des Devises : les courbes s’affichent en entier sur écran moyen', desc: 'Sur les écrans de taille intermédiaire — petite tablette, téléphone en paysage, fenêtre réduite — le bas du graphique Force des Devises était coupe : l’axe des dates disparaissait et plusieurs étiquettes de devises (NZD, JPY, CHF, CAD, AUD) passaient sous le pli, sans aucun signe que quelque chose manquait. La carte recevait une taille minimale bien inférieure à celle exigée par le graphique qu’elle contient. Les deux sont désormais accordées : la carte réserve la hauteur qu’il faut, et les courbes s’affichent entières avec leur axe et toutes leurs étiquettes. Rien ne change sur grand écran.' },
  { id: 'dtpu-20260828-risque-histo-entier', ts: Date.UTC(2026, 7, 28, 19, 0), title: 'Sentiment de Risque : l’historique reste entier dans une carte courte', desc: 'Dans le widget Sentiment de Risque, la bande d’historique quotidien avait une hauteur FIGée face à une jauge qui, elle, refusait de se resserrer. Des que la carte manquait de hauteur, c’est le bas de l’historique qui disparaissait : les barres négatives coupées en plein milieu, l’axe des dates et le titre passes sous le pli, sans que rien ne le signale. La bande se resserre désormais quand la place manque, jusqu’à rester lisible, et ne cede la main qu’après la jauge. Quand la carte est assez haute, rien ne change : la bande garde exactement sa taille d’avant, au pixel près.' },
  { id: 'dtpu-20260828-jamais-de-relance-apres-fusion', ts: Date.UTC(2026, 7, 28, 17, 0), title: 'Après la réunion de deux comptes, plus aucune relance de paiement sur l’ancienne adresse', desc: 'Quand deux fiches d’une même personne sont réunies, l’ancienne adresse est désactivée et datée dans le passe. Or notre contrôle des abonnements échus balaie les deux derniers jours sans distinguer les comptes désactivés : l’ancienne adresse pouvait donc recevoir un courriel « votre abonnement à expire » dans les heures suivant la réunion. Pour un membre actif, qui venait de payer, et à cause d’une opération faite pour lui. Une adresse absorbée est désormais reconnue comme telle partout ou une relance de paiement peut partir, et en est exclue definitivement. La correction est retroactive : les réunions déjà effectuées sont couvertes, sans rien avoir à refaire.' },
  { id: 'dtpu-20260828-fusion-sans-doublon', ts: Date.UTC(2026, 7, 28, 15, 0), title: 'Réunir deux comptes sans renvoyer d’identifiants en double', desc: 'Quand on réunit deux fiches d’une même personne, le renvoi des identifiants devient une case à cocher, DÉCOCHÉE par défaut. Si le client a déjà reçu ses accès, la fusion se fait sans lui réexpédier un courriel inutile, et le mot de passe qu’il possède déjà continue de fonctionner puisqu on n’y touche pas. La case reste disponible pour les cas ou les identifiants n’ont jamais été reçus. Une exception, automatique : lorsque le compte de destination doit être créé de toutes pieces, son mot de passe n’existe nulle part — les accès partent alors quoi qu’il arrive.' },
  { id: 'dtpu-20260828-temoignage-varie', ts: Date.UTC(2026, 7, 28, 12, 0), title: 'Témoignage mensuel : cinq présentations différentes, et tous vos avis mis à contribution', desc: 'Le courriel mensuel de témoignage partait chaque mois avec le MÊME objet, la MÊME accroche et le MÊME avis — celui le mieux note, choisi en premier à chaque fois. Autrement dit, douze fois par an rigoureusement le même message. Deux changements : il existe désormais CINQ présentations distinctes, avec chacune son objet, son accroche et son bouton, servies à tour de role — jamais deux fois la même de suite. Et les avis tournent eux aussi : on cite en priorité ceux qui ne l’ont jamais été, avant de revenir aux plus anciens. Le titre de l’avis, quand il y en a un, est désormais affiche. Le rendez-vous passe du premier lundi au PREMIER MARDI du mois, comme les autres contenus. La parole des membres, elle, n’est jamais réécrite : seule sa présentation change.' },
  { id: 'dtpu-20260828-fusion-selection', ts: Date.UTC(2026, 7, 28, 9, 0), title: 'Réunir deux comptes se fait en les cochant dans la liste', desc: 'La réunion de deux fiches d’une même personne se pilote désormais depuis la liste des comptes elle-même : on coche les deux lignes, on choisit laquelle garder, et un aperçu complet s’affiche AVANT toute écriture — opération, échéance retenue, sort du compte absorbe. Rien n’est modifie tant que la fusion n’est pas confirmée. À la confirmation, l’accès déjà paye est intégralement conserve (c’est toujours l’échéance la plus lointaine qui est gardée), le compte absorbe est suspendu et non supprime, et le résultat des envois de courriel s’affiche ligne par ligne, succès comme echec.' },
  { id: 'dtpu-20260827-nom-du-compte', ts: Date.UTC(2026, 7, 27, 22, 0), title: 'Votre compte porte enfin votre nom', desc: 'Les comptes ouverts automatiquement après un paiement naissaient SANS NOM. La plateforme de paiement nous transmettait bien votre nom, nous ne le lisions simplement jamais — au point qu’un client était introuvable dans nos outils en cherchant son nom, alors que son compte existait bel et bien. C’est corrigé : votre nom est repris à l’ouverture du compte, et votre pseudo sert de repli si aucun nom n’est disponible. Les comptes déjà ouverts sans nom récupèrent le leur automatiquement au premier renouvellement — mais uniquement s’il est vide : un nom corrigé à la main n’est jamais ecrase.' },
  { id: 'dtpu-20260827-fusion-panneau', ts: Date.UTC(2026, 7, 27, 20, 0), title: 'Réunir deux comptes d’une même personne, depuis le panneau', desc: 'Une même personne pouvait se retrouver avec deux fiches — le plus souvent une adresse anonyme créée par un paiement Apple Pay et sa vraie adresse. Les réunir demandait une intervention technique ; c’est désormais un bouton dans le panneau Campagne, avec une SIMULATION obligatoire avant toute écriture : vous voyez exactement ce qui va se passer avant de confirmer. À l’exécution, l’accès déjà paye est intégralement conserve — c’est toujours l’échéance la plus lointaine qui est gardée — le compte absorbe est suspendu et non supprime, un mot de passe neuf est généré, et le courriel d’accès part sur LES DEUX adresses pour qu’au moins un des deux arrive. L’ancienne adresse reste rattachée au compte : un renouvellement paye dessus prolonge le bon accès au lieu d’en creer un troisième.' },
  { id: 'dtpu-20260827-compte-recolle', ts: Date.UTC(2026, 7, 27, 18, 0), title: 'Un accès créé sur une adresse masquee peut être recolle à votre vraie adresse', desc: 'Suite du correctif précédent. Quand un abonnement paye par Apple Pay avec « Masquer mon adresse » avait déjà ouvert un accès sur l’adresse relais anonyme, le compte existait bien mais restait introuvable sous la vraie adresse, et le courriel d’accès partait vers une boîte relais qu’Apple ne relaie pas toujours. Nous pouvons désormais recoller ce compte à la vraie adresse en une opération : l’accès déjà paye est conserve intégralement — c’est toujours l’échéance la plus lointaine qui est gardée, jamais la plus courte — un mot de passe neuf est généré et le courriel d’accès part enfin dans la bonne boîte. Si deux comptes existaient pour la même personne, ils sont réunis en un seul. L’ancienne adresse reste rattachée : un renouvellement paye sous celle-ci prolonge le bon compte au lieu d’en creer un troisième.' },
  { id: 'dtpu-20260827-abonnement-jamais-perdu', ts: Date.UTC(2026, 7, 27, 14, 0), title: 'Un abonnement paye ne peut plus passer inaperçu chez nous', desc: 'Nous avons trouvé et corrigé une panne silencieuse : dans certains cas, un abonnement bel et bien paye n’ouvrait aucun accès de notre cote, sans le moindre signal d’erreur. La cause : notre lecture des abonnements cherchait l’adresse e-mail à un seul endroit precis du message reçu. Quand la plateforme de paiement la place ailleurs — ce qui arrive notamment avec Apple Pay et l’option « Masquer mon adresse » — l’abonnement devenait invisible pour nous, y compris pour le contrôle de sécurité qui passe toutes les dix minutes et qui existe justement pour rattraper ce genre d’oubli. Les deux échouaient au même endroit. L’adresse est désormais recherchée partout ou elle peut se trouver, et nous retenons aussi le nom d’utilisateur comme seconde identité : même si l’adresse est masquee ou changée, votre abonnement reste rattache à votre compte. Un renouvellement paye sous l’une ou l’autre de vos identités prolonge le même accès, sans jamais creer de second compte.' },
  { id: 'dtpu-20260827-apple-pay-acces', ts: Date.UTC(2026, 7, 27, 10, 0), title: 'Payer avec Apple Pay et « Masquer mon adresse » ne prive plus de son accès', desc: 'Quand un abonnement est règle par Apple Pay avec l’option « Masquer mon adresse », Apple ne transmet pas la vraie adresse e-mail mais une adresse relais anonyme. Le desk créait donc le compte sur cette adresse relais : le client était introuvable dans nos outils sous son vrai e-mail, et son mail d’accès partait vers une boîte relais qu’Apple ne relaie pas toujours. Une table de correspondance rattache désormais l’adresse relais à la vraie adresse : le compte est créé au bon endroit, le mail d’accès arrive dans la vraie boîte, et un renouvellement paye sous l’une ou l’autre des deux adresses prolonge bien le même compte, sans jamais en creer un second. Rien ne change pour les abonnements payes par carte.' },
  { id: 'dtpu-20260827-onglets-horloge-atteignables', ts: Date.UTC(2026, 7, 27, 0, 0), title: 'Panneau à onglets et Horloge mondiale : plus rien d’inatteignable', desc: 'L’audit systématique des 38 widgets de la bibliothèque — un examen par widget, mesures à l’appui — à trouve deux recoins ou du contenu pouvait être coupe sans aucun moyen d’y accéder. Dans le PANNEAU À ONGLETS d’abord : un widget embarque exigeant plus de hauteur que l’onglet n’en offre — la jauge de risque et son historique, par exemple — était ampute en silence, sans barre de défilement (mesure : un tiers du contenu perdu). L’onglet défile désormais, comme les cartes simples l’ont toujours fait, et sur téléphone le panneau retrouve sa pleine hauteur qu’une règle lui volait. L’HORLOGE MONDIALE ensuite : dans une carte étroite, les villes se repliaient sur plusieurs rangées écrasées — météo, vent et pays coupes au bas de chaque cellule. Chaque rangée garde maintenant sa hauteur entière et la carte défile s’il le faut. Quand tout tient, rien ne change, au pixel près.' },
  { id: 'dtpu-20260826-topbar-pilule-risque', ts: Date.UTC(2026, 7, 26, 23, 0), title: 'Mobile : la pilule RISK ON / RISK OFF quitte la barre du haut', desc: 'Sur téléphone, la pilule d’état de risque — RISK ON, RISK OFF, NEUTRE — se glissait entre la barre de recherche et les icones, ou elle finissait souvent tronquee faute de place. Elle disparaît de la barre du haut sur mobile : la rangée respire et la recherche garde ses aises. L’information, elle, ne disparaît pas : le climat de risque reste à un geste, dans l’onglet RISQUE et le widget Sentiment de Risque. Sur ordinateur, rien ne change.' },
  { id: 'dtpu-20260826-calculatrice-un-ecran', ts: Date.UTC(2026, 7, 26, 22, 0), title: 'Calculatrice : tout tient sur un écran de téléphone, résultat compris', desc: 'Sur mobile, la calculatrice de taille de position empilait ses sept champs sur toute la hauteur : le résultat — la raison d’être de la page — naissait sous le pli et il fallait defiler pour le voir. Le formulaire passe en deux colonnes (Devise et Solde cote à côté, Risque et Stop-loss, Spread et Commission, la Paire en pleine largeur), les cartes de résultat se resserrent d’un cran et le bouton Copier rejoint le coin de la taille de position. Résultat : saisie ET résultat visibles ensemble, sans defiler, la taille se met à jour sous vos yeux pendant que vous tapez. Sur les très petits écrans, le défilement reste disponible en secours — rien n’est jamais coupe.' },
  { id: 'dtpu-20260826-calendrier-date-en-ligne', ts: Date.UTC(2026, 7, 26, 21, 0), title: 'Widget Calendrier : la date rejoint la ligne des filtres, une ligne de gagnée', desc: 'Sur téléphone, dans le widget Calendrier économique, le selecteur de période — les fleches et la date « 24 - 28 août » — occupait sa propre ligne sous les filtres Tous, Élevé, Moyen, Faible. Il se place désormais à droite de Faible, sur la même ligne, cale au bord : une ligne d’écran rendue au calendrier lui-même. Les fleches gardent leur taille tactile pleine ; seuls les boutons de filtre se resserrent d’un rien. Et si votre écran est vraiment trop étroit ou votre zoom pousse, la date repasse simplement dessous — rien ne se coupe jamais.' },
  { id: 'dtpu-20260826-mobile-graphes-atteignables', ts: Date.UTC(2026, 7, 26, 20, 0), title: 'Sur téléphone, les graphes et les boutons du haut restent toujours atteignables', desc: 'Trois recoins du desk pouvaient devenir inaccessibles sur mobile, sans barre de défilement ni indice. L’onglet FORCE d’abord : ses deux graphes — séance en haut, semaine en bas — se partageaient la hauteur de l’écran et se faisaient couper, le bas des courbes et les badges de devises restaient hors de portée. Chaque graphe reçoit désormais sa pleine hauteur et le panneau défile de l’un à l’autre ; sur grand écran, rien ne change. Les icones en haut à droite ensuite — IA, Flash Marche, Alertes, Support, profil : selon la taille de l’écran et le zoom choisi dans vos réglages, les dernières pouvaient sortir de l’écran sans aucun moyen de les rejoindre. Quand la place manque, la rangée se laisse maintenant balayer du doigt ; quand tout tient, rien ne bouge. Enfin le widget Sentiment de Risque naissait trop court d’un tiers : jauge et historique reclament 450 pixels, la carte s’ouvrait à 300 — il fallait defiler dès la pose. Il naît désormais à sa taille.' },
  { id: 'dtpu-20260826-widget-monde-defilement', ts: Date.UTC(2026, 7, 26, 19, 0), title: 'Widget Monde : les places qui ne tenaient pas étaient perdues, elles sont accessibles', desc: 'Le widget Sessions de marché affiche quatre places : Sydney, Tokyo, Londres et New York. Quand la hauteur disponible manquait — sur téléphone, dans un panneau court ou une zone redimensionnée — les dernières places étaient coupées SANS AUCUNE TRACE : ni barre de défilement, ni indice, aucun moyen d’y accéder. Perdre New York et Londres vide pourtant le widget de son intérêt. Le contenu peut désormais defiler quand la place manque vraiment. Les paliers de densite resserrent toujours l’affichage en premier : le défilement n’intervient qu’en dernier recours.' },
  { id: 'dtpu-20260826-mobile-etiquettes', ts: Date.UTC(2026, 7, 26, 18, 0), title: 'Mobile : les étiquettes du fil se voient toutes d’un coup d’œil', desc: 'Sur téléphone, les étiquettes sous chaque actualité — le pays, le thème, Info, la réaction — pouvaient rester sur une seule ligne à faire defiler, si bien que les dernières étaient coupées au bord de l’écran. Une étiquette qu’il faut aller chercher d’un geste n’est pas lue. Elles reviennent désormais à la ligne et s’affichent toutes, au prix d’une ou deux lignes de plus par actualité.' },
  { id: 'dtpu-20260826-banques-une-par-puce', ts: Date.UTC(2026, 7, 26, 17, 0), title: 'Banques centrales : une banque par puce, et la décision annoncée', desc: 'Deux corrections sur la façon dont les banques centrales sont racontées. Dans le Récap Quotidien, deux institutions pouvaient se retrouver mélangées dans une seule puce — « ECB et BoJ : ... » — ce qu’aucune note de desk ne ferait. Désormais une puce par banque, jamais deux, même quand le fait est commun ; et un discours ou un ton se range toujours sous SA banque. Surtout : quand une banque à decide dans la journée, la puce OUVRE sur la décision — HAUSSE, BAISSE ou MAINTIEN, avec le niveau atteint. Dans le Récap Hebdo, la décision de taux de la semaine était produite depuis toujours mais n’était affichée NULLE PART : elle apparaît maintenant en tête de la rubrique Banque centrale de chaque devise, avant les propos. Vous voyez donc d’un coup d’œil ce que la banque a fait, avant de lire ce qu’elle a dit.' },
  { id: 'dtpu-20260826-macro-quatre-du-radar', ts: Date.UTC(2026, 7, 26, 16, 0), title: 'Macro : les mêmes quatre rubriques que le Radar de Biais', desc: 'Sous MACRO, les actualités du jour se rangent désormais dans les QUATRE rubriques du Radar de Biais, avec les mêmes mots et dans le même ordre : POLITIQUE MONÉTAIRE, INFLATION, CROISSANCE ÉCONOMIQUE, EMPLOI. Deux surfaces du même desk ne peuvent pas nommer différemment la même chose : vous retrouvez d’un onglet à l’autre le vocabulaire que vous connaissez. L’ancienne rubrique « Banques centrales » disparaît comme intitulé et rejoint POLITIQUE MONÉTAIRE — c’était la même matière sous deux noms — en gardant sa place en tête : la décision d’abord, son écho dans l’actualité ensuite. Au passage, une actualité sur les taux qui tombait faute de rubrique ou aller à maintenant la sienne. Une rubrique sans actualité ce jour-la ne s’affiche toujours pas.' },
  { id: 'dtpu-20260826-semaine-figee', ts: Date.UTC(2026, 7, 26, 15, 0), title: 'Semaine à Venir : un agenda stable, publié une fois pour la semaine', desc: 'La Semaine à Venir se reconstruisait toutes les 40 minutes, soit environ vingt-cinq fois par jour. Un agenda de semaine ne change pas d’une heure à l’autre : il est désormais publié UNE FOIS, le samedi, et reste stable jusqu au week-end suivant. Concretement, ce que vous consultez lundi est exactement ce que vous retrouverez vendredi — l’ordre des jours, les libellés, le profil de risque ne bougent plus sous vos yeux. Consequence à connaître : un rendez-vous ajoute au calendrier en cours de semaine n’apparaitra qu’au week-end suivant.' },
  { id: 'dtpu-20260826-semaine-rendez-vous-majeurs', ts: Date.UTC(2026, 7, 26, 14, 0), title: 'Semaine à Venir : Jackson Hole et les grands rendez-vous ne sont plus oublies', desc: 'La Semaine à Venir ne retenait que les publications classées à impact élevé ou moyen par le calendrier. Ce filtre convient aux CHIFFRES, pas aux RENDEZ-VOUS : un symposium, une audition au Congrès ou une conference de presse n’a ni consensus ni précédent à afficher, donc les fournisseurs les classent souvent en impact faible. Jackson Hole, qui déplace le dollar à lui seul, était donc absent de votre agenda. C’est corrigé : les symposiums de banquiers centraux, les gouverneurs des huit banques nommement, les minutes, les conferences de presse, les rapports de politique monétaire, les auditions, le secrétaire au Trésor américain, l’OPEP et les sommets G7 et G20 entrent désormais quel que soit leur classement. Et ils entrent à leur vraie mesure : Jackson Hole ou un discours du président de la Fed pesent comme une décision de taux dans le profil de risque de la semaine. Le repechage reste cible : les publications mineures ne remontent pas pour autant.' },
  { id: 'dtpu-20260826-macro-classement-affine', ts: Date.UTC(2026, 7, 26, 13, 0), title: 'Macro : deux familles d’actualités qui passaient au travers sont reconnues', desc: 'Correction du classement des actualités du jour. Les indices d’activité — comme l’Indice d’activité nationale de la Fed de Chicago — n’étaient reconnus par aucune rubrique et se retrouvaient dans la liste sans titre, alors qu’ils mesurent exactement la même chose qu’un PMI : ils rejoignent CROISSANCE ÉCONOMIQUE. Les sujets de politique commerciale — guerre commerciale, tarifs, droits de douane, rétorsion — sont eux aussi reconnus désormais. Rappel de lecture : sous MACRO, la liste sans titre en tête regroupe ce qui ne releve d’aucune de vos trois rubriques, essentiellement les mouvements de matières premières et de devises. Elle est en tête, et non à la suite, pour qu’on ne la prenne pas pour la suite des Banques centrales.' },
  { id: 'dtpu-20260826-alertes-lisibilite', ts: Date.UTC(2026, 7, 26, 12, 0), title: 'Alertes : les descriptions et les heures se lisent enfin sans effort', desc: 'Dans le panneau ALERTES, l’heure de chaque alerte — « il y a 13 min » — était affichée dans un gris si sombre qu’elle se devinait plus qu’elle ne se lisait : mesure sur le fond du panneau, son contraste tombait à 3,2 pour 1 quand le seuil de lisibilité d’un petit texte est de 4,5. Elle passe à 6,2 pour 1 et gagne un demi-point de taille. Les descriptions, déjà correctes, gagnent un cran pour rester au-dessus de l’heure : le titre reste le plus lisible, puis la description, puis l’heure. C’est le plancher qui remonte, pas la hiérarchie qui s’ecrase.' },
  { id: 'dtpu-20260825-macro-trois-rubriques', ts: Date.UTC(2026, 7, 26, 11, 0), title: 'Macro : vos trois rubriques, et rien d’autre', desc: 'Précision sur le classement des actualités du jour. Trois rubriques seulement portent un intitulé sous MACRO : INFLATION, CROISSANCE ÉCONOMIQUE et EMPLOI, aux cotes des BANQUES CENTRALES. Une rubrique sans actualité ce jour-la ne s’affiche pas du tout. Les mouvements de marché et d’énergie — le pétrole, l’or, l’indice dollar, le yen — ne relèvent d’aucune des trois : ils restent affichés, en tête de la section et sans intitulé, pour que rien ne se perde et qu’on ne les prenne pas pour des propos de banque centrale. Même présentation sur le desk et dans le mail.' },
  { id: 'dtpu-20260825-macro-news-categorisees', ts: Date.UTC(2026, 7, 26, 10, 0), title: 'Macro : chaque actualité du jour porte sa catégorie', desc: 'Sous MACRO, les actualités du jour étaient regroupées sous un intitulé fourre-tout, « Autres moteurs ». Elles portent maintenant leur catégorie : une news sur les prix se range sous INFLATION, une sur les ventes au détail ou la production sous CROISSANCE ÉCONOMIQUE, une sur le chômage ou les salaires sous EMPLOI, une décision de banque centrale sous POLITIQUE MONÉTAIRE. Une catégorie sans actualité ce jour-la ne s’affiche pas du tout. Et rien ne se perd : les mouvements de marché et d’énergie — l’or, l’indice dollar, une raffinerie à l’arrêt — qui ne relèvent d’aucune de ces familles restent affichés sous Macro, simplement sans intitulé. Le classement est le même que celui des chiffres publiés, et il reconnait désormais les deux langues : les libellés du calendrier arrivent en anglais quand les actualités sont rédigées en français. Même changement sur le desk et dans le mail.' },
  { id: 'dtpu-20260825-familles-sous-macro', ts: Date.UTC(2026, 7, 26, 9, 0), title: 'Récap Quotidien : les chiffres du jour passent sous Macro, et sont mieux classes', desc: 'Deux changements sur la lecture des publications du jour. Elles se lisent maintenant APRÈS Macro et non avant : le rapport va du recit — géopolitique, moteurs, banques centrales — vers les chiffres qui l’étayent. Et leur classement ne repose plus sur des mots-cles approximatifs mais sur une table de correspondance indicateur par indicateur : CPI, Core CPI, PCE, Core PCE et PPI vont en INFLATION ; NFP, taux de chômage, salaire horaire, ADP et JOLTS vont en EMPLOI ; PIB, ventes au détail et les PMI vont en CROISSANCE ÉCONOMIQUE ; les décisions de taux ont leur propre rubrique POLITIQUE MONÉTAIRE. La table a été étendue aux équivalents hors États-Unis — un IPCH européen, un Tankan japonais, un Ifo allemand ou un taux directeur australien sont reconnus comme leurs homologues americains. Et rien ne se perd : une publication qui ne rentre dans aucune famille garde sa place sous Autres, au lieu de disparaitre. Même classement sur le desk et dans le mail.' },
  { id: 'dtpu-20260825-cb-dans-macro', ts: Date.UTC(2026, 7, 26, 8, 0), title: 'Récap Quotidien : les banques centrales se lisent avec le reste de la macro', desc: 'La posture des banques centrales avait sa propre section, juste avant Macro. Les deux parlaient pourtant de la même chose : ce qui fait bouger les devises ce jour-la. Elles n’en font plus qu’une. Sous MACRO, vous trouvez désormais Banques centrales — décision, minutes, discours, avec leur réaction de marché chiffrée — puis Autres moteurs : stocks, flux, commerce. Quand une seule des deux matières existe ce jour-la, la section reste telle que vous la connaissiez, sans sous-titre inutile. Même changement sur le desk et dans le mail.' },
  { id: 'dtpu-20260825-geo-trois-points', ts: Date.UTC(2026, 7, 25, 23, 45), title: 'Géopolitique : les trois développements qui comptent, au lieu de quatorze', desc: 'La section Géopolitique du Récap Quotidien déroulait jusqu’à quatorze puces : chaque développement du dossier, y compris les phrases sans substance du type « le porte-parole refuse de commenter » ou « les positions restent éloignées ». Tant qu’une rubrique de synthèse la distillait, cette longueur passait ; depuis son retrait, la liste brute restait seule et se lisait comme un mur. Elle garde désormais les TROIS développements qui comptent, sur le desk comme dans le mail. Le classement ne doit rien au hasard : passent en premier ceux dont l’effet marche est mesure, puis ceux qui portent un chiffre, puis ceux qui relèvent du vocabulaire des développements majeurs (sanctions, frappes, cessez-le-feu, droits de douane...). Les trois retenus sont ensuite remis dans l’ordre de la note : vous lisez la journée dans sa séquence, pas dans un classement. Rien n’est perdu cote données, seul l’affichage est resserre.' },
  { id: 'dtpu-20260824-recap-quotidien-reparation', ts: Date.UTC(2026, 7, 25, 23, 30), title: 'Le Récap Quotidien se rouvre normalement depuis l’onglet Analystes', desc: 'Une erreur introduite plus tôt dans la journée empechait le Récap Quotidien de s’afficher : il apparaissait bien dans la liste de l’onglet Analystes, mais rien ne s’ouvrait au clic. En cause, le rangement des chiffres du jour par famille livre ce matin, qui lisait une valeur avant qu’elle n’existe et faisait echouer tout l’affichage du rapport. C’est repare, le rapport se rouvre normalement avec ses rubriques Croissance économique, Emploi et Inflation. Aucune donnée n’a été perdue : seul l’affichage était touche.' },
  { id: 'dtpu-20260824-hebdo-miroir-desk', ts: Date.UTC(2026, 7, 25, 23, 0), title: 'Récap Hebdo par mail : exactement les rubriques du rapport, et rien d’autre', desc: 'Le mail du samedi portait NEUF rubriques quand le rapport du desk n’en affiche que deux : Géopolitique, avec sa chronologie rapide, puis La semaine devise par devise. Les sept autres étaient des rubriques que le desk avait retirées au fil du temps parce qu’elles repetaient les blocs devise : les Points macro cles (Performance Cross-Asset, Commerce International et Tarifs, Technologie et Innovation), la section Banques centrales autonome, le Calendrier économique, À surveiller, et l’image de la Force des devises. Le mail les publiait encore. Il ne montre désormais que ce que le rapport montre : vous lisez la même chose des deux cotes. Le Bilan de la semaine écoulée, lui, garde ses propres rubriques, ce sont celles que le desk lui donne. Au passage, dans le Récap Quotidien, la rubrique À surveiller se resserre : chaque rendez-vous tenait sur cinq lignes parce que Haut, Prévision, Bas et Précédent étaient empilés ; ils se suivent maintenant sur une seule ligne, et une référence vide ne s’écrit plus du tout.' },
  { id: 'dtpu-20260824-quotidien-familles', ts: Date.UTC(2026, 7, 25, 22, 0), title: 'Récap Quotidien : les chiffres du jour se rangent par famille', desc: 'Les publications de la journée étaient listées sous CHAQUE séance, mélangées : une inflation, un PMI et des inscriptions au chômage se suivaient parce qu’ils étaient sortis à la même heure, pas parce qu’ils parlaient de la même chose. Elles se rangent désormais par famille, comme dans le Récap Hebdo : CROISSANCE ÉCONOMIQUE, EMPLOI, INFLATION — les banques centrales gardant leur section à part. Chaque ligne porte sa devise, son réel, l’attendu et le précédent, avec la couleur de la surprise, et reste cliquable pour ouvrir son decryptage. Les séances, elles, gardent ce qui leur est propre : leur analyse. Vous lisez donc la journée par thème, une seule fois, au lieu de trois listes horaires ou il fallait retrouver soi-même les chiffres qui se repondent. Même changement sur le desk et dans le mail.' },
  { id: 'dtpu-20260824-quotidien-entete-etiquettes', ts: Date.UTC(2026, 7, 25, 21, 0), title: 'Récap Quotidien : étiquettes plus courtes, titre date, et une redite en moins', desc: 'Trois réglages sur le Récap Quotidien. Les ÉTIQUETTES du rapport étaient écrites en toutes lettres — « Rachat de bons du Trésor americain », « Ventes au détail néo-zélandaises » — et sept d’entre elles prenaient trois lignes avant même le texte. Elles sont désormais raccourcies par règles (« Rachat Trésor US », « Ventes détail NZ ») : deux lignes au lieu de trois, et une étiquette déjà courte reste intacte. Jamais de troncature en plein mot. Le TITRE porte maintenant sa date : « Votre Récap Quotidien — vendredi 21 août 2026 » sur une seule ligne, au lieu du nom seul suivi de la date en dessous. Enfin la rubrique « Points cles à retenir » disparaît du rapport, sur le desk comme dans le mail : elle distillait en trois lignes la section Géopolitique qui la précède immédiatement, donc vous relisiez la même journée deux fois de suite.' },
  { id: 'dtpu-20260824-hebdo-forts-bouton', ts: Date.UTC(2026, 7, 25, 20, 0), title: 'Récap Hebdo par mail : fin du doublon, et le bouton passe après le rapport', desc: 'Deux réglages demandes sur piece. La rubrique « Temps forts de la semaine écoulée » est retirée du mail : elle répétait mot pour mot les publications que le Calendrier économique déroule juste en dessous, la même donnée deux fois. Le desk ne l’affiche pas non plus sur ce rapport. Rien n’est perdu, un doublon disparaît. Et le bouton « Ouvrir le desk » quitte le haut du mail pour se placer APRÈS le récap, sous la phrase de cloture : vous lisez d’abord le rapport, on vous propose ensuite d’ouvrir le desk, au lieu d’un appel à l’action pose avant toute valeur.' },
  { id: 'dtpu-20260824-hebdo-mail-fidele', ts: Date.UTC(2026, 7, 25, 19, 0), title: 'Votre Récap Hebdo par mail : l’introduction revient, et l’ordre est celui du desk', desc: 'Le mail du samedi portait vos rubriques, mais pas dans l’ordre du rapport — et il lui manquait sa première page. L’INTRODUCTION, les deux ou trois phrases qui ouvrent le Récap Hebdo et donnent le verdict de la semaine, ne partait JAMAIS. Elle était bien écrite, puis perdue au moment d’assembler le mail, sans qu’aucune erreur ne le signale : vous receviez le rapport sans son ouverture. Elle est de retour, en tête. La GÉOPOLITIQUE remonte ensuite en premier, comme sur le desk, au lieu d’arriver en septième position derrière quatre rubriques : sur un mail long, elle tombait dans la partie que Gmail replié derrière « Message tronque ». Les Points macro cles portent enfin leur nom, au lieu de s’afficher sous le titre « Synthèse de la semaine » emprunte à l’autre rapport hebdomadaire. Et trois rubriques qui pouvaient rester vides sans raison sont reparées : les Temps forts de la semaine, désormais classes par importance avant d’être coupes à neuf — une décision de taux ou un chiffre d’inflation ne peut plus être evince par les sondages de confiance du lundi —, le Calendrier économique, et les Moteurs de chaque devise, dont les formats les plus anciens étaient écartés en silence.' },
  { id: 'dtpu-20260824-reaction-bandeau-retire', ts: Date.UTC(2026, 7, 25, 18, 0), title: 'Réaction : le bandeau sur les cotations en retard disparaît', desc: 'Sous le graphique de réaction, un bandeau vous annoncait que les cotations suivant la publication n’étaient pas encore arrivées, que le flux est diffère d’une dizaine de minutes et que le graphique se completerait tout seul. Le flux etant diffère par construction, ce bandeau se posait sur presque chaque publication fraiche et recouvrait le bas du graphique. Il est retiré. Rien ne change au fonctionnement : le repère reste pose sur la dernière cotation connue, et le graphique continue de se completer tout seul tant que vous le laissez ouvert. Le message « Marche ferme » reste en place, lui : quand une publication tombe hors des heures de cotation, aucune cotation n’arrivera avant la réouverture, et mieux vaut le dire que laisser lire une réaction qui n’a pas eu lieu.' },
  { id: 'dtpu-20260824-hebdo-structure-desk', ts: Date.UTC(2026, 7, 25, 17, 0), title: 'Votre Récap Hebdo arrive dans le mail avec la structure du desk', desc: 'Même traitement que pour le Récap Quotidien : le rapport hebdomadaire vous arrive avec exactement les rubriques du desk, et dans le même ordre. Deux manquaient purement et simplement. « L’essentiel », qui ouvre le rapport et reste la seule rubrique que lira un lecteur presse, et « Temps forts de la semaine écoulée », avec les chiffres des publications à fort impact : elles sont la désormais. Et « Synthèse de la semaine », la rubrique la plus lue du rapport, ne pouvait en réalité JAMAIS s’afficher dans le mail, car il la cherchait sous un nom qu’elle ne portait pas ; rien ne le signalait, la rubrique disparaissait simplement. Corrige. Enfin les rubriques se suivent maintenant dans l’ordre du rapport et non dans celui ou le programme les calculait : L’essentiel, Temps forts de la semaine écoulée, Synthèse de la semaine, Calendrier économique, Géopolitique et sa chronologie rapide, puis la semaine devise par devise.' },
  { id: 'dtpu-20260824-etiquettes-recap', ts: Date.UTC(2026, 7, 25, 16, 0), title: 'Les étiquettes du Récap Quotidien passent aussi dans le mail', desc: 'Sur le desk, votre Récap Quotidien porte ses thèmes du jour juste sous le titre : « Fed », « BoJ », « PMI », « Géopolitique Moyen-Orient »... On les lit d’un coup d’œil avant même d’entrer dans le texte, et elles font partie du rapport, pas du decor du lecteur. Le mail n’en portait aucune. Elles suivent maintenant la date, exactement comme sur le desk.' },
  { id: 'dtpu-20260824-mail-bon-rapport', ts: Date.UTC(2026, 7, 25, 15, 0), title: 'Le mail « Votre Récap Quotidien » porte bien le Récap Quotidien', desc: 'Le desk publié deux rapports dans la journée : le « Point Marche · Ouverture US », juste avant la séance américaine, et le Récap Quotidien, qui clôt la journée. Le mail prenait simplement le plus récent des deux : en journée, c’était donc l’Ouverture US qui partait sous le titre « Votre Récap Quotidien », avec une organisation qui ne ressemblait pas à celle du rapport annonce. Le mail exige désormais LE Récap Quotidien, et sa structure : synthèse, géopolitique et points cles, banques centrales, macro, les trois séances avec leurs chiffres publiés, puis les rendez-vous à surveiller. La planification suit la même règle : tant que le Récap Quotidien du jour n’est pas publié, le mail ne part pas et repasse au cycle suivant. La sortie de l’Ouverture US ne declenche plus rien.' },
  { id: 'dtpu-20260824-propos-explication', ts: Date.UTC(2026, 7, 25, 14, 0), title: 'Les news de propos vous disent enfin de quoi il retourne', desc: 'Quand une personnalite politique ou un banquier central s’exprime, le fil regroupe ses phrases sur une seule carte, et l’onglet Info se contentait de les traduire. Vous lisiez la citation sans savoir de quel dossier elle relevait, ni pourquoi un desk le suit. Désormais, sous les propos, une courte note du desk dit de quel dossier il s’agit et, quand il y en a vraiment un, par quel canal ce dossier touche les marchés : énergie, commerce, prime de risque, politique monétaire. Beaucoup de declarations n’ont aucun canal de marché : dans ce cas la note se limite au sujet, en une phrase, plutôt que d’en inventer un. Les propos, eux, ne bougent pas d’un mot, la note s’ajoute en dessous. Elle est préparée à l’avance : elle est déjà la quand vous ouvrez, elle n’arrive jamais par-dessus ce que vous êtes en train de lire. Trois garde-fous : le desk ne prete jamais une fonction ni un titre à quelqu un qu’il ne connait pas avec certitude, il ne dit jamais dans quel sens un marché va aller ni quoi faire de votre argent, et il ne se contente jamais de reformuler la phrase que vous venez de lire. Quand il n’a rien de sur à dire, il se tait et vous voyez la citation seule, comme avant.' },
  { id: 'dtpu-20260824-mail-recap-seul', ts: Date.UTC(2026, 7, 25, 13, 0), title: 'Le mail du mercredi ne fait plus que vous donner le Récap Quotidien', desc: 'Il portait encore une accroche sur le climat de risque, l’image de la force des devises, une ligne de biais et un bouton pose avant le contenu. Tout cela a disparu : vous ouvrez le mail et vous tombez directement sur le rapport du jour, dans l’ordre exact du desk, la synthèse en tête puis géopolitique, banques centrales, macro, les trois séances avec leurs chiffres publiés et enfin les rendez-vous à surveiller. Un seul bouton subsiste, en pied, pour ouvrir le desk. Et l’envoi ATTEND désormais la publication du récap : tant qu’il n’est pas sorti, le mail ne part pas et repasse au cycle suivant, au lieu d’expedier celui de la veille.' },
  { id: 'dtpu-20260824-radar-colonne-biais', ts: Date.UTC(2026, 7, 25, 12, 0), title: 'Radar de Biais : la colonne Biais ne se coupe plus en plein mot', desc: 'Sur le Radar de Biais, la dernière colonne payait la largeur du tableau : « Légèrement haussier » s’affichait « Légère... » et il fallait faire defiler pour lire le biais, c’est-a-dire la conclusion. Mesure : le tableau réclamait 940 pixels pour se montrer en entier, et debordait de 278 pixels sur un panneau de 640. Trois économies sans retirer la moindre information : le libelle de biais à le droit de passer à la ligne, les intitulés de colonne cessent d’être insécables (« POLITIQUE MONÉTAIRE » imposait 132 pixels à une colonne qui n’en demande que 80), et les gouttières passent de 12 à 9 pixels. Le tableau tient désormais des 760 pixels. Sur un panneau plus étroit encore, il défile toujours, mais plus rien n’est tronque en silence.' },
  { id: 'dtpu-20260824-textes-qui-changent', ts: Date.UTC(2026, 7, 25, 11, 0), title: 'Fini le résume qui change tout seul pendant que vous le lisez', desc: 'En ouvrant Info sur une news, vous voyiez d’abord la dépêche d’origine, puis le texte était REMPLACE quelques secondes plus tard par la lecture du desk. Vous commenciez une phrase et elle se dérobait. Désormais, quand la lecture du desk est déjà prete elle s’affiche directement ; sinon c’est un voile de chargement qui occupe la place, à la hauteur exacte du texte à venir, et le texte définitif se pose dessus. Rien ne bouge plus sous vos yeux et la page ne saute pas. Si la lecture du desk tarde ou echoue, la dépêche d’origine prend le relais, et une réponse qui arriverait en retard ne vient plus ecraser ce que vous êtes en train de lire. La règle vaut pour TOUS les panneaux du fil, pas seulement Info.' },
  { id: 'dtpu-20260824-axe-dates-risque', ts: Date.UTC(2026, 7, 25, 10, 0), title: 'Sentiment du risque : les dates sous le graphique redeviennent lisibles', desc: 'Sur la bande d’historique du sentiment, l’axe des dates s’affichait en 9 pixels gris très pale. Mesure du contraste sur le fond du desk : 3,99 pour 1, en dessous même du minimum de 4,5 recommande pour du petit texte, et plus faible que tous les autres axes du terminal. Les dates passent en 11 pixels, plus claires et en gras léger, avec des repères verticaux un peu moins fantomatiques : 9,11 pour 1 en thème sombre et 7,56 en thème clair, les deux au-dessus du seuil le plus exigeant. C’est exactement le réglage déjà retenu pour le profil de risque de la semaine.' },
  { id: 'dtpu-20260824-reaction-cadre-vide', ts: Date.UTC(2026, 7, 25, 9, 0), title: 'Réaction : plus de grand rectangle noir quand il n’y à rien a tracer', desc: 'Quand une publication est trop ancienne pour que les cotations à la minute la couvrent encore, le bouton Réaction affiche une phrase qui l’explique. Mais le cadre du graphique, taille pour des bougies, gardait ses 320 pixels : la phrase flottait au-dessus d’un grand vide noir et il fallait faire defiler pour retrouver le fil. Le cadre se replie désormais sur son texte, une ligne, et la lecture reprend aussitôt. S’il retrouve des bougies plus tard, il reprend sa hauteur normale.' },
  { id: 'dtpu-20260824-recaps-offerts', ts: Date.UTC(2026, 7, 25, 8, 0), title: 'Vos deux récaps arrivent désormais ENTIERS dans votre boîte mail', desc: 'Le point marche du mercredi devient « Votre Récap Quotidien » et le digest du samedi « Votre Récap Hebdo » : ils ne résument plus le rapport du desk, ils le DONNENT en entier. Le quotidien porte la synthèse complète, la géopolitique et ses points cles, les banques centrales, la macro, les trois séances avec les chiffres publiés rattaches à chacune (heure, réel, attendu, précédent), et « À surveiller » déroule comme le calendrier. L’hebdo porte l’introduction, le recit géopolitique et sa chronologie, les banques centrales avec leurs propos dates, les thèmes macro, puis TOUTES les devises, chacune avec son résumé, sa politique monétaire, son pricing, son inflation, sa croissance et son emploi, ses moteurs, son biais et sa semaine à venir. Plus aucune coupe : ce que le desk publié, vous le lisez. Au passage, le Récap Quotidien perd deux rubriques : « À surveiller » n’est plus qu’un calendrier déroule (les puces qui le precedaient repetaient le tableau juste en dessous) et « Actualité des entreprises » disparaît, hors sujet sur un terminal macro et forex.' },
  { id: 'dtpu-20260823-eclairages-desk', ts: Date.UTC(2026, 7, 24, 19, 0), title: 'Les Éclairages prennent le nom du desk', desc: 'Le panneau d’analyse des rapports s’appelle désormais « Éclairages desk » : mêmes cartes par actif, mêmes badges ACHAT / VENTE / NEUTRE, sous le nom de la lecture maison du desk. Rien d’autre ne change.' },
  { id: 'dtpu-20260823-emails-identite', ts: Date.UTC(2026, 7, 24, 18, 0), title: 'Nos e-mails font peau neuve : une seule identité, des contenus à jour', desc: 'Tous les e-mails DataTradingPro (bienvenue, campagne hebdomadaire, annonces, rappels) partagent désormais la même identité visuelle : bandeau doré, même en-tête, mêmes titres, mêmes boutons et encadrés : on reconnait un mail DTP au premier coup d’œil. Leurs contenus sont realignes sur le desk d’aujourd’hui : la lecture banque centrale sur chaque publication, le graphe de réaction à la minute, les nouveaux widgets d’analyse cites par leur vrai nom. Rien ne change à la cadence ni à la désinscription.' },
  { id: 'dtpu-20260823-lecture-par-la-posture', ts: Date.UTC(2026, 7, 24, 17, 0), title: 'Chaque statistique se lit désormais face à la posture de sa banque centrale', desc: 'Un principe de desk institutionnel entre dans le terminal : l’impact d’une publication ne dépend pas seulement de son écart au consensus, mais de la POSTURE de sa banque centrale : un CPI plus chaud que prévu face à une banque ouvertement dovish fait peu bouger sa devise, car le marché sait qu’elle n’entend pas réagir. Concretement : le Decryptage de chaque publication (CPI, NFP, PMI...) porte désormais un bloc Banque centrale compact : le ton récent MESURE sur les vraies declarations, une ligne « Lecture par la posture » qui dit si ce ton amplifie ou amortit la surprise, les derniers propos du banquier central dates et attribués, et la prochaine réunion avec son pricing. Et la lecture « Impact marche » des statistiques confronte elle aussi le chiffre au pricing réel de la prochaine réunion, au lieu de commenter l’écart dans le vide.' },
  { id: 'dtpu-20260823-accueil-calendrier-entier', ts: Date.UTC(2026, 7, 24, 16, 0), title: 'Accueil : les chiffres du calendrier ne sont plus jamais coupes', desc: 'Sur l’écran d’accueil, le calendrier économique tronquait ses valeurs (« 1.41... ») et ses intitulés de colonnes : le panneau était juste au-dessus du seuil ou la table s’adapte. Le mode compact s’applique désormais des 700 pixels de largeur de panneau : les colonnes Haut et Bas (presque toujours vides) s’effacent, les intitulés s’abregent proprement, et les chiffres réel / prévision / précédent s’affichent TOUJOURS en entier : c’est le nom de l’événement qui cede la place, jamais la donnée.' },
  { id: 'dtpu-20260823-six-widgets', ts: Date.UTC(2026, 7, 24, 15, 0), title: 'Six nouveaux widgets d’analyse : courbe des taux, corrélations, volatilité par heure...', desc: 'La bibliothèque Mon Desk s’enrichit de six widgets construits sur la nouvelle grammaire (verdict factuel, données situées, fraicheur affichée). COURBE DES TAUX US : les 4 échéances du Trésor et l’écart 10 ans - 3 mois sur 90 jours, avec le verdict pentue / plate / inversée et sa lecture d’école. PROCHAINE RÉUNION BC : les 8 banques centrales triées par réunion la plus proche, compte à rebours vivant et scénario price, les issues encore ouvertes signalées. CORRÉLATIONS ENTRE PAIRES : la matrice 30 séances des 7 majeures : deux positions corrélées font une seule exposition, le widget le dit. VOLATILITÉ PAR HEURE : le profil moyen des 24 heures, l’heure courante marquee, pics et creux nommes par session. ÉCART AU CONSENSUS : les 10 dernières publications majeures, réel contre attendu, avec le bilan directionnel des surprises. PERFORMANCE DE LA SEMAINE : le classement des 8 devises depuis lundi. Chacun arrive avec sa fiche d’aide complète (lecture, source, quoi surveiller).' },
  { id: 'dtpu-20260823-calculatrice-couts-aide', ts: Date.UTC(2026, 7, 24, 14, 0), title: 'Calculatrice : spread et commission inclus au calcul + un vrai guide dans chaque widget', desc: 'La calculatrice de taille de position accepte désormais le spread de l’actif (en pips) et la commission par lot ; champs vides = zero, calcul identique à avant. Quand ils sont renseignes, la taille en tient compte honnetement : le spread se paie à l’entrée, la commission par lot aussi, et la perte maximale affichée reste alors EXACTEMENT votre risque, couts compris : une carte « Couts (déjà inclus) » détaillé ce que la position absorbe. La mise en page respire sur grand écran : résultats bornes et centres, chiffres plus grands. Et le volet d’aide « ? » de CHAQUE widget devient un vrai guide en cinq sections : ce que montre le widget, comment le lire, d’où vient la donnée et à quelle cadence elle se rafraîchit, ce qu’il faut surveiller, et les réglages : les quarante et un widgets du desk sont couverts, écrits d’après ce que chacun fait réellement.' },
  { id: 'dtpu-20260823-widgets-vivants', ts: Date.UTC(2026, 7, 24, 13, 0), title: 'Les nouveaux widgets prennent vie : chaque carte dit ce que ses chiffres signifient', desc: 'Refonte complète des quinze widgets récemment ajoutes, sur un constat simple : des chiffres bruts sans lecture semblent morts. Chaque carte porte désormais une LIGNE DE VERDICT qui dit ce que la donnée signifie maintenant (« aujourd’hui : 50 pips, 78% de la moyenne : séance dans la norme », « Août est historiquement le meilleur mois d’EUR/USD : 4 années sur 4 en hausse », « Les fonds sont nettement acheteurs nets d’EUR, rapport du 12/08 »), toujours factuelle, jamais un conseil. Chaque valeur est SITUÉE (vs moyenne, percentile, seuil) au lieu d’être affichée seule. Chaque carte PROUVE sa fraicheur : horodatage discret (« à l’instant », « il y a 4 min ») et fondu sobre de la valeur qui change, sans jamais clignoter. Le present est marque en or : mois en cours, place en séance, position actuelle. Et une série de rigueurs invisibles : un dimanche, une carte dit « vendredi » et non « aujourd’hui » ; un mois entamé ne biaise plus les moyennes historiques ; une donnée absente se tait au lieu de compter pour zero ; le COT est date par son rapport hebdomadaire. Le bandeau de cotations cesse enfin de sauter à chaque mise à jour.' },
  { id: 'dtpu-20260823-widgets-corrections', ts: Date.UTC(2026, 7, 24, 12, 0), title: 'Widgets : Remplacer remplace vraiment, cartes IA jamais coupées, noms plus parlants', desc: 'Trois corrections nettes. Le bouton Remplacer d’un onglet occupe AJOUTAIT un onglet au lieu de remplacer le widget en place : il remplace désormais (seul un onglet composite reste protégé, pour ne pas ecraser plusieurs widgets d’un coup). Les cartes Éclairages IA se dimensionnent pour qu’un nombre entier tienne toujours à l’écran : plus jamais de badge ACHAT/VENTE/NEUTRE coupe en plein milieu, et les fleches avancent par page entière. Enfin, cinq widgets au nom opaque sont renommes pour dire ce qu’ils montrent : Rendement moyen par mois (ex-Courbe saisonnière), Probabilité de mouvement, Historique d’un indicateur, Carte de chaleur FX, Sentiment des particuliers et Particuliers par paire.' },
  { id: 'dtpu-20260823-lisibilite-rapports', ts: Date.UTC(2026, 7, 24, 11, 0), title: 'Rapports plus scannables, Radar ordonne, courbes Taux visibles, infobulles courtes', desc: 'Série d’affinages demandes sur pieces. Le Récap Hebdo devient lisible à vue d’œil : introduction et recit géopolitique resserres en phrases courtes et denses, résumés par devise en 2-3 phrases verdict d’abord, et la Chronologie rapide détaillé désormais CHAQUE jour ou le fil à bouge au lieu de compresser la semaine en deux blocs. La Semaine à Venir enrichit ses descriptions d’une phrase « pourquoi ça compte » propre à la famille du jour (NFP, CPI, PIB, PMI...) au lieu de répéter la même formule. Le Radar de Biais classe ses devises dans l’ordre fixe des salles de marché (USD, EUR, JPY, GBP, CHF, AUD, CAD, NZD) : l’œil mémorise. Les mini-courbes de l’onglet Taux, quasi invisibles, retrouvent leur présence. Les infobulles des boutons vont à l’essentiel (Aide, Réglages, Remplacer, Retirer...). Et sept widgets qui avaient perdu leur catégorie dans la bibliothèque la retrouvent, tout comme la fiche d’aide du Sentiment de Risque, écrite depuis des semaines mais jamais affichée à cause d’un champ mal place.' },
  { id: 'dtpu-20260823-tags-weekend', ts: Date.UTC(2026, 7, 24, 10, 0), title: 'Week-end : plus de tags de marché sur les news publiées marchés fermés', desc: 'Une actualité publiée pendant la fermeture du week-end n’a aucune réaction de marché à montrer, ni sur le moment, ni plus tard. Les tags de paire, le tag or et le bouton Réaction ne se posent donc plus sur ces publications (une news du vendredi consultée le dimanche garde les siens : sa réaction existe). Et quand une réaction s’avere introuvable sur une news en semaine, le panneau EXPLIQUE désormais pourquoi avant de retirer le bouton, au lieu de le faire disparaitre sans un mot sous le clic. Le tag XAUUSD reçoit aussi son contour, comme les paires de devises.' },
  { id: 'dtpu-20260822-reaction-minute', ts: Date.UTC(2026, 7, 24, 9, 0), title: 'Réaction à la bougie d’une minute, analyse plus rapide et horodatages exacts', desc: 'Trois affinages sur la lecture d’une publication. Le graphique de réaction choisit désormais son unité selon le mouvement réellement mesure : quand le marché à bouge (un CPI du matin, l’or), il trace la bougie d’UNE minute sur une fenêtre serrée autour de la publication : on voit la réaction seconde après seconde ; quand la fenêtre est plate, il garde la vue large en cinq minutes, plus lisible. L’unité ne change jamais en cours de lecture. L’or s’affiche à deux décimales, comme il se cote. Les statistiques majeures qui tombent en titre nu (sans article) deviennent eligibles à l’Analyse et passent en tête de file : la lecture arrive dans les minutes qui suivent le chiffre. Enfin, l’en-tête des panneaux Analyse et Impact marche affiche l’heure VRAIE de la génération, pas celle de la news.' },
  { id: 'dtpu-20260822-lecture-weekend', ts: Date.UTC(2026, 7, 24, 8, 0), title: 'Fil : majuscules des phrases traduites + graphique de réaction lisible le week-end', desc: 'Deux finitions de lecture. Les dépêches traduites en français commencaient parfois leurs phrases en minuscule : chaque retour à la ligne ouvre désormais sa phrase avec une majuscule, y compris sur les traductions déjà en mémoire. Et le graphique de réaction ouvert un samedi ne montrait qu’une poignée de bougies étirées sur toute la largeur : quand le marché était ferme au moment de la publication, il affiche désormais les trois dernières heures réellement cotées avant la fermeture : un contexte dense et lisible (vérifie : 37 bougies, 25 points d’amplitude, contre une dizaine etirée avant), le repère et la note de fermeture restant en place.' },
  { id: 'dtpu-20260822-geo-or', ts: Date.UTC(2026, 7, 24, 7, 0), title: 'Les actualités géopolitiques montrent leur marche refuge : l’or', desc: 'Une tension géopolitique importante n’expose pas une paire de devises : elle expose l’or, la valeur refuge. Ces actualités portent désormais une pastille dorée XAUUSD ; un clic ouvre le graphique de réaction de l’or, bougies minute par minute avec le repère rouge sur l’instant exact de la publication : la même mecanique que sur les statistiques. La source des bougies est le contrat à terme sur l’or, le seul à offrir de vraies bougies à la minute (vérifie : zero bougie plate sur la séance). Les actualités dont l’or est le sujet du titre reçoivent la même pastille.' },
  { id: 'dtpu-20260822-mobile-defilement', ts: Date.UTC(2026, 7, 24, 6, 0), title: 'Mobile : le défilement du terminal est enfin fluide et chaque vue tient l’écran', desc: 'Grand audit du rendu sur téléphone : 48 vérifications automatisées, chaque défaut mesure puis contre-vérifie avant correction. Le résultat le plus visible : le fil d’actualité défile désormais DANS son cadre : la barre de recherche et les filtres restent en place, la date du jour reste épinglée en haut pendant la lecture, et une dépêche qui arrive ne fait plus sauter la page sous le doigt. Le panneau déplié d’une news occupe toute la largeur (une bande restait vide à droite). Les vues Risque et Force des Devises retrouvent leur pleine hauteur : les courbes s’affichaient parfois sur un écran vide. La Saisonnalite, la vue paire, le lecteur de rapports, le tableau des Banques (colonne fixe en défilement), le Radar de Biais (colonne Biais revenue à l’écran) et une vingtaine d’autres détails (tailles de texte sous le seuil de lisibilité, zones de tap trop petites, survols qui restaient colles après un toucher) sont corriges dans la même passe.' },
  { id: 'dtpu-20260822-tag-indicateur-impact', ts: Date.UTC(2026, 7, 24, 5, 0), title: 'Fil : l’indicateur est nomme avec son drapeau, et l’Impact marche arrive sur les statistiques', desc: 'Quand une statistique tombe avec son chiffre (taux de chômage australien, CPI americain...), sa ligne porte désormais un tag qui NOMME l’indicateur, drapeau du pays en tête : on identifie la publication d’un coup d’œil, et le survol du tag en donne la definition. Le tag de la paire la plus exposée (deux drapeaux, cliquable vers la réaction du marché) reste à ses cotes. Et la lecture « Impact marche », jusqu ici réservée aux grandes analyses d’événement, est maintenant générée aussi pour les statistiques importantes du fil : verdict, mecanisme et actifs exposés avec leurs fleches, dans la même grille de lectures que Info, Analyse et Réaction. Le tout apparaît en direct, sans recharger la page.' },
  { id: 'dtpu-20260822-boutons-harmonises', ts: Date.UTC(2026, 7, 24, 4, 0), title: 'Boutons des widgets : mêmes tailles partout et ordre plus intuitif', desc: 'Passe d’harmonisation sur l’ensemble du terminal, pour un rendu de vrai système de design. Les petits boutons en tête de chaque widget (réglages, remplacer, aide, fermer) avaient, selon la vue, des tailles légèrement différentes : ils sont désormais parfaitement carres et identiques partout, sur ordinateur comme sur téléphone ou la zone tactile s’agrandit d’un bloc pour le doigt. Leur ordre devient plus logique et IDENTIQUE partout, en-têtes de cartes comme barres des panneaux à onglets : d’abord les commandes qui modifient le widget, puis l’aide, et la fermeture toujours à l’extreme droite. Les onglets de panneau adoptent aussi une seule taille de texte. Sur téléphone, les titres du fil ne touchent plus le bord et le défilement est plus doux. Rien ne change au fonctionnement : ce sont uniquement les dimensions et l’alignement qui sont mis au propre.' },
  { id: 'dtpu-20260821-bandeaux-premium', ts: Date.UTC(2026, 7, 24, 3, 0), title: 'Les bandeaux de panneau gagnent une finition premium plus soignée', desc: 'Les en-têtes de panneau du terminal, jusque-la des barres plates, reçoivent une finition plus soignée et sobre : un très léger dégradé de tête pour la profondeur, un fin repère doré juste avant le titre comme signature du desk, et un cheveu doré qui affleure le bas du bandeau, un peu plus marque à la demande, qui se précise au survol. C’est purement visuel, present pour tous les utilisateurs, et pense pour rester epure à la manière d’un terminal institutionnel.' },
  { id: 'dtpu-20260821-force-grille', ts: Date.UTC(2026, 7, 24, 2, 0), title: 'Force des Devises : grille de fond remise et courbes plus nerveuses', desc: 'Deux ajustements demandes en comparant notre graphique à une référence. La grille de fond horizontale, discrete et grise, est remise derrière les courbes, en complement de la grille verticale qui existait déjà : le graphique retrouve son quadrillage léger, sans les lignes colorées par devise qui avaient été retirées. Les courbes, elles, sont rendues avec davantage de points : la donnée était déjà fine côté serveur, mais le trace en simplifiait une partie pour éviter le moire ; ce filtre est allégé, si bien que les courbes montrent désormais leur vraie nervosite, plus proche de ce que l’on attend d’un indicateur de force des devises.' },
  { id: 'dtpu-20260821-icones-onglets', ts: Date.UTC(2026, 7, 24, 1, 0), title: 'Panneau à onglets : choisir une icone pour chaque onglet', desc: 'Dans la configuration du panneau à onglets, chaque onglet peut recevoir une icone, choisie dans une petite palette epurée, et affichée à côté de son nom dans la barre. Dix-huit icones au trait fin, aux couleurs du terminal : graphique, bougies, tendance, calendrier, horloge, cloche, globe, banque et d’autres. On l’ouvre d’un clic sur le carre à gauche du nom de l’onglet, on choisit, et l’icone apparaît aussitôt ; un bouton permet de la retirer. Le choix est enregistre automatiquement et suit le compte.' },
  { id: 'dtpu-20260821-dtp-partout', ts: Date.UTC(2026, 7, 24, 0, 0), title: 'Le nom s’affiche partout en trois lettres : DTP', desc: 'Le nom écrit en toutes lettres DataTradingPro laisse place au sigle DTP, plus court et plus lisible, là où il apparaît : en haut à gauche du terminal, sur l’écran de démarrage, et sur le site vitrine, pied de page et maquettes du produit compris. L’identité reste la même, l’affichage est simplement plus compact et plus net.' },
  { id: 'dtpu-20260821-separateurs', ts: Date.UTC(2026, 7, 23, 23, 30), title: 'Le filet de séparation entre les lignes devient enfin visible', desc: 'Les fines lignes qui séparent les lignes du fil d’actualité et du calendrier existaient déjà, mais règlées si bas qu’on ne les voyait pas : sept niveaux d’écart avec le fond, invisibles à l’œil. Elles sont relevées au niveau exact qui avait été valide sur le calendrier, environ dix-huit niveaux d’écart : visibles pour guider la lecture d’une ligne à l’autre, tout en restant discrètes et sobres, dans l’esprit d’une grille de terminal institutionnel. Le fil d’actualité masquait en plus son filet par une règle prioritaire qui forçait l’ancienne valeur : c’est corrigé, la séparation s’y voit désormais comme sur le calendrier.' },
  { id: 'dtpu-20260821-premium-tous', ts: Date.UTC(2026, 7, 23, 23, 0), title: 'L’habillage premium du desk est maintenant visible par tout le monde', desc: 'L’habillage premium, d’abord réserve au compte administrateur le temps de le valider, est désormais actif pour tous les utilisateurs sur l’ensemble du terminal : la scene sombre en profondeur, le halo doré très dilue, le fin filet doré en tête de chaque carte et le soupçon d’or sous les barres. Rien ne change au fonctionnement ni aux droits, c’est purement visuel, et l’effet n’a aucun cout d’affichage : il ne recalcule aucune mise en page, n’intercepte aucun geste, et se coupe si l’appareil demande la sobriéte.' },
  { id: 'dtpu-20260821-mobile-apercu', ts: Date.UTC(2026, 7, 23, 22, 0), title: 'Mobile : news entières et données de widgets lisibles + aperçu des modèles aux couleurs DTP', desc: 'Sur téléphone, le panneau qui se déplie sous une news (Info, Analyse, Réaction) heritait de la colonne étroite du titre et devenait illisible : il occupe désormais toute la largeur de l’écran, le texte retourne à la ligne et plus rien n’est masque. Les titres ne sont plus tronqués. Cote widgets, les données plus larges que la carte se font désormais defiler au doigt au lieu d’être coupées : un chiffre coupe est une information perdue. Enfin, l’aperçu des modèles de disposition abandonne ses blocs verts et bleus satures pour une palette tonale alignée sur l’identité dorée du terminal, plus sobre et plus professionnelle.' },
  { id: 'dtpu-20260821-lot-desk', ts: Date.UTC(2026, 7, 23, 21, 0), title: 'Fil plus lisible, Flash Marche parlant sur les news majeures, Assistant IA à 10 questions', desc: 'Trois améliorations. Le fil de news gagne un filet de séparation très discret entre les lignes et un texte de titre un cran plus net, pour suivre la lecture sans fatigue, dans l’esprit d’une grille de terminal institutionnel. Le Flash Marche en direct lit désormais à voix haute UNIQUEMENT les news économiques majeures, publications de données à fort impact, résultats du calendrier et décisions de banques centrales, au lieu de commenter tout le flux : la voix ne se declenche que pour ce qui bouge vraiment le marché, et elle est fiabilisée, plus de silence au démarrage et une voix plus naturelle quand le système en propose une. L’Assistant IA Macro passe de cinq à dix questions par jour et par compte, et ses réponses s’appuient davantage sur les données live du terminal avec une lecture actionnable en fin de réponse.' },
  { id: 'dtpu-20260821-premium', ts: Date.UTC(2026, 7, 23, 20, 0), title: 'Habillage premium étendu à tout le terminal et au site', desc: 'Le traitement premium, jusque-la limite à la vue des widgets pour le compte administrateur, couvre désormais la totalite du desk, toutes ses vues, le panneau latéral et le panneau d’administration : une scene sombre en profondeur, un halo doré très dilue en mouvement lent, un fin filet doré en tête de chaque carte qui se précise au survol, et un soupçon d’or sous les barres. L’effet reste réserve au compte administrateur sur le desk, et n’a aucun cout d’affichage : rien n’intercepte les gestes, aucune mise en page n’est recalculée, et l’animation se coupe si l’appareil demande la sobriéte. Le site vitrine, public, reçoit dans le même esprit un halo doré derrière l’accroche et des cartes qui se soulevent doucement au survol. Le logo en haut à gauche du site affiche maintenant un sceau DTP doré à côté du nom.' },
  { id: 'dtpu-20260821-aide-corrigee', ts: Date.UTC(2026, 7, 23, 19, 0), title: 'Aide des widgets : le bouton fonctionne, et il apparaît aussi dans le panneau à onglets', desc: 'Le point d’interrogation ajoute plus tôt ne repondait pas au clic : il cherchait la carte dans un endroit ou la liste des cartes ne se trouve pas, et sortait donc sans rien faire ni rien signaler. Corrige. Il manquait par ailleurs sur les widgets empilés dans un panneau à onglets, alors que c’est justement la qu’il sert le plus : ces widgets sont rangés sous des étiquettes très courtes, comme FORCE ou MONDE, qui ne disent rien de ce qu’ils font. Le bouton y figure désormais, en première position comme sur les cartes. La barre d’onglets gagne au passage deux pixels de hauteur : elle était assez serrée pour que les libellés touchent presque le filet du bas.' },
  { id: 'dtpu-20260821-onglets-sobres', ts: Date.UTC(2026, 7, 23, 18, 0), title: 'Onglets : le soulignement doré disparaît au profit d’un marquage plus sobre', desc: 'Chaque barre d’onglets du terminal portait un trait doré de deux pixels sous l’onglet actif. Répète sur toutes les barres, ce trait banalisait la couleur de marque au point qu’elle ne signalait plus rien : sur un terminal de marché, la couleur doit être réservée à ce qui porte un sens, une hausse, une baisse, une alerte, jamais à la simple navigation. L’onglet actif se distingue désormais par son encre passée au blanc, sa graisse, et un fond à peine plus clair qui l’assied sans le souligner. Dans la bibliothèque de widgets, les noms des cartes ne sont plus en gras : sur une grille ou tout est en gras, plus rien ne ressort, et c’est l’aperçu visuel de chaque carte qui doit porter l’attention.' },
  { id: 'dtpu-20260821-ecran-noir-veille', ts: Date.UTC(2026, 7, 23, 17, 0), title: 'Application de bureau : la vraie cause de l’écran noir après une longue ouverture', desc: 'Trois correctifs avaient déjà été tentes sans succès. La recherche a montré pourquoi. D’abord, la mise en veille du poste et le verrouillage de session n’étaient surveilles nulle part : or c’est exactement le moment ou Windows reconstruit l’affichage, et une fenêtre peut ne pas s’y raccrocher. Elle reste alors noire alors que tout fonctionne derrière. Ensuite, le sauvetage rechargeait la page, ce qui ne recrée pas la surface d’affichage : quand c’est elle qui est perdue, tous les rechargements du monde repeignent du noir. Enfin la surveillance automatique lisait ce que dessine le moteur de rendu, pas ce qui arrive à l’écran, donc elle ne pouvait pas voir ce type de panne. L’application force désormais un repeint à chaque reveil du poste, et si un incident revient elle recrée sa fenêtre au lieu de recharger la page. Un journal d’incidents est écrit sur le poste pour que la prochaine occurrence, s’il y en a une, soit diagnostiquee sur des traces et non sur des hypothèses. Version 1.0.19.' },
  { id: 'dtpu-20260821-audit-securite', ts: Date.UTC(2026, 7, 23, 16, 0), title: 'Audit de sécurité : correctifs appliqués, dont une faille qui visait le compte administrateur', desc: 'Un audit complet du terminal a été mene. Le défaut le plus sérieux permettait à un abonne d’envoyer une piece jointe piegée dans la messagerie de support : le fichier passait pour une image parce que seul le debut de son nom était vérifie, et son contenu s’exécutait ensuite dans la session de l’administrateur au moment de lire le message. La vérification porte désormais sur la forme complète du fichier, et seuls les formats d’image classiques sont acceptes ; tout le reste est affiche comme du texte. Corrige aussi : les pages qui fabriquent les images des e-mails étaient accessibles sans compte et exposaient en clair des widgets réserves aux abonnes, elles sont maintenant réservées au serveur lui-même. Les couleurs du Radar de Biais sont par ailleurs realignées sur la charte du terminal, avec une nuance légèrement assombrie sur un palier dont le texte blanc passait sous le seuil de lisibilité.' },
  { id: 'dtpu-20260821-widgets-vivants', ts: Date.UTC(2026, 7, 23, 15, 0), title: 'Les cartes de Mon Desk se mettent toutes à jour, y compris celles qui restaient figées', desc: 'Vérification faite carte par carte : vingt-deux des trente-quatre widgets se rafraichissaient déjà, douze jamais. Trois n’en ont pas besoin puisque leur contenu vient de vous, les Notes, la Calculatrice et le Panneau à onglets. Les neuf autres sont corrigées. Le cas le plus trompeur était le Barometre des Devises : en carte, son minuteur vérifiait que l’onglet Barometre du terminal était ouvert, ce qui n’est jamais le cas dans Mon Desk. Il se supprimait donc lui-même quinze secondes après l’affichage. La carte paraissait vivante et ne bougeait plus jamais, ce qui est pire qu’une carte sans mise à jour puisque rien ne le signale. La Force des Devises, elle, restait figée à l’instant de son affichage. Les cadences suivent la vitesse réelle de chaque source : une minute pour le calendrier économique dont les valeurs se remplissent au fil des publications, cinq minutes pour les taux directeurs, trente minutes pour les données historiques comme la saisonnalite ou le positionnement COT. Sur ces dernières le rythme sert surtout à se reparer : si le premier chargement echouait, la carte restait en erreur jusqu au rechargement de la page. Aucune carte ne se rafraîchit lorsqu elle est masquee ou hors écran.' },
  { id: 'dtpu-20260821-aide-widgets', ts: Date.UTC(2026, 7, 23, 14, 0), title: 'Chaque widget explique désormais à quoi il sert', desc: 'Un point d’interrogation apparaît dans l’en-tête de chaque widget, sans exception. Il ouvre un volet à droite qui dit ce que le widget montre, comment le lire, et quels réglages il propose. Douze widgets parmi les plus denses reçoivent en plus une lecture approfondie : Force des Devises, Différentiel de taux, Taux directeurs, Radar de Biais, Calendrier économique, Sentiment de Risque, Positionnement COT, Barometre des Devises, Calculatrice de position, Journal de trading, Sessions de marché et Horloge mondiale. On y explique par exemple pourquoi la moyenne du différentiel de taux exclut la devise concernée, ou pourquoi une probabilité affichée sur une réunion de banque centrale ne dit pas ce qui va arriver mais ce qui est déjà dans les prix. Le volet reprend la grammaire des autres panneaux du terminal : il se cale sous la barre du haut, un seul volet reste ouvert à la fois, et la touche Echap le ferme.' },
  { id: 'dtpu-20260821-essai-fr-large', ts: Date.UTC(2026, 7, 23, 13, 0), title: 'Essai d’un mois : toutes les dépêches dépliées arrivent directement en français', desc: 'La pre-traduction ne se limite plus aux news importantes : pendant un mois, toute dépêche que vous dépliez s’ouvre directement en français, sans le bref passage par l’anglais qui précédait la bascule. Deux garde-fous encadrent l’essai. Cette tache est la première à ceder : elle s’arrêté d’elle-même dès que la consommation quotidienne d’intelligence artificielle approche son plafond, et le terminal revient alors au comportement actuel, la traduction à l’ouverture. Un plafond qui lui est propre l’empeche par ailleurs de consommer la réserve destinée à des contenus qui n’ont aucun repli, comme les analyses du Radar de Biais ou la Semaine à Venir. Les dépêches importantes sont traduites en premier, de sorte que si la journée se coupe en cours de route, ce sont celles qui comptent qui auront été faites. Le volume traite chaque jour est mesure et consultable, pour decider à la fin du mois sur des chiffres plutôt que sur une impression.' },
  { id: 'dtpu-20260821-depeches-fr', ts: Date.UTC(2026, 7, 23, 12, 0), title: 'Les dépêches importantes s’ouvrent directement en français', desc: 'Jusqu ici, une news importante dont la dépêche était trop courte pour mériter une analyse s’affichait en anglais, puis basculait en français après un aller-retour. D’ou l’anglais visible une fraction de seconde, et durablement les jours ou le service de traduction ne repondait pas. Ces dépêches sont désormais traduites À L’AVANCE, en tache de fond : le depliage s’ouvre directement en français, sans requête et sans clignotement. La portée est volontairement limitée aux news importantes. Le fil dépassé mille dépêches par jour et tout traduire consommerait le budget réserve à des contenus qui n’ont aucun repli, comme les narratifs du Radar de Biais ou la Semaine à Venir. Le reste du fil garde la traduction à l’ouverture, déjà en place. Et si une traduction echoue, rien n’est enregistre : la dépêche sera retentée au passage suivant plutôt que de rester figée en anglais.' },
  { id: 'dtpu-20260821-biais-taux', ts: Date.UTC(2026, 7, 23, 11, 0), title: 'Radar de Biais : le taux directeur de chaque banque, juste avant le biais', desc: 'Le tableau disait qu’une politique monétaire était restrictive ou accommodante sans jamais montrer le niveau, alors que c’est lui qui fait le portage, et que le portage pèse déjà dans le calcul du biais. Une colonne Taux directeur est ajoutée avant la colonne Biais. Le fond vert s’intensifie avec le taux, de sorte que le classement des devises se lit d’un coup d’œil, sans avoir à comparer les chiffres un à un ; l’échelle se recalcule chaque jour sur le taux le plus élevé du moment plutôt que d’être figée. La donnée vient de la même source que le widget Différentiel de taux et que l’onglet Taux : trois endroits qui affichent un taux directeur ne peuvent pas se contredire. Si la source est momentanement indisponible, la colonne affiche un point et le reste du tableau est intact.' },
  { id: 'dtpu-20260821-synthese-sans-resume', ts: Date.UTC(2026, 7, 23, 10, 0), title: 'Synthèse des Marches : le résume de tête disparaît, le rapport va droit au fait', desc: 'Le rapport de cloture s’ouvrait sur quatre puces de synthèse qui redisaient ce que les rubriques donnaient juste en dessous. Le Stoxx et le DXY y figuraient une première fois, puis une seconde dans Marches ; les PMI une première fois, puis une seconde dans Macro. Sur un texte déjà court que l’on parcourt entre deux publications, un résumé place avant fait lire deux fois la même chose. Il est retiré : le rapport commence directement par la géopolitique, qui donne le regime de la séance, puis enchaîne sur la macro, les banques centrales, les marchés et les échéances à surveiller.' },
  { id: 'dtpu-20260821-synthese-structure', ts: Date.UTC(2026, 7, 23, 9, 0), title: 'Synthèse des Marches : même structure que les autres rapports du desk', desc: 'Le rapport de cloture suivait sa propre organisation, heritée d’empilements successifs : treize rubriques, dont plusieurs disaient la même chose. Trois d’entre elles portaient des chiffres publiés, quatre decoupaient le marché en actions, devises, obligataire et matières premières pour souvent deux lignes chacune, et trois autres alignaient des titres qui reprenaient ce que la géopolitique et la macro venaient d’expliquer. Il en reste cinq, dans l’ordre des récaps quotidien et hebdomadaire : la synthèse en tête, puis Géopolitique, Macro, Banques centrales et Marches, et enfin À surveiller. La géopolitique passe devant la macro parce que c’est elle qui donne le regime de la séance, et c’est déjà l’ordre des autres rapports. La rubrique Banques centrales dit qui a parle, sur quel ton, et ce que cela change pour la prochaine réunion ; elle disparaît les jours sans intervention plutôt que de rester vide. Passer d’un rapport à l’autre ne demande plus de réapprendre ou regarder.' },
  { id: 'dtpu-20260821-synthese-courte', ts: Date.UTC(2026, 7, 23, 8, 0), title: 'Synthèse des Marches : plus courte, et les chiffres enfin écrits en français', desc: 'Le rapport quotidien s’était allonge au point de se lire comme un article. Il redisait en prose des chiffres qu’il venait d’écrire : une ligne annoncait réel -0,5 pour -0,5 attendu, puis expliquait que les ventes avaient stagne. Deux fois la même information. Les consignes de rédaction sont resserrées : le bloc de tête passe à quatre ou six puces d’une seule phrase, chaque publication économique tient sur une ligne, et les rubriques de marché sur deux à trois lignes au lieu de cinq. Une ligne, une information. Les chiffres sont par ailleurs normalises en écriture française : virgule décimale, espace avant le pourcentage, et séparateur de milliers converti. Ce dernier point n’était pas cosmétique : un cours de l’or écrit 4,647 à l’anglaise se lisait 4,647 en français, soit mille fois moins. Les rapports du jour se régénèrent automatiquement.' },
  { id: 'dtpu-20260821-fiche-indicateurs', ts: Date.UTC(2026, 7, 23, 7, 0), title: 'Chaque publication économique porte désormais sa definition, celle de la fiche du desk', desc: 'Sous une donnée économique, le desk explique maintenant ce que mesure l’indicateur, en reprenant mot pour mot la fiche pedagogique qui alimente déjà le Decryptage du calendrier. Même source pour les deux écrans, donc jamais deux explications différentes du même chiffre. La lecture face au consensus vient de la même fiche, y compris pour les indicateurs inverses ou un chiffre qui monte est une mauvaise nouvelle, comme le chômage ou les inscriptions hebdomadaires. Sur les indices d’activité, la valeur est située par rapport au seuil de 50 : à 56,8 l’activité progresse encore, même quand le chiffre deçoit les attentes. C’était un vrai risque de lecture. Les phrases sont écrites directement, sans étiquette devant : sur un desk, la phrase se suffit.' },
  { id: 'dtpu-20260821-donnees-trader', ts: Date.UTC(2026, 7, 23, 6, 0), title: 'Données économiques : le sens pour la devise, un repère sur l’indicateur, et le bon tag', desc: 'Suite directe de l’amélioration précédente, cette fois pensée pour la lecture d’un desk. Trois ajouts. La ligne de lecture précise désormais dans quel sens la surprise pousse la devise concernée, en passant par les anticipations de taux, et elle le formule comme un mecanisme et non comme une consigne : une donnée ne fixe jamais un cours à elle seule. Une ligne Repère explique en une phrase ce que mesure l’indicateur, pour qui ne le suit pas toutes les semaines. Sur les indices d’activité elle rappelle le seuil de 50 et le situe : à 53,2 l’activité progresse encore, même quand le chiffre decoit les attentes. C’était un vrai risque de lecture, un essoufflement face au consensus pouvant se lire comme un recul. Enfin, le tag. Une publication chiffrée affichait le tag du PAYS, US par exemple, qui ne menait nulle part, au lieu du tag de la DEVISE, seul à ouvrir la réaction du marché au clic. La cause était une catégorie de la source rangeant ces news parmi les commentaires. Un titre qui porte Actual, Forecast et Previous n’est pas un commentaire : il est désormais traite comme la publication qu’il est. Le tag pays disparaît quand la devise le dit déjà, pour qu’un tag affiche corresponde toujours à une fonction.' },
  { id: 'dtpu-20260821-donnees-lisibles', ts: Date.UTC(2026, 7, 23, 5, 0), title: 'Données économiques : le résume explique enfin ce que le chiffre veut dire', desc: 'Sous chaque publication économique, le résume se lisait comme un relevé de calcul : « Sort à 0.6 vs 0.4 attendu ». Trois choses manquaient. L’unité avait disparu, alors que selon l’indicateur il peut s’agir de pourcents, de points ou de milliers d’emplois. Les décimales étaient rabotées, si bien qu’un précédent à 1,0% s’affichait « (1) » et se lisait comme un renvoi de note. Et surtout, hors indices d’activité et inflation, aucune lecture n’était proposée : le lecteur recevait une soustraction, pas une information. Les chiffres portent désormais leur unité, en écriture française, et la comparaison précise sa période, d’un mois sur l’autre ou sur un an. Une ligne « Ce que ça dit » traduit la publication en clair pour l’emploi, la consommation, la croissance, la production, le moral des acteurs, l’immobilier, les prix et les indices d’activité. Elle tient compte du fait qu’un chiffre en hausse n’est pas toujours une bonne nouvelle : une hausse du chômage ou des inscriptions au chômage est lue comme telle. Sur les indicateurs trop ambigus pour être tranches sans risque de contresens, le desk se tait plutôt que d’affirmer.' },
  { id: 'dtpu-20260821-session-unique', ts: Date.UTC(2026, 7, 23, 4, 0), title: 'Un compte, une connexion : la règle s’applique désormais partout', desc: 'Le terminal n’autorise qu’une seule connexion active par compte. C’était déjà le cas, mais deux situations y échappaient. La première : les comptes de l’équipe n’étaient pas soumis à la règle, ce qui la rendait invisible à qui la testait avec son propre accès. La seconde, plus importante : deux personnes qui se transmettaient une session ouverte n’étaient pas séparées, parce que rien ne permettait de les distinguer. Chaque navigateur porte maintenant une empreinte qui lui est propre et qui ne se transmet pas avec une session copiee. La règle est simple et sans surprise : la connexion la plus récente garde la main, la précédente est fermée dans les vingt secondes avec un message qui l’explique. Ouvrir plusieurs onglets sur le même ordinateur ne change rien, c’est le même navigateur. Se connecter depuis un autre appareil ferme la session précédente, comme sur un service de streaming.' },
  { id: 'dtpu-20260821-force-quadrillage', ts: Date.UTC(2026, 7, 23, 3, 0), title: 'Force des Devises : le quadrillage pointille disparaît, les courbes respirent', desc: 'Le graphique portait deux séries de traits pointillés horizontaux : les paliers de l’échelle, et surtout une ligne par devise, tirée depuis sa pastille en travers de toute la largeur. À huit devises affichées, cela faisait huit traits de couleurs différentes posés par dessus les courbes, pour une information que la pastille donne déjà au bout de chaque ligne. Les deux sont retirés. Ce que la lecture y perd : rien. Sur ce graphique aucune valeur ne se lit sur une horizontale, ce qui compte est le classement des devises entre elles et leur position par rapport au zero. Le zero reste donc trace, en blanc plein, et les graduations chiffrées restent dans la colonne de droite pour qui veut le niveau exact. Les repères d’heures, eux, sont conserves : ce sont eux qui rattachent un mouvement à un moment.' },
  { id: 'dtpu-20260821-mobile-lot3', ts: Date.UTC(2026, 7, 23, 2, 0), title: 'iPhone à encoche et fleches du calendrier : les derniers réglages mobiles', desc: 'Sur les iPhone récents, la barre du haut reçoit un retrait de près de 50 pixels pour laisser passer l’encoche. Le logo, lui, se voyait imposer la hauteur totale : il debordait sous la barre et son séparateur venait barrer la moitie de la rangée d’onglets. De même, la recherche de symbole depliee se posait à cheval sous la barre d’état. Les deux sont recales sur la zone réellement utilisable, sans aucun effet sur les autres appareils. Les fleches qui font defiler les mois du calendrier, elles, n’avaient aucun réglage mobile et mesuraient moins de la moitie de la taille minimale pour être touchées au doigt : corrigé.' },
  { id: 'dtpu-20260821-mobile-lot2', ts: Date.UTC(2026, 7, 23, 1, 0), title: 'Téléphone : la recherche de paire, le tableau des banques et Mon Desk redeviennent utilisables', desc: 'Quatre corrections mesurées. Ouvrir une paire faisait basculer la vue mais créait son onglet HORS ÉCRAN : la barre continuait d’afficher les premiers onglets, impossible de savoir ou l’on était ni de refermer la paire. La barre suit désormais l’onglet actif. Dans le tableau des banques, faire defiler vers la droite faisait sortir le nom de la banque de l’écran : on lisait des chiffres sans savoir de qui ils étaient ; la colonne d’identité reste maintenant visible, comme dans le Radar de Biais. La poignée de redimensionnement du Radar invitait à tirer sans jamais repondre au doigt : elle repond. Et la barre Mon Desk, qui coupait ses onglets de disposition alors que la moitie de la barre restait vide, se replie proprement.' },
  { id: 'dtpu-20260821-journal-voix', ts: Date.UTC(2026, 7, 23, 0, 0), title: 'Journal de trading : un ton coherent, et l’indicateur de mode qui s’explique', desc: 'Le Journal était le seul endroit du desk à vous tutoyer, alors que le site, la page de connexion et l’ensemble du terminal vous vouvoient. Un lecteur passait donc du vouvoiement au tutoiement en changeant simplement d’onglet. Onze formulations sont alignées. L’indicateur en haut à droite, qui affichait Gabarit DTP ou Journal perso sans rien expliquer, dit désormais ce que le mode change concretement : avec le gabarit, les colonnes et options sont celles du desk ; dès que vous importez votre propre journal, ce sont vos colonnes qui prennent la main, sans mélange entre les deux.' },
  { id: 'dtpu-20260821-calc-direct', ts: Date.UTC(2026, 7, 22, 23, 0), title: 'La calculatrice de position repond pendant que vous tapez', desc: 'Il fallait cliquer sur Calculer pour obtenir un résultat, et modifier un chiffre ne changeait rien tant qu’on ne cliquait pas ailleurs. Les champs ne reagissaient qu’à la perte du focus. Le résultat se met désormais à jour à chaque frappe, et le bouton a disparu : un bouton qui ne fait rien de plus que ce qui vient de se produire tout seul fait douter que le chiffre affiche soit le bon. Trois paliers de risque sont ajoutes, 0,5%, 1% et 2%, qui couvrent l’essentiel des cas et remplacent une saisie par un clic. Le palier actif est mis en evidence.' },
  { id: 'dtpu-20260821-ecran-noir-final', ts: Date.UTC(2026, 7, 22, 22, 0), title: 'Application de bureau : l’écran noir ne peut plus revenir en boucle', desc: 'Le correctif précédent rechargeait l’affichage dès qu’il devenait noir. C’est le bon reflexe une fois, mais si c’est la carte graphique du poste qui est en cause, le problème revient et l’application se recharge indéfiniment sous vos yeux, ce qui est pire que le défaut d’origine. Désormais, au troisième rechargement en moins d’une heure, l’application en tire la conclusion : elle bascule ce poste en rendu logiciel et redémarre. L’affichage est un peu moins fluide mais il fonctionne, et le réglage est conserve : le poste est traite une fois pour toutes, pas à chaque démarrage. Version 1.0.18, installée automatiquement.' },
  { id: 'dtpu-20260821-mobile-audit', ts: Date.UTC(2026, 7, 22, 21, 0), title: 'Le desk sur téléphone : ce qui était injoignable redevient utilisable', desc: 'Un audit du desk mesure au navigateur, écran par écran, a montré que plusieurs commandes étaient tout simplement hors d’atteinte sur téléphone. La recherche de symbole, seul accès à la vue paire, était rognée à cent pour cent sous 385 pixels : invisible ET intapable. La barre du haut passe désormais sur deux rangées sur les petits écrans, ce qui lui rend toute sa largeur, et rien n’a été supprime au passage : ni le Journal, ni la Calculatrice, ni le support. Les zones à toucher sont remises au standard partout : chevron d’ouverture d’une actualité, boutons Info, Analyse, Réaction et Impact, icones de la barre, œil du mot de passe, poignée du graphique de l’onglet Banques. Le bord droit du desk ne bloque plus le défilement au doigt. Les écrans à encoche respectent enfin la zone sure. Et les textes qui tombaient sous le seuil de lisibilité sont relevés.' },
  { id: 'dtpu-20260821-login-mobile', ts: Date.UTC(2026, 7, 22, 20, 0), title: 'La page de connexion montre tout, d’un seul écran sur téléphone', desc: 'Sur téléphone, la page s’ouvrait sur une mosaique d’images qui occupait un quart de l’écran et repoussait le reste plus bas. Les boutons de téléchargement étaient coupes et le lien Mac Intel carrement inatteignable : la page ne defilait pas comme elle aurait du, à cause d’une hauteur figée. Corrige, et vérifie par la mesure sur trois tailles de téléphone. La mosaique laisse désormais place au contenu utile dès qu’on est sur un petit écran, elle reste entière sur ordinateur. Deux informations manquantes sont ajoutées, comme sur les meilleurs terminaux : un moyen de nous joindre depuis l’écran ou vous êtes bloque si la connexion echoue, et la mention de la marque en pied de page. Les deux boutons de téléchargement restent cote à côté : les empiler rejetait de nouveau le bas de page hors de l’écran.' },
  { id: 'dtpu-20260821-ia-nuit', ts: Date.UTC(2026, 7, 22, 19, 0), title: 'L’intelligence du desk ne dort plus la nuit', desc: 'Les traitements de fond étaient coupes de 21h à 8h30 pour économiser le quota, à une époque ou celui-ci était trois fois plus étroit. Relevé du jour : 24 pour cent du budget mensuel consomme à douze jours de la fin du mois, et un seul appel dans la journée. La coupure ne protégeait donc plus rien et coutait quelque chose : rien ne se preparait pendant la nuit, et les rapports se generaient au moment ou vous les ouvriez le matin au lieu d’être prêts. Le desk travaille désormais 24h/24. Les vraies protections restent en place et ne dépendent pas de l’heure : un plafond quotidien lisse sur les jours restants du mois, et une réserve de 40 pour cent du quota aux demandes faites depuis le desk, qui passent donc toujours en priorité.' },
  { id: 'dtpu-20260821-reaction-retrouvee', ts: Date.UTC(2026, 7, 22, 18, 0), title: 'Le bouton Réaction ne se supprime plus lui-même', desc: 'Sur une publication majeure, ouvrir Réaction pouvait faire DISPARAITRE le bouton et basculer sur Info. Le panneau ne savait pas quel marche était expose par cette actualité-la : il le demandait à une variable globale qui n’est renseignée que si vous avez d’abord clique le tag de la paire, et qui pouvait même porter la paire d’une AUTRE actualité. Faute de marché à mesurer, il retombait sur le detecteur de chocs, ne trouvait rien, et en concluait qu’il n’y avait pas de réaction à montrer. Le panneau utilise désormais la paire déduite pour cette actualité précise, qui ne peut pas venir d’ailleurs.' },
  { id: 'dtpu-20260821-flux-differe', ts: Date.UTC(2026, 7, 22, 17, 0), title: 'Une actualité qui vient de tomber le dit clairement, au lieu d’annoncer une fermeture', desc: 'Les cotations gratuites arrivent avec une dizaine de minutes de décalage. Sur une actualité qui vient de tomber, les minutes qui la suivent n’existent donc pas encore : le graphique ressemble alors exactement à celui d’une actualité publiée marché fermé, alors que le marché est ouvert et que les cotations arrivent. Le desk distingue désormais les deux et le dit dans les mots justes : cotations en cours d’arrivée d’un cote, marché fermé de l’autre. Le message disparaît de lui-même dès que les cotations sont la, pour ne pas rester affiche à tort.' },
  { id: 'dtpu-20260821-reaction-lisible', ts: Date.UTC(2026, 7, 22, 16, 0), title: 'Le graphique de réaction devient enfin lisible', desc: 'Il montrait 30 minutes avant la publication et 90 après, à la minute. Le soir, cet intervalle ne contient que deux points et demi d’amplitude : il n’y avait littéralement rien à voir, et huit minutes sur dix s’y dessinaient en trait plat faute d’echange. Ce n’était ni la source ni la qualite des données, c’était qu’on zoomait sur un intervalle ou le prix ne parcourt rien. Le graphique montre désormais six heures avant et deux heures après, en bougies de cinq minutes : environ 90 bougies, 30 points d’amplitude, et la grande majorité avec un vrai corps. Le contexte d’avant est ce qui rend le mouvement d’après lisible. Le cercle rouge marque toujours la minute exacte de la publication.' },
  { id: 'dtpu-20260821-marche-ferme', ts: Date.UTC(2026, 7, 22, 15, 0), title: 'Une actualité tombée marché fermé le dit, au lieu d’afficher un cadre vide', desc: 'Le marche des changes ferme une heure par jour et tout le week-end. Une actualité publiée pendant cette coupure n’a aucune cotation qui lui corresponde : le graphique affichait alors un cadre noir avec un message d’indisponibilité. Il montre désormais la séance qui précède, avec un bandeau qui précise que le marché était ferme et à quelle heure remonte la dernière cotation. Sans cette mention, le repère se poserait sur la dernière bougie d’avant la fermeture et se lirait comme une réaction qui n’a pas eu lieu.' },
  { id: 'dtpu-20260821-fxcm-partout', ts: Date.UTC(2026, 7, 22, 14, 30), title: 'Tous les graphiques TradingView passent sur le même broker', desc: 'Le desk melangeait cinq fournisseurs de cotation selon l’instrument : les paires venaient de FXCM, l’or et l’argent d’un autre, les indices de trois autres encore. Cinq cotations, cinq séries d’écarts et cinq calendriers d’ouverture dans la même fenêtre. Tout passe désormais sur FXCM, vérifie instrument par instrument. Les indices sont des contrats sur différence, donc quelques points d’écart avec l’indice comptant : c’est le prix à payer pour lire toutes les cartes dans la même unité.' },
  { id: 'dtpu-20260821-tag-analysis', ts: Date.UTC(2026, 7, 22, 14, 0), title: 'Le tag Analysis disparaît de la ligne d’actualité', desc: 'Il répétait la catégorie déjà écrite à gauche du titre, et il voisinait avec le bouton Analyse de la même actualité : deux pastilles presque homonymes cote à côté, dont une seule est cliquable. Le filtre anti-doublon ne l’attrapait pas, parce qu’il compare les libellés traduits et que ce tag-la était reste en anglais.' },
  { id: 'dtpu-20260822-tag-normal', ts: Date.UTC(2026, 7, 22, 13, 0), title: 'Le tag de paire apparaît vraiment sur les actualités qui nomment leur paire', desc: 'La règle livrée plus tôt aujourd’hui ne fonctionnait pas : le verrou avait été leve à un endroit du code mais pas à celui ou le tag est réellement pose, si bien qu’aucune actualité de priorité normale n’obtenait son tag ni son graphique, pas même l’exemple fourni pour la demontrer. Une relecture adverse automatisée l’à trouve, preuve à l’exécution. C’est corrigé et vérifie autrement : le contrôle execute désormais le vrai code et regarde le résultat affiche, au lieu de vérifier la fonction qui choisit la devise. Le filtre qui écarte les commentaires de marché vagues reste intact, il a été reverifie sur dix cas.' },
  { id: 'dtpu-20260822-reaction-mesuree', ts: Date.UTC(2026, 7, 22, 12, 0), title: 'La Réaction ne dit plus que ce qui a été mesure', desc: 'Le bloc Réaction pouvait citer un marché sur lequel le desk n’avait AUCUNE mesure : sur une décision de banque centrale, il a affiche une variation du DXY alors que seule la paire exposée avait été relevée. Un chiffre plausible reste un chiffre invente. Trois corrections : le desk transmet désormais la matière réelle (amplitude en points, niveaux de depart et d’arrivée, durée) au lieu d’un simple pourcentage, il interdit explicitement de nommer un marché non mesure, et un contrôle automatique refuse et fait réécrire toute phrase qui prete une valeur à un marché absent des mesures. Si la réécriture echoue, le desk rédigé lui-même une phrase batie uniquement sur les chiffres relevés. Un défaut de signe, present depuis l’origine, faussait par ailleurs le chiffre transmis à l’analyse : il est corrigé. Les textes écrits avant ce correctif ne sont plus servis. Enfin, quand un marché ne bouge pas après une publication, le desk l’écrit au lieu de chercher un mouvement : c’est une information, cela veut dire que le chiffre était déjà intégré.' },
  { id: 'dtpu-20260822-app-ecran-noir', ts: Date.UTC(2026, 7, 22, 10, 0), title: 'Application de bureau : l’écran noir après une longue ouverture est corrigé', desc: 'Laissée ouverte plusieurs heures, l’application pouvait n’afficher plus que du noir alors que la fenêtre repondait encore. Les deux protections en place ne pouvaient pas l’attraper : l’une exige que l’affichage soit mort, l’autre que la fenêtre soit figée, et ici ni l’un ni l’autre. C’est le composant graphique qui tombait, en laissant tout le reste vivant. Trois ajouts : la protection qui manquait sur ce composant, la mise en veille de l’affichage désactivée quand l’application passe en arriere-plan, et une vérification toutes les deux minutes qui recharge la page si l’écran est réellement noir, après deux constats de suite pour ne jamais recharger sous vos yeux sans raison. La mise à jour se fait toute seule au prochain démarrage, en version 1.0.17.' },
  { id: 'dtpu-20260822-paire-nommee', ts: Date.UTC(2026, 7, 22, 9, 0), title: 'Une actualité qui nomme sa paire ouvre son graphique', desc: 'Quand un titre écrit lui-même la paire dont il parle, par exemple « USD/JPY recule de 17 points, de 159,05 à 158,88 », il porte désormais son tag de paire et ouvre son graphique au clic. Ces titres étaient jusqu ici écartés avec les récits de marché, parce qu’ils en ont la tournure. Mais la différence compte : un recit vague sur l’euro qui reflue laisse le lecteur deviner de quoi on parle, alors qu’un titre qui nomme sa paire et ses niveaux designe exactement ce que le graphique doit montrer. Les récits sans paire nommée restent écartés, comme avant.' },
  { id: 'dtpu-20260822-poignee-visible', ts: Date.UTC(2026, 7, 22, 8, 0), title: 'La poignée de redimensionnement du graphique se voit', desc: 'Le graphique des transactions bancaires se redimensionnait déjà, mais sa poignée était invisible tant qu’on ne la survolait pas, et personne ne survole au hasard la bordure d’un panneau. Elle porte désormais un trait visible et une courte barre arrondie en son centre, la marque habituelle de ce qui se tire. Elle est horizontale quand le graphique est sous le tableau, verticale quand il est à côté.' },
  { id: 'dtpu-20260822-reaction-majeures', ts: Date.UTC(2026, 7, 22, 6, 0), title: 'Le bouton Réaction apparaît sur toutes les publications majeures', desc: 'Il n’apparaissait presque jamais : il attendait qu’un detecteur signale un mouvement, or ses seuils sont ceux d’un choc : quarante points sur l’euro-dollar en huit minutes. Sur dix heures de séance, aucun actif ne les franchissait. Désormais, dès que le desk à etabli quel marche est expose par une publication, il mesure la réaction de CE marche, sans seuil : l’amplitude devient le contenu du panneau et non sa condition d’apparition. Un marche qui ne bouge presque pas après un chiffre est d’ailleurs une information. Le bloc ne montre plus qu’une phrase, comme demande, au lieu d’un tableau de prix suivi de la même chose en toutes lettres.' },
  { id: 'dtpu-20260822-remplacer-onglets', ts: Date.UTC(2026, 7, 22, 5, 0), title: 'Remplacer un widget marche aussi dans les panneaux à onglets', desc: 'Le bouton Remplacer était arrive sur l’en-tête des cartes, mais pas dans la barre d’un widget place dans un panneau à onglets : alors que c’est justement la qu’on change le plus souvent de widget. Il y est désormais, et vise l’onglet ou la case concernée.' },
  { id: 'dtpu-20260822-frise-seances', ts: Date.UTC(2026, 7, 22, 4, 0), title: 'La frise des séances se lit d’un coup d’œil', desc: 'Le widget Sessions de marché, en affichage Horaires des places, est refait : l’axe est gradue toutes les trois heures au lieu de six, chaque plage porte son horaire ÉCRIT DANS la barre au lieu d’un texte à côté, et un trait vertical marque l’heure courante en traversant les quatre places : c’est lui qui montre d’un coup quelles séances se chevauchent, donc ou se trouve la liquidite. Chaque place garde aussi SA couleur, ouverte ou fermée : elles viraient toutes au même gris une fois fermées et la frise perdait sa lecture d’ensemble.' },
  { id: 'dtpu-20260822-format-lectures', ts: Date.UTC(2026, 7, 22, 3, 0), title: 'Les quatre lectures d’une news ont maintenant le même format', desc: 'Info, Réaction, Analyse et Impact marche s’affichent cote à côté dans une grille. Leurs longueurs étaient très inégales : un bloc de deux lignes voisinait avec un pave de six, et l’œil en concluait à tort que le plus court comptait moins. Les quatre visent désormais la même longueur, entre deux cents et deux cent quatre-vingts caracteres, chacun gardant strictement son role. Assez pour dire quelque chose, assez court pour être lu d’un trait.' },
  { id: 'dtpu-20260822-bouton-remplacer', ts: Date.UTC(2026, 7, 22, 2, 0), title: 'Remplacer un widget se fait en un clic', desc: 'Changer le widget d’un emplacement demandait d’ouvrir ses réglages puis de cliquer Remplacer. C’est le geste le plus courant de la personnalisation : il passe dans l’en-tête, à côté de la croix, et ouvre directement la bibliothèque. La croix garde exactement sa fonction. Dupliquer, plein écran et verrouiller restent dans les réglages, ou ils sont écrits en toutes lettres.' },
  { id: 'dtpu-20260822-bank-resize', ts: Date.UTC(2026, 7, 22, 1, 30), title: 'Le graphique des transactions bancaires se redimensionne', desc: 'Une poignée borde désormais le graphique de l’onglet Banques : tirez-la pour lui donner plus de place, ou pour rendre la place au tableau. Elle ajuste la hauteur quand le graphique est sous le tableau et la largeur quand il est à côté. Un double-clic revient à la taille d’origine.' },
  { id: 'dtpu-20260822-axe-heures', ts: Date.UTC(2026, 7, 22, 1, 0), title: 'Les heures du graphique Force des Devises se lisent enfin', desc: 'La ligne des heures sous le graphique était trop pale pour être lue sans effort : son contraste tombait sous le seuil de lisibilité. Elle est éclaircie, légèrement agrandie, et ses chiffres passent en chasse fixe pour que l’axe ne semble plus vibrer quand il défile. Un filet le sépare des courbes.' },
  { id: 'dtpu-20260821-tags-uniformes', ts: Date.UTC(2026, 7, 22, 0, 0), title: 'Les quatre boutons d’une news ont enfin la même allure', desc: 'Le bouton Réaction se distinguait des trois autres par sa FORME : fond rempli et coins plus arrondis, là où Info, Analyse et Impact marche sont des pastilles à simple contour. Seule la couleur doit les differencier, puisque c’est elle qui dit à quoi chaque bouton repond. Les quatre sont désormais identiques au pixel près, seules leurs quatre couleurs changent. Les deux drapeaux du tag de paire se lisent aussi comme deux cercles distincts, séparés par un fin anneau sombre : sur deux drapeaux aux couleurs proches ils fusionnaient en une tache.' },
  { id: 'dtpu-20260821-tag-reaction', ts: Date.UTC(2026, 7, 21, 23, 0), title: 'Le tag Réaction réapparaît sur les news importantes', desc: 'Le bouton Réaction, qui montre ce que le prix a fait juste après une publication, ne s’affichait plus sur aucune actualité. Il n’apparaît que si le desk détecté un mouvement de marché, or la lecture des cotations echouait en silence : aucun mouvement détecté, donc aucun bouton. Trois de nos graphiques dependaient de cette même lecture et sont rétablis d’un coup. Le bouton reprend aussi sa place, entre Analyse et Impact marche.' },
  { id: 'dtpu-20260821-fond-description', ts: Date.UTC(2026, 7, 21, 22, 0), title: 'Le fond du détail d’une actualité couvre toute la largeur', desc: 'Quand vous dépliez une actualité, le fond du bloc de détail s’arretait avant le bord gauche de la carte, surtout sur téléphone et dans les widgets étroits : il restait une bande sombre le long du texte. Le décalage était calcule à partir de la largeur des colonnes du bureau, or sur un écran étroit la ligne se replie et ces colonnes ne sont plus au même endroit. Le desk mesure désormais le décalage réel, ce qui fonctionne quelle que soit la mise en page, et le recalcule si vous tournez votre téléphone ou redimensionnez la fenêtre.' },
  { id: 'dtpu-20260821-graphiques-fiabilite', ts: Date.UTC(2026, 7, 21, 20, 0), title: 'Graphiques : la source est dite, et le fil revient à 100 news par lot', desc: 'Le graphique de réaction indique désormais d’où viennent ses bougies et quel est son délai : elles proviennent du contrat à terme, seule cotation qui fournisse de vraies bougies à la minute sur le change, et le flux est diffère d’une dizaine de minutes. Le graphique se complète tout seul tant qu’il reste ouvert, pour que les minutes qui suivent la publication finissent par apparaître. Mieux vaut dire ce que montre un graphique que laisser croire à un direct qu’on ne peut pas tenir. Le graphique de l’onglet Banques passe sur la même technologie, en gardant ses lignes Entrée, Objectif et Stop, et ne peut plus rester vide sans raison. Le fil, lui, affiche 100 actualités puis un bouton Charger plus tous les 100.' },
  { id: 'dtpu-20260821-roles-couleurs', ts: Date.UTC(2026, 7, 21, 18, 0), title: 'Chacune des quatre lectures dit une chose, et une seule', desc: 'Les quatre lectures d’une publication avaient des roles qui se chevauchaient : Réaction expliquait le pourquoi et le ton du communique, ce qui est justement le travail d’Analyse et d’Impact marche. Vous lisiez trois fois le même raisonnement. Réaction ne dit plus que ce que le PRIX a fait : sens, amplitude en points, niveaux de depart et d’arrivée, et si le mouvement a tenu. Info dit ce qui a été annonce, Analyse ce que cela veut dire, Impact marche ce que cela implique. Les couleurs des quatre boutons sont aussi plus lisibles : celle d’Analyse était sous le seuil de contraste et fatiguait à la lecture. Et les drapeaux des paires deviennent ronds, comme dans le Radar de Biais.' },
  { id: 'dtpu-20260821-blocs-largeur', ts: Date.UTC(2026, 7, 21, 16, 0), title: 'Le graphique et ses quatre lectures prennent toute la largeur', desc: 'Le panneau qui s’ouvre sous une news était aligne sous le titre, ce qui laissait un quart de la ligne inutilise à gauche. C’est bien pour du texte, qui se lit en diagonale, mais cela ecrasait le graphique et les quatre blocs. Ils reprennent désormais toute la largeur : chaque bloc gagne un quart de sa taille. Les blocs sont aussi mis en forme comme demande, en paragraphes sans puces, avec l’heure collée au titre. La ligne de rappel au-dessus du graphique, qui répétait la paire et l’heure déjà affichées ailleurs, est retirée.' },
  { id: 'dtpu-20260821-quatre-lectures', ts: Date.UTC(2026, 7, 21, 14, 0), title: 'Les quatre lectures d’une news s’affichent ensemble sous le graphique', desc: 'Au clic sur le marché expose d’une publication, le graphique est désormais suivi des quatre lectures affichées EN MÊME TEMPS : le résume du chiffre, la réaction du marché avec les prix avant et après, l’analyse du desk et l’impact marche. Il fallait auparavant ouvrir chaque onglet à son tour et mémoriser l’un pour lire l’autre, alors qu’une réaction se comprend en confrontant les quatre. La pastille de couleur de chaque bloc reprend celle de son bouton, pour savoir d’un coup d’œil a quoi il repond. Sur téléphone les blocs s’empilent au lieu de se serrer. La rangée de tags suit aussi un ordre fixe : les thèmes, puis la paire, puis les quatre lectures.' },
  { id: 'dtpu-20260821-fil-profondeur', ts: Date.UTC(2026, 7, 21, 11, 0), title: 'Le fil se déroule sur au moins six heures avant Charger plus', desc: 'Le bouton Charger plus pouvait arriver après une heure de fil à peine, selon le nombre de dépêches tombées. La règle était comptée en nombre d’articles, or la densite du fil varie énormément : une heure de publication peut en compter soixante quand une heure calme en compte huit. Le fil garantit désormais au moins six heures d’historique deroulables d’un seul tenant, et va chercher ce qui manque tout seul si besoin. Le bouton continue de tomber pile à un changement de jour, jamais au milieu d’une journée coupée en deux.' },
  { id: 'dtpu-20260821-tags-doublons', ts: Date.UTC(2026, 7, 21, 9, 0), title: 'Fin des tags qui répètent la catégorie', desc: 'Sur une publication de la zone euro, la ligne affichait la catégorie Données EU à gauche, puis les tags Données et EU à droite : trois fois la même information. Un tag dont le libelle est déjà un mot de la catégorie n’apprend rien, il ne s’affiche plus. La règle compare mot à mot, donc un tag qui recoupe partiellement la catégorie sans dire la même chose reste bien visible.' },
  { id: 'dtpu-20260821-cercle-rouge', ts: Date.UTC(2026, 7, 21, 8, 0), title: 'Le cercle rouge est de retour sur le graphique de réaction', desc: 'Le graphique qui s’ouvre au clic sur le marché expose d’une news est désormais epure : plus de barre d’outils, plus d’indicateurs, plus de volume, juste les bougies. Et surtout, un cercle rouge marque la minute exacte ou le chiffre est tombe, avec un trait vertical, exactement comme demande. Il suit le graphique quand vous zoomez ou faites defiler, et reste visible quelle que soit la largeur, y compris sur téléphone. L’échelle de prix à droite affiche le détail au dix-milliemme, ce qu’il faut pour lire une réaction de quelques points. Les bougies à la minute viennent des contrats à terme, seule source qui en fournisse de vraies à cette échelle : le comptant renvoie un prix unique par minute, donc des bougies plates.' },
  { id: 'dtpu-20260821-creneau-agenda', ts: Date.UTC(2026, 7, 21, 6, 0), title: 'Plus de graphique sur une ligne d’agenda', desc: 'Le fil publié séparément le rendez-vous et son résultat : une ligne FOMC Rate Statement annonce le creneau, une ligne avec le chiffre annonce la publication. Le marche expose s’affichait sur les deux, or sur la ligne d’agenda rien n’est encore tombe : le graphique se serait ouvert sur un moment ou il ne s’est rien produit. Il faut désormais que le titre porte une valeur publiée, ou qu’il rapporte les propos d’un banquier central, pour que le marché expose apparaisse.' },
  { id: 'dtpu-20260821-reaction-tradingview', ts: Date.UTC(2026, 7, 21, 5, 0), title: 'La réaction du marché passe sur un graphique TradingView', desc: 'Le graphique qui s’ouvre au clic sur le marché expose d’une news est désormais un vrai TradingView : bougies à la minute, en direct, avec le zoom et les outils habituels. La raison du changement est une mesure : notre fournisseur de cotations ne livre pas de vraie bougie à la minute sur le change, il renvoie un seul prix par minute. Les bougies sortaient donc en tirets plats. L’heure exacte de publication du chiffre est rappelée au-dessus du graphique pour retrouver la minute qui compte.' },
  { id: 'dtpu-20260821-tag-publication', ts: Date.UTC(2026, 7, 21, 4, 30), title: 'Le marche expose ne s’affiche plus que sur les vraies publications', desc: 'Le tag de paire apparaissait aussi sur des commentaires de marché, alors qu’il ouvre un graphique cale sur l’instant d’une publication. Sur un recit du type l’euro recule depuis son plus haut de trois mois, cet instant n’est pas celui ou le marché à bouge : le graphique laissait croire à un lien qui n’existe pas. Il est maintenant réserve aux événements dates, c’est-a-dire un chiffre publié ou une décision de banque centrale. Les commentaires économiques, les analyses de marché, les flux de change, les annonces à venir et les sujets hors change en sont exclus. Sur les news importantes en circulation, une sur neuf porte désormais un tag, et chacune correspond à une publication réelle.' },
  { id: 'dtpu-20260821-tag-donnees', ts: Date.UTC(2026, 7, 21, 4, 0), title: 'Le tag Données disparaît du fil', desc: 'Le tag Données n’apportait aucune information que la catégorie affichée à gauche ne donnait déjà. Il est retiré : la rangée de tags gagne en lisibilité.' },
  { id: 'dtpu-20260821-paire-deduite', ts: Date.UTC(2026, 7, 21, 3, 0), title: 'Le marche expose s’affiche maintenant sur les vraies news', desc: 'Le tag de paire, qui ouvre la réaction du marché au clic, n’apparaissait en pratique jamais : il attendait que la news porte un tag de devise, or aucune ne le fait. Le desk deduit désormais le marché expose du titre lui-même : une inflation britannique donne GBPUSD, un chiffre australien AUDUSD, une décision de la Fed EURUSD. Quand deux devises sont citées, c’est le croisement au dollar qui est propose. Et quand le marché expose n’est pas une paire ou reste ambigu, comme sur une news géopolitique, sur l’or ou sur un croisement euro contre livre, aucun tag n’apparaît : mieux vaut pas de graphique qu’un graphique sans rapport.' },
  { id: 'dtpu-20260821-reaction-m1', ts: Date.UTC(2026, 7, 21, 2, 0), title: 'Réaction du marché : bougies à la minute, et on voit enfin l’après', desc: 'Le graphique qui s’ouvre au clic sur la devise d’une news importante passe en bougies d’une minute, sur une fenêtre serrée autour de la publication. Celle-ci se place au premier quart : les trois quarts restants montrent ce que le marché a fait APRÈS le chiffre, ce qui est précisément la question qu’on se pose. Une échelle de prix apparaît à droite, avec le dernier cours encadré en vert ou en rouge selon le sens du mouvement depuis la publication. Sur une news plus ancienne, le graphique redescend automatiquement en 5 puis 15 minutes et annonce toujours l’unité qu’il affiche. Deux défauts corrigés au passage : les mèches qui dépassaient étaient rognées sans prévenir, donc le pic provoqué par la publication pouvait être amputé ; et l’heure de publication s’affichait sous le graphique au lieu de légender son trait.' },
  { id: 'dtpu-20260820-tags-drapeaux', ts: Date.UTC(2026, 7, 21, 1, 0), title: 'Le marché exposé s’affiche en clair sur les news importantes', desc: 'Sur une publication importante, la devise concernée devient le marché le plus exposé et s’affiche avec les drapeaux des deux pays et le nom de la paire, EURUSD par exemple. Un clic dessus ouvre la réaction du marché. Les drapeaux ne servent que là : ils signalent qu’un graphique vous attend, plutôt que de décorer chaque tag.' },
  { id: 'dtpu-20260821-analyse-rapide', ts: Date.UTC(2026, 7, 21, 0, 30), title: 'L’analyse d’une publication arrive en quelques minutes au lieu d’une heure', desc: 'Après un chiffre important, le desk attendait une heure entière avant de publier son analyse. Ce délai ne servait qu’à laisser les dépêches arriver, ce qu’une autre vérification faisait déjà mieux : le desk s’abstient tant qu’il n’a pas assez de matière. L’analyse paraît maintenant huit à treize minutes après la publication, quand elle vous est encore utile.' },
  { id: 'dtpu-20260821-fil-briefings', ts: Date.UTC(2026, 7, 21, 0, 0), title: 'Fin des rapports qui réapparaissaient sans raison en tête du fil', desc: 'Certains rapports internes, normalement réservés à l’onglet Analystes, se glissaient dans le fil d’actualité à chaque reconnexion du terminal, notamment au retour sur l’onglet du navigateur. Ils semblaient sortir de nulle part et restaient épinglés en haut. Le filtre qui les écarte existait pour les envois en direct mais manquait à l’envoi initial : il est désormais posé sur tous les chemins.' },
  { id: 'dtpu-20260820-widget-differentiel', ts: Date.UTC(2026, 7, 20, 23, 30), title: 'Nouveau widget : Différentiel de taux', desc: 'Le comparatif des taux directeurs devient un widget de la bibliothèque, à poser où vous voulez sur votre desk. Chaque devise est comparée à la moyenne des sept autres banques centrales : vert quand le portage joue pour elle, rouge quand il joue contre, avec l’écart en points. Trois classements au choix : par écart, par taux ou par devise. À ne pas confondre avec le widget Taux directeurs, qui répond à une autre question : ce que la banque fera à sa prochaine réunion. L’onglet Biais, lui, retrouve sa présentation d’origine.' },
  { id: 'dtpu-20260820-biais-portage', ts: Date.UTC(2026, 7, 20, 22, 30), title: 'Radar de Biais : le différentiel de taux devient une colonne à part entière', desc: 'Le portage, c’est-à-dire l’écart entre le taux d’une banque centrale et celui des sept autres, pesait déjà dans le calcul du biais depuis le mois d’août. Il s’affiche désormais comme les autres catégories, dans sa propre colonne : Favorable quand le portage joue pour la devise, Défavorable quand il joue contre, Neutre entre les deux, avec l’écart en points. Le bandeau des taux, lui, ne chevauche plus le tableau sur téléphone : il défile sur une seule ligne.' },
  { id: 'dtpu-20260820-tag-devise-graphique', ts: Date.UTC(2026, 7, 20, 21, 30), title: 'Cliquez sur la devise d’une news importante pour voir le marché réagir', desc: 'Sur une publication importante, la devise concernée devient cliquable et porte les drapeaux du marché le plus exposé : sur une inflation britannique, un clic sur GBP ouvre le graphique GBP/USD en bougies, avec l’instant exact de la publication entouré d’une bulle rouge. Le déclencheur et la réaction sur un seul écran, sans quitter le fil.' },
  { id: 'dtpu-20260820-reaction-bulle', ts: Date.UTC(2026, 7, 20, 20, 0), title: 'Réaction du marché : le moment de la publication saute aux yeux', desc: 'Sur une news importante, le tag du marché exposé porte désormais les drapeaux des deux devises et ouvre le graphique en bougies, avec l’instant exact de la publication entouré d’une bulle rouge : vous voyez d’un coup d œil ce qui a bougé et quand. Les panneaux Analyse et Impact marché affichent aussi l’heure à laquelle le desk les à écrits. Au passage, un défaut corrigé : ce graphique affichait Réaction indisponible depuis hier soir alors que les données arrivaient normalement.' },
  { id: 'dtpu-20260820-rapports-creneau', ts: Date.UTC(2026, 7, 20, 19, 0), title: 'Fin des piles de rapports après une mise à jour', desc: 'Après un redémarrage du serveur, les rapports de la journée pouvaient être régénérés tous en même temps, même quand leur heure de publication n’était pas encore arrivée : neuf rapports empilés à la même minute, en pleine nuit. La règle qui empêchait cela ne protégeait que trois rapports sur onze ; elle les couvre désormais tous. Un rapport ne peut plus paraître avant son heure.' },
  { id: 'dtpu-20260820-newsletter-acces', ts: Date.UTC(2026, 7, 20, 18, 0), title: 'S’inscrire à la newsletter ne crée plus de compte au terminal', desc: 'Rejoindre la newsletter déclenchait la même chose qu’un abonnement au desk : création d’un compte et envoi du courriel d’accès avec un mot de passe. Deux offres différentes, un seul traitement. C’est corrigé : seul un abonnement au terminal ouvre un accès, et une inscription à la newsletter reste une inscription à la newsletter. Les abonnés payants ne sont pas affectés : leur accès est vérifié auprès de la plateforme de paiement avant toute création.' },
  { id: 'dtpu-20260820-vitrine-sync', ts: Date.UTC(2026, 7, 20, 16, 30), title: 'Le site vitrine affiche désormais les nouveautés du desk en direct', desc: 'La page d’accueil publique gagne une section Nouveautés alimentée par le même fil que l’onglet DTP du desk : chaque évolution du terminal apparaît sur le site vitrine sans intervention, avec sa date. Les visiteurs voient ce que les abonnés reçoivent réellement, semaine après semaine.' },
  { id: 'dtpu-20260822-rapports-heure', ts: Date.UTC(2026, 7, 22, 15, 0), title: 'Chaque rapport reprend sa vraie heure dans le fil', desc: 'Après une mise à jour du serveur, les rapports du jour régénérés pouvaient s’empiler dans le fil à l’heure du redémarrage, tous à la même minute. Chaque rapport rattrapé est désormais horodaté à son créneau réel : la préparation de Londres à 7h45, le récap d’Asie à 9h30, le récap de New York à 22h15. Le fil se remet en ordre de lui-même, y compris pour les rapports déjà mal datés.' },
  { id: 'dtpu-20260822-rapports-stables', ts: Date.UTC(2026, 7, 22, 14, 0), title: 'Les rapports du jour ne se republient plus en bloc après une mise à jour', desc: 'Les jours à très fort volume d’actualité, les rapports du matin pouvaient être évincés de la mémoire du fil, et un redémarrage les republiait alors tous d’un coup, horodatés à l’instant du redémarrage : neuf rapports empilés à la même minute. Les rapports sont désormais protégés de cette éviction : ils gardent leur heure et leur place. Le chargement de la journée en cours va aussi plus loin : même un jour de FOMC à plus de mille dépêches se parcourt jusqu à sa première news avant de passer au jour précédent.' },
  { id: 'dtpu-20260822-impact-structure', ts: Date.UTC(2026, 7, 22, 12, 0), title: 'Impact marché : un verdict, un mécanisme, les actifs fléchés', desc: 'Le bouton Impact marché des titres importants se structure : une phrase de verdict en gras, le mécanisme en une ou deux phrases, puis la liste des actifs concernés avec leur direction (Brent ↑, Or ↑, USD ↑ demande refuge…). Toujours descriptif, jamais un conseil. Le graphique de réaction passe aussi en vraies bougies, avec l’instant de la publication marqué et son étiquette horaire. Les tags de catégorie du fil, eux, reviennent à leur forme d’avant.' },
  { id: 'dtpu-20260822-fil-fomc', ts: Date.UTC(2026, 7, 22, 10, 0), title: 'Fil d’actualité : les Minutes des banques centrales sont analysées, et le fil ne se fige plus', desc: 'Trois corrections d’un coup. Les Minutes du FOMC, les comptes rendus de la BCE, de la RBA et de la BoJ déclenchent désormais une analyse complète environ une heure après publication : le ton, ce qui s’est dit, les divisions, et l’impact pour la devise : ils passaient au travers parce qu’ils ne publient pas de chiffre. Le fil se resynchronise maintenant au retour au premier plan sur mobile : il pouvait rester figé sur de vieilles news avec la pastille verte allumée. Et la journée en cours se charge désormais en entier : vous remontez jusqu à la première news du jour, et Charger plus ouvre le jour précédent.' },
  { id: 'dtpu-20260822-biais-taux', ts: Date.UTC(2026, 7, 22, 8, 0), title: 'Onglet Biais : les taux directeurs s’affichent au-dessus de la matrice', desc: 'Le différentiel de taux pèse déjà dans le biais : c’est le portage, un moteur structurel des devises. Il devient visible : un bandeau en tête de l’onglet Biais affiche le taux directeur de chacune des huit banques, trié du plus haut au plus bas, avec l’écart à la moyenne des sept autres : exactement la grandeur que le modèle consomme. Vert quand le portage joue pour la devise, rouge quand il joue contre, neutre dans la zone où il ne pèse pas.' },
  { id: 'dtpu-20260822-recap-mentor', ts: Date.UTC(2026, 7, 22, 6, 0), title: 'Récap quotidien : la structure d’une vraie note de desk', desc: 'Le récap du soir se réorganise autour de ce qui a fait bouger les marchés. La section Géopolitique devient une note de renseignement complète, chaque développement attribué à sa source, suivie de Points clés à retenir : la synthèse en quelques lignes avec leur conséquence. Une section Banques centrales dédiée déroule chaque intervention en chaîne : l’institution, le fait, ce qu’il signale, et la réaction du marché chiffrée. La section Macro se concentre sur les autres moteurs : données, flux, commerce. Le mail Point Marché reprend le même ordre : points clés géopolitiques, banques centrales, macro.' },
  { id: 'dtpu-20260821-habillage-terminal', ts: Date.UTC(2026, 7, 21, 23, 30), title: 'Le desk resserre son habillage : plus dense, plus net, plus terminal', desc: 'Après validation sur le compte de l’équipe, l’habillage terminal passe à tout le monde sur ordinateur. Les angles se resserrent, les bandeaux s’affinent, les onglets gagnent de fins séparateurs et les lignes du calendrier, des news et des listes affichent plus d’information à l’écran. Les ombres portées disparaissent des panneaux : la structure vient des filets, comme sur une vraie station de travail. Sur mobile, rien ne change : les hauteurs tactiles restent intactes.' },
  { id: 'dtpu-20260820-widgets-ouverts', ts: Date.UTC(2026, 7, 20, 23, 55), title: 'Les quatorze nouveaux widgets sont ouverts à tous', desc: 'Fin du rodage : les quatorze widgets ajoutés cette semaine sont disponibles dès maintenant dans la bibliothèque de Mon Desk, pour tous les comptes. Cotations et matrice des croisements, chaleur de séance, liste de suivi, amplitude et volatilité sous toutes leurs coutures, compte à rebours d’événement, série d’un indicateur, courbe saisonnière, et un bloc-notes qui vous suit d’un appareil à l’autre. Chaque carte à ses réglages : paire, unité, profondeur d’historique, seuils.' },
  { id: 'dtpu-20260821-reaction-graphique', ts: Date.UTC(2026, 7, 21, 22, 30), title: 'Le tag du marché exposé ouvre maintenant sa réaction en graphique', desc: 'Sur les analyses d’événement, le tag du marché le plus exposé (AUD/USD, EUR/USD…) n’est plus une simple étiquette : un clic ouvre la courbe 15 minutes de ce marché, avec l’instant exact de la publication marqué d’un trait. Vous voyez le déclencheur et la réaction sur le même écran. Au passage : les couleurs du sentiment de risque suivent désormais la zone du cadran (un état faible ou neutre est ambre, comme l’aiguille), la frise des sessions a été reprise (colonnes alignées, états discrets, seule la séance ouverte porte sa couleur), et les sauvegardes automatiques n’affichent plus que la plus récente, les anciennes restant à un clic.' },
  { id: 'dtpu-20260821-bascule-theme', ts: Date.UTC(2026, 7, 21, 21, 0), title: 'Changer de thème met à jour le panneau de risque immédiatement', desc: 'Après un passage du clair au sombre (ou l’inverse), le graphique d’historique du sentiment gardait le fond de l’ancien thème jusqu au rechargement de la page. Le changement de thème reconstruit maintenant ce graphique sur-le-champ, avec les données déjà chargées, et le badge comme la ligne d’état reprennent aussitôt les encres du nouveau thème.' },
  { id: 'dtpu-20260821-clair-risque', ts: Date.UTC(2026, 7, 21, 20, 0), title: 'Thème clair : le panneau de risque et le fil rentrent dans le rang', desc: 'En thème clair, plusieurs zones restaient sombres : la ligne d’état du sentiment, le badge sous la jauge, le graphique d’historique sur fond noir, les lignes de news importantes en bordeaux et le bandeau de date du fil. Tout passe en bases claires, avec des encres foncées calculées pour rester lisibles : vert profond pour l’appétit, rouge brique pour l’aversion, ambre foncé pour le neutre.' },
  { id: 'dtpu-20260821-risque-couleurs', ts: Date.UTC(2026, 7, 21, 19, 0), title: 'Sentiment de risque : trois couleurs qui tranchent enfin', desc: 'La jauge gardait son dégradé, mais le badge, la ligne d’état et l’historique en barres prenaient des teintes intermédiaires : une légère aversion s’affichait ambre, un appétit modéré vert olive. Désormais l’état tranche : aversion en rouge, appétit en vert, neutre en ambre, sur le badge comme sur chaque barre de l’historique. La couleur de chaque jour suit l’état réellement mesuré ce jour-là, pas une interpolation.' },
  { id: 'dtpu-20260821-fil-impact', ts: Date.UTC(2026, 7, 21, 18, 0), title: 'Fil d’actualité : le bouton Impact rejoint Info, Analyse et Réaction', desc: 'Les titres importants portent désormais quatre boutons. Info résume la nouvelle en langage clair. Analyse déroule le contexte complet : ce qui a été décidé, l’écart aux attentes, le ton. Réaction montre comment le marché a bougé et quand. Et Impact, le nouveau, isolé la lecture prospective : ton restrictif ou accommodant, maintien ou mouvement à la prochaine réunion, le point précis à surveiller ensuite. Au passage, deux corrections : nos rapports (Synthèse des Marchés, analyses d’événement) ne sont plus écrasés quelques secondes après ouverture par un résumé automatique, et les puces Devises et Obligations, qui ne discriminaient rien sur un desk forex, disparaissent des titres.' },
  { id: 'dtpu-20260821-sauvegardes-lisibles', ts: Date.UTC(2026, 7, 21, 16, 0), title: 'Sauvegardes automatiques : on voit enfin quand, quoi et comment revenir', desc: 'Les sauvegardes automatiques de vos dispositions s’affichaient en trois pastilles identiques qui ne disaient leur effet qu’au survol. Chaque sauvegarde à désormais sa ligne : son ancienneté en clair (il y a 2 h, il y a 3 j), sa date exacte, la plus récente est marquée, et le bouton Restaurer est écrit noir sur blanc. La restauration reste réversible : votre état actuel reprend la tête de l’historique.' },
  { id: 'dtpu-20260821-volets-epures', ts: Date.UTC(2026, 7, 21, 14, 0), title: 'Volets Widgets et Layouts : des écrans épurés', desc: 'Les textes d’explication qui s’accumulaient sous la liste des layouts et dans les écrans de création ont été retirés : la liste montre vos dispositions, rien d’autre. Ce que ces textes expliquaient reste accessible au bon endroit : le rôle de chaque bouton s’affiche à son survol, et les actions d’ensemble vivent en bas du volet.' },
  { id: 'dtpu-20260821-creation-layout', ts: Date.UTC(2026, 7, 21, 12, 0), title: 'Créer un layout : le parcours passe à deux étapes claires', desc: 'La création d’une disposition suit désormais l’ordre naturel : vous nommez d’abord votre layout et choisissez son icône (parmi les icônes du desk, des émojis ou des drapeaux, avec recherche), puis vous choisissez la grille de départ. L’en-tête du volet affiche l’étape où vous êtes. La liste de vos layouts gagne aussi quatre boutons directs sur chaque ligne : étoile pour le layout d’ouverture, crayon pour renommer, dossier pour l’afficher ou le retirer de la barre, corbeille pour supprimer. Les layouts retirés portent un badge Fermé.' },
  { id: 'dtpu-20260821-icones-layouts', ts: Date.UTC(2026, 7, 21, 9, 0), title: 'Choisissez une icône, un émoji ou un drapeau pour chacun de vos layouts', desc: 'L’écran de création d’une disposition propose désormais trois familles au lieu d’une : les icônes du desk, une sélection d’émojis, et les drapeaux des grandes places. Un champ de recherche filtre dans chacune. Au passage, un défaut d’affichage est corrigé : la barre de sauvegardes automatiques débordait du volet et poussait les boutons hors de l’écran ; et pendant la création, le pied du volet n’affiche plus un second bouton Créer qui prêtait à confusion.' },
  { id: 'dtpu-20260820-annonce-widgets', ts: Date.UTC(2026, 7, 20, 23, 30), title: 'Une annonce va récapituler les quatorze nouveaux widgets', desc: 'Un courriel unique va reprendre, en clair, les quatorze widgets ajoutés cette semaine à la bibliothèque de Mon Desk : cotations et matrice des croisements, amplitude et volatilité, compte à rebours et séries macro, bloc-notes et liste de suivi. Il explique aussi ce que ces cartes n’affichent volontairement PAS, et pourquoi trois widgets envisagés ont été abandonnés faute de donnée fiable. Vous le recevrez une seule fois : il ne fait pas partie de la rotation hebdomadaire.' },
  { id: 'dtpu-20260820-volets-refonte', ts: Date.UTC(2026, 7, 20, 22, 0), title: 'Volets Widgets et Layouts : nouvelle présentation, plus directe', desc: 'Les deux volets prennent une présentation plus lisible. En haut, une icône, le nom de l’écran et une phrase qui dit à quoi il sert, à la place du bandeau et des onglets. Vos layouts passent en liste : une ligne par disposition, avec sa poignée de déplacement, son nom, et ses actions alignées à droite. La miniature de l’agencement n’a pas disparu, elle se déplie d’un clic sur le chevron, ce qui laisse voir dix dispositions d’un coup au lieu de trois. En bas, deux boutons pleine largeur pour créer un layout et ouvrir la bibliothèque ; export, import et réinitialisation restent juste en dessous.' },
  { id: 'dtpu-20260820-volet-vignettes', ts: Date.UTC(2026, 7, 20, 20, 0), title: 'La bibliothèque de widgets passe en vignettes, trois par rangée', desc: 'Les cartes de la bibliothèque étaient horizontales : une petite image à gauche, le nom et sa description à droite. La description doublait la hauteur de chaque carte et noyait le nom qu’on cherche. Les cartes montrent désormais leur aperçu en grand, en haut, avec le nom centré dessous, trois par rangée : on balaie la bibliothèque à l œil au lieu de la lire. La description reste accessible en survolant la carte. Un compteur indique le nombre de widgets affichés, et les cartes encore en préparation portent un cadenas.' },
  { id: 'dtpu-20260820-volet-gauche', ts: Date.UTC(2026, 7, 20, 18, 0), title: 'Le panneau Personnaliser passe en volet, à gauche de votre desk', desc: 'La bibliothèque de widgets et la gestion des dispositions s’ouvraient dans une fenêtre au centre, qui recouvrait précisément le desk que vous êtes en train de composer. Elles glissent maintenant depuis le bord gauche, sur toute la hauteur : vous voyez votre desk pendant que vous choisissez, et chaque bloc de réglages porte son intitulé. Les deux onglets, Widgets et Layouts, gardent la même largeur pour que rien ne saute quand vous basculez de l’un à l’autre.' },
  { id: 'dtpu-20260820-widgets-lisibles', ts: Date.UTC(2026, 7, 20, 17, 0), title: 'Widgets : des couleurs qui disent quelque chose, et plus de cartes à moitié vides', desc: 'La distribution des variations et la série d’un indicateur s’affichaient entièrement en doré, alors que leur donnée à un sens : les séances de baisse passent en rouge et celles de hausse en vert, et chaque publication se colore selon son sens par rapport à la précédente, ce qui est écrit sous le graphique. Les trois séances d’Amplitude par séance ont chacune leur teinte. Sept cartes réservaient jusqu à 57 pixels de vide sous leur contenu : leur hauteur par défaut a été recalculée sur ce qu’elles affichent vraiment. Enfin, les notes explicatives ne s’effacent plus qu’en fonction de la taille de la carte, et non de celle de votre fenêtre.' },
  { id: 'dtpu-20260819-widgets-fiables', ts: Date.UTC(2026, 7, 19, 23, 30), title: 'Widgets : le bloc « Bougies indisponibles » corrigé, et les cartes se réparent seules', desc: 'Le widget Fréquence d’amplitude restait bloqué sur un message d’erreur alors que la donnée arrivait normalement : une faute de code de notre côté, corrigée. Plus largement, les six widgets qui lisent des bougies partagent désormais un cache commun, réessaient une fois en cas d’incident passager de la source, et se rafraîchissent d’eux-mêmes. Une coupure de quelques secondes ne laisse plus une carte morte jusqu au rechargement.' },
  { id: 'dtpu-20260819-securite-session', ts: Date.UTC(2026, 7, 19, 22, 0), title: 'Sécurité : changer votre mot de passe déconnecte désormais les autres appareils', desc: 'Jusqu ici, modifier son mot de passe ne coupait aucune session déjà ouverte ailleurs : le réflexe naturel de quelqu un dont le compte a fuité restait sans effet. C’est corrigé, et l’appareil depuis lequel vous faites le changement reste connecté. Le flux temps réel du desk exige lui aussi une session valide, et il se ferme immédiatement quand une session prend fin.' },
  { id: 'dtpu-20260820-widgets-reglages', ts: Date.UTC(2026, 7, 20, 14, 0), title: 'Les nouveaux widgets gagnent leurs réglages, et leurs vignettes leurs couleurs', desc: 'Quatre des widgets ajoutés cette semaine n’avaient aucun panneau de réglages, et six ne laissaient même pas changer de paire : un défaut de configuration de ma part, corrigé. Chacun dispose maintenant de deux à quatre réglages utiles : horizon de variation sur la matrice, devise mise en avant, moyenne ou médiane sur la volatilité, unité en pips ou en pourcentage, second seuil de comparaison, alerte quand le cours approche d’un extrême, verrou de lecture seule sur les notes. Les vignettes de la bibliothèque, elles, reprennent la palette des widgets historiques au lieu du tout doré.' },
  { id: 'dtpu-20260820-notes-ticklist', ts: Date.UTC(2026, 7, 20, 8, 0), title: 'Notes et Liste de suivi : deux outils qui vous suivent d’un appareil à l’autre', desc: 'Le bloc-notes garde vos observations par compte : vous les retrouvez sur un autre poste, et chaque carte à son propre document, même dupliquée. La liste de suivi affiche les paires que vous choisissez avec leur cours et leur variation du jour. Elle s’en tient volontairement à ces deux colonnes : les indicateurs de biais et de positionnement de la source ont des valeurs de repli qu’il serait trompeur de présenter comme des verdicts.' },
  { id: 'dtpu-20260819-amplitude-seance', ts: Date.UTC(2026, 7, 19, 23, 0), title: 'Amplitude par séance : ce que la paire parcourt à Tokyo, Londres et New York', desc: 'Un nouveau widget compare l’amplitude moyenne d’une paire pendant chacune des trois grandes séances, aux heures locales de chaque place et en tenant compte des changements d’heure, qui ne tombent pas le même jour d’un continent à l’autre. Les séances se chevauchent : la carte le rappelle, la somme des trois ne fait pas la journée.' },
  { id: 'dtpu-20260819-widgets-lot4', ts: Date.UTC(2026, 7, 19, 21, 0), title: 'Deux widgets statistiques : distribution des variations et volatilité', desc: 'La distribution des variations montre la forme réelle des séances d’une paire : combien de journées à plus 0,3 pour cent, combien à moins 1 pour cent. Les statistiques de volatilité donnent l’écart-type des variations et l’amplitude vraie moyenne, en séance et en semaine. Les deux excluent la période en cours, qui n’a pas encore de clôture, et signalent les trous de série plutôt que de calculer par-dessus.' },
  { id: 'dtpu-20260819-widgets-lot3', ts: Date.UTC(2026, 7, 19, 18, 0), title: 'Trois widgets de plus : chaleur de séance, amplitude, hauts et bas', desc: 'La chaleur de séance colore les 28 croisements majeurs selon leur variation du jour. L\'amplitude quotidienne indique de combien une paire bouge en moyenne par séance, en excluant la journée en cours tant qu\'elle n\'est pas terminée. Les points hauts et bas donnent les extrêmes de la séance et de la semaine, avec un curseur qui situe le cours entre les deux. En rodage interne, comme les précédents.' },
  { id: 'dtpu-20260819-apercus', ts: Date.UTC(2026, 7, 19, 15, 0), title: 'Bibliothèque de widgets : chaque carte montre ce qu\'elle contient', desc: 'Les widgets ajoutés cette semaine apparaissaient avec une vignette vide dans la bibliothèque : impossible de deviner à quoi ils ressemblent avant de les poser. Chacun a désormais son icône et son aperçu, dessinés à l\'image de son contenu réel : la grille des croisements, les barres de saisonnalité de part et d\'autre du zéro, la courbe d\'amplitude. Leurs libellés ont aussi retrouvé leurs accents.' },
  { id: 'dtpu-20260819-widgets-lot2', ts: Date.UTC(2026, 7, 19, 12, 0), title: 'Deux widgets macro de plus : compte à rebours et série d’indicateur', desc: 'Le compte à rebours isolé le prochain chiffre attendu et affiche le temps qui reste, puis le résultat des sa publication. La série d’indicateur montre les dernières parutions d’une statistique (inflation, emploi...) en barres, avec la surprise par rapport à la prévision. Comme les précédents, ils sont en rodage interne et apparaissent en Bientôt le temps d’être éprouvés.' },
  { id: 'dtpu-20260819-widgets-lot1', ts: Date.UTC(2026, 7, 19, 9, 0), title: 'Bibliothèque de widgets : quatre nouveautés en préparation', desc: 'Quatre widgets rejoignent la bibliothèque : un bandeau de cotations défilant, une matrice des taux croises entre les huit majeures, une courbe de saisonnalite et une fréquence d’amplitude qui indique la part des séances ou une paire parcourt au moins X pips. Ils sont en cours de rodage sur les comptes internes et apparaissent pour l’instant en Bientôt ; ils s’ouvriront à tous une fois éprouvés.' },
  { id: 'dtpu-20260819-theme-clair', ts: Date.UTC(2026, 7, 19, 1, 0), title: 'Thème clair : tout se lit, partout', desc: 'Le thème clair laissait des textes presque invisibles : noms de devises, titres de volets, pourcentages, badges. Le desk a été passé au crible écran par écran, texte par texte, sur l\'ensemble des onglets. Les verts, rouges, ambres et ors gardent leur sens mais s\'assombrissent juste ce qu\'il faut pour se détacher du fond clair. Le thème sombre, lui, n\'a pas bougé d\'un pixel.' },
  { id: 'dtpu-20260819-frise-responsive', ts: Date.UTC(2026, 7, 19, 0, 45), title: 'Sessions de marché : la frise s\'adapte à la taille de votre carte', desc: 'En rétrécissant la carte, la quatrième séance passait sous le bord et il fallait faire défiler. La frise se resserre désormais d\'elle-même : interligne, pistes et libellés s\'ajustent pour que les quatre places tiennent d\'un seul coup d\'œil, même sur une carte très basse.' },
  { id: 'dtpu-20260818-cot-fonds', ts: Date.UTC(2026, 7, 18, 23, 30), title: 'COT : choisissez la catégorie d\'intervenants', desc: 'Le widget COT par devise vous laisse désormais choisir la catégorie du rapport CFTC : Leveraged Funds par défaut, la référence des salles de marché, mais aussi Asset Managers, Dealers, non-commerciaux et autres reportables. La catégorie affichée est rappelée en haut de la carte, pour lire deux angles côte à côte sans les confondre.' },
  { id: 'dtpu-20260818-graphique-paires', ts: Date.UTC(2026, 7, 18, 23, 15), title: 'Widget Graphique : les 28 paires majeures au sélecteur', desc: 'Le sélecteur du widget Graphique n\'offrait qu\'une poignée de paires. Il propose maintenant les 28 croisements des huit devises majeures, suivis des indices et des matières premières du desk.' },
  { id: 'dtpu-20260818-app-veille', ts: Date.UTC(2026, 7, 18, 23, 0), title: 'Application de bureau : plus d\'écran noir après plusieurs jours', desc: 'Laissée ouverte plusieurs jours, l\'application pouvait afficher une fenêtre noire. Elle se remet seule d\'aplomb : le desk se recharge de lui-même, et vous retrouvez votre écran sans avoir à quitter l\'application.' },
  { id: 'dtpu-20260818-cot-devise', ts: Date.UTC(2026, 7, 18, 22, 0), title: 'Nouveau widget : le COT d\'une devise, volumes réels à l\'appui', desc: 'Le positionnement CFTC d\'une devise en anneau : positions short et long en contrats réels, pourcentages, et la position nette avec son verdict. La devise se choisit dans les réglages. Même design animé que le DMX par paire.' },
  { id: 'dtpu-20260818-graphique-tv', ts: Date.UTC(2026, 7, 18, 20, 0), title: 'Widget Graphique : le graphique TradingView complet', desc: 'Le widget Graphique embarque désormais le vrai graphique TradingView : outils de dessin, indicateurs, toutes les unités de temps, sur la paire de votre choix. Et si TradingView est injoignable, le widget retombe automatiquement sur les bougies du desk : jamais de carte vide.' },
  { id: 'dtpu-20260818-calendrier-lisibilite', ts: Date.UTC(2026, 7, 18, 20, 0), title: 'Calendrier économique : des lignes plus lisibles, partout', desc: 'Le nom de l\'événement ressort désormais devant l\'heure, les publications à fort impact sont en gras, et la bande de date se distingue mieux en balayant la liste. Les derniers intitulés de colonnes passent en français (Pays, Dev., Haut, Bas). Et si vous masquez les colonnes Haut ou Bas, chaque chiffre reste sous le bon intitulé, sur le desk comme sur la carte Mon Desk.' },
  { id: 'dtpu-20260818-biais-comportement', ts: Date.UTC(2026, 7, 18, 18, 0), title: 'Radar de Biais : ce que font réellement les prix entre dans le verdict', desc: 'Le verdict de chaque devise intègre désormais son comportement observé sur la semaine, gradué selon l\'ampleur du mouvement : un yen qui décroche pèse plein pot, une pente marginale pèse à peine. C\'est la lecture d\'un desk : les données comptent, et ce que le marché en fait aussi.' },
  { id: 'dtpu-20260818-biais-trend', ts: Date.UTC(2026, 7, 18, 16, 0), title: 'Radar de Biais : la ligne Trend dit enfin ce que font les prix', desc: 'La ligne Trend affichait Range pour les huit devises, semaine après semaine, à cause d\'un seuil calibré pour une ancienne échelle de données. Elle lit désormais la vraie pente hebdomadaire de la force de chaque devise : un yen qui décroche s\'affiche en repli, un dollar australien qui monte s\'affiche en hausse.' },
  { id: 'dtpu-20260818-biblio-lisible', ts: Date.UTC(2026, 7, 18, 14, 0), title: 'Mon Desk : la bibliothèque de widgets se lit d\'un coup d\'œil', desc: 'Choisir un widget demandait de lire chaque carte mot à mot. Le nom passe devant, la description suit à sa juste place, et toutes les cartes font désormais la même hauteur : l\'œil descend la liste sans à-coups. Le « + » d\'ajout ne chevauche plus jamais un nom de widget, l\'étoile des favoris ne cache plus l\'aperçu, et les rubriques se détachent nettement des cartes qu\'elles annoncent. Sur écran étroit, les cartes prennent toute la largeur au lieu de se serrer à deux par ligne, et sur téléphone la description s\'affiche en entier. Les filtres de catégorie sont réparés : « Analyse de marché » ne renvoyait plus aucun widget, et une catégorie « Vues du desk » s\'ajoute pour retrouver les onglets du desk en un clic.' },
  { id: 'dtpu-20260818-recap-chrono-fr', ts: Date.UTC(2026, 7, 18, 12, 0), title: 'Récap Hebdo : plus une seule ligne en anglais dans la chronologie', desc: 'Une ligne de la Chronologie rapide pouvait rester en anglais quand la source ne l\'était pas. Elle est désormais écartée : le rapport reste intégralement en français.' },
  { id: 'dtpu-20260818-desk-icone', ts: Date.UTC(2026, 7, 18, 12, 0), title: 'Mon Desk : nommez vos dispositions et donnez-leur une icône', desc: 'Choisir une disposition ouvre maintenant un écran de nommage : vous lui donnez son nom et, si vous le souhaitez, une icône parmi dix-huit. L\'icône apparaît dans la barre d\'onglets et sur sa carte dans le gestionnaire, ce qui permet de reconnaître un desk d\'un coup d\'œil sans lire son nom. Vos dispositions existantes ne changent pas d\'aspect. L\'icône suit aussi les fichiers exportés et réimportés.' },
  { id: 'dtpu-20260818-alertes-arrivee', ts: Date.UTC(2026, 7, 18, 10, 0), title: 'Alertes : les notifications arrivent en douceur', desc: 'Une notification qui apparaissait d\'un coup au milieu de la liste se remarquait mal. L\'entrée est désormais animée très discrètement, et une notification non lue porte un bref liseré doré qui s\'efface. Rien de clignotant : c\'est un panneau de travail.' },
  { id: 'dtpu-20260818-biais-tendance', ts: Date.UTC(2026, 7, 18, 8, 0), title: 'Radar de Biais : la DIRECTION des données compte, plus seulement leur niveau', desc: 'La croissance et l\'emploi ne lisaient que le niveau et ignoraient la tendance : un emploi solide mais qui se dégrade pesait autant qu\'un emploi qui accélère. Les deux comptent désormais, comme l\'inflation le faisait déjà. Les biais collent mieux à la lecture d\'un desk macro.' },
  { id: 'dtpu-20260818-biais-relatif', ts: Date.UTC(2026, 7, 18, 6, 0), title: 'Radar de Biais : la politique monétaire lue en relatif', desc: 'Quand toutes les banques centrales tiennent le même discours, être ferme n\'est plus un avantage : le change est un marché relatif. Le pilier monétaire ne compare plus une banque à zéro mais aux sept autres. Les biais collent nettement mieux à la lecture d\'un desk macro.' },
  { id: 'dtpu-20260817-news-alignement', ts: Date.UTC(2026, 7, 18, 0, 0), title: 'Fil d\'actualité : la description alignée sous le titre', desc: 'Le texte déplié d\'une actualité était décalé vers la droite par rapport à la première lettre du titre. Il commence désormais exactement sous le titre, ce qui rend la lecture plus nette.' },
  { id: 'dtpu-20260817-dmx-paire', ts: Date.UTC(2026, 7, 17, 23, 0), title: 'Nouveau widget : le DMX d\'une seule paire, en anneau', desc: 'En complément de l\'Aperçu DMX qui liste toutes les paires, un nouveau widget isolé LA paire de votre choix et montre le partage acheteurs/vendeurs en anneau. La paire se choisit dans les réglages, parmi les 39 paires suivies.' },
  { id: 'dtpu-20260817-seances-horaires', ts: Date.UTC(2026, 7, 17, 22, 0), title: 'Sessions de marché : la carte ou les horaires, au choix', desc: 'Le widget Sessions de marché propose un second affichage dans ses réglages : une frise des horaires d\x27ouverture des quatre places, à votre heure, avec le repère de l\x27instant présent. Plus lisible que la mappemonde quand la carte est basse.' },
  { id: 'dtpu-20260817-eclairages-corps', ts: Date.UTC(2026, 7, 17, 21, 0), title: 'Rapports : les Éclairages IA ne restent plus muets sur Nordea et Goldman', desc: 'Certains rapports affichaient « Éclairages IA indisponibles ». Deux causes : Nordea publié ses articles dans une application dont la page ne contient aucun texte, et chez Goldman Sachs le lecteur ne récupérait que le pied de page du site. Le desk va désormais chercher le corps du rapport au bon endroit dans les deux cas.' },
  { id: 'dtpu-20260817-vraies-dates', ts: Date.UTC(2026, 7, 17, 19, 0), title: 'Recherche institutionnelle : la vraie date de chaque rapport', desc: 'Les rapports HSBC, Goldman Sachs, Nordea, Natixis, MUFG, Westpac, KBC, QCAM, UniCredit et Société Générale affichent désormais leur date de publication réelle, allée chercher à la source. Fini l\'horodatage du moment où le desk a repéré le lien : la colonne Date dit ce qu\'elle prétend dire, et le classement par fraîcheur devient juste.' },
  { id: 'dtpu-20260817-banques-dates', ts: Date.UTC(2026, 7, 17, 17, 0), title: 'Recherche institutionnelle : des dates de publication honnêtes', desc: 'Goldman Sachs publié de nouveau dans l\'onglet, avec ses vraies dates. Les rapports Wells Fargo affichent la date du document et non celle où le desk les a repérés. Et quand une banque ne date pas sa publication, la colonne indique « n.d. » au lieu d\'une date inventée.' },
  { id: 'dtpu-20260817-banques-rapports', ts: Date.UTC(2026, 7, 17, 14, 0), title: 'Recherche institutionnelle : les rapports manquants sont de retour', desc: 'Quand une banque publiait plusieurs notes le même jour, une seule arrivait dans le desk et les autres étaient perdues en silence. Pour MUFG, cela représentait un rapport reçu sur cinq. Tous remontent désormais, pour toutes les banques. Les archives d\'années passées cessent aussi de réapparaître datées du jour en tête de liste.' },
  { id: 'dtpu-20260817-bandeau-defile', ts: Date.UTC(2026, 7, 17, 13, 0), title: 'Accueil : le bandeau de cotations défile, sans barre', desc: 'La barre de défilement apparue sous le bandeau est retirée, et la bande avance de nouveau toute seule, en continu, quels que soient les réglages d’animation de votre système. Passez la souris dessus pour la mettre en pause et lire une cotation au calme.' },
  { id: 'dtpu-20260817-bandeau-anim', ts: Date.UTC(2026, 7, 17, 12, 0), title: 'Accueil : le bandeau défile même avec les animations réduites', desc: 'Si votre système demande aux applications de limiter les animations, le bandeau de cotations s’arrêtait complètement. Un téléscripteur dont le mouvement EST le contenu : le couper supprimait sa fonction. Il défile désormais deux fois plus lentement dans ce mode, au lieu de se figer, et reste arrêtable d’un survol ou défilable à la main.' },
  { id: 'dtpu-20260817-bandeau-vitesse', ts: Date.UTC(2026, 7, 17, 9, 0), title: 'Accueil : le bandeau de cotations défile enfin visiblement', desc: 'Le bandeau du haut avançait d’un caractère toutes les cinq secondes : il défilait, mais trop lentement pour qu’on le voie. Sa vitesse est désormais constante et lisible, quel que soit le nombre de paires affichées. Et si votre système demande aux applications de limiter les animations, la bande ne bouge plus mais devient défilable à la main : vous gardez accès à toutes les cotations.' },
  { id: 'dtpu-20260817-ecran-vide', ts: Date.UTC(2026, 7, 17, 8, 30), title: 'Application de bureau : plus d’écran noir au lancement', desc: 'Il arrivait que l’application s’ouvre sur un fond noir, sans le desk ni la page de connexion. Le terminal vérifie maintenant lui-même qu’il s’est bien affiché : si rien n’apparaît, il se recharge une fois, puis vous ramène à la connexion. Vous obtenez donc toujours l’un ou l’autre, jamais une fenêtre vide. La vérification de session part aussi dès l’ouverture, au lieu d’attendre vingt secondes.' },
  { id: 'dtpu-20260815-titres-typo', ts: Date.UTC(2026, 7, 15, 23, 0), title: 'Fil d’actualité : la ponctuation des titres harmonisée', desc: 'Le long tiret disparaît aussi des titres de dépêches. Rien d’autre ne change : aucun mot n’est touché, aucun titre n’est traduit ni raccourci. Quand le nom du média figure en fin de titre, il est simplement séparé par un point médian, le même que le desk emploie partout ailleurs.' },
  { id: 'dtpu-20260815-pdf-bandeau', ts: Date.UTC(2026, 7, 15, 22, 0), title: 'Rapports de banques : une bande de moins avant le document', desc: 'Le bandeau qui répétait le titre du rapport et son nombre de pages a été retiré de la visionneuse PDF. Le titre figure déjà juste au-dessus, et le nombre de pages n’apprenait rien qu’un défilement ne montre. Le document commence donc plus haut dans l’écran.' },
  { id: 'dtpu-20260815-cal-onglet-colonnes', ts: Date.UTC(2026, 7, 15, 21, 0), title: 'Calendrier : les colonnes se règlent aussi dans l\'onglet', desc: 'La petite roue dentée du bandeau Calendrier ouvre enfin quelque chose : un volet où masquer les colonnes High et Low. Le réglage est retenu par compte, donc vous le retrouvez sur vos autres appareils, et il vaut aussi bien pour l\'onglet que pour la carte Calendrier de Mon Desk. Les deux colonnes restent affichées tant que vous n\'y touchez pas.' },
  { id: 'dtpu-20260815-bougies-reelles', ts: Date.UTC(2026, 7, 15, 19, 0), title: 'Widget Graphique : de vraies bougies de marché', desc: 'Le graphique de Mon Desk affiche désormais les vraies bougies du marché, celles qui alimentent déjà l\'onglet Banques, sur toutes les unités de temps et pour les paires de devises comme pour les indices et les matières premières. Si la source ne répond pas, l\'écran le dit clairement au lieu de tracer une courbe. L\'histogramme de volume a été retiré : le change au comptant n\'a pas de volume centralisé, et mieux vaut une rubrique en moins qu\'une rubrique approximative.' },
  { id: 'dtpu-20260815-cal-colonnes', ts: Date.UTC(2026, 7, 15, 17, 0), title: 'Calendrier économique : masquer les colonnes High et Low', desc: 'Les colonnes High et Low, qui donnent les bornes de la fourchette de consensus, peuvent désormais être masquées depuis les réglages de la carte Calendrier. Deux interrupteurs, un par colonne, et le tableau se resserre aussitôt sur Réel, Prévision et Précédent. Elles restent affichées par défaut : votre calendrier ne change pas tant que vous n\'y touchez pas.' },
  { id: 'dtpu-20260815-hebdo-courbes', ts: Date.UTC(2026, 7, 15, 16, 0), title: 'Récap Hebdo : la courbe de chaque devise, jusque dans l\'e-mail', desc: 'Sous chaque devise, le rapport affiche sa courbe de force de la semaine. L\'e-mail du samedi la reprend maintenant aussi, devise par devise. Les intertitres passent en blanc pour mieux ressortir, l\'ouverture retrouve un vrai paragraphe au lieu d\'un texte coupé, et « Fed / Pricing » ou « BoJ / Pricing » laissent place à un intitulé unique, « Banque centrale », lisible sans connaître le sigle de chaque institution. Ce dernier changement vaut aussi dans le rapport du desk.' },
  { id: 'dtpu-20260815-hebdo-mail-identique', ts: Date.UTC(2026, 7, 15, 12, 0), title: 'Récap Hebdo par e-mail : le rapport du desk, à l\'identique', desc: 'Le mail du samedi ne résume plus le rapport, il le reprend : mêmes rubriques, même déroulé, du fil géopolitique jusqu à la semaine devise par devise. Chaque devise y arrive complète, avec sa croissance, son emploi, son inflation, sa banque centrale et son pricing, ses moteurs, sa semaine à venir et son biais. Seule différence assumée : l\'aperçu porte trois devises sur huit, les cinq autres vous attendent sur le desk.' },
  { id: 'dtpu-20260815-hebdo-geo-doublon', ts: Date.UTC(2026, 7, 15, 10, 0), title: 'Récap Hebdo : la géopolitique racontée une seule fois', desc: 'Le rapport ouvre déjà sur le fil géopolitique de la semaine. Chaque devise y revenait ensuite avec un thème « Géopolitique » qui redisait les mêmes événements. Ces répétitions sont retirées : dans la partie devise par devise, l\'influence de la géopolitique apparaît désormais par son canal réel, le pétrole, l\'appétit pour le risque ou les flux obligataires, c\'est à dire ce qui touche vraiment la devise.' },
  { id: 'dtpu-20260815-widget-fil-vide', ts: Date.UTC(2026, 7, 15, 9, 30), title: 'Widget Fil d\'actualité : plus de blanc sous le bouton', desc: 'Depuis que les propos d\'un même intervenant sont regroupés en une seule carte, le widget affichait moins de lignes que prévu et laissait un grand vide sous « Charger plus », alors qu\'il restait des actualités à montrer. La liste se complète maintenant d\'elle même jusqu à remplir le cadre.' },
  { id: 'dtpu-20260814-typographie', ts: Date.UTC(2026, 7, 14, 21, 0), title: 'Une écriture plus nette dans tout le desk', desc: 'Le long tiret qui parsemait les textes du terminal a disparu de l\'ensemble des écrans, des rapports et des e-mails. Chaque phrase retrouve la ponctuation qui lui convient : deux-points quand une idée en explique une autre, virgule pour une incise, trait d\'union pour une fourchette de chiffres. La règle s\'applique aussi aux textes rédigés automatiquement, donc elle tient dans la durée au lieu de se défaire à la prochaine génération.' },
  { id: 'dtpu-20260814-hebdo-extrait', ts: Date.UTC(2026, 7, 14, 20, 0), title: 'Récap Hebdo par e-mail : un extrait fidèle du rapport', desc: 'Le mail hebdomadaire suit exactement les parties du rapport du desk et n\'en donne qu\'un aperçu : trois devises sur huit, les temps forts géopolitiques, les chiffres marquants et les banques centrales. Il l\'indique désormais clairement et renvoie au rapport complet, où les huit devises sont analysées une à une.' },
  { id: 'dtpu-20260814-hebdo-durable', ts: Date.UTC(2026, 7, 14, 19, 0), title: 'Récap Hebdo : le mail retrouve tout son contenu', desc: 'Le mail hebdomadaire pouvait partir amputé : il ne gardait que l\'introduction et le graphique de force des devises, sans la géopolitique, la macro, les chiffres, les banques centrales ni les devises. Le rapport était stocké dans la file d\'actualité, qui tourne en quelques heures et finissait par l\'effacer. Il est désormais conservé à part, et le mail retrouve toutes ses sections.' },
  { id: 'dtpu-20260814-mail-hebdo-macro', ts: Date.UTC(2026, 7, 14, 18, 0), title: 'Récap Hebdo par e-mail : la section Macro rejoint le mail', desc: 'Le mail hebdomadaire suit désormais l\'ordre du rapport du desk : l\'essentiel, le fil géopolitique, la macro, les chiffres de la semaine, les banques centrales, les devises et la force des devises. Les thèmes macro avaient leur place dans le rapport mais pas dans le mail, où ils se réduisaient à une seule phrase.' },
  { id: 'dtpu-20260814-horizons-chf', ts: Date.UTC(2026, 7, 14, 16, 0), title: 'Radar de Biais : quand la banque et le marché ne disent pas la même chose', desc: 'Un nouveau repère apparaît sur la politique monétaire quand l\'orientation de fond d\'une banque centrale et ce que le marché anticipe pour sa prochaine réunion s\'opposent : une tension qui annonce souvent un retournement ; l\'infobulle précise le sens de chacun. Par ailleurs le franc suisse est désormais lu comme il doit l\'être : par l\'appétit pour le risque, sa vraie force motrice, et non par ses seules publications domestiques.' },
  { id: 'dtpu-20260814-recaps-seance', ts: Date.UTC(2026, 7, 14, 15, 0), title: 'Récaps de séance : la même structure que le récap quotidien', desc: 'Asie, Londres et New York se lisent désormais avec les rubriques du récap quotidien, dans le même ordre et en français : Géopolitique, Macro, Analyse de séance, À surveiller. Fini les intertitres anglais « CENTRAL BANKS & DATA » ou « ON WATCH » : dans l’onglet Analystes, passer d’un rapport à l’autre ne demande plus de réapprendre où regarder. Le contenu, lui, reste propre à chaque séance.' },
  { id: 'dtpu-20260814-puces', ts: Date.UTC(2026, 7, 14, 14, 0), title: 'Analyses : listes allégées', desc: 'Les petits points des listes à puces disparaissent des analyses du fil : le texte reste aligné, la lecture est plus nette.' },
  { id: 'dtpu-20260814-portage-gradue', ts: Date.UTC(2026, 7, 14, 9, 0), title: 'Radar de Biais : l\'avantage de taux compte maintenant par paliers', desc: 'Le niveau du taux directeur d\'une devise, comparé aux sept autres grandes banques, ne comptait qu\'au-delà d\'un écart de 1,5 point et pas du tout en dessous : une livre à 1,45 point d\'avance ne recevait rien, une livre à 1,50 recevait tout. Cet apport progresse désormais avec l\'écart, ce qui colle à la réalité du portage et évite qu\'un biais bascule sur cinq centièmes de point. Les devises très au-dessus ou très en dessous de la moyenne (franc suisse, yen, dollar australien) conservent exactement la lecture qu\'elles avaient.' },
  { id: 'dtpu-20260814-fil-repare', ts: Date.UTC(2026, 7, 14, 13, 0), title: 'Fil d\'actualité : panne de la nuit réparée', desc: 'Le fil est resté muet entre jeudi soir et vendredi début d\'après-midi. La cause est identifiée et corrigée à la racine : chaque tentative de reconnexion laissait derrière elle un onglet de navigateur, jusqu à saturer le serveur et l\'empêcher de se reconnecter, plus la panne durait, plus elle se verrouillait. Les actualités de la période manquante sont récupérées automatiquement.' },
  { id: 'dtpu-20260814-apercu-graphique', ts: Date.UTC(2026, 7, 14, 1, 30), title: 'Bibliothèque de widgets : le Graphique a enfin son aperçu', desc: 'Dans la bibliothèque de Mon Desk, la carte du widget Graphique n\'affichait qu\'une minuscule icône perdue dans un cadre vide. Elle montre désormais une vraie miniature en chandeliers, comme les autres widgets.' },
  { id: 'dtpu-20260814-graphique-banques', ts: Date.UTC(2026, 7, 14, 1, 0), title: 'Onglet Banques : un vrai graphique de trading', desc: 'Le graphique des positions de banques se manipule maintenant comme un terminal : cinq unités de temps (M15, H1, H4, D1, W1) sur de vraies bougies, bande de navigation pour se déplacer dans l\'historique, zoom à la molette, et les repères de prix et de date qui suivent le curseur sur les axes. Les niveaux d\'entrée, objectif et stop de chaque banque restent affichés.' },
  { id: 'dtpu-20260813-couleurs-ton-bc', ts: Date.UTC(2026, 7, 14, 0, 20), title: 'Ton des banques centrales : la couleur suit enfin le sens', desc: 'Un ton hawkish ou dovish s\'affichait en ambre et bleu à certains endroits, en vert et rouge à d\'autres : le même ton pouvait donc changer de couleur d\'une vue à l\'autre. Partout désormais : vert quand le ton soutient la devise, rouge quand il pèse sur elle, gris quand il est neutre.' },
  { id: 'dtpu-20260813-couleurs-donnees', ts: Date.UTC(2026, 7, 13, 23, 55), title: 'Données publiées : la couleur dit tout de suite si c\'est bon pour la devise', desc: 'Dans les récaps et la Semaine à Venir, chaque chiffre publié se colore selon ce qu\'il signifie POUR LA DEVISE : vert quand il la soutient, rouge quand il pèse sur elle, blanc quand il sort pile au consensus. Les indicateurs inversés sont traités correctement : un chômage plus élevé que prévu s\'affiche en rouge, pas en vert. Sans prévision à comparer, aucun jugement de couleur.' },
  { id: 'dtpu-20260813-campagne-coherence-2', ts: Date.UTC(2026, 7, 13, 23, 30), title: 'Campagne e-mail : dates et indicateur de fraîcheur unifiés', desc: 'Les dates s\'écrivent désormais pareil dans les cinq onglets : comparer un envoi entre le Journal et les Statistiques ne demande plus de conversion mentale. Et une seule pastille En direct, celle de l\'en-tête : on en voyait deux clignoter à des rythmes différents sur certaines vues.' },
  { id: 'dtpu-20260813-admin-echappement', ts: Date.UTC(2026, 7, 13, 23, 0), title: 'Panneau d\'administration : listes de contacts sécurisées', desc: 'Les listes qui affichent des adresses e-mail (liste noire, accès offerts, destinataires, journal des envois) échappent désormais leur contenu, et les adresses contenant des caractères de balisage sont refusées dès l\'inscription. Aucune action de votre part.' },
  { id: 'dtpu-20260813-campagne-coherence', ts: Date.UTC(2026, 7, 13, 22, 0), title: 'Campagne e-mail : la semaine Invitation retrouve ses repères', desc: 'Une semaine sur six, celle du mail Invitation, le programme perdait son repère « cette semaine » et son bandeau de prochain envoi : précisément la semaine où ce mail part à toute la liste. C\'est réparé. Le nombre de contacts exclus d\'un envoi ne compte plus deux fois une même adresse, et le panneau ne recharge plus en continu des blocs que vous ne regardez pas.' },
  { id: 'dtpu-20260813-pilotage-allege', ts: Date.UTC(2026, 7, 13, 21, 0), title: 'Campagne e-mail : un écran de pilotage allégé', desc: 'La grille de douze indicateurs du Pilotage disparaît : elle répétait deux fois les mêmes nombres et quatre de ses cartes ne mesuraient que le mail de bienvenue tout en s\'affichant comme les chiffres de la campagne. Les données d\'audience restent dans l\'onglet Audience, les résultats par envoi dans Statistiques. Le prochain e-mail annonce maintenant le bon contenu et sa vraie heure de départ.' },
  { id: 'dtpu-20260813-analyses-tag-pays', ts: Date.UTC(2026, 7, 13, 20, 0), title: 'Analyses de données : un tag en moins, une heure juste', desc: 'Sur les analyses d\'événement, le tag de pays disparaît quand le titre le dit déjà : ANALYSE PPI US n\'a pas besoin d\'une étiquette US à côté. Le tag de la paire la plus exposée, lui, reste en tête.' },
  { id: 'dtpu-20260813-couleurs-inflation', ts: Date.UTC(2026, 7, 13, 19, 0), title: 'Radar de Biais : les couleurs disent toutes la même chose', desc: 'Dans le tableau macro, le NIVEAU d\'inflation s\'affichait sur une échelle de température (doré quand élevé, bleu quand bas) pendant que tout le reste du tableau parlait en impact sur la devise. Une inflation Élevée sortait donc dorée juste à côté d\'une Hausse verte, alors que les deux disent la même chose. Désormais une seule lecture partout : vert = soutient la devise, rouge = pèse sur elle, gris = neutre.' },
  { id: 'dtpu-20260813-analyses-donnees-us', ts: Date.UTC(2026, 7, 13, 18, 0), title: 'Quatre nouvelles données américaines désormais analysées', desc: 'Les prix à la production (PPI), l\'emploi privé ADP, les postes à pourvoir (JOLTS) et les ventes au détail donnent maintenant lieu à une analyse complète environ une heure après leur publication, comme le CPI ou le PIB : le chiffre face aux attentes, ce qui a surpris, la réaction des marchés et ce que la Fed peut en tirer. Le rapport de midi s\'appelle désormais Point Marché · Ouverture US.' },
  { id: 'dtpu-20260813-grappes-propos', ts: Date.UTC(2026, 7, 13, 16, 0), title: 'Fil d\'actus : les propos d\'un même intervenant regroupés', desc: 'Quand un banquier central enchaîne les déclarations, le fil ne se remplit plus de dix lignes quasi identiques : ses propos sont réunis en une seule carte, qui indique combien elle en contient et les déroule au clic. Le regroupement suit désormais toute la durée d\'une audition, et s\'applique aussi au widget Actus et aux news attachées à une paire.' },
  { id: 'dtpu-20260812-graphique-repare', ts: Date.UTC(2026, 7, 12, 21, 30), title: 'Widget Graphique : il s\'affiche désormais dans Mon Desk', desc: 'Le widget Graphique lancé ce matin affichait « Graphique indisponible » : sa barre d\'outils cherchait un élément qui n\'existe que dans l\'onglet Marchés. Corrigé : choisissez votre paire et votre unité de temps, le chandelier s\'affiche dans votre grille.' },
  { id: 'dtpu-20260812-biais-calendrier-seul', ts: Date.UTC(2026, 7, 12, 20, 30), title: 'Radar de Biais : le verdict ne dépend plus que des chiffres publiés', desc: 'Le biais de chaque devise se calculait pour deux tiers sur les colonnes que vous lisez : politique monétaire, inflation, croissance, emploi, et pour un tiers sur des éléments qui ne sont pas des publications économiques : la tendance des prix et le positionnement des maisons de recherche. Un biais pouvait donc bouger sans qu\'aucun chiffre ne soit sorti. Désormais seules les données du calendrier économique le font évoluer.' },
  { id: 'dtpu-20260812-plus-de-reglages-memo', ts: Date.UTC(2026, 7, 12, 19, 0), title: 'Encore quatre réglages qui vous suivent désormais', desc: 'Le type de rapport dans la bibliothèque Analystes, les filtres banque et type de l\'onglet Institutions, et la colonne de tri de la Liste FX sont maintenant enregistrés sur votre compte. Vous les retrouvez à la reconnexion, y compris depuis un autre appareil. Les champs de recherche, eux, restent volontairement vierges à chaque ouverture : un filtre texte restauré en silence donnerait une liste presque vide sans qu\'on comprenne pourquoi.' },
  { id: 'dtpu-20260812-mondesk-bibliotheque', ts: Date.UTC(2026, 7, 12, 22, 30), title: 'Mon Desk : votre bibliothèque d\'espaces de travail', desc: 'Vos dispositions s\'affichent en cartes centrées dans le bloc Mon Desk de l\'accueil : aperçu du desk flouté et assombri, traversé des couleurs de graphes du terminal, nom au centre, date de dernière modification en bas, tri Récents et bouton Nouveau desk dans l\'en-tête. Sur téléphone, une carte par ligne, parfaitement lisible.' },
  { id: 'dtpu-20260812-widgets-onglets-memo', ts: Date.UTC(2026, 7, 12, 17, 0), title: 'Mon Desk : les réglages des widgets placés dans un panneau à onglets sont enfin retenus', desc: 'Un widget posé dans un panneau à onglets : deux Force des Devises côte à côte, par exemple, oubliait son unité de temps au rechargement. Il lisait bien sa configuration mais ne parvenait jamais à l\'enregistrer. Vos choix sont désormais sauvegardés sur votre compte et restaurés à la reconnexion, y compris depuis un autre appareil.' },
  { id: 'dtpu-20260812-reglages-etanches', ts: Date.UTC(2026, 7, 12, 15, 30), title: 'Vos réglages restent les vôtres, même sur un ordinateur partagé', desc: 'Sur un poste utilisé par plusieurs personnes, les réglages laissés par la session précédente pouvaient être repris par le compte suivant. Chaque jeu de réglages porte désormais la marque de son propriétaire : il est écarté dès qu\'un autre compte se connecte, et la déconnexion nettoie ce qui reste. Vos préférences continuent bien sûr de vous suivre d\'un appareil à l\'autre.' },
  { id: 'dtpu-20260812-conforme-consensus', ts: Date.UTC(2026, 7, 12, 14, 30), title: 'Calendrier : un chiffre conforme aux attentes se voit enfin', desc: 'Un résultat sorti exactement sur la prévision s\'affichait en blanc, comme un chiffre qu\'on ne peut pas juger faute de consensus. Deux situations pourtant très différentes. Le résultat conforme prend désormais la couleur neutre du terminal : vous distinguez d\'un coup d œil une publication sans surprise d\'une publication non comparable.' },
  { id: 'dtpu-20260812-data-instantanee', ts: Date.UTC(2026, 7, 12, 13, 30), title: 'Calendrier : les chiffres apparaissent dès leur publication', desc: 'Quand une annonce importante tombait, son résultat pouvait mettre plusieurs minutes à s\'afficher : au point de voir une ligne du CPI renseignée pendant que les trois autres de la même minute étaient encore vides. Le terminal sait désormais qu\'un chiffre est attendu et interroge la source toutes les 20 secondes jusqu à ce qu\'il arrive, puis reprend son rythme normal.' },
  { id: 'dtpu-20260812-apercu-repare', ts: Date.UTC(2026, 7, 12, 23, 30), title: 'Mes desks : l\'aperçu de vos dispositions s\'affiche enfin', desc: 'La carte de chaque desk restait vide sur certains écrans. La miniature était bien calculée et présente, mais une règle de style écrite plus loin dans la feuille annulait sa hauteur : les blocs existaient, écrasés à zéro pixel. C\'est corrigé : l\'aperçu occupe la carte entière et montre la vraie disposition de vos widgets.' },
  { id: 'dtpu-20260812-mails-lisibles', ts: Date.UTC(2026, 7, 12, 22, 0), title: 'E-mails : des textes plus courts et une ponctuation plus nette', desc: 'Le mot d\'introduction qui suit l\'avis d\'un membre était devenu un paragraphe convenu sur le travail de l\'équipe ; il tient maintenant en une phrase, qui rebondit sur ce que ce membre à réellement dit. Et le tiret long, banni de nos e-mails, ressortait encore quand il était écrit sous sa forme technique : il est désormais filtré sous toutes ses formes.' },
  { id: 'dtpu-20260812-jpy-cadre', ts: Date.UTC(2026, 7, 12, 21, 0), title: 'Force des Devises : plus aucune courbe coupée en bas du cadre', desc: 'Le graphique laissait volontairement sortir du cadre une devise nettement plus mobile que les autres, pour ne pas écraser les six restantes. Le seuil était trop bas : le yen le franchissait lors d\'une semaine ordinaire et devenait illisible, pour un gain de lisibilité minime. Les huit devises tiennent désormais dans le cadre sur toutes les périodes.' },
  { id: 'dtpu-20260812-tf-force-memo', ts: Date.UTC(2026, 7, 12, 20, 0), title: 'Force des Devises : votre unité de temps reste celle que vous avez choisie', desc: 'Les périodes des deux panneaux Force des Devises repassaient sur les valeurs par défaut après une déconnexion. Elles sont désormais enregistrées par le même mécanisme que vos autres réglages, celui qui suit déjà votre compte d\'un appareil à l\'autre. Vous choisissez TD en haut et TW en bas, vous revenez : c\'est encore là.' },
  { id: 'dtpu-20260812-apercu-desk-look', ts: Date.UTC(2026, 7, 12, 18, 0), title: 'Mes desks : l\'aperçu occupe toute la carte, aux couleurs du terminal', desc: 'La vignette qui montre la forme de votre desk remplit désormais la carte entière au lieu de tenir dans un coin, et elle a pris les vraies couleurs du terminal : panneaux gris ardoise, barre de titre plus foncée, bordure fine, au lieu des blocs verts et bleus qui n\'existent nulle part dans le desk. Un fin liseré rappelle la famille de chaque widget.' },
  { id: 'dtpu-20260812-nzd-inflation', ts: Date.UTC(2026, 7, 12, 16, 0), title: 'Radar de Biais : le niveau d\'inflation du dollar néo-zélandais enfin affiché', desc: 'La colonne Inflation du NZD restait vide, faute de recevoir la seule publication comparable à la cible de sa banque centrale : la Nouvelle-Zélande ne publie son indice des prix qu\'une fois par trimestre. C\'est corrigé : le NZD affiche désormais son niveau comme les sept autres devises.' },
  { id: 'dtpu-20260812-apercu-desks', ts: Date.UTC(2026, 7, 12, 16, 30), title: 'Mes desks : l\'aperçu des dispositions fiabilisé sur mobile', desc: 'Sur certains téléphones, la vignette qui montre la forme de votre desk pouvait ne pas s\'afficher et laisser une carte vide. Sa hauteur et ses couleurs ne dépendent plus de fonctions CSS récentes que les navigateurs mobiles anciens ignorent.' },
  { id: 'dtpu-20260812-mails-rapports', ts: Date.UTC(2026, 7, 12, 14, 0), title: 'E-mails : le même sommaire que le rapport que vous ouvrez', desc: "Le point marché reprend désormais les rubriques du Récap Quotidien : Géopolitique, Macro, Analyse par session, À surveiller, et le porte sous son vrai nom. Le point de la semaine ouvre sur la même introduction que le rapport, ajoute le fil géopolitique et affiche le biais de chaque devise. Ce que vous lisez dans votre boîte ressemble enfin à ce que vous retrouvez sur le desk." },
  { id: 'dtpu-20260812-biais-temps-reel', ts: Date.UTC(2026, 7, 12, 12, 0), title: 'Radar de Biais : réaction immédiate aux chiffres, et un contrôle qui corrige', desc: 'Quand une publication à fort impact tombe : CPI, emploi, décision de taux, le Radar est prévenu directement par le calendrier et recalcule dans la foulée, au lieu d\'attendre de la découvrir plus tard. Un chiffre publié en retard n\'est plus manqué. Et un second contrôle passe désormais derrière chaque biais avant affichage : si le verdict contredit les colonnes que vous lisez, il est recalculé sur ces colonnes plutôt que publié tel quel.' },
  { id: 'dtpu-20260812-widget-graphique', ts: Date.UTC(2026, 7, 12, 9, 0), title: 'Mon Desk : un widget graphique, et des bougies plus lisibles', desc: 'Nouveau widget « Graphique » : choisissez votre paire et votre unité de temps, et gardez le chandelier sous les yeux à côté du fil ou du calendrier. Vous pouvez en poser plusieurs, chacun sur sa paire. Les bougies elles-mêmes ont été reprises : vert et rouge francs, mèches enfin visibles, corps mieux espacés : on lit le rapport de force d\'un coup d\'œil.' },
  { id: 'dtpu-20260812-reglages-memorises', ts: Date.UTC(2026, 7, 12, 9, 30), title: 'Vos réglages vous suivent, d\'un appareil à l\'autre', desc: 'La période du Force des Devises, le type de positionnement COT, l\'unité de temps et le tri du DMX, le filtre d\'impact du calendrier, l\'onglet des alertes, le tri du Journal, l\'ordre de vos onglets : tout cela est désormais mémorisé sur votre compte. Vous vous reconnectez, même depuis un autre ordinateur, et le desk est exactement comme vous l\'aviez laissé.' },
  { id: 'dtpu-20260812-sauvegardes-3', ts: Date.UTC(2026, 7, 12, 10, 0), title: 'Mon Desk : trois sauvegardes de vos dispositions', desc: 'Vos dispositions sont sauvegardées automatiquement une fois par jour, et les trois dernières versions sont conservées. Si quelque chose se passe mal, le gestionnaire vous propose désormais chaque sauvegarde avec sa date : un clic pour revenir en arrière, et l\'opération reste réversible.' },
  { id: 'dtpu-20260812-calendrier-doublons', ts: Date.UTC(2026, 7, 12, 8, 30), title: 'Calendrier : plus de lignes en double', desc: 'Certaines publications apparaissaient deux fois à la même heure : le CPI américain affichait notamment deux lignes identiques. Le calendrier n\'affiche plus que les taux publiés (CPI m/m, CPI y/y, Core CPI…), comme la référence du marché, et une même annonce ne peut plus se dédoubler.' },
  { id: 'dtpu-20260812-alertes-onglets', ts: Date.UTC(2026, 7, 12, 8, 0), title: 'Alertes : tous les onglets visibles d\'emblée', desc: 'La barre d\'onglets du volet Alertes défilait horizontalement : l\'onglet DTP, celui des nouveautés du desk, restait hors champ. Elle tient maintenant entièrement à l\'écran dès l\'ouverture.' },
  { id: 'dtpu-20260811-cot-epure',     ts: Date.UTC(2026, 7, 11, 21, 30), title: 'Positionnement COT : cartes épurées', desc: 'Chaque devise tient maintenant en deux temps : le donut dit qui domine et de combien, anneau affiné, camp minoritaire en retrait, et le pourcentage central précise enfin s\'il s\'agit des acheteurs ou des vendeurs, puis une seule ligne donne les positions longues, la position nette et les positions courtes. Les encadrés et liserés qui répétaient la même information ont disparu.' },
  { id: 'dtpu-20260811-biais-categories', ts: Date.UTC(2026, 7, 11, 23, 0), title: 'Radar de Biais : le verdict découle des colonnes', desc: 'Le biais de chaque devise se calcule désormais à partir des catégories que vous lisez : politique monétaire en tête, puis emploi, croissance et inflation, avec le ton réel des banques centrales et le différentiel de taux. Il est aussi replacé face aux sept autres devises : sur le marché des changes tout est relatif, et huit devises ne peuvent pas monter ensemble. Résultat : une lecture qui correspond enfin à ce que montrent les colonnes.' },
  { id: 'dtpu-20260811-geo-fusion',    ts: Date.UTC(2026, 7, 11, 22, 0),  title: 'Récap Hebdo : le fil géopolitique d\'un seul tenant', desc: 'Le récit de la semaine et sa chronologie ne sont plus deux sections qui se suivent en racontant la même chose : le récit explique les enjeux et les blocages, la chronologie enchaîne les faits datés, le tout sous une seule rubrique Géopolitique.' },
  { id: 'dtpu-20260811-cal-ff',        ts: Date.UTC(2026, 7, 11, 20, 30), title: 'Calendrier : les noms que vous connaissez', desc: 'Les événements du calendrier portent désormais les intitulés de référence du marché : « CPI y/y », « Core CPI m/m », « Non-Farm Employment Change » : au lieu de libellés maison. Vous retrouvez d\'un coup d\'œil la publication que vous suivez ailleurs.' },
  { id: 'dtpu-20260811-surveiller',    ts: Date.UTC(2026, 7, 11, 20, 0),  title: '« À surveiller » : l\'essentiel, et son décryptage', desc: 'Le tableau du récap quotidien ne liste plus que les publications à fort impact : fini les stocks hebdomadaires et les demandes de prêts qui noyaient les vraies échéances. Et chaque ligne s\'ouvre d\'un clic sur son Décryptage : ce que mesure l\'indicateur, comment lire le chiffre face à la prévision, et ce qui est en jeu.' },
  { id: 'dtpu-20260811-lecture-rapports', ts: Date.UTC(2026, 7, 11, 19, 30), title: 'Rapports : une lecture plus directe', desc: 'Le Récap Hebdo se parcourt d\'un trait : les devises s\'enchaînent comme dans une note de desk, sans carte à déplier une par une, et chaque bloc porte le nom de sa banque centrale (« Fed / Pricing », « BoE / Pricing »). La ligne de période a quitté les en-têtes de tous les rapports : la date rejoint le titre, l\'écran respire.' },
  { id: 'dtpu-20260811-impact-marche', ts: Date.UTC(2026, 7, 11, 17, 30), title: 'Analyses d\'événement : « Impact marché », marché exposé et 5 banques de plus', desc: 'Chaque analyse d\'un événement majeur se termine désormais par un bloc « Impact marché » : ce que le résultat implique pour la suite, ton restrictif ou accommodant, plutôt maintien ou mouvement à la prochaine réunion, et le point précis à surveiller ensuite. La news porte aussi le marché le plus exposé (ex. AUD/USD). Et la couverture s\'élargit : les décisions de la RBA, de la BoJ, de la Banque du Canada, de la RBNZ et de la BNS sont désormais analysées comme celles de la Fed, de la BCE et de la BoE.' },
  { id: 'dtpu-20260811-biais-v42', ts: Date.UTC(2026, 7, 11, 16, 0), title: 'Radar de Biais : niveaux mesurés et données restaurées', desc: 'Croissance et Emploi affichent désormais un NIVEAU (PMI face au seuil d\'expansion, chômage face à sa propre moyenne) ET sa dynamique, comme l\'inflation. Le niveau d\'inflation se compare à la cible de CHAQUE banque centrale et n\'est plus jamais déduit d\'une surprise. La posture affichée d\'une banque centrale ne se confond plus avec l\'effet du différentiel de taux, et les moteurs de la semaine expliquent leur mécanisme au survol.' },
  { id: 'dtpu-20260811-force-7d', ts: Date.UTC(2026, 7, 11, 14, 0), title: 'Force des Devises : courbes 7D/1M haute densité', desc: 'Les vues 7 jours et 1 mois passent en données horaires réelles (~120 et ~500 points au lieu de 5-7) : accélérations, ralentissements et retournements deviennent visibles. Et plus aucune courbe ne disparaît sous le bord du graphique : les valeurs finales de toutes les devises restent lisibles.' },
  { id: 'dtpu-20260811-weekly-structure', ts: Date.UTC(2026, 7, 11, 13, 0), title: 'Récap Hebdo : une note de desk, deux temps', desc: 'Le rapport se lit maintenant en deux temps : le récit géopolitique de la semaine avec sa chronologie rapide, puis la semaine devise par devise, Croissance économique, Emploi, Inflation, Politique monétaire avec le pricing, les rendez-vous datés de la semaine à venir, et le biais. Chaque devise garde sa courbe de force. Les blocs qui répétaient ces mêmes informations (Points Macro Clés, section Banques Centrales, vue d\'ensemble Force des Devises) ont été retirés.' },
  { id: 'dtpu-20260811-fxdaily-structure', ts: Date.UTC(2026, 7, 11, 12, 0), title: 'Récap quotidien : plus court, plus clair', desc: 'Le rapport tient désormais en une lecture : une synthèse d\'ouverture unique (le fil des séances et le fait dominant), puis Géopolitique, Macro et À surveiller, chaque puce déroulant ce qui s\'est passé, pourquoi ça compte et la réaction du marché. L\'analyse par séance se lit en une phrase, les chiffres restant listés dessous avec leur heure. Quatre sections qui faisaient doublon ont disparu, et les propos marquants rejoignent les avis de maisons de recherche dans « Commentaires des banques ».' },
  { id: 'dtpu-20260810-recap-actes',   ts: Date.UTC(2026, 7, 10, 13, 0), title: 'Récap Hebdo : lecture en 3 actes', desc: 'Le Récap Hebdo des Marchés est désormais balisé en trois actes numérotés : Géopolitique, Macro & Banques Centrales, Biais par devise, pour suivre le fil de la semaine d\'un coup d\'œil.' },
  { id: 'dtpu-20260810-gew-essentiel', ts: Date.UTC(2026, 7, 10, 12, 30), title: 'Récap Éco des Marchés : « L\'essentiel » en 3 points', desc: 'Le rapport s\'ouvre sur la semaine résumée en 3 phrases simples. Chaque puce indique sa conséquence marché (→) et le calendrier replié les publications secondaires : l\'important reste visible.' },
  { id: 'dtpu-20260810-inst-rapides',  ts: Date.UTC(2026, 7, 10, 12, 0), title: 'Institutions : ouverture des rapports accélérée', desc: 'Les PDF récents sont préparés en avance côté serveur : l\'ouverture d\'un rapport de banque est quasi instantanée, même la première fois.' },
  { id: 'dtpu-20260810-institutions',  ts: Date.UTC(2026, 7, 10, 11, 0), title: 'Institutions : couverture des banques élargie', desc: 'Natixis, Goldman Sachs, Société Générale, UniCredit et Nordea alimentent à nouveau l\'onglet, et CIBC rejoint le catalogue avec ses rapports PDF (dont le flash NFP).' },
  { id: 'dtpu-20260809-nfp-tete',      ts: Date.UTC(2026, 7, 9, 12, 0), title: 'Semaine à Venir : le NFP remonte en tête', desc: 'Les publications majeures (NFP, décisions de taux) sont désormais classées en tête de la Semaine à Venir et de son alerte news.' },
  { id: 'dtpu-20260808-decryptage',    ts: Date.UTC(2026, 7, 8, 12, 0), title: 'Décryptage : lisibilité améliorée sur mobile', desc: 'Le bloc cause → conséquence du Décryptage s\'adapte maintenant aux panneaux étroits : plus de texte tronqué sur téléphone.' },
];
// ── NOUVEAUTÉS PUBLIQUES pour la VITRINE (20/08, demande user « le site vitrine doit être à jour à
//    chaque fois qu'on met à jour le desk ») : mêmes entrées que l'onglet DTP du desk, champs
//    réduits (titre, texte, date), 6 dernières, CORS * comme les endpoints hero. La landing les
//    affiche dans sa section « Nouveautés » : publier une entrée DTP_UPDATES met la vitrine à jour,
//    sans toucher la landing. ──
/* ⚠️ LE VETO CADRATIN S'APPLIQUE AU SERVE (audit 28/08) : 131 annonces livrées portaient « — »
   dans le panneau DTP — le veto du 14/08 (« banni de tout le contenu AFFICHÉ ») était appliqué
   partout SAUF sur ce chemin, qui recopiait title/desc tels quels. On nettoie À LA SORTIE, par la
   même règle unique que tout le desk (`_noDash` → ai.sansCadratin : deux-points pour une
   explication, virgule ensuite) : les 393 entrées livrées en profitent sans réécrire l'histoire,
   et une entrée future qui en porterait un ne l'affichera jamais. */
app.get('/api/updates-public', (req, res) => {
  res.set('Access-Control-Allow-Origin', '*');
  res.set('Cache-Control', 'public, max-age=600');
  const now = Date.now();
  res.json({ items: DTP_UPDATES.slice(0, 6).map(u => ({ t: _noDash(u.title), d: _noDash(u.desc), ts: Math.min(u.ts, now) })) });
});

app.get('/api/dtp-updates', (req, res) => {
  if (!req.session?.userId) return res.json({ items: [] });
  // ts borné au présent : une entrée datée de la journée (midi UTC) lue le matin partait dans le
  // futur → « il y a -3640s » dans le panneau (capture user 10/08). Le client a la même ceinture.
  res.json({ items: DTP_UPDATES.map(u => ({ ...u, title: _noDash(u.title), desc: _noDash(u.desc), ts: Math.min(u.ts, Date.now()) })) });
});

app.get('/api/notif-config', async (req, res) => {
  if (!req.session?.userId) return res.json({ cfg: null });
  try {
    const v = await auth.aiCacheGet('notifcfg:' + req.session.userId);
    res.json({ cfg: (v && typeof v === 'object') ? _npCleanCfg(v) : null });
  } catch { res.json({ cfg: null }); }
});
app.post('/api/notif-config', async (req, res) => {
  if (!req.session?.userId) return res.status(401).json({ ok: false });
  try {
    const cfg = _npCleanCfg(req.body || {});
    await auth.aiCacheSet('notifcfg:' + req.session.userId, cfg);
    res.json({ ok: true });
  } catch { res.status(500).json({ ok: false }); }
});

/* ═══ NOTIFICATIONS PUSH VERS L'APP MOBILE (09/09) ═══════════════════════════════════════════════
   CE QUI MANQUAIT, ET C'ÉTAIT LA MOITIÉ DU PRODUIT. La coquille native sait déjà demander
   l'autorisation de notifier et produire un jeton Expo (`mobile/App.js`, ordre `dtp:push`) — mais
   PERSONNE ne le ramassait : ni le desk, ni le serveur. Le jeton naissait et mourait dans la
   WebView. Aucune alerte ne pouvait donc arriver écran verrouillé, alors que c'est la raison d'être
   de l'app ET la capacité native sur laquelle repose son passage en revue Apple (règle 4.2 : une
   app qui n'est qu'un site emballé est refusée). Le chemin est branché de bout en bout ici.

   ⚠️ CE QUI DÉCLENCHE UN PUSH EST VOLONTAIREMENT PLUS ÉTROIT QUE LA CLOCHE DU DESK. Le panneau
   d'alertes range cinq familles (dtp, institution, analyst, eco, news) ; une notification qui
   réveille un téléphone la nuit n'a pas le même coût qu'une ligne de plus dans un panneau. Seul
   `_highImpact` part — la donnée macro tier-1 AVEC son chiffre publié, la géopolitique tier-1 —,
   c'est-à-dire le drapeau que le serveur pose déjà à l'ingestion (`upgradeItemPriority`). On NE
   RECOPIE PAS `_npKind` côté serveur : une copie de la taxonomie client aurait divergé au premier
   changement, et c'est la copie oubliée qui se met à mentir. On projette donc sur les DEUX seules
   clés qu'un push peut porter (`eco` si la dépêche porte un chiffre, `news` sinon), et l'utilisateur
   qui a coupé l'une d'elles dans son panneau Filtre ne la reçoit pas non plus sur son téléphone.

   ⚠️ TROIS GARDE-FOUS, TOUS APPRIS AILLEURS DANS CE DÉPÔT :
   1. UN ITEM N'EST POUSSÉ QU'UNE FOIS (`_pushDejaVus`). Le cycle de news rediffuse un item quand il
      est enrichi (analyse, impact, traduction) : sans ce verrou, la même publication réveillerait le
      téléphone trois fois dans l'heure. Ensemble borné, comme `_npReadIds` côté client.
   2. PLAFOND PAR COMPTE ET PAR HEURE. Un jour de FOMC + NFP + CPI peut sortir six tier-1 en vingt
      minutes. Au-delà du plafond on se TAIT plutôt que de vider la batterie de quelqu'un — et c'est
      le meilleur moyen de ne pas se faire couper les notifications pour de bon.
   3. UN JETON MORT EST RETIRÉ. Expo répond `DeviceNotRegistered` quand l'app est désinstallée : le
      garder ferait échouer chaque envoi, indéfiniment et en silence.

   ⚠️ AUCUNE ÉNUMÉRATION D'ANNUAIRE À L'ENVOI. Balayer `getAllUsers()` à chaque cycle de news pour
   lire une clé KV par compte, c'est exactement ce qui coupe le service sur cet hébergement (512 Mo,
   la leçon de l'audit de parrainage). Un INDEX unique (`pushusers`) liste les seuls comptes qui ont
   réellement un appareil ; il est lu UNE fois, puis servi de mémoire. */
const PUSH_IDX_KEY = 'pushusers';
const PUSH_MAX_APPAREILS = 5;                    // par compte : téléphone + tablette + rechanges
const PUSH_MAX_HEURE = 6;                        // notifications par compte et par heure
const PUSH_LOT = 100;                            // Expo accepte 100 messages par requête
const PUSH_TIMEOUT_MS = 8000;
const PUSH_URL = 'https://exp.host/--/api/v2/push/send';
const _PUSH_RX_JETON = /^Expo(?:nent)?PushToken\[[A-Za-z0-9._%+-]{1,128}\]$/;
let _pushIdx = null;                             // Set<userId> — hydraté à la première utilisation
const _pushDejaVus = new Set();                  // ids d'items déjà poussés (borné)
const _pushHoraire = new Map();                  // userId → tableau d'horodatages (fenêtre glissante)
let _pushBusy = false;

async function _pushIndex() {
  if (_pushIdx) return _pushIdx;
  try {
    const v = await auth.aiCacheGet(PUSH_IDX_KEY, 366 * 86400000);
    _pushIdx = new Set(Array.isArray(v) ? v.map(String) : (v && Array.isArray(v.ids) ? v.ids.map(String) : []));
  } catch { _pushIdx = new Set(); }
  return _pushIdx;
}
async function _pushIndexAjouter(userId) {
  const idx = await _pushIndex();
  if (idx.has(String(userId))) return;
  idx.add(String(userId));
  try { await auth.aiCacheSet(PUSH_IDX_KEY, [...idx]); } catch {}
}
async function _pushIndexRetirer(userId) {
  const idx = await _pushIndex();
  if (!idx.delete(String(userId))) return;
  try { await auth.aiCacheSet(PUSH_IDX_KEY, [...idx]); } catch {}
}
const _pushCle = uid => 'push:' + String(uid);
async function _pushJetons(userId) {
  try {
    const v = await auth.aiCacheGet(_pushCle(userId), 366 * 86400000);
    const arr = (v && Array.isArray(v.tokens)) ? v.tokens : [];
    return arr.filter(j => j && _PUSH_RX_JETON.test(String(j.t || '')));
  } catch { return []; }
}
async function _pushPoserJetons(userId, jetons) {
  if (!jetons.length) { try { await auth.aiCacheSet(_pushCle(userId), { tokens: [] }); } catch {} return _pushIndexRetirer(userId); }
  try { await auth.aiCacheSet(_pushCle(userId), { tokens: jetons.slice(-PUSH_MAX_APPAREILS) }); } catch {}
  return _pushIndexAjouter(userId);
}

/* L'app enregistre son jeton à chaque ouverture : Expo le fait tourner (réinstallation, restauration
   de sauvegarde, mise à jour du système), et un jeton périmé ne prévient pas — il échoue seulement. */
app.post('/api/push/token', async (req, res) => {
  if (!req.session?.userId) return res.status(401).json({ ok: false });
  const t = String((req.body && req.body.token) || '').trim();
  if (!_PUSH_RX_JETON.test(t)) return res.status(400).json({ ok: false, error: 'jeton invalide' });
  const plat = ['ios', 'android'].includes(String(req.body && req.body.plat)) ? req.body.plat : 'inconnu';
  try {
    const jetons = (await _pushJetons(req.session.userId)).filter(j => j.t !== t);   // ré-enregistrement = remise à jour, pas doublon
    jetons.push({ t, plat, at: Date.now() });
    await _pushPoserJetons(req.session.userId, jetons);
    res.json({ ok: true, appareils: Math.min(jetons.length, PUSH_MAX_APPAREILS) });
  } catch (e) { res.status(500).json({ ok: false }); }
});
/* Déconnexion, ou refus de l'autorisation depuis les réglages du téléphone : l'appareil se retire
   lui-même. Sans ce chemin, un jeton ne partirait QUE par l'échec `DeviceNotRegistered`, qui exige
   une désinstallation complète. */
app.post('/api/push/stop', async (req, res) => {
  if (!req.session?.userId) return res.status(401).json({ ok: false });
  const t = String((req.body && req.body.token) || '').trim();
  try {
    const restants = t ? (await _pushJetons(req.session.userId)).filter(j => j.t !== t) : [];
    await _pushPoserJetons(req.session.userId, restants);
    res.json({ ok: true });
  } catch { res.status(500).json({ ok: false }); }
});

// Ce que le push peut porter : deux clés seulement, projetées sur la taxonomie du panneau Filtre.
const _pushClef = it => (/-?\d/.test(String((it && it.headline) || '')) ? 'eco' : 'news');
function _pushTexte(it) {
  const h = String((it && it.headline) || '').replace(/\s+/g, ' ').trim();
  return { title: 'DataTradingPro', body: h.length > 178 ? h.slice(0, 177) + '…' : h };
}
// Fenêtre glissante d'une heure, purgée à la lecture : pas de minuteur, pas de croissance.
function _pushSousPlafond(userId, combien) {
  const cle = String(userId), maintenant = Date.now();
  const vus = (_pushHoraire.get(cle) || []).filter(t => maintenant - t < 3600000);
  /* ⚠️ CETTE SORTIE A L'AIR REDONDANTE AVEC LE `Math.min` CI-DESSOUS. ELLE NE L'EST PAS. Sans elle,
     un compte au-delà du plafond donnerait `PUSH_MAX_HEURE - vus.length` NÉGATIF, donc un `place`
     négatif — et l'appelant teste `if (!place) continue`, qui laisse passer un nombre négatif. Le
     plafond serait franchi précisément dans le cas où il doit tenir. */
  if (vus.length >= PUSH_MAX_HEURE) { _pushHoraire.set(cle, vus); return 0; }
  const place = Math.min(combien, PUSH_MAX_HEURE - vus.length);
  for (let i = 0; i < place; i++) vus.push(maintenant);
  _pushHoraire.set(cle, vus);
  return place;
}
async function _pushExpo(messages) {
  const morts = new Set();
  for (let i = 0; i < messages.length; i += PUSH_LOT) {
    const lot = messages.slice(i, i + PUSH_LOT);
    const ac = new AbortController();
    const minuteur = setTimeout(() => ac.abort(), PUSH_TIMEOUT_MS);
    try {
      const r = await fetch(PUSH_URL, {
        method: 'POST', signal: ac.signal,
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: JSON.stringify(lot),
      });
      const d = await r.json();
      (d && Array.isArray(d.data) ? d.data : []).forEach((rep, k) => {
        if (rep && rep.status === 'error' && rep.details && rep.details.error === 'DeviceNotRegistered') {
          morts.add(lot[k] && lot[k].to);
        }
      });
    } catch (e) { console.warn('[Push] envoi impossible :', e.message); }
    finally { clearTimeout(minuteur); }
  }
  return morts;
}
async function _pushEnvoyer(items) {
  if (_pushBusy) return;
  const neufs = (items || []).filter(it => it && it._highImpact === true && !_pushDejaVus.has(it.id));
  if (!neufs.length) return;
  neufs.forEach(it => _pushDejaVus.add(it.id));
  if (_pushDejaVus.size > 4000) { for (const id of _pushDejaVus) { _pushDejaVus.delete(id); if (_pushDejaVus.size <= 3000) break; } }
  _pushBusy = true;
  try {
    const idx = await _pushIndex();
    if (!idx.size) return;
    const messages = [];
    const parJeton = new Map();                                    // jeton → userId, pour retirer un appareil mort
    for (const uid of idx) {
      let cfg = null;
      try { cfg = await auth.aiCacheGet('notifcfg:' + uid); } catch {}
      if (cfg && (cfg.enabled === false || cfg.push === false)) continue;
      const coupees = new Set(Array.isArray(cfg && cfg.catsOff) ? cfg.catsOff : []);
      const pourLui = neufs.filter(it => !coupees.has(_pushClef(it)));
      if (!pourLui.length) continue;
      const place = _pushSousPlafond(uid, pourLui.length);
      if (!place) continue;
      const jetons = await _pushJetons(uid);
      if (!jetons.length) { await _pushIndexRetirer(uid); continue; }
      for (const it of pourLui.slice(0, place)) {
        const { title, body } = _pushTexte(it);
        for (const j of jetons) {
          parJeton.set(j.t, uid);
          messages.push({ to: j.t, title, body, sound: 'default', priority: 'high', channelId: 'alertes', data: { id: String(it.id) } });
        }
      }
    }
    if (!messages.length) return;
    const morts = await _pushExpo(messages);
    for (const jeton of morts) {
      const uid = parJeton.get(jeton);
      if (!uid) continue;
      await _pushPoserJetons(uid, (await _pushJetons(uid)).filter(j => j.t !== jeton));
      console.log('[Push] appareil désinstallé, jeton retiré du compte ' + uid);
    }
    console.log('[Push] ' + messages.length + ' notification(s) envoyée(s) pour ' + neufs.length + ' publication(s) tier-1');
  } catch (e) { console.error('[Push]', e.message); }
  finally { _pushBusy = false; }
}

