// ── PHOTO DE PROFIL (avatar) — persistante PAR COMPTE (KV Supabase avatar:<userId>, modèle symrecent).
// Stockée comme data URL (déjà compressée/recadrée côté client à ~256px → ~20-60 Ko). Suit la
// reconnexion → modifier sa photo sur un appareil la met à jour sur TOUS les autres. Préfixe hors purge 31j. ──
const _AV_MAX = 300000;   // garde-fou : data URL > ~300 Ko refusée (le client envoie ~40 Ko après recadrage)
app.get('/api/profile-avatar', async (req, res) => {
  res.set('Cache-Control', 'no-store');   // JAMAIS de cache navigateur : sinon une vieille réponse {avatar:null} se fige et la photo « ne suit pas » sur l'appareil
  if (!req.session?.userId) return res.status(401).json({ avatar: null });
  try {
    const v = await auth.aiCacheGet('avatar:' + req.session.userId, 8640000000000);
    const a = (v && typeof v.avatar === 'string') ? v.avatar : (typeof v === 'string' ? v : null);
    // deleted:true = photo SUPPRIMÉE volontairement (clé présente, avatar null) — distinct de
    // « jamais définie » (pas de clé) → le front peut migrer un vieux cache local vers le compte
    // SANS jamais ressusciter une photo que l'utilisateur a retirée.
    const deleted = !!(v && typeof v === 'object' && v.avatar === null);
    res.json({ avatar: (a && /^data:image\//.test(a)) ? a : null, deleted });
  } catch { res.json({ avatar: null }); }
});
/* ── PHOTO DU SUPPORT, POSÉE DEPUIS L'ADMIN (26/08) ────────────────────────────────────────────
   Elle était une CONSTANTE dans le code : la changer voulait dire modifier un fichier, redéployer,
   et vider le cache de chaque navigateur. Elle vit désormais au même endroit que les avatars des
   comptes — le KV — mais sous une clé GLOBALE : l'admin la dépose une fois, tous les clients la
   voient. Aucun déploiement, aucune purge de cache à demander.
   Même contrat que /api/profile-avatar (data URL raster, jamais de SVG, taille bornée) : cette
   image s'affiche chez tous les clients, la règle ne peut pas être plus laxiste.
   Un cache mémoire évite un aller-retour KV à chaque ouverture de conversation ; il est vidé à
   l'écriture, donc la nouvelle photo part immédiatement. */
const _SUPAV_KEY = 'supportav:global';
let _supAvCache = { ts: 0, val: undefined };
app.get('/api/support-avatar', async (_req, res) => {
  res.set('Cache-Control', 'no-store');   // même raison que /api/profile-avatar : une réponse figée « pas de photo » ne doit jamais se cacher
  try {
    if (_supAvCache.val === undefined || Date.now() - _supAvCache.ts > 5 * 60 * 1000) {
      const v = await auth.aiCacheGet(_SUPAV_KEY, 8640000000000);
      _supAvCache = { ts: Date.now(), val: (v && typeof v.avatar === 'string') ? v.avatar : null };
    }
    res.json({ avatar: _supAvCache.val });
  } catch { res.json({ avatar: null }); }
});
app.post('/api/admin/support-avatar', requireSameOrigin, requireAdmin, async (req, res) => {
  try {
    const a = req.body && req.body.avatar;
    if (a === null || a === '') {
      await auth.aiCacheSet(_SUPAV_KEY, { avatar: null });
      _supAvCache = { ts: Date.now(), val: null };
      return res.json({ ok: true, avatar: null });
    }
    if (typeof a !== 'string' || !/^data:image\/(png|jpe?g|webp);base64,/.test(a)) return res.status(400).json({ ok: false, error: 'format image invalide (JPEG, PNG ou WebP)' });
    if (a.length > _AV_MAX) return res.status(413).json({ ok: false, error: 'image trop lourde (recadrez/compressez)' });
    await auth.aiCacheSet(_SUPAV_KEY, { avatar: a });
    _supAvCache = { ts: Date.now(), val: a };
    console.log('[Support] photo du support mise à jour → visible par tous les clients');
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

app.post('/api/profile-avatar', async (req, res) => {
  if (!req.session?.userId) return res.status(401).json({ ok: false });
  try {
    const a = req.body && req.body.avatar;
    if (a === null || a === '') { await auth.aiCacheSet('avatar:' + req.session.userId, { avatar: null }); return res.json({ ok: true, avatar: null }); }
    if (typeof a !== 'string' || !/^data:image\/(png|jpe?g|webp|gif);base64,/.test(a)) return res.status(400).json({ ok: false, error: 'format image invalide' });
    if (a.length > _AV_MAX) return res.status(413).json({ ok: false, error: 'image trop lourde (recadrez/compressez)' });
    await auth.aiCacheSet('avatar:' + req.session.userId, { avatar: a });
    res.json({ ok: true });
  } catch { res.status(500).json({ ok: false }); }
});

// ══ SYSTÈME DE WIDGETS « MON DESK » — layouts composés PAR COMPTE (KV Supabase wdg:<userId>) ══════
// L'utilisateur compose son desk : il choisit ses widgets, les arrange, enregistre plusieurs layouts
// nommés et bascule de l'un à l'autre. Modèle = journal:/avatar: (données privées, objet structuré,
// TTL « forever »). Le préfixe 'wdg:' n'est PAS dans AICACHE_PRUNABLE → JAMAIS purgé par la
// rétention 31 j (un layout perdu = le cockpit du client effacé).
// EXCEPTION ASSUMÉE à la règle « volatil » de CLAUDE.md (splitter/chat = reset au reload) : un cockpit
// se refabrique en plusieurs minutes — il DOIT suivre le compte, comme les recherches récentes et la
// config d'alertes (exceptions déjà validées par le user).
// Déployé DERRIÈRE UN FLAG ADMIN côté client : ces routes sont inertes pour qui n'ouvre pas l'onglet.
const _WDG_KV_TTL = 8640000000000;      // « forever » (la BDD reste la vérité) — NE PAS omettre : le défaut 6 h re-télécharge à chaque expiration (egress)
const _WDG_MAX_LAYOUTS = 12;            // cap anti-abus / anti-OOM
const _WDG_MAX_ITEMS = 24;              // widgets par layout
const _WDG_ID_RX = /^[a-z0-9-]{2,40}$/; // ids de widgets = catalogue front (kebab-case)
// Sanitisation SERVEUR : on reconstruit l'objet champ par champ (jamais de confiance au client).
// Cles de reglage qui portent une LISTE jointe par « | » : elles depassent la limite de 32
// caracteres imposee aux valeurs simples. Tronquer y perdrait la moitie du choix EN SILENCE —
// le reglage semblerait accepte puis reviendrait ampute au rechargement.
//   off    = sections decochees du fil d actualite
//   villes = places affichees par l horloge mondiale (27 au catalogue ~= 110 caracteres)
//   ticks  = paires suivies par la Ticklist (28 codes de 7 caracteres + separateurs ~= 223)
//            ⚠️ AJOUTE LE 19/08 EN MEME TEMPS QUE LE WIDGET, et pas apres : sans cette entree la
//            liste serait coupee a 32 caracteres au PREMIER enregistrement, l utilisateur
//            retrouverait 4 paires au lieu de 28 au rechargement, et rien ne le lui dirait.
//            C est exactement l incident deja paye sur les villes de l Horloge.
const _WDG_LISTES = new Set(['off', 'villes', 'ticks']);

function _wdgClean(body) {
  const b = (body && typeof body === 'object') ? body : {};                  // null/undefined/scalaire → objet vide
  const inLayouts = Array.isArray(b.layouts) ? b.layouts : [];
  const seen = new Set();                                                    // ids déjà pris → unicité GARANTIE
  const layouts = inLayouts
    .filter(l => l && typeof l === 'object')                                 // null/42/'x' dans le tableau : écartés AVANT toute lecture de champ
    .slice(0, _WDG_MAX_LAYOUTS)
    .map((l, i) => {
      const items = (Array.isArray(l.items) ? l.items : []).slice(0, _WDG_MAX_ITEMS)
        .filter(it => it && typeof it.w === 'string' && _WDG_ID_RX.test(it.w))
        .map(it => {
          const o = {
            w: it.w,                                                         // id du widget (catalogue front)
            h: Math.min(900, Math.max(120, parseInt(it.h, 10) || 260)),      // hauteur px (rétro-compat ancien modèle)
            col: (it.col === 2 || it.col === '2') ? 2 : 1,                   // (rétro-compat)
          };
          // MODÈLE GRILLE v2 (bug corrigé 23/07) : le sanitizer ne gardait QUE h/col → les tailles {gw,gh}
          // et le verrouillage étaient PERDUS à chaque save/reload (l'utilisateur re-perdait son agencement).
          const gw = parseInt(it.gw, 10), gh = parseInt(it.gh, 10);
          if (isFinite(gw)) o.gw = Math.min(12, Math.max(1, gw));
          if (isFinite(gh)) o.gh = Math.min(60, Math.max(3, gh));
          if (it.locked) o.locked = true;
          // Widget « Panneau à onglets » : sous-widgets (ids catalogue front), cap 8 — même piège que gw/gh :
          // tout champ non repris ici serait détruit au save/reload.
          if (Array.isArray(it.tabs)) {
            // Cap 12 (était 8) : la Vue générale v5 porte les 9 onglets de la nav du desk — au cap 8,
            // TAUX et BANQUES auraient été JETÉS EN SILENCE au premier save.
            const tabs = it.tabs.filter(t => typeof t === 'string' && _WDG_ID_RX.test(t)).slice(0, 12);
            if (tabs.length) o.tabs = tabs;
          }
          // Libellés d'onglets PERSONNALISÉS (double-clic → renommage, 28/07) — alignés sur tabs,
          // 18 chars max, balises retirées. Même piège que gw/gh : non repris ici = détruit au save.
          if (o.tabs && Array.isArray(it.tabLabels)) {
            const tl = it.tabLabels.slice(0, o.tabs.length)
              .map(s => (typeof s === 'string' ? s.replace(/[<>]/g, '').trim().slice(0, 18) : ''));
            if (tl.some(Boolean)) o.tabLabels = tl;
          }
          // ICONES D ONGLET PERSONNALISEES (21/08, demande user) : meme contrat que tabLabels, tableau
          // PARALLELE aligne sur tabs. On ne stocke qu un SLUG court [a-z0-9-] (le front le mappe sur un
          // SVG d une liste fixe) : jamais de balise, jamais de markup. Non repris ici = detruit au save,
          // le piege documente juste au-dessus.
          if (o.tabs && Array.isArray(it.tabIcons)) {
            const ti = it.tabIcons.slice(0, o.tabs.length)
              .map(s => (typeof s === 'string' ? s.replace(/[^a-z0-9-]/g, '').slice(0, 20) : ''));
            if (ti.some(Boolean)) o.tabIcons = ti;
          }
          // DISPOSITION D'UN ONGLET (06/08) : un onglet peut contenir NON PAS un widget mais une petite
          // grille de 2 à 4 widgets. Le modèle garde `tabs` en CHAÎNES — l'onglet composite y est le
          // sentinel « grille » (qui passe déjà _WDG_ID_RX, comme « vide ») — et la disposition vit dans
          // ce tableau PARALLÈLE, aligné positionnellement, exactement comme tabLabels.
          //   forme d'une entrée : "<code>:<id>|<id>…"   ex. "2c:calendrier-jour|vue-taux"
          //   entrée vide ('') = onglet simple, le comportement d'avant.
          // Passer par des objets dans `tabs` aurait été bien pire : le filtre l.820 les jetterait, et
          // comme tabLabels ET tabCfg sont conditionnés à `o.tabs`, un panneau aurait perdu d'un coup
          // ses onglets, ses noms ET ses réglages. On valide la FORME, pas le sens.
          if (o.tabs && Array.isArray(it.tabGrid)) {
            const tg = it.tabGrid.slice(0, o.tabs.length)
              .map(s => (typeof s === 'string' ? s.replace(/[^a-z0-9|:-]/g, '').slice(0, 240) : ''));
            if (tg.some(Boolean)) o.tabGrid = tg;
          }
          // RÉGLAGES PAR WIDGET (contrat déclaratif du front, 28/07) — tout tient dans UN seul champ `cfg`.
          // C'est délibéré : le serveur n'a pas à connaître le catalogue front, donc AJOUTER UN RÉGLAGE
          // NE DEMANDE PLUS DE TOUCHER À CE SANITIZER (le piège « champ non repris ici = détruit au save »
          // ne peut plus se reproduire pour les réglages). On valide la FORME, pas le sens :
          // clés courtes [a-z0-9_], valeurs scalaires bornées, 12 clés max par widget.
          if (it.cfg && typeof it.cfg === 'object' && !Array.isArray(it.cfg)) {
            const cfg = {};
            for (const k of Object.keys(it.cfg).slice(0, 12)) {
              if (!/^[a-z0-9_]{1,24}$/.test(k)) continue;
              const v = it.cfg[k];
              if (typeof v === 'boolean') cfg[k] = v;
              else if (typeof v === 'number' && isFinite(v)) cfg[k] = Math.max(-99999, Math.min(99999, Math.round(v)));
              // 32 caractères suffisent à un choix (« today », « high »…) — SAUF aux réglages qui
              // portent une LISTE (ex. `off` = sections décochées du fil, jointes par « | ») :
              // tronquer à 32 en aurait silencieusement perdu la moitié. 240 pour ceux-là.
              else if (typeof v === 'string') cfg[k] = v.replace(/[<>]/g, '').slice(0, (_WDG_LISTES.has(k) ? 240 : 32));
            }
            if (Object.keys(cfg).length) o.cfg = cfg;
          }
          // RÉGLAGES PROPRES À CHAQUE ONGLET (04/08, « chaque widget doit pouvoir avoir ses propres
          // réglages ») : it.tabCfg = { "<index d'onglet>": {cfg} }. Même validation de FORME que
          // `cfg` (le serveur ignore le catalogue front) ; sans cette reprise, le champ serait
          // détruit au save — le piège documenté juste au-dessus.
          if (o.tabs && it.tabCfg && typeof it.tabCfg === 'object' && !Array.isArray(it.tabCfg)) {
            const tc = {};
            // Clé = index d'onglet (« 3 »), OU index d'onglet + index de CELLULE pour un onglet composite
            // (« 3-1 » = 2e cellule du 4e onglet). Sans le second membre, un réglage de cellule serait
            // rejeté ici EN SILENCE : pris à l'écran, revenu au défaut au rechargement.
            for (const k of Object.keys(it.tabCfg).slice(0, 48)) {
              if (!/^\d{1,2}(-\d{1,2})?$/.test(k) || parseInt(k, 10) >= o.tabs.length) continue;
              const src = it.tabCfg[k];
              if (!src || typeof src !== 'object' || Array.isArray(src)) continue;
              const one = {};
              for (const k2 of Object.keys(src).slice(0, 12)) {
                if (!/^[a-z0-9_]{1,24}$/.test(k2)) continue;
                const v = src[k2];
                if (typeof v === 'boolean') one[k2] = v;
                else if (typeof v === 'number' && isFinite(v)) one[k2] = Math.max(-99999, Math.min(99999, Math.round(v)));
                // Même exception que pour `cfg` : `off` porte une LISTE (sections décochées du fil
                // en onglet) — 32 caractères l'auraient tronquée en silence.
                else if (typeof v === 'string') one[k2] = v.replace(/[<>]/g, '').slice(0, (_WDG_LISTES.has(k2) ? 240 : 32));
              }
              if (Object.keys(one).length) tc[k] = one;
            }
            if (Object.keys(tc).length) o.tabCfg = tc;
          }
          return o;
        });
      // Unicité de l'id : sans ça, deux layouts homonymes (ou un repli 'layout-2' entrant en collision
      // avec un id explicite 'layout-2') rendraient `active` ambigu → le front rouvrirait le mauvais desk.
      let id = (typeof l.id === 'string' && _WDG_ID_RX.test(l.id)) ? l.id : 'layout-' + (i + 1);
      if (seen.has(id)) { let n = 2; while (seen.has(id + '-' + n)) n++; id = id + '-' + n; }
      seen.add(id);
      return {
        id,
        name: String(l.name || 'Sans nom').replace(/[<>]/g, '').trim().slice(0, 40) || 'Sans nom',
        // ICÔNE de la disposition (17/08) : un simple identifiant du catalogue front (« graphe »,
        // « boussole »…). Le serveur ne connaît pas ce catalogue et n'a pas à le connaître : il valide
        // la FORME, comme pour `cfg`. ⚠️ Sans cette reprise, le champ serait DÉTRUIT au premier save
        // et l'icône choisie disparaîtrait au rechargement — le piège déjà rencontré sur gw/gh.
        ico: (typeof l.ico === 'string' && /^[a-z0-9-]{1,20}$/.test(l.ico)) ? l.ico : undefined,
        fav: !!l.fav,
        hidden: !!l.hidden,   // layout MASQUÉ (fermé) : absent de la barre d'onglets, ré-ouvrable au gestionnaire
        // Date de dernière modification (12/08) : affichée sur la carte d'accueil, comme une
        // bibliothèque d'espaces de travail. Bornée pour qu'un client ne puisse pas écrire de date
        // fantaisiste ; absente = carte sans date, jamais d'erreur.
        maj: (Number.isFinite(+l.maj) && +l.maj > 16e11 && +l.maj < Date.now() + 864e5) ? Math.round(+l.maj) : undefined,
        items,
      };
    });
  return {
    layouts,
    active: (typeof b.active === 'string' && seen.has(b.active)) ? b.active : (layouts[0] ? layouts[0].id : null),
    // Préférences GLOBALES. ⚠️ Tout champ absent de ce return est SILENCIEUSEMENT détruit au save/reload
    // (même piège que gw/gh, cf. commentaire plus haut).
    gap: (b.gap === 'loose' ? 'loose' : 'tight'),                 // densité (défaut = COLLÉS, demande user 26/07)
    gapV: (b.gapV === 2 ? 2 : 0),                                 // version de la préférence densité (migration one-shot)
    deskV: (Number.isInteger(b.deskV) && b.deskV > 0 && b.deskV < 100) ? b.deskV : 0,   // version de la COMPOSITION du layout par défaut : sans ce champ la migration se rejouerait à CHAQUE chargement et écraserait le desk en boucle
    actV: (b.actV === 2 ? 2 : 0),                                 // one-shot « Vue générale active par défaut » (03/08) — même piège : non repris ici, la migration écraserait le choix de l'utilisateur à chaque chargement
    tipSeen: (b.tipSeen === 1 || b.tipSeen === true) ? 1 : 0,     // astuce gestes (bord droit/coin/⠿) déjà fermée ?
    // FAVORIS de la bibliothèque (10/08, phase 2) : ids de widgets épinglés, section « Favoris » en tête.
    // Forme seule (le serveur ignore le catalogue front), cap 30 — même piège : non repris ici = détruit au save.
    wfavs: Array.isArray(b.wfavs) ? b.wfavs.filter(x => typeof x === 'string' && _WDG_ID_RX.test(x)).slice(0, 30) : [],
  };
}
/* ── HISTORIQUE DES DISPOSITIONS : 3 versions par compte, une par jour ────────────────────────────
   Stocké dans wdg:<uid>:hist = { v: [{ at, cfg }, …] }, du PLUS RÉCENT au plus ancien.
   Règle d'admission : on ne pousse un nouveau jalon que si le dernier a plus de ~24 h. Sans ce
   verrou, une session de mise en page normale (une dizaine d'enregistrements) chasserait les trois
   versions en quelques minutes et le filet ne couvrirait plus que l'heure écoulée.
   L'ancien slot unique wdg:<uid>:bak est LU en amorce (comptes déjà sauvegardés) et continue d'être
   écrit, pour qu'un retour en arrière du code ne perde rien. */
const _WDG_HIST_MAX = 3;
const _WDG_HIST_MS  = 24 * 3600e3;
async function _wdgHistLire(uid) {
  let h = null;
  try { h = await auth.aiCacheGet('wdg:' + uid + ':hist', _WDG_KV_TTL); } catch {}
  let v = (h && Array.isArray(h.v)) ? h.v : [];
  v = v.filter(x => x && x.at && x.cfg && Array.isArray(x.cfg.layouts));
  if (!v.length) {
    // Amorce depuis l'ancienne sauvegarde à slot unique.
    try {
      const bak = await auth.aiCacheGet('wdg:' + uid + ':bak', _WDG_KV_TTL);
      if (bak && bak.at && bak.cfg && Array.isArray(bak.cfg.layouts)) v = [{ at: bak.at, cfg: bak.cfg }];
    } catch {}
  }
  return v.sort((a, b) => b.at - a.at).slice(0, _WDG_HIST_MAX);
}
async function _wdgHistPush(uid) {
  const cur = await auth.aiCacheGet('wdg:' + uid, _WDG_KV_TTL);
  if (!cur || !Array.isArray(cur.layouts) || !cur.layouts.length) return;   // rien à sauvegarder
  const v = await _wdgHistLire(uid);
  if (v.length && Date.now() - v[0].at < _WDG_HIST_MS) return;              // jalon du jour déjà pris
  const neuf = [{ at: Date.now(), cfg: cur }, ...v].slice(0, _WDG_HIST_MAX);
  await auth.aiCacheSet('wdg:' + uid + ':hist', { v: neuf });
  await auth.aiCacheSet('wdg:' + uid + ':bak', { at: neuf[0].at, cfg: neuf[0].cfg });   // compat descendante
}
/* ── NOTES DE WIDGET (19/08) ─────────────────────────────────────────────────────────────────
   Pourquoi une route separee : le texte d une note ne peut PAS vivre dans `cfg`, dont les valeurs
   sont plafonnees a 32 caracteres (240 pour les listes). Un magasin dedie, une cle par compte.

   TROIS BORNES, parce qu un magasin sans plafond finit toujours par exploser :
   - 4000 caracteres par note ;
   - 48 documents par compte, le plus ancien evince quand on depasse ;
   - a la LECTURE, on ne rend que les documents encore references par une carte du compte. Les
     orphelins (cartes supprimees) cessent d etre servis et sortent au prochain enregistrement.
     Sans cela, chaque note supprimee resterait immortelle dans la base.
   Le reste du depot borne deja tout (12 layouts, 24 widgets, 12 cles de reglage) : cette route ne
   fait pas exception. */
const _NOTES_MAX_DOCS = 48;
const _NOTES_MAX_CAR = 4000;
const _NOTES_TTL = 10 * 365 * 24 * 3600 * 1000;   // une note n expire pas

function _notesClean(v) {
  const src = (v && typeof v === 'object' && v.docs && typeof v.docs === 'object') ? v.docs : {};
  const out = {};
  // Tri par fraicheur AVANT le plafond : on evince le plus ancien, jamais le plus recent.
  const cles = Object.keys(src)
    .filter((k) => /^[a-z0-9]{4,24}$/.test(k))
    .sort((a, b) => (Number(src[b] && src[b].maj) || 0) - (Number(src[a] && src[a].maj) || 0))
    .slice(0, _NOTES_MAX_DOCS);
  for (const k of cles) {
    const d = src[k];
    if (!d || typeof d !== 'object') continue;
    out[k] = { t: String(d.t == null ? '' : d.t).slice(0, _NOTES_MAX_CAR), maj: Number(d.maj) || 0 };
  }
  return { docs: out };
}

app.get('/api/widget-notes', async (req, res) => {
  if (!req.session?.userId) return res.json({ docs: {} });
  try {
    const uid = req.session.userId;
    const v = _notesClean(await auth.aiCacheGet('wdgnotes:' + uid, _NOTES_TTL));
    // Ne rendre que les documents encore references par une carte : un document orphelin n a plus
    // de proprietaire, le servir ne ferait que gonfler la reponse.
    let vivants = null;
    try {
      const cfg = await auth.aiCacheGet('wdg:' + uid, _WDG_KV_TTL);
      if (cfg && Array.isArray(cfg.layouts)) {
        vivants = new Set();
        cfg.layouts.forEach((l) => (l && Array.isArray(l.items) ? l.items : []).forEach((it) => {
          if (it && it.cfg && typeof it.cfg.doc === 'string') vivants.add(it.cfg.doc);
        }));
      }
    } catch {}
    if (vivants) {
      Object.keys(v.docs).forEach((k) => { if (!vivants.has(k)) delete v.docs[k]; });
    }
    res.json(v);
  } catch { res.json({ docs: {} }); }
});

app.post('/api/widget-notes', async (req, res) => {
  if (!req.session?.userId) return res.status(401).json({ ok: false });
  try {
    const uid = req.session.userId;
    const b = req.body || {};
    const doc = String(b.doc || '');
    if (!/^[a-z0-9]{4,24}$/.test(doc)) return res.status(400).json({ ok: false, error: 'document invalide' });
    const cur = _notesClean(await auth.aiCacheGet('wdgnotes:' + uid, _NOTES_TTL));
    cur.docs[doc] = { t: String(b.t == null ? '' : b.t).slice(0, _NOTES_MAX_CAR), maj: Date.now() };
    // Re-sanitise A L ECRITURE aussi : c est elle qui applique le plafond et l eviction.
    const net = _notesClean(cur);
    await auth.aiCacheSet('wdgnotes:' + uid, net, _NOTES_TTL);
    res.json({ ok: true, maj: net.docs[doc] ? net.docs[doc].maj : Date.now() });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

app.get('/api/widgets', async (req, res) => {
  if (!req.session?.userId) return res.json({ cfg: null });
  try {
    const v = await auth.aiCacheGet('wdg:' + req.session.userId, _WDG_KV_TTL);
    res.json({ cfg: (v && typeof v === 'object' && Array.isArray(v.layouts)) ? _wdgClean(v) : null });   // cfg:null = aucun layout enregistré → le front propose ses presets
  } catch { res.json({ cfg: null }); }
});
app.post('/api/widgets', async (req, res) => {
  if (!req.session?.userId) return res.status(401).json({ ok: false });
  try {
    const uid = req.session.userId;
    const cfg = _wdgClean(req.body || {});
    // SAUVEGARDE PAR COMPTE — 3 VERSIONS, UNE PAR JOUR (demande user 12/08 : « un backup 24 h avant
    // pour chaque user, on garde les 3 dernières versions »). L'ancien filet n'avait QU'UN slot,
    // rafraîchi toutes les 6 h : après un bug resté quelques heures invisible, la seule sauvegarde
    // disponible portait déjà l'état cassé. Trois jalons espacés d'au moins 24 h donnent une vraie
    // fenêtre de récupération — jusqu'à trois jours en arrière.
    try { await _wdgHistPush(uid); } catch {}
    await auth.aiCacheSet('wdg:' + uid, cfg);
    res.json({ ok: true, cfg });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});
// État des sauvegardes — `at` = la plus récente (compat avec l'affichage « Restaurer la sauvegarde
// du … »), `versions` = les 3 jalons disponibles, du plus récent au plus ancien.
app.get('/api/widgets/backup', async (req, res) => {
  if (!req.session?.userId) return res.json({ at: null, versions: [] });
  try {
    const v = await _wdgHistLire(req.session.userId);
    res.json({
      at: v.length ? v[0].at : null,
      versions: v.map((x, i) => ({ i, at: x.at, panneaux: (x.cfg.layouts || []).length })),
    });
  } catch { res.json({ at: null, versions: [] }); }
});
// RESTAURATION (réversible) : la version choisie devient la config courante, et la config courante
// prend la tête de l'historique → un « Restaurer » malencontreux se re-restaure d'un clic.
// `i` (0 = la plus récente) choisit le jalon ; absent → la plus récente, comportement d'origine.
app.post('/api/widgets/restore', async (req, res) => {
  if (!req.session?.userId) return res.status(401).json({ ok: false });
  try {
    const uid = req.session.userId;
    const v = await _wdgHistLire(uid);
    const i = Math.max(0, Math.min(v.length - 1, parseInt((req.body && req.body.i), 10) || 0));
    if (!v.length) return res.json({ ok: false, error: 'aucune sauvegarde' });
    const restored = _wdgClean(v[i].cfg);
    const cur = await auth.aiCacheGet('wdg:' + uid, _WDG_KV_TTL);
    await auth.aiCacheSet('wdg:' + uid, restored);
    if (cur && Array.isArray(cur.layouts) && cur.layouts.length) {
      // La config d'avant la restauration devient le jalon le plus récent : le retour arrière est
      // toujours à un clic, et les deux autres versions restent disponibles.
      const neuf = [{ at: Date.now(), cfg: cur }, ...v.filter((_, k) => k !== i)].slice(0, _WDG_HIST_MAX);
      await auth.aiCacheSet('wdg:' + uid + ':hist', { v: neuf });
      await auth.aiCacheSet('wdg:' + uid + ':bak', { at: neuf[0].at, cfg: neuf[0].cfg });
    }
    res.json({ ok: true, cfg: restored });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

// ── JOURNAL DE TRADING — persistant PAR COMPTE (KV Supabase journal:<userId>, même modèle que
// symrecent : suit la reconnexion, même sur un autre appareil). Données PRIVÉES de l'utilisateur.
// Le préfixe 'journal:' n'est PAS dans AICACHE_PRUNABLE → jamais purgé par la rétention 31 j. ──
const _JR_MAX = 500;   // cap anti-abus / anti-OOM (≈ large pour un journal perso)
const _JR_KV_TTL = 8640000000000;   // « forever » côté cache RAM (la BDD reste la vérité)
// Colonnes CUSTOM (façon Notion) : valeurs libres par entrée, rangées dans un sac `props` (clé custom → valeur).
function _jrCleanProps(p) {
  if (!p || typeof p !== 'object' || Array.isArray(p)) return undefined;
  const out = {}; let n = 0;
  for (const k in p) {
    if (n++ >= 24) break;
    const kk = String(k).slice(0, 32); if (!kk) continue;
    const v = p[k];
    if (Array.isArray(v)) { const a = v.map(x => String(x || '').trim().slice(0, 30)).filter(Boolean).slice(0, 12); if (a.length) out[kk] = a; }
    else if (typeof v === 'number' && isFinite(v)) out[kk] = v;
    else if (v != null && v !== '') out[kk] = String(v).slice(0, 200);
  }
  return Object.keys(out).length ? out : undefined;
}
// Définitions de colonnes PAR COMPTE : ordre / masquage / renommage / colonnes custom (façon Notion).
function _jrCleanCols(arr) {
  if (!Array.isArray(arr)) return undefined;
  const seen = new Set(), out = [];
  for (const c of arr.slice(0, 40)) {
    if (!c || typeof c !== 'object') continue;
    const k = String(c.k || '').slice(0, 32); if (!k || seen.has(k)) continue; seen.add(k);
    const col = { k, builtin: c.builtin !== false, label: String(c.label || k).slice(0, 40), hidden: !!c.hidden };
    if (!col.builtin) { col.type = typeof c.type === 'string' ? c.type.slice(0, 10) : 'text'; const w = parseInt(c.w, 10); if (isFinite(w)) col.w = Math.max(70, Math.min(280, w)); }
    out.push(col);
  }
  return out.length ? out : undefined;
}
// Sections narratives du volet détail (façon page Notion) : clés fixes, texte long (analyse écrite).
const _JR_SECT_KEYS = ['fondaBias', 'technical', 'entry', 'management', 'close', 'erreur'];
function _jrCleanSections(o) {
  if (!o || typeof o !== 'object') return undefined;
  const out = {};
  for (const k of _JR_SECT_KEYS) { const v = o[k]; if (v != null && v !== '') out[k] = String(v).slice(0, 4000); }
  return Object.keys(out).length ? out : undefined;
}
function _jrCleanEntries(arr) {
  if (!Array.isArray(arr)) return [];
  const num = v => { const n = parseFloat(v); return isFinite(n) ? n : null; };
  const str = (v, n) => String(v == null ? '' : v).slice(0, n || 40);
  const tags = v => (Array.isArray(v) ? v : (v ? String(v).split(/[,;|]+/) : [])).map(x => String(x || '').trim().slice(0, 30)).filter(Boolean).slice(0, 12);
  return arr.map(e => e && typeof e === 'object' ? {
    id:    String(e.id || '').slice(0, 24) || (Date.now().toString(36) + Math.random().toString(36).slice(2, 7)),
    ts:    Number(e.ts) || Date.now(),
    pair:  String(e.pair || '').toUpperCase().replace(/[^A-Z0-9/.\-]/g, '').slice(0, 12),
    dir:   e.dir === 'SELL' ? 'SELL' : 'BUY',
    lots:  num(e.lots), entry: num(e.entry), exit: num(e.exit), pl: num(e.pl),
    note:  String(e.note || '').slice(0, 300),
    // ── champs riches (journal façon Notion / dashboard de stats) ──
    // Sélecteurs simples (1 valeur) : result/session/grade/account. Multi-tags (N valeurs) : conf/entryT/err/setup/tf/sl.
    result: str(e.result, 12), session: str(e.session, 24), grade: str(e.grade, 8), account: str(e.account, 32),
    fonda: num(e.fonda), rr: num(e.rr), risk: num(e.risk), r: num(e.r), pnlPct: num(e.pnlPct), equity: num(e.equity),
    conf: tags(e.conf), entryT: tags(e.entryT), err: tags(e.err), setup: tags(e.setup), tf: tags(e.tf), sl: tags(e.sl),
    sections: _jrCleanSections(e.sections),   // analyses écrites du volet détail (Fonda Bias, Technical, Entry…)
    props: _jrCleanProps(e.props),   // valeurs des colonnes custom
  } : null).filter(e => e && e.pair.length >= 2).slice(0, _JR_MAX);
}
app.get('/api/journal', async (req, res) => {
  if (!req.session?.userId) return res.status(401).json({ entries: [] });
  // OUVERT à tous les comptes connectés depuis le 03/07/2026 (fin de la phase « en développement »).
  try {
    const v = await auth.aiCacheGet('journal:' + req.session.userId, _JR_KV_TTL);
    // custom = false → gabarit DTP (options par défaut) ; true → journal PERSO importé (options de l'utilisateur uniquement)
    // cols = définitions de colonnes du compte (null → le client applique le gabarit standard)
    res.json({ entries: _jrCleanEntries(v && v.entries), custom: !!(v && v.custom), cols: (v && v.cols) || null, startCap: (v && isFinite(v.startCap) && v.startCap > 0) ? v.startCap : null });
  } catch { res.json({ entries: [], custom: false, cols: null }); }
});
app.post('/api/journal', async (req, res) => {
  if (!req.session?.userId) return res.status(401).json({ ok: false });
  // OUVERT à tous les comptes connectés depuis le 03/07/2026 (fin de la phase « en développement »).
  try {
    const entries = _jrCleanEntries(req.body && req.body.entries);
    const custom = !!(req.body && req.body.custom);   // mémorise si le compte a personnalisé son journal (import) → ne jamais re-proposer le gabarit DTP
    const cols = _jrCleanCols(req.body && req.body.cols);   // colonnes du compte (ordre/masquage/renommage/custom)
    const stored = { entries, custom }; if (cols) stored.cols = cols;
    const startCap = parseFloat(req.body && req.body.startCap);   // capital de départ (courbe $ Capital auto)
    if (isFinite(startCap) && startCap > 0 && startCap < 1e9) stored.startCap = startCap;
    await auth.aiCacheSet('journal:' + req.session.userId, stored);
    res.json({ ok: true, count: entries.length });
  } catch { res.status(500).json({ ok: false }); }
});
// ─── Journal : images d'un trade (captures de graphiques) — clé KV SÉPARÉE par trade (jrimg:<user>:<id>),
//     chargées À LA DEMANDE → la liste du journal reste légère (anti-egress). 2 emplacements, ≤600 Ko/image
//     (déjà compressée côté client en JPEG ≤1280px). Admin-only comme le reste du journal (en dev).
const _JR_IMG_MAX = 600 * 1024;
app.get('/api/journal/img', async (req, res) => {
  if (!req.session?.userId) return res.status(401).json({ images: [] });
  const trade = String((req.query && req.query.trade) || '').slice(0, 32);
  if (!trade) return res.json({ images: [] });
  try { const v = await auth.aiCacheGet('jrimg:' + req.session.userId + ':' + trade, _JR_KV_TTL); res.json({ images: Array.isArray(v) ? v : [] }); }
  catch { res.json({ images: [] }); }
});
app.post('/api/journal/img', async (req, res) => {
  if (!req.session?.userId) return res.status(401).json({ ok: false });
  const trade = String((req.body && req.body.trade) || '').slice(0, 32);
  if (!trade) return res.status(400).json({ ok: false });
  let imgs = Array.isArray(req.body && req.body.images) ? req.body.images.slice(0, 2) : [];
  imgs = imgs.map(x => (typeof x === 'string' && /^data:image\//.test(x) && x.length <= _JR_IMG_MAX) ? x : null);
  try { await auth.aiCacheSet('jrimg:' + req.session.userId + ':' + trade, imgs); res.json({ ok: true }); }
  catch { res.status(500).json({ ok: false }); }
});

// ─── Admin routes (admin only) — tous async pour Supabase ────────────────────
// ═══ PLAN (cadence) MODIFIABLE — override admin en KV, pas de nouvelle colonne DB ═══════════════
// La cadence (mensuel/annuel/7 j/illimité) est normalement DÉRIVÉE des dates. Quand les dates
// mentent (import Whop aux échéances cassées) ou que l'admin connaît la vraie cadence (ex. Chris =
// mensuel d'après son historique Whop), l'override PRIME. Une seule clé KV `plancads`
// ({ userId → cadence }) → 1 lecture, pas 1 par compte.
let _planCads = {}, _planCadsLoaded = false;
const _CAD_VALS = ['mensuel', 'annuel', '7j', 'illimite'];
const _CAD_LBL = { mensuel: 'Mensuel', annuel: 'Annuel', '7j': '7 jours', illimite: 'Illimité' };
async function _planCadsLoad() {
  try { const v = await auth.aiCacheGet('plancads', 366 * 86400000); if (v && typeof v === 'object') _planCads = Object.assign({}, v, _planCads); } catch (e) {}
  _planCadsLoaded = true;   // les écritures locales faites AVANT le chargement survivent (overlay ci-dessus)
}
setTimeout(() => { _planCadsLoad().catch(() => {}); }, 22000);
// TOUTE écriture passe ici : garantit la map chargée d'abord (sinon une écriture précoce, webhook au
// boot par ex., repartirait d'une map vide et RASERAIT les overrides existants au aiCacheSet).
async function _planCadSet(id, cad) {
  if (!_planCadsLoaded) await _planCadsLoad().catch(() => {});
  const k = String(id);
  if (cad && _CAD_VALS.includes(cad)) _planCads[k] = cad; else delete _planCads[k];
  try { await auth.aiCacheSet('plancads', _planCads); } catch (e) {}
}
// Cadence RÉELLEMENT prise par le client, lue de sa période de facturation Whop (ms) — '' si illisible.
function _cadFromPeriod(startMs, endMs) {
  if (!startMs || !endMs || endMs <= startMs) return '';
  const j = (endMs - startMs) / 86400000;
  if (j >= 25 && j <= 35) return 'mensuel';
  if (j >= 350 && j <= 380) return 'annuel';
  if (j >= 5 && j <= 9) return '7j';
  return '';
}
function _cadOf(u) {
  if (!u || u.role !== 'client') return '';
  const o = _planCads[String(u.id)]; if (o) return o;
  if (!u.expires_at) return 'illimite';
  const span = u.created_at ? new Date(u.expires_at) - new Date(u.created_at) : 0;
  if (span > 0 && span <= 8.5 * 86400000) return '7j';
  if (span >= 300 * 86400000) return 'annuel';
  return 'mensuel';                                            // défaut (dates incohérentes incluses) — la synchro Whop corrige au renouvellement
}

app.get('/api/admin/users', requireAdmin, async (_req, res) => {
  try {
    const us = await auth.getAllUsers();
    // Les deux ÉTATS que le panneau doit pouvoir BASCULER. Sans eux il proposerait « désinscrire »
    // à quelqu'un qui l'est déjà, et l'admin ne saurait pas où il en est.
    // ⚠️ UNE seule requête groupée pour toute la liste (emailLogHasMany), jamais un appel par
    // compte : à 49 comptes cela ferait 49 allers-retours Supabase à chaque ouverture de l'écran.
    let uns = {};
    try { uns = await auth.emailLogHasMany(us.map(u => 'unsub:' + String(u.email || '').toLowerCase().trim())); } catch (e) {}
    res.json(us.map(u => {
      const em = String(u.email || '').toLowerCase().trim();
      return Object.assign({}, u, {
        plancad: _planCads[String(u.id)] || '',
        unsub: !!uns['unsub:' + em],
        unsubFige: (() => { try { return auth.estUnsubPermanent(em); } catch (e) { return false; } })(),
        blackliste: (() => { try { return auth.isEmailBlacklisted(em); } catch (e) { return false; } })(),
      });
    }));
  }
  catch (e) { res.status(500).json({ error: e.message }); }
});

// Vue d'ensemble SANTÉ (bandeau du tableau de bord + badges d'onglets) : signaux légers, zéro calcul lourd.
app.get('/api/admin/overview', requireAdmin, (_req, res) => {
  const out = { at: Date.now(), aiOk: true, mailOk: true, campCrit: 0, dripActive: false, blastActive: false };
  try { out.aiOk = !(ai.backoffActive && ai.backoffActive()); } catch {}
  try { const mh = mailer.getMailHealth && mailer.getMailHealth(); out.mailOk = !mh || mh.ok !== false; } catch {}
  try { const cut = Date.now() - 48 * 3600e3; out.campCrit = (_campaignErrors || []).filter(e => e && e.at > cut && e.level === 'critical').length; } catch {}
  try { out.dripActive = !!(_dripState && _dripState.active); out.blastActive = !!(_campSchedule && _campSchedule.active); } catch {}
  res.json(out);
});

// ─── Dashboard FINANCIER admin (KPIs + revenu estimé + prévision + Whop) ──────
//    Tout est calculé depuis la table users (données réelles). Le revenu est ESTIMÉ
//    à partir des prix connus (mensuel/annuel) et de la durée d'accès de chaque abonné.
const PRICE_MONTHLY = parseFloat(process.env.PRICE_MONTHLY) || 24.99;
const PRICE_ANNUAL  = parseFloat(process.env.PRICE_ANNUAL)  || 239.99;
/* `?force=1` (26/08) : `whop.revenueStats()` garde ses chiffres 10 MINUTES en cache. Un paiement
   encaissé à l'instant n'apparaît donc pas tout de suite — et rien ne le dit, ce qui se lit comme
   « le paiement n'est pas arrivé » alors qu'il est bien là. Le rafraîchissement forcé permet de
   vérifier immédiatement, sans attendre l'expiration du cache. Le défaut reste le cache : on ne
   rappelle pas l'API Whop à chaque ouverture du tableau de bord. */
app.get('/api/admin/finance', requireAdmin, async (req, res) => {
  try {
    const users = await auth.getAllUsers({ fresh: req.query.force === '1' });
    let _revenuWhop = null;
    try { _revenuWhop = await whop.revenueStats({ force: req.query.force === '1' }); } catch (e) { console.warn('[Finance] revenu Whop indisponible :', e.message); }
    const now = Date.now(), DAY = 86400000;
    const monthKey = ts => { const d = new Date(ts); return d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0'); };
    const curMonth = monthKey(now);
    const lastMonth = monthKey(new Date(new Date().setUTCMonth(new Date().getUTCMonth() - 1)));

    // Classe un client → cycle + revenu mensuel-équivalent (mrr)
    const classify = u => {
      if (u.role !== 'client') return { cycle: 'staff', mrr: 0 };
      const crt = u.created_at ? new Date(u.created_at).getTime() : 0;
      const exp = u.expires_at ? new Date(u.expires_at).getTime() : 0;
      if (_isFriend(u)) return { cycle: 'unlimited', mrr: 0 };         // type Amis → offert, 0 € quel que soit le cycle
      if (!exp) return { cycle: 'unlimited', mrr: 0 };                 // accès offert / illimité
      if (_isTrialAccount(u)) return { cycle: 'trial', mrr: 0 };       // essai → 0 € (jamais compté au MRR)
      // (Audit 28/07) La CADENCE réelle (_cadOf : override admin / synchro Whop / dates) prime sur
      // la fenêtre création→échéance — un mensuel fidèle ne bascule plus « annuel » au MRR après
      // 10 mois de renouvellements cumulés.
      const cad = _cadOf(u);
      if (cad === 'annuel') return { cycle: 'annual', mrr: PRICE_ANNUAL / 12 };
      return { cycle: 'monthly', mrr: PRICE_MONTHLY };                 // mensuel (défaut, multi-mois ramené au mois)
    };

    const dist = { monthly: 0, annual: 0, trial: 0, unlimited: 0 };
    const signupsByMonth = {};                                        // 12 derniers mois
    for (let i = 11; i >= 0; i--) { const d = new Date(); d.setUTCMonth(d.getUTCMonth() - i); signupsByMonth[monthKey(d.getTime())] = 0; }

    let totalUsers = users.length, clients = 0, activeSubs = 0, trials = 0, suspended = 0, expired = 0;
    let mrr = 0, atRiskMrr = 0, expiringSoon = 0, newThisMonth = 0, newLastMonth = 0, churned30 = 0, newSubs30 = 0;

    for (const u of users) {
      if (u.role === 'client') {
        clients++;
        const c = classify(u);
        const exp = u.expires_at ? new Date(u.expires_at).getTime() : 0;
        const isExpired = exp && exp < now;
        const isActive  = u.active && !isExpired;
        if (!u.active) suspended++;
        if (isExpired) expired++;
        // churn : abonnés payants expirés dans les 30 derniers jours
        if (exp && now - exp > 0 && now - exp <= 30 * DAY && c.mrr > 0) churned30++;
        if (isActive && c.cycle in dist) dist[c.cycle]++;
        if (isActive && c.mrr > 0) { activeSubs++; mrr += c.mrr; }
        if (isActive && c.cycle === 'trial') trials++;
        if (isActive && c.mrr > 0 && exp && exp - now > 0 && exp - now <= 7 * DAY) { expiringSoon++; atRiskMrr += c.mrr; }
      }
      // inscriptions par mois (tous comptes)
      if (u.created_at) {
        const mk = monthKey(new Date(u.created_at).getTime());
        if (mk in signupsByMonth) signupsByMonth[mk]++;
        if (mk === curMonth) newThisMonth++;
        if (mk === lastMonth) newLastMonth++;
        if (now - new Date(u.created_at).getTime() <= 30 * DAY && u.role === 'client' && classify(u).mrr > 0) newSubs30++;
      }
    }

    // Chiffres RÉELS Whop (si configuré) → priment sur l'estimation locale pour MRR + abonnés actifs.
    let whopStats = null;
    try { whopStats = await whop.getStats(PRICE_MONTHLY); } catch {}
    const useWhop = !!(whopStats && typeof whopStats.active === 'number');
    if (useWhop) { activeSubs = whopStats.active; mrr = whopStats.mrr; }

    const arr = mrr * 12;
    const arpu = activeSubs ? mrr / activeSubs : 0;
    const growthPct = newLastMonth ? ((newThisMonth - newLastMonth) / newLastMonth * 100) : (newThisMonth ? 100 : 0);
    const churnRate = (activeSubs + churned30) ? (churned30 / (activeSubs + churned30) * 100) : 0;
    const netAdds = newSubs30 - churned30;

    // Revenu NET par mois (12 derniers mois) = somme du MRR des clients RÉELLEMENT actifs ce mois-là.
    // Aucune projection/prévision : uniquement du net tombé.
    const revenueByMonth = {};
    for (let i = 11; i >= 0; i--) { const d = new Date(); d.setUTCMonth(d.getUTCMonth() - i); revenueByMonth[monthKey(d.getTime())] = 0; }
    for (const u of users) {
      if (u.role !== 'client') continue;
      const c = classify(u); if (c.mrr <= 0) continue;
      const crt = u.created_at ? new Date(u.created_at).getTime() : 0;
      const exp = u.expires_at ? new Date(u.expires_at).getTime() : Number.POSITIVE_INFINITY;
      for (const mk of Object.keys(revenueByMonth)) {
        const [yy, mm] = mk.split('-').map(Number);
        const mStart = Date.UTC(yy, mm - 1, 1), mEnd = Date.UTC(yy, mm, 1) - 1;
        if (crt <= mEnd && exp >= mStart) revenueByMonth[mk] += c.mrr;
      }
    }
    Object.keys(revenueByMonth).forEach(k => { revenueByMonth[k] = +revenueByMonth[k].toFixed(2); });

    res.json({
      generatedAt: new Date().toISOString(),
      source: useWhop ? 'whop' : 'local',   // 'whop' = MRR/abonnés réels Whop ; 'local' = estimation table users
      pricing: { monthly: PRICE_MONTHLY, annual: PRICE_ANNUAL, currency: '€' },
      kpis: {
        totalUsers, clients, activeSubs, trials, suspended, expired,
        mrr: +mrr.toFixed(2), arr: +arr.toFixed(2), arpu: +arpu.toFixed(2),
        newThisMonth, newLastMonth, growthPct: +growthPct.toFixed(1),
        churned30, churnRate: +churnRate.toFixed(1), netAdds,
        expiringSoon, atRiskMrr: +atRiskMrr.toFixed(2),
      },
      distribution: dist,
      signupsByMonth,
      revenueByMonth,
      whop: { configured: (() => { try { return whop.configured(); } catch { return false; } })(), renewUrl: process.env.WHOP_RENEW_URL || 'https://whop.com/joined/justonetrader/products/jot-dtp/', webhookSecret: !!process.env.WHOP_WEBHOOK_SECRET },
      // REVENU RÉELLEMENT ENCAISSÉ (Whop). Les champs ci-dessus restent des ESTIMATIONS calculées
      // depuis la table users et une grille de prix ; celui-ci, non : c'est l'argent reçu.
      // null si Whop n'est pas joignable → le client garde alors l'estimation, en le disant.
      revenu: _revenuWhop,
    });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// Diagnostic IA — révèle l'état RÉEL des clés sur le serveur déployé (sans exposer
// les valeurs) + un test de génération en direct. Ouvre /api/admin/ai-status connecté
// en admin pour savoir si Gemini/Claude fonctionnent sur Render.
app.get('/api/admin/ai-status', requireAdmin, async (req, res) => {
  const st = (() => { try { return ai.status(); } catch { return { error: 'ai.status indisponible' }; } })();
  // Mode DRY par défaut : la page de statut ne déclenche PLUS de vraie génération à chaque ouverture
  // (en incident on la rafraîchit en boucle = RPD Gemini + crédits Claude gaspillés). ?live=1 = test réel.
  let test = { ok: null, dry: true, hint: 'ajouter ?live=1 pour un test de génération réel' };
  if (req.query.live === '1') {
    const t0 = Date.now();
    try {
      const out = await ai.generateText('Réponds exactement: OK', 20);
      test = { ok: true, ms: Date.now() - t0, sample: String(out).slice(0, 60) };
    } catch (e) {
      test = { ok: false, ms: Date.now() - t0, error: String(e && e.message || e).slice(0, 300) };
    }
  }
  // État du budget Gemini (pacing intra-journée) — pour voir la marge restante.
  let budget = null;
  try {
    _aiReset();
    const cap = _aiDailyCap();
    const dayTotal = Object.values(_aiUsage.dayCounts || {}).reduce((a, b) => a + b, 0);
    const frac = _aiDayFraction();
    budget = {
      monthlyBudget: GEMINI_MONTHLY_BUDGET,
      monthUsed: _aiUsage.total || 0,
      dailyCap: cap,
      usedToday: dayTotal,
      remainingToday: Math.max(0, cap - dayTotal),
      pacedCeilNow: Math.ceil(cap * frac) + AI_BURST,
      dayElapsed: Math.round(frac * 100) + '%',
      byCategory: _aiUsage.dayCounts || {},
      claudeOverBudgetByCategory: _aiUsage.claudeCounts || {},   // déversements Claude (crédits payants) du jour, comptés À PART
      weekend: _aiIsWeekend(),
    };
  } catch (e) { budget = { error: String(e && e.message || e) }; }
  res.json({
    mail: (() => { try { return mailer.getMailHealth(); } catch { return null; } })(),   // santé email (Gmail vérifié ?, envoyés/échoués)
    env: {
      GEMINI_API_KEY: !!(process.env.GEMINI_API_KEY || process.env.GOOGLE_API_KEY),
      ANTHROPIC_API_KEY: !!process.env.ANTHROPIC_API_KEY,
      ANTHROPIC_API_KEY2: !!process.env.ANTHROPIC_API_KEY2,
      ANTHROPIC_API_KEY3: !!process.env.ANTHROPIC_API_KEY3,
      ANTHROPIC_API_KEY4: !!process.env.ANTHROPIC_API_KEY4,
    },
    ai: st,
    test,
    budget,
    swTitles: { total: _swCache.length, withAiTitle: _swCache.filter(w => w && w.aiTitle).length },
    // Usage learner (Phase 1) : ce que le système a APPRIS de la demande (créneau jour×heure × catégorie).
    learner: {
      currentSlot: _aiDemandSlot(), expectedNow: aiExpectedDemand(), slotsLearned: Object.keys(_aiDemand).length,
      busiestSlots: Object.entries(_aiDemand).map(([s, v]) => ({ slot: s, total: v._t || 0 })).sort((a, b) => b.total - a.total).slice(0, 6),
    },
  });
});

