// ─── Réaction : explication Gemini du mouvement de marché (cache persistant) ───
const REACT_CACHE_FILE = path.join(_CACHE_DIR, 'cache_reaction.json');
const _reactCache = _loadJsonMap(REACT_CACHE_FILE);
// ── Le panneau Réaction ne doit dire QUE ce qui a été mesuré ────────────────────────────────
// Instruments qu'un modèle cite spontanément quand il comble un budget de caractères. La liste
// n'a pas à être exhaustive : elle couvre ce qui a été observé en production (« le DXY a augmenté
// de 0,14 % » sur une news RBA, alors que seule AUD/USD avait été mesurée).
// ⚠️ PAS de « or » ni « argent » nus : en français ce sont d'abord une conjonction et de la
// monnaie (« or le mouvement… », « l'argent des institutionnels »). Mesuré au banc : le mot nu
// déclenchait à tort. Le métal se nomme donc par des formes non ambiguës.
const _RX_INSTRUMENT = /\b(DXY|dollar index|indice dollar|XAU|XAG|gold|silver|l['’]or|d['’]or|once d['’]or|p[ée]trole|crude|Brent|WTI|rendements?|yields?|Treasuries?|Bunds?|Gilts?|OAT|S&P\s?500|SPX|Nasdaq|NDX|Dow|CAC\s?40|DAX|FTSE|Nikkei|Bitcoin|BTC|VIX|[A-Z]{3}\/[A-Z]{3})\b/gi;
// Une valeur de marché : avec unité, ou simple décimale (un cours se dit « 0.7040 », sans unité).
const _RX_CHIFFRE = /[+-]?\d+(?:[.,]\d+)?\s*(?:%|pips?|points?|pdb|bps?|dollars?|cents?|\$|€|£|¥)|[+-]?\d+[.,]\d+/gi;
// VRAI si le texte accroche un CHIFFRE à un instrument qui n'a pas été mesuré.
// ⚠️ ON RATTACHE CHAQUE CHIFFRE AU PLUS PROCHE INSTRUMENT QUI LE PRÉCÈDE, jamais à une fenêtre
// de N caractères : mesuré au banc, la fenêtre attribuait « AUD/USD touchait 0.7040 » au « DXY »
// cité juste avant, et condamnait une phrase parfaitement honnête. Un chiffre sans instrument
// devant lui appartient à la news elle-même (« taux maintenu à 4,35 % ») et ne prouve rien.
// On ne sanctionne que le chiffre : nommer un marché sans lui prêter de valeur reste une tournure,
// lui prêter une valeur qu'on n'a pas mesurée est une invention.
function _reactionInvente(texte, labels) {
  const t = String(texte || '');
  if (!t) return false;
  const permis = new Set((labels || []).map(l => String(l).toUpperCase().replace(/[^A-Z]/g, '')));
  const marques = [];
  _RX_INSTRUMENT.lastIndex = 0;
  for (let m; (m = _RX_INSTRUMENT.exec(t));) {
    marques.push({ i: m.index, nom: m[0].toUpperCase().replace(/[^A-Z]/g, '') });
  }
  if (!marques.length) return false;
  _RX_CHIFFRE.lastIndex = 0;
  for (let c; (c = _RX_CHIFFRE.exec(t));) {
    let porteur = null;
    for (const mk of marques) { if (mk.i < c.index) porteur = mk; else break; }
    if (!porteur) continue;                                        // chiffre de la news, pas d'un marché
    if (c.index - porteur.i > 120) continue;                       // trop loin : le lien n'est pas établi
    if (!permis.has(porteur.nom)) return true;                     // valeur prêtée à un marché non mesuré
  }
  return false;
}
// Repli 100 % déterministe : rien que les chiffres reçus, dans une phrase lisible. Il ne se
// déclenche qu'après un second refus, mais il garantit que le panneau ne peut PAS mentir.
function _reactionRepli(data) {
  const d = (data || [])[0];
  if (!d || !d.label) return [];
  // Les cours arrivent en NOMBRES : 0.70600 devient 0.706 et un cours de change amputé de ses
  // décimales se lit faux. On rétablit la convention de la paire (3 décimales en yen, 5 sinon).
  const dec = /JPY/i.test(d.label) ? 3 : 5;
  const prix = v => (typeof v === 'number' ? v.toFixed(dec) : String(v));
  // « A progressé de 0 point » ne veut rien dire. Un marché qui ne bouge pas après une
  // publication est pourtant un RÉSULTAT, souvent le plus parlant : il dit que le chiffre était
  // déjà intégré. On l'écrit comme tel.
  if (!d.points) return [d.label + ' est resté quasi inchangé dans les minutes qui ont suivi la publication, à moins d\'un point de son niveau d\'avant.'];
  const sens = d.dir === 'up' ? 'progressé' : 'reculé';
  const bouts = [d.label + ' a ' + sens];
  if (d.points != null) bouts.push('de ' + d.points + ' point' + (Math.abs(d.points) > 1 ? 's' : ''));
  if (d.pct) bouts.push('(' + d.pct + ')');
  if (d.ref != null && d.pic != null) bouts.push(', de ' + prix(d.ref) + ' à ' + prix(d.pic));
  if (d.minutes) bouts.push(', en ' + d.minutes + ' min');
  return [bouts.join(' ').replace(/ ,/g, ',') + ' après la publication.'];
}

app.post('/api/reaction-explain', async (req, res) => {
  const { id, headline, moves } = req.body || {};
  const _labels = Array.isArray(req.body && req.body.labels) ? req.body.labels.filter(Boolean) : [];
  const _mdata  = Array.isArray(req.body && req.body.data)   ? req.body.data.filter(Boolean)   : [];
  if (!headline || !moves) return res.json({ text: '' });

  // Explication en FRANÇAIS pour TOUTES les news (demande user 2026-07-01) — « important » ne pilote plus que le budget.
  const _imp = _isImportantNews(headline, '', '') || !!req.body.important;
  // Banque centrale ? /api/reaction-explain ne reçoit pas la catégorie → on la retrouve via l'item (par id), sinon regex sur le titre.
  const _rcb = _CB_NEWS.has((((allNews || []).find(i => i && i.id === id) || {}).category)) || /\b(fed|fomc|powell|warsh|ecb|bce|lagarde|boe|bailey|boj|ueda|snb|schlegel|boc|macklem|rba|bullock|rbnz)\b/i.test(headline);
  // Préfixe bumpé à chaque changement de RÔLE du panneau : sans cela, les explications déjà en
  // cache — écrites avec l'ancienne consigne, donc empiétant sur Analyse — continueraient d'être
  // servies pendant des jours.
  // ⚠️ PRÉFIXE BUMPÉ (fr6/frcb5) : les explications déjà en cache ont été écrites depuis un
  // chiffre à double signe et sous un prompt qui autorisait l'invention. Sans ce bump, elles
  // continueraient d'être servies pendant des jours, correctif ou pas.
  const cacheKey = (_rcb ? 'frcb5:' : 'fr6:') + (id || headline.substring(0, 120));
  if (_reactCache.has(cacheKey)) { _aiCacheStats.react.hit++; return res.json(_reactCache.get(cacheKey)); }
  _aiCacheStats.react.miss++;

  // PLUS de pré-check budget (2026-07-01) : le refus laissait la réaction sans explication (ou en anglais côté
  // repli). Clic utilisateur → on tente toujours la chaîne ; Claude réservé à l'important via claudeOverBudget.
  // Cooldown d'échec : chaîne entière en échec pour cette clé il y a <90 s → repli immédiat (retente après).
  if (_aiFailCooling(cacheKey)) { _aiCacheStats.coolskip++; return res.json({ bullets: [], text: '' }); }

  try {
    if (_aiInflightMap.has(cacheKey)) _aiCacheStats.coalesced++;   // génération identique DÉJÀ en vol → partage (1 seule requête IA)
    const result = await _aiInflight(cacheKey, async () => {
      const _langRule = 'Réponds en FRANÇAIS (traduis si la source est dans une autre langue).';   // desk 100% FR
      // ⚠️ CE PANNEAU NE DIT QUE CE QUE LE PRIX A FAIT. Les quatre lectures d'une même news ont des
      // rôles DISTINCTS (référence fournie) : Info = ce qui a été annoncé, Réaction = ce que le prix
      // a fait, Analyse = ce que ça veut dire, Impact marché = ce que ça implique. Le prompt
      // demandait auparavant « le pourquoi » et, sur une banque centrale, « le TON du discours et
      // l'impact sur les anticipations de taux » : il produisait donc la même chose que les deux
      // panneaux suivants, et le lecteur lisait trois fois le même raisonnement.
      const _prompt = `You are a markets reporter on a trading desk.
Describe THE PRICE ACTION that followed the news below, as ONE bullet of 1 to 2 sentences.
LONGUEUR : vise 200 à 280 caractères AU TOTAL, espaces compris. Ce budget est le MÊME pour les quatre lectures d'une news (Info, Réaction, Analyse, Impact marché) : elles s'affichent côte à côte dans une grille, et un bloc deux fois plus court que son voisin passe à tort pour moins important.
The SUBJECT is the price: how it first behaved (one-way move, or two-way chop), the RANGE in pips, then where it settled shortly after.
A SHORT attribution clause to the DATA ITSELF is welcome, inside the same sentence — never a separate thought.
Model answer (target style): « Action de prix à double sens dans un couloir de 6 points, le sous-jacent au-dessus du consensus étant compensé par un indice global conforme et un ralentissement des services. GBP/USD a ensuite penché modestement à la hausse. »
⚠️ NE COMMENTE PAS le TON du communiqué, les ANTICIPATIONS DE TAUX ni ce que cela IMPLIQUE pour la suite.${_rcb ? " Même pour une communication de BANQUE CENTRALE : ne commente NI le ton (hawkish/dovish), NI les anticipations de taux." : ""} Ces trois-là appartiennent aux panneaux « Analyse » et « Impact marché » de la MÊME news : les répéter ici dirait trois fois la même chose. Ici, on RACONTE LE PRIX.
⚠️⚠️ RÈGLE ABSOLUE — N'INVENTE AUCUN CHIFFRE ET AUCUN INSTRUMENT.
Les SEULS instruments que tu peux nommer sont ceux listés dans « Observed moves » ci-dessous : ${_labels.join(', ') || '(voir Observed moves)'}.
Les SEULS chiffres que tu peux écrire sont ceux qui y figurent (pourcentage, points, niveaux, durée) ; tu peux les reformuler, jamais en ajouter.
Il t'est INTERDIT de citer le DXY, l'or, le pétrole, les rendements obligataires, les indices actions ou toute autre paire, même « s'ils ont probablement bougé » : tu n'as AUCUNE mesure sur eux, et une valeur plausible reste une valeur inventée.
Si la matière fournie est maigre, écris une phrase plus courte. Ne comble jamais un budget de caractères avec un chiffre que tu n'as pas reçu.
Keep tickers/instruments as-is (Brent, EUR/USD…). ${_langRule}
Start each bullet with • . Reply ONLY with the bullet(s), no preamble.

Headline: ${headline}
Observed moves: ${String(moves).slice(0, 500)}`;
      // ⚠️ 500 et non 300 : la matière transmise porte désormais points, niveaux et durée. À 300 on
      // tronquait en plein milieu, et un modèle qui reçoit un chiffre coupé le complète de tête.
      const _rendu = t => {
        let b = String(t || '').split('\n').map(l => l.trim())
          .filter(l => /^[•\-\*]/.test(l)).map(l => l.replace(/^[•\-\*]\s*/, '').trim()).filter(Boolean).slice(0, 3);
        if (!b.length) { const c = String(t || '').replace(/^[•\-\*\s]+/, '').trim(); if (c) b = [c]; }
        return b;
      };
      const _tirer = p => aiSmart('news', p, _rcb ? 300 : 220, { important: true, priority: 'user', claudeOverBudget: _imp });

      let bullets = _rendu(await _tirer(_prompt));
      // GARDE-FOU : le prompt INTERDIT d'inventer, ce filet VÉRIFIE. Une consigne n'est pas une
      // garantie, et c'est exactement ici qu'un « DXY +0,14 % » sans aucune mesure derrière est
      // passé à l'écran sur une news RBA.
      if (_labels.length && _reactionInvente(bullets.join(' '), _labels)) {
        _aiCacheStats.reactInvent = (_aiCacheStats.reactInvent || 0) + 1;
        bullets = _rendu(await _tirer(_prompt + '\n\n⚠️ TA RÉPONSE PRÉCÉDENTE CITAIT UN CHIFFRE SUR UN INSTRUMENT NON MESURÉ. Recommence en ne nommant QUE ' + _labels.join(', ') + ' et en n\'écrivant QUE les chiffres fournis. Une phrase plus courte est préférable à un chiffre inventé.'));
        if (_reactionInvente(bullets.join(' '), _labels)) {
          // Deux refus : on cesse de demander et on écrit nous-mêmes, avec les seuls chiffres reçus.
          const repli = _reactionRepli(_mdata);
          if (repli.length) bullets = repli;
          else return { bullets: [], text: '' };   // rien de sûr à dire : on se tait
        }
      }
      const r = { bullets, text: bullets.join(' ') };   // text conservé pour rétro-compat
      if (bullets.length) {
        _reactCache.set(cacheKey, r);
        if (_reactCache.size > 2000) _reactCache.delete(_reactCache.keys().next().value);
        _saveJsonMap(REACT_CACHE_FILE, _reactCache);
      }
      return r;
    });
    res.json(result);
  } catch (e) {
    _aiFailMark(cacheKey);   // panne totale sur cette clé → cooldown 90 s
    console.error('[Reaction API]', e.message);
    res.json({ bullets: [], text: '' });
  }
});

// ─── Traduction FR universelle des contenus SOURCE (citations speaker, propos Fed/BCE agrégés,
//     puces d'article scrapées…) qui échappaient aux résumés IA → « FR pour tout » (demande user).
//     Batch + cache DURABLE par texte (chaque citation traduite 1 seule fois, réutilisée ensuite) +
//     coalescing (2 users, même contenu → 1 appel). Repli = texte original (jamais cassé). Gratuit-first
//     (claudeOverBudget:false → Groq/Gemini/GitHub/OpenRouter/Cohere, jamais de crédits payants pour une trad).
/* Heuristique « ce texte est-il DÉJÀ en français ? ». Définie ICI, au niveau module, parce que
   DEUX chemins s'en servent : l'anti-poison du cache de traduction, et la pré-traduction de fond
   qui doit éviter de dépenser une requête sur une dépêche déjà française. Elle était locale à la
   fonction de traduction ; l'utiliser ailleurs aurait voulu dire la recopier. */
const _looksFr = s => /[àâçéèêëîïôùûüœÀÂÇÉÈÊËÎÏÔÙÛ]/.test(s) || /\b(le|la|les|des|une?|du|au|aux|est|sont|pour|avec|sur|dans|plus|selon|après|avant)\b/i.test(s);
/* ⚠️ CE QUE REND LE TRADUCTEUR N'ÉTAIT VÉRIFIÉ PAR PERSONNE (01/09, capture user : cinq lignes du
   fil EN ITALIEN, « je veux pas voir ça »). Les deux pré-traductions de fond ne testaient que deux
   choses avant de STOCKER : que la réponse ne soit pas vide, et qu'elle diffère de la source (le
   garde-fou « _traduireLot rend la source quand il échoue »). Une réponse italienne passe ces deux
   tests haut la main — elle n'est ni vide, ni identique à l'anglais d'origine. Elle était donc
   posée dans `_titreFr` / `_descFr`, qui sont des champs D'AFFICHAGE : la ligne s'affichait en
   italien, définitivement, puisqu'un champ rempli n'est jamais retenté.
   `_looksFr` existait déjà — mais seulement EN AMONT (« cette dépêche est-elle déjà française ?
   alors n'en paie pas la traduction »). Personne ne l'appliquait EN AVAL, à ce qui revient.
   Le contrôle de sortie ci-dessous ajoute la réciproque : la traduction doit ressembler à du
   français ET ne porter aucun marqueur d'une AUTRE langue latine. Les marqueurs sont choisis pour
   ne jamais mordre sur du français réel : on écarte `los`/`las` (« Los Angeles », « Las Vegas »)
   et `mais`, qui est un mot français. Éprouvé sur les cinq lignes de la capture, leurs équivalents
   espagnols et huit titres français légitimes — dont la traduction française de la phrase
   italienne elle-même, qui doit passer. */
const _RX_NON_FR = /\b(?:della|dello|delle|degli|nella|nello|sono|gli|più|anche|questo|questa|miliardi|milioni|rispetto|precedente|previsto|aumento|crescita|esportazioni|importazioni|sondaggio|superando|provvisorio|lavorativo|coreane?|giorno|annua|según|millones|dólares|exportaciones|importaciones|mercado|precios|aumentó|creció|não|são)\b/i;
const _traductionFrValide = t => { const s = String(t || '').trim(); return !!s && _looksFr(s) && !_RX_NON_FR.test(s); };
const TRANSLATE_CACHE_FILE = path.join(_CACHE_DIR, 'cache_translate.json');
const _trCache = _loadJsonMap(TRANSLATE_CACHE_FILE);
const _trKey = t => 'tr:' + String(t).slice(0, 200);
// Enveloppe de sortie d'un lot de traduction. L'ancienne formule plafonnait à 1200 tokens : un lot
// de propos longs dépassait ce budget, la réponse se coupait en route, et les dernières lignes
// revenaient sans marqueur — donc en anglais. On compte ~2,6 caractères par token, +45 % pour le
// français (plus verbeux que l'anglais), + les marqueurs [[n]].
function _trBudget(lignes) {
  const car = lignes.join(' ').length;
  return Math.max(300, Math.min(4000, Math.round((car / 2.6) * 1.45) + 60 * lignes.length + 120));
}
/* ─── TRADUCTION D'UN LOT : IMPLEMENTATION UNIQUE ────────────────────────────────────────────
   Appelee par DEUX chemins : l'endpoint /api/translate (au clic, priorite « user ») et la
   pre-traduction de fond des news importantes (priorite « background »).
   ⚠️ C'est une extraction, pas une reecriture. Ecrire un second traducteur a cote aurait donne
   deux comportements a maintenir pour la meme tache : le cache anti-poison, la relance ciblee des
   lignes ratees et le cooldown de panne auraient diverge, et c'est la copie oubliee qui se met a
   mentir. Meme lecon que `requireAuth` qui recopiait la regle de session, corrige le matin meme.
   Renvoie { translations, fallback? } ; ne jette jamais. */
async function _traduireLot(texts, opts = {}) {
  const r = await _traduireLotBrut(texts, opts);
  if (r && Array.isArray(r.translations)) r.translations = r.translations.map(_pctColle);
  return r;
}
async function _traduireLotBrut(texts, opts = {}) {
  const _prio = opts.priority || 'user';
  const result = texts.map(t => _trCache.has(_trKey(t)) ? _trCache.get(_trKey(t)) : null);
  const missIdx = result.map((v, i) => (v == null ? i : -1)).filter(i => i >= 0);
  if (!missIdx.length) return ({ translations: result });   // tout en cache → 0 appel IA

  const toTr = missIdx.map(i => texts[i]);
  const cacheKey = 'trb:' + toTr.join('').slice(0, 300);   // coalescing des batches identiques simultanés
  if (_aiFailCooling(cacheKey)) { missIdx.forEach(i => { if (result[i] == null) result[i] = texts[i]; }); return ({ translations: result, fallback: true }); }
  try {
    const out = await _aiInflight(cacheKey, async () => {
      const numbered = toTr.map((t, i) => `[[${i + 1}]] ${t}`).join('\n');
      const txt = await aiSmart('news', `Translate each numbered line into natural, professional FRENCH for a trading terminal.
RULES:
- Keep the [[n]] marker of each line EXACTLY, one line per marker, SAME order.
- Preserve tickers, numbers, percentages, currency pairs and institution names (Fed, ECB, BoE, EUR/USD, Brent…) unchanged.
- If a line is ALREADY in French, return it unchanged (with its marker).
- Reply ONLY with the [[n]] lines translated : no preamble, no extra text.

${numbered}`, _trBudget(toTr), { important: true, priority: _prio, claudeOverBudget: false });   // important:true OBLIGATOIRE : aiAllowed('news') exige opts.important (sans lui → 100 % des trads refusées par le budget, BUG corrigé 03/07) ; gratuit-first : jamais de crédits payants pour une simple traduction
      const map = {};
      String(txt || '').split('\n').forEach(l => { const m = l.match(/^\s*\[\[(\d+)\]\]\s*(.+?)\s*$/); if (m) { const n = parseInt(m[1], 10) - 1; if (n >= 0 && n < toTr.length) map[n] = m[2].trim(); } });
      const passe1 = toTr.map((orig, i) => map[i] || null);
      // RELANCE CIBLÉE. Un modèle rate parfois une ligne isolée (marqueur oublié, ligne recopiée
      // telle quelle) : elle ressortait en anglais AU MILIEU du français, ce qui se voit
      // immédiatement. On rejoue UNIQUEMENT les lignes ratées, une seule fois, et seulement si
      // l'échec est partiel — un échec total est une panne de cascade, pas un raté de rédaction,
      // et relancer ne ferait que gaspiller le budget.
      const rates = passe1.map((v, i) => (v == null || v === toTr[i] ? i : -1)).filter(i => i >= 0);
      if (rates.length && rates.length <= 6 && rates.length < toTr.length) {
        try {
          const t2 = await aiSmart('news', `Translate each numbered line into natural, professional FRENCH. Keep the [[n]] marker EXACTLY, one line per marker, same order. Preserve tickers, numbers and institution names. Reply ONLY with the [[n]] lines.

${rates.map((i, k) => `[[${k + 1}]] ${toTr[i]}`).join('\n')}`, _trBudget(rates.map(i => toTr[i])), { important: true, priority: _prio, claudeOverBudget: false });
          String(t2 || '').split('\n').forEach(l => {
            const m = l.match(/^\s*\[\[(\d+)\]\]\s*(.+?)\s*$/); if (!m) return;
            const k = parseInt(m[1], 10) - 1, cible = rates[k];
            if (cible != null && m[2].trim() && m[2].trim() !== toTr[cible]) passe1[cible] = m[2].trim();
          });
        } catch {}
      }
      return passe1;
    });
    // ANTI-POISON : ne JAMAIS cacher la source anglaise comme « traduction ». Un raté du modèle
    // (marqueur manquant / ligne renvoyée telle quelle) répondait l'original ET le figeait dans le
    // cache durable → cette phrase restait en anglais pour toujours. Désormais : on ne met en cache
    // qu'une vraie traduction, ou une identité si la source est DÉJÀ française (accents/mots outils).
    missIdx.forEach((origIdx, k) => {
      const src = texts[origIdx];
      const fr = out && out[k];
      if (fr && (fr !== src || _looksFr(src))) { result[origIdx] = fr; _trCache.set(_trKey(src), fr); }
      else result[origIdx] = src;   // échec sur cette ligne → source affichée, PAS cachée → retentera au prochain passage
    });
    while (_trCache.size > 8000) _trCache.delete(_trCache.keys().next().value);
    _saveJsonMap(TRANSLATE_CACHE_FILE, _trCache);
    return ({ translations: result });
  } catch (e) {
    _aiFailMark(cacheKey);
    missIdx.forEach(i => { if (result[i] == null) result[i] = texts[i]; });   // IA en panne → original
    return ({ translations: result, fallback: true });
  }
}

app.post('/api/translate', async (req, res) => {
  const texts = Array.isArray(req.body && req.body.texts)
    ? req.body.texts.map(t => String(t || '').replace(/\s+/g, ' ').trim()).filter(t => t.length >= 2).slice(0, 16)
    : [];
  if (!texts.length) return res.json({ translations: [] });
  res.json(await _traduireLot(texts, { priority: 'user' }));
});

// ─── Analyst Outlook endpoint ────────────────────────────────────────────────
const _outlookCache = new Map();

// Rassemble TOUTES les données pertinentes du terminal pour une paire (force des devises,
// COT, sentiment retail contrarien, risk on/off) → bloc texte injecté dans le prompt :
// l'IA conclut le biais à partir de l'ensemble, pas des seuls titres. Tout est servi depuis
// le cache (instantané) ; chaque source est tolérante aux pannes (try/catch indépendants).
async function _gatherTerminalContext(pair) {
  const [base, quote] = String(pair || '').toUpperCase().split('/').map(s => s.trim());
  if (!base || !quote) return '';
  const lines = [];
  // 1) Force des devises (dernière valeur de chaque devise)
  try {
    const s = await computeCurrencyStrength('today');
    const last = c => { const a = s && s.series && s.series[c]; return (a && a.length) ? a[a.length - 1].v : null; };
    const sb = last(base), sq = last(quote);
    if (sb != null || sq != null) {
      const verdict = (sb != null && sq != null) ? (sb > sq ? `${base} stronger` : sq > sb ? `${quote} stronger` : 'balanced') : 'n/a';
      lines.push(`Currency strength (today): ${base}=${sb != null ? sb.toFixed(2) : 'n/a'}, ${quote}=${sq != null ? sq.toFixed(2) : 'n/a'} → ${verdict}`);
    }
  } catch {}
  // 2) COT — positionnement spéculatif (leveraged funds) = signal de tendance
  try {
    const cot = await fetchCOTData('lev_money');
    const f = k => (cot || []).find(x => x.key === k);
    const cbp = f(base), cqp = f(quote);
    if (cbp) lines.push(`COT ${base}: ${cbp.longPct}% long / ${cbp.shortPct}% short (net ${cbp.net > 0 ? '+' : ''}${cbp.net})`);
    if (cqp) lines.push(`COT ${quote}: ${cqp.longPct}% long / ${cqp.shortPct}% short (net ${cqp.net > 0 ? '+' : ''}${cqp.net})`);
  } catch {}
  // 3) Sentiment retail (Myfxbook) = signal CONTRARIEN
  try {
    const ro = await fetchCommunityOutlook('H1');
    const r = (ro || []).find(x => x.symbol === base + quote);
    if (r) lines.push(`Retail sentiment ${base}/${quote}: ${r.longPct}% long / ${r.shortPct}% short, contrarian read: crowd ${r.longPct > r.shortPct ? 'net LONG → bearish bias' : 'net SHORT → bullish bias'}`);
  } catch {}
  // 4) Risk sentiment global (safe-haven vs risk-on)
  try {
    const risk = await fetchRiskSentiment();
    if (risk && risk.label) lines.push(`Global risk sentiment: ${risk.label}${typeof risk.score === 'number' ? ` (score ${risk.score.toFixed(2)})` : ''}`);
  } catch {}
  return lines.join('\n');
}

app.post('/api/analyst-outlook', async (req, res) => {
  const { pair, cb, headlines } = req.body || {};
  if (!pair) return res.status(400).json({ error: 'pair required' });

  // Clé de cache : paire + heure (bucket horaire) UNIQUEMENT — fini les `headlines` du client
  // dans la clé (cache contournable à volonté = générations infinies). Rafraîchi au plus 1×/h/paire.
  const _hourBucket = Math.floor(Date.now() / (60 * 60 * 1000));
  const cacheKey = `${pair}:${_hourBucket}`;
  if (_outlookCache.has(cacheKey)) return res.json(_outlookCache.get(cacheKey));

  try {
    const terminal = await _gatherTerminalContext(pair).catch(() => '');
    const text = await aiSmart('outlook', `You are a professional forex analyst. Provide a structured market outlook for ${pair}.

CONCLUDE the bias by weighing ALL the terminal data below TOGETHER (not a single factor):
- Currency strength & COT (leveraged funds) = momentum/trend signals.
- Retail sentiment = CONTRARIAN (crowd heavily long → bearish, heavily short → bullish).
- Global risk sentiment drives safe-havens (USD, JPY, CHF, Gold) vs risk currencies (AUD, NZD, CAD).
- Recent headlines = catalysts.

Pair: ${pair}
Central banks: ${cb || 'N/A'}

TERMINAL DATA:
${terminal || 'No positioning data available.'}

Recent headlines (last 24h):
${headlines || 'None available'}

Respond with ONLY valid JSON in this exact format:
{
  "bias": "bullish|bearish|neutral",
  "confidence": 65,
  "summary": "One sentence overall bias summary (max 30 words)",
  "bullets": [
    "Bullet 1: specific driver with instrument impact",
    "Bullet 2: specific driver with instrument impact",
    "Bullet 3: specific driver with instrument impact"
  ],
  "levels": [
    {"type": "resistance", "price": "1.0950", "note": "50-day EMA / key pivot"},
    {"type": "support",    "price": "1.0820", "note": "200-day EMA"},
    {"type": "support",    "price": "1.0750", "note": "Monthly low"}
  ]
}
Base "bias", "confidence" and "summary" on the WEIGHT OF EVIDENCE across the terminal data above. Be specific. Use actual levels where known. Max 3 levels. Output only valid JSON.`, 700, { priority: 'user' });
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (!jsonMatch) throw new Error('No JSON');
    const result = JSON.parse(jsonMatch[0]);
    _outlookCache.set(cacheKey, result);
    if (_outlookCache.size > 200) _outlookCache.delete(_outlookCache.keys().next().value);
    res.json(result);
  } catch (e) {
    console.error('[Analyst Outlook]', e.message);
    res.status(500).json({ error: e.message });
  }
});

// ─── London Open Preparation Report ─────────────────────────────────────────

let _londonPrepCache = null;
let _londonPrepTs    = 0;
const LONDON_PREP_TTL = 30 * 60 * 1000; // 30 min cache

function buildTemplateLondonPrep(sections, allRecent) {
  const now     = new Date();
  const timeStr = now.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Paris' });
  const dateStr = now.toLocaleDateString('en-GB',  { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/Paris' });
  const toItems = (arr, max = 5) => arr.slice(0, max).map(i => `${i.time} : ${i.headline}`);

  return {
    title: `London Open Preparation : ${dateStr}`,
    generatedAt: timeStr,
    newsCount: allRecent.length,
    sections: [
      { id:'geopolitical', title:'GEOPOLITICAL RISK', icon:'⚑',  items: toItems(sections.geopolitical) },
      { id:'centralbanks', title:'CENTRAL BANKS',     icon:'🏛', items: toItems(sections.centralBanks) },
      { id:'apac',         title:'APAC SESSION WRAP', icon:'🌏', items: toItems(sections.asian)        },
      { id:'fx',           title:'FX',                 icon:'💱', items: toItems(sections.fx)           },
      { id:'fixedincome',  title:'FIXED INCOME',       icon:'📊', items: toItems(sections.fixedIncome)  },
      { id:'commodities',  title:'COMMODITIES',        icon:'🛢', items: [...toItems(sections.energy,3), ...toItems(sections.metals,2)] },
      { id:'data',         title:'DATA RECAP',         icon:'📋', items: toItems(sections.data)         },
      { id:'notable',      title:'NOTABLE COMMENTS',   icon:'💬', items: toItems(sections.notable)      },
    ].filter(s => s.items.length > 0),
    keyRisks: [],
  };
}

async function generateLondonPrep(force = false) {
  if (!force && _londonPrepCache && Date.now() - _londonPrepTs < LONDON_PREP_TTL) return _londonPrepCache;

  const cutoff     = Date.now() - 14 * 60 * 60 * 1000; // last 14 hours
  const recentNews = allNews.filter(i => i.timestamp > cutoff);

  const CB_CATS = new Set(['Fed','ECB','BoJ','BoE','BoC','RBA','SNB','RBNZ']);
  const DATA_CATS = new Set(['Economic Commentary','EU Data','US Data','UK Data',
    'Swiss Data','Japanese Data','Canadian Data','Australian Data','Chinese Data']);

  const sections = {
    geopolitical: recentNews.filter(i => i.category === 'Geopolitical' ||
      /iran|russia|ukraine|israel|hamas|nato|north\s+korea|ceasefire|nuclear\s+deal/i.test(i.headline)),
    centralBanks: recentNews.filter(i => CB_CATS.has(i.category)),
    fx:           recentNews.filter(i => i.category === 'FX Flows' || i.category === 'Market Analysis'),
    fixedIncome:  recentNews.filter(i => i.category === 'Fixed Income'),
    energy:       recentNews.filter(i => i.category === 'Energy & Power'),
    metals:       recentNews.filter(i => i.category === 'Metals'),
    data:         recentNews.filter(i => DATA_CATS.has(i.category) && i.priority === 'high'),
    asian:        recentNews.filter(i => i.category === 'Asian News' ||
      /\b(?:japan|tokyo|nikkei|boj|china|pboc|shanghai|hong kong|singapore|asx|australia|rba|rbnz|new zealand)\b/i.test(i.headline)),
    trade:        recentNews.filter(i => i.category === 'Trade'),
    notable:      recentNews.filter(i => CB_CATS.has(i.category) && /says?|said|notes?|warns?|signals?|sees?\s/i.test(i.headline)),
  };

  const summarise = (items, max = 6) =>
    items.length ? items.slice(0, max).map(i => `[${i.time}] ${i.headline}`).join('\n') : 'Nothing significant';

  const dateStr = new Date().toLocaleDateString('en-GB', {
    weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/Paris',
  });
  const timeStr = new Date().toLocaleTimeString('fr-FR', {
    hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Paris',
  });

  const prompt = `You are a professional market analyst writing a London Open preparation bulletin (style: Newsquawk/Rannforex). Today is ${dateStr}, ${timeStr} Paris.

OVERNIGHT HEADLINES (last 14h):
GEOPOLITICAL:\n${summarise(sections.geopolitical)}
CENTRAL BANKS:\n${summarise(sections.centralBanks)}
FX / MACRO:\n${summarise(sections.fx)}
FIXED INCOME:\n${summarise(sections.fixedIncome)}
ENERGY:\n${summarise(sections.energy)}
METALS:\n${summarise(sections.metals)}
DATA:\n${summarise(sections.data)}
ASIAN SESSION:\n${summarise(sections.asian)}
TRADE:\n${summarise(sections.trade)}

Write a structured London Open prep report. Return ONLY valid JSON:
{
  "title": "London Open Preparation : ${dateStr}",
  "generatedAt": "${timeStr} CET",
  "headline": "One-sentence overall market bias for London open",
  "sections": [
    {"id":"geopolitical","title":"GEOPOLITICAL RISK","icon":"⚑","content":"2-3 sentence summary","items":["bullet 1","bullet 2","bullet 3"]},
    {"id":"centralbanks","title":"CENTRAL BANKS","icon":"🏛","content":"2-3 sentence summary","items":["bullet 1","bullet 2","bullet 3"]},
    {"id":"apac","title":"APAC SESSION WRAP","icon":"🌏","content":"2-3 sentence summary","items":["bullet 1","bullet 2"]},
    {"id":"fx","title":"FX","icon":"💱","content":"2-3 sentence summary","items":["bullet 1","bullet 2","bullet 3"]},
    {"id":"fixedincome","title":"FIXED INCOME","icon":"📊","content":"1-2 sentence summary","items":["bullet 1","bullet 2"]},
    {"id":"commodities","title":"COMMODITIES","icon":"🛢","content":"2-3 sentence summary","items":["bullet 1","bullet 2","bullet 3"]},
    {"id":"data","title":"DATA RECAP","icon":"📋","content":"Summary of key data released","items":["bullet 1","bullet 2"]},
    {"id":"notable","title":"NOTABLE CB COMMENTS","icon":"💬","content":"Key central banker statements","items":["bullet 1","bullet 2"]}
  ],
  "keyRisks": ["risk 1","risk 2","risk 3"],
  "watchlist": [{"pair":"EUR/USD","bias":"bearish","reason":"ECB dovish"},{"pair":"USD/JPY","bias":"bullish","reason":"BoJ hold"}]
}
Be specific : name instruments (EUR/USD, DXY, XAU/USD, Brent, US10Y) and levels where known. Skip sections with no relevant news. Only output valid JSON.`;

  try {
    const text = await ai.generateText(prompt, 2500);
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (!jsonMatch) throw new Error('No JSON in response');
    const report = JSON.parse(jsonMatch[0]);
    report.newsCount = recentNews.length;
    _londonPrepCache = report;
    _londonPrepTs    = Date.now();
    console.log('[LondonPrep] Report generated via AI');
    return report;
  } catch (e) {
    console.error('[LondonPrep] AI failed, using template:', e.message);
    const fallback = buildTemplateLondonPrep(sections, recentNews);
    _londonPrepCache = fallback;
    _londonPrepTs    = Date.now();
    return fallback;
  }
}

app.get('/api/london-prep', async (req, res) => {
  try {
    const force  = req.query.force === '1';
    const report = await generateLondonPrep(force);
    res.json(report);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// Auto-generate London prep at 08:45 Paris time every day
(function scheduleLondonPrep() {
  function msToNext0845Paris() {
    const now = new Date();
    const paris = new Date(now.toLocaleString('en-US', { timeZone: 'Europe/Paris' }));
    const target = new Date(paris);
    target.setHours(8, 45, 0, 0);
    if (paris >= target) target.setDate(target.getDate() + 1); // already past — schedule for tomorrow
    return target.getTime() - paris.getTime();
  }
  const delay = msToNext0845Paris();
  console.log(`[LondonPrep] Auto-generation scheduled in ${Math.round(delay / 60000)} min`);
  setTimeout(function run() {
    generateLondonPrep(true)
      .then(() => console.log('[LondonPrep] Auto-generated at 08:45 Paris'))
      .catch(e  => console.error('[LondonPrep] Auto-generation failed:', e.message));
    setInterval(() => {
      generateLondonPrep(true)
        .then(() => console.log('[LondonPrep] Auto-generated at 08:45 Paris'))
        .catch(e  => console.error('[LondonPrep] Auto-generation failed:', e.message));
    }, 24 * 60 * 60 * 1000); // every 24h
  }, delay);
})();

