// Normalise le biais renvoyé par l'IA vers l'enum FR EXACT (5 niveaux) ; tolérant aux variantes FR/EN.
const _RECAP_BIAS_ENUM = ['Haussier', 'Légèrement haussier', 'Neutre', 'Légèrement baissier', 'Baissier'];
function _recapBiasNorm(b) {
  const s = _stripMd(String(b || '')).trim();
  const hit = _RECAP_BIAS_ENUM.find(x => x.toLowerCase() === s.toLowerCase());
  if (hit) return hit;
  const l = s.toLowerCase();
  if (/tr[eè]s\s+hauss|very\s+bull|strong\s+bull/.test(l)) return 'Haussier';   // échelle à 5 crans : plus de « Très »
  if (/tr[eè]s\s+baiss|very\s+bear|strong\s+bear/.test(l)) return 'Baissier';
  if (/hauss|bull/.test(l)) return 'Haussier';
  if (/baiss|bear/.test(l)) return 'Baissier';
  return 'Neutre';
}
// COHÉRENCE Radar ↔ Récap : mappe la conclusion Smart Bias (EN, source de vérité déterministe) vers le
// biais FR du recap. ÉCHELLE UNIQUE À CINQ CRANS (demande user 11/08) — Haussier · Légèrement haussier ·
// Neutre · Légèrement baissier · Baissier. Le palier « faible » existe DÉSORMAIS aussi dans le recap :
// l'aplatir en « Haussier » faisait dire au rapport plus que ce que le Radar mesurait.
function _sbConcToRecapFr(en) {
  const s = String(en || '').toLowerCase();
  if (/weak\s*bull/.test(s)) return 'Légèrement haussier';
  if (/weak\s*bear/.test(s)) return 'Légèrement baissier';
  if (/bull|uptrend/.test(s)) return 'Haussier';
  if (/bear|downtrend/.test(s)) return 'Baissier';
  return 'Neutre';
}
// « Valeur absente » : détecte les remplissages fantômes que l'IA glisse parfois dans un catalyseur (« Non
// disponible », « N/A », tirets, points d'interrogation…) → à vider / filtrer côté parse (pas de ligne vide affichée).
const _recapIsNA = s => {
  s = String(s == null ? '' : s).trim().toLowerCase().replace(/[.\s]+$/, '');
  return !s || /^(n\/?a|non[\s-]*(disponible|renseign[ée]e?|communiqu[ée]e?|pr[ée]cis[ée]e?)|inconnue?|aucune?|—+|-+|\?+)$/.test(s);
};
// Catalyseurs à EXCLURE (demande user « sert à rien, cohérent avec l'onglet BIAIS ») : le POSITIONNEMENT
// (COT/CFTC, net positions, hedge funds, particuliers) vit dans l'onglet BIAIS (piliers Hedge Fund / Retail),
// PAS dans les catalyseurs ÉCONOMIQUES du recap. On drop toute ligne dont la donnée relève du positionnement.
const _RECAP_CAT_DROP_RX = /\bCFTC\b|\bCOT\b|\bNC\b|net\s*(short|long|position)|positions?\s*(nettes?|net|short|long|courtes?|longues?)|non[- ]?comm|spécul|speculativ|positionnement|hedge\s*fund|retail\s*position|myfxbook|open\s*interest/i;
// Garde-fou déterministe (crédibilité institutionnelle) : l'IA traduit parfois la RBA/RBNZ en « Réserve fédérale
// d'Australie/Nouvelle-Zélande » (confusion avec la Fed US). On corrige les mis-nommings connus dans le texte libre.
function _recapFixCbNames(s) {
  return String(s == null ? '' : s)
    .replace(/R[ée]serve\s+f[ée]d[ée]rale\s+d['’\s]*Australie/gi, "Banque de réserve d'Australie (RBA)")
    .replace(/R[ée]serve\s+f[ée]d[ée]rale\s+australienne/gi, "Banque de réserve d'Australie (RBA)")
    .replace(/R[ée]serve\s+f[ée]d[ée]rale\s+de\s+(la\s+)?Nouvelle[\s-]Z[ée]lande/gi, 'Banque de réserve de Nouvelle-Zélande (RBNZ)')
    .replace(/R[ée]serve\s+f[ée]d[ée]rale\s+n[ée]o[\s-]z[ée]landaise/gi, 'Banque de réserve de Nouvelle-Zélande (RBNZ)');
}
