  return String(t == null ? '' : t)
    .replace(/^\s*(?:la\s+)?(?:journée|séance|jour)\b[^:]{0,70}?\b20\d{2}\b[^:]{0,15}:\s*/i, '')
    .replace(/^\s*(?:le\s+|ce\s+)?(?:lundi|mardi|mercredi|jeudi|vendredi|samedi|dimanche)\b[^:]{0,45}?\b20\d{2}\b[^:]{0,15}:\s*/i, '')
    .trim();
