/* Seuil RELATIF à l'échelle des données, pas une constante (18/08). Le seuil fixe 0,4 datait d'une
   ancienne échelle de la force des devises : mesuré en production, les deltas hebdo vont de -0,261
   (JPY, net repli) à +0,230 (AUD, nette hausse). 0,4 était donc INATTEIGNABLE et la ligne affichait
   « Range » pour les huit devises, semaine après semaine, y compris quand le yen décrochait. Une
   ligne qui dit toujours la même chose n'informe pas : elle ment par omission.
   Le seuil devient 60 % de la moyenne des amplitudes du moment (plancher 0,04) : il suit l'échelle
   des données au lieu de la présumer, et une future recalibration de la force des devises ne le
   tuera pas une seconde fois. */
/* Pose tendanceHebdo + penteHebdo sur chaque cellule de la macroTable, depuis l ETAT MODULE
   (_sbPenteHebdo, rempli par _sbTrendRow). AUCUNE variable locale du site d appel n est lue :
   la premiere version referencait `trend`, hors de portee au site d attache, et le try/catch
   avalait la ReferenceError : le payload sortait sans comportement, EN SILENCE. C est la recidive
   exacte du piege de portee du 17/08 : d ou cette fonction autonome, et un journal en cas de vide
   plutot qu un silence. */
let _sbPenteHebdo = {};   // pentes hebdo brutes du dernier _sbTrendRow (etat module, cf. _sbAttacherComportement)
/* Pente NORMALISEE par le plus grand mouvement du moment : la devise qui a le plus bouge vaut +-1,
   les autres au prorata. C est la graduation de la lecture de reference : un yen qui decroche pese
   plein pot, une pente a peine au-dessus du seuil pese a peine. */
function _sbPenteNorm() {
  const abs = Object.values(_sbPenteHebdo).filter(Number.isFinite).map(Math.abs);
  const mx = abs.length ? Math.max.apply(null, abs) : 0;
  const out = {};
  if (mx <= 0) return out;
  for (const c of Object.keys(_sbPenteHebdo)) {
    const d = _sbPenteHebdo[c];
    if (Number.isFinite(d)) out[c] = Math.max(-1, Math.min(1, d / mx));
  }
  return out;
}
function _sbAttacherComportement(macroTable) {
  try {
    const pn = _sbPenteNorm();
    const seuil = _sbSeuilPente(Object.values(_sbPenteHebdo));
    let poses = 0;
    for (const c of Object.keys(macroTable || {})) {
      const d = _sbPenteHebdo[c];
      if (!Number.isFinite(d) || !macroTable[c]) continue;
      macroTable[c].tendanceHebdo = d > seuil ? 'Uptrend' : d < -seuil ? 'Downtrend' : 'Range';
      if (Number.isFinite(pn[c])) macroTable[c].penteHebdo = pn[c];
      poses++;
    }
    if (!poses) console.warn('[SmartBias] comportement observé : aucune pente disponible (la force des devises n a pas encore tourné ?)');
    return poses;
  } catch (e) { console.warn('[SmartBias] comportement observé :', e && e.message); return 0; }
}
function _sbSeuilPente(deltas) {
  const abs = deltas.filter(d => Number.isFinite(d)).map(Math.abs);
  if (!abs.length) return 0.04;
  return Math.max(0.04, 0.6 * abs.reduce((a, b) => a + b, 0) / abs.length);
}
// Trend RÉEL dérivé de la force des devises (pente sur la semaine)
async function _sbTrendRow() {
  const out = {};
  try {
    const cs = await computeCurrencyStrength('week');
    const deltas = {};
    SB_CURRENCIES.forEach(c => {
      const s = cs?.series?.[c];
      deltas[c] = (s && s.length >= 2) ? (s[s.length - 1].v - s[0].v) : NaN;
    });
    const seuil = _sbSeuilPente(Object.values(deltas));
    _sbPenteHebdo = deltas;   // gardees pour la graduation du comportement observe (_sbPenteNorm)
    SB_CURRENCIES.forEach(c => {
      const d = deltas[c];
      out[c] = !Number.isFinite(d) ? 'Range' : d > seuil ? 'Uptrend' : d < -seuil ? 'Downtrend' : 'Range';
    });
  } catch { SB_CURRENCIES.forEach(c => out[c] = 'Range'); }
  return out;
}

// Technical RÉEL : direction de la force de la devise sur 1 JOUR (lecture court terme du prix),
// DISTINCT de Trend qui, lui, mesure la pente sur la semaine. 0 IA, 0 invention.
async function _sbTechnicalRow() {
  const out = {};
  try {
    const cs = await computeCurrencyStrength('1d');
    // Même correction d'échelle que _sbTrendRow : le seuil fixe 0,3 souffrait du même mal.
    const deltas = {};
    SB_CURRENCIES.forEach(c => {
      const s = cs?.series?.[c];
      deltas[c] = (s && s.length >= 2) ? (s[s.length - 1].v - s[0].v) : NaN;
    });
    const seuil = _sbSeuilPente(Object.values(deltas));
    SB_CURRENCIES.forEach(c => {
      const d = deltas[c];
      out[c] = !Number.isFinite(d) ? 'Range' : d > seuil ? 'Uptrend' : d < -seuil ? 'Downtrend' : 'Range';
    });
  } catch { SB_CURRENCIES.forEach(c => out[c] = 'Range'); }
  return out;
}

// Sentiment RÉEL : régime de risque global (Risk Sentiment du terminal, _riskData.pct ∈ [-100;+100])
// mappé par PROFIL de devise — risk-on → pro-cycliques (AUD/NZD/CAD) haussières & refuges
// (USD/JPY/CHF) baissiers ; inverse en risk-off. Mapping FX standard, 100% data-driven.
const _SB_RISK_PROFILE = { AUD: 1, NZD: 1, CAD: 0.8, EUR: 0.4, GBP: 0.4, USD: -0.5, JPY: -1, CHF: -1 };
// « Performance Cross-Asset » (pilier de la matrice) : régime de risque global × profil de la devise,
// noté sur 5 niveaux (mouvement marqué + profil fort → « Very »). Ce pilier alimente la conclusion (poids 1).
function _sbSentimentRow() {
  const out = {};
  const pct = (_riskData && typeof _riskData.pct === 'number') ? _riskData.pct : 0;   // >0 risk-on, <0 risk-off
  SB_CURRENCIES.forEach(c => {
    const v = pct * (_SB_RISK_PROFILE[c] || 0);   // ∈ [-100;+100], pondéré par la sensibilité au risque
    out[c] = v > 45 ? 'Very Bullish' : v > 15 ? 'Bullish' : v < -45 ? 'Very Bearish' : v < -15 ? 'Bearish' : 'Neutral';
  });
  return out;
}

// Biais par BANQUE et par devise, dérivé de la recherche RÉELLE de chaque banque (onglet Institution).
// → Couvre AUTOMATIQUEMENT toute banque présente dans _brCache : ajouter une source banque dans
//   Institution la fait apparaître ici. 1 appel IA/banque (hebdo, caché). Repli : {} (le front retombe
//   alors sur les positions de trade). N'invente rien (basé sur les titres de recherche réels).
async function _sbBankStances() {
  if (!Array.isArray(_brCache) || !_brCache.length) return {};
  const cutoff = Date.now() - 35 * 24 * 60 * 60 * 1000;   // ~5 semaines : couvre TOUTES les banques (certaines publient moins souvent que 2 semaines)
  const _strip = h => String(h || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
  const byBank = new Map();
  for (const a of _brCache) {
    if (!a || !a.institution || (a.timestamp || 0) < cutoff) continue;
    const arr = byBank.get(a.institution) || [];
    if (arr.length < 6) {
      // Biais basé sur le CONTENU RÉEL de la recherche (pas juste le titre) : fullContent (SEB/PDF) →
      // contenu structuré IA en cache (_brSegCache) → description → titre. C'est la matière de l'onglet Institution.
      const _seg = a.url ? _brSegCache.get(BR_SEG_VER + a.url) : null;
      const body = a.fullContent || (typeof _seg === 'string' ? _seg : '') || a.description || '';   // (le cache peut contenir un marqueur d'échec {f:ts} → ignoré)
      arr.push(`• ${a.title || ''}. ${_strip(body)}`.slice(0, 1300));
    }
    byBank.set(a.institution, arr);
  }
  const out = {};
  const OKV = ['Very Bullish', 'Bullish', 'Neutral', 'Bearish', 'Very Bearish'];
  let consecFail = 0;   // circuit breaker DOUX : on n'arrête qu'après 3 échecs IA d'AFFILÉE (un échec ponctuel/RPM ne tue plus toutes les banques suivantes) ; remis à 0 à chaque succès
  const prev = (_smartBias && _smartBias.bankStances) || {};   // biais déjà déterminés aux passes précédentes
  for (const [bank, heads] of byBank) {
    const clean = (bank || '').replace(/\s+Research$/i, '').trim();
    if (prev[clean] && Object.keys(prev[clean]).length) { out[clean] = prev[clean]; continue; }   // DÉJÀ fait → on garde, on ne re-dépense PAS le quota dessus → chaque passe traite des banques NOUVELLES (progression)
    const st = {};
    if (consecFail < 3 && aiAllowed('bank', { scheduled: true })) {
      const digest = heads.join('\n\n').slice(0, 3500);
      const prompt = `Tu es analyste FX. D'après UNIQUEMENT la recherche récente (articles / notes / PDF) de la banque "${bank}" ci-dessous, déduis son biais directionnel sur chaque devise majeure (${SB_CURRENCIES.join(', ')}).
Réponds UNIQUEMENT en JSON: {${SB_CURRENCIES.map(c => `"${c}":"Bullish|Bearish|Neutral"`).join(',')}}. Si la banque ne se prononce pas clairement sur une devise → "Neutral". N'invente RIEN.

Recherche ${bank} :
${digest}`;
      try {
        const t = await aiSmart('bank', prompt, 220, { scheduled: true });   // (aiSmart compte déjà via aiNote — le double débit de la part 'bank' est supprimé)
        const m = (t || '').match(/\{[\s\S]*\}/);
        if (m) { const obj = JSON.parse(m[0]); for (const c of SB_CURRENCIES) if (OKV.includes(obj[c])) st[c] = obj[c]; }
        consecFail = 0;   // succès → on continue sur toutes les banques suivantes
      } catch (e) { consecFail++; }   // échec ponctuel → on tente la banque suivante ; 3 d'affilée → on s'arrête (reprise au prochain retry)
    }
    out[clean] = st;   // TOUJOURS lister la banque (Neutral pour les devises sans biais IA → jamais de faux biais)
  }
  return out;
}

// Seasonality RÉELLE (même méthodo que market-bulls : rendement moyen du mois civil sur 5 ans),
// dérivée de la courbe saisonnière déjà calculée par FX List (_seasonal) → AUCUN fetch en plus, AUCUNE IA.
// Par paire : rendement saisonnier du MOIS COURANT = seasonal[m] - seasonal[m-1] (courbe cumulée Jan→Déc).
// Agrégation par devise comme la force : la devise de base gagne quand la paire monte, la devise de cotation perd.
async function _sbSeasonalityRow() {
  const out = {};
  try {
    const fx = await computeFxList();
    const pairs = fx?.pairs || [];
    const m = new Date().getUTCMonth();   // mois courant (le bias se régénère chaque semaine)
    const score = {}, cnt = {};
    SB_CURRENCIES.forEach(c => { score[c] = 0; cnt[c] = 0; });
    pairs.forEach(p => {
      const s = p.seasonal;
      if (!Array.isArray(s) || s.length < 12) return;
      const mRet = s[m] - (m > 0 ? s[m - 1] : 0);   // rendement saisonnier moyen du mois courant
      if (!Number.isFinite(mRet)) return;
      if (SB_CURRENCIES.includes(p.base))  { score[p.base]  += mRet; cnt[p.base]++; }
      if (SB_CURRENCIES.includes(p.quote)) { score[p.quote] -= mRet; cnt[p.quote]++; }
    });
    SB_CURRENCIES.forEach(c => {
      const avg = cnt[c] ? score[c] / cnt[c] : 0;   // tendance saisonnière nette de la devise (%)
      out[c] = avg > 0.25 ? 'Bullish' : avg < -0.25 ? 'Bearish' : 'Neutral';
    });
  } catch { SB_CURRENCIES.forEach(c => out[c] = 'Neutral'); }
  return out;
}

// ════════ MODÈLE DE CONFLUENCE (déterministe) ════════
// Chaque ligne de la matrice est notée depuis sa SOURCE RÉELLE ; la Conclusion = moyenne pondérée des
// lignes AFFICHÉES (façon pro) → elle découle TOUJOURS de la matrice (zéro divergence opaque). L'IA ne
// note QUE Monetary Policy (jugement banque centrale) + les biais par banque (_sbBankStances).
const _SB_BIAS5 = ['Very Bullish', 'Bullish', 'Neutral', 'Bearish', 'Very Bearish'];   // échelle des LIGNES (sans « Weak »)
// Inversion contrarian (Retail) : foule longue → pression baissière dans la conclusion.
const _SB_FLIP = { 'Very Bullish': 'Very Bearish', 'Bullish': 'Bearish', 'Weak Bullish': 'Weak Bearish', 'Neutral': 'Neutral', 'Range': 'Neutral', 'Weak Bearish': 'Weak Bullish', 'Bearish': 'Bullish', 'Very Bearish': 'Very Bullish' };
// Agrégat d'une liste de biais → 1 valeur 5 niveaux (parent = enfants). Sert à Fundamental (8 sous-indic.)
// et Bank Overview (N banques). Seuils alignés sur la charte (très/normal/neutre).
const _SB_AGG_SC = { 'Very Bullish': 2, 'Bullish': 1, 'Weak Bullish': 0.5, 'Uptrend': 1, 'Neutral': 0, 'Range': 0, 'Weak Bearish': -0.5, 'Bearish': -1, 'Downtrend': -1, 'Very Bearish': -2 };
function _sbAvgToBias(vals) {
  let s = 0, n = 0;
  (vals || []).forEach(v => { if (v != null && _SB_AGG_SC[v] != null) { s += _SB_AGG_SC[v]; n++; } });
  const a = n ? s / n : 0;
  return a >= 1.4 ? 'Very Bullish' : a >= 0.35 ? 'Bullish' : a <= -1.4 ? 'Very Bearish' : a <= -0.35 ? 'Bearish' : 'Neutral';
}
// Mappe un SCORE continu (-2..+2) vers une stance 5-échelles (mêmes seuils que _sbAvgToBias) — utilisé par le
// mélange DESK+TE du pilier fondamental pour retomber sur une valeur de cellule cohérente avec le reste de la matrice.
const _sbScoreToBias = a => a >= 1.4 ? 'Very Bullish' : a >= 0.35 ? 'Bullish' : a <= -1.4 ? 'Very Bearish' : a <= -0.35 ? 'Bearish' : 'Neutral';

// Hedge Fund Positioning RÉEL = COT CFTC non-commercial (grandes spéculatives). % long des spéculateurs → 5 niveaux. 0 IA.
async function _sbHedgeRow() {
  const out = {}; SB_CURRENCIES.forEach(c => out[c] = 'Neutral');
  try {
    const cot = await fetchCOTData('noncomm');
    (Array.isArray(cot) ? cot : []).forEach(r => {
      if (!r || !SB_CURRENCIES.includes(r.key)) return;
      const lp = Number(r.longPct);
      if (!Number.isFinite(lp)) return;
      out[r.key] = lp >= 62 ? 'Very Bullish' : lp >= 54 ? 'Bullish' : lp <= 38 ? 'Very Bearish' : lp <= 46 ? 'Bearish' : 'Neutral';
    });
  } catch (e) { console.warn('[SmartBias] COT (hedge) indispo:', e.message); }
  return out;
}

// Retail Positioning RÉEL = position de la FOULE (myfxbook), agrégée par devise via les paires majeures.
// AFFICHÉE telle quelle (foule longue → "Bullish") ; le caractère CONTRARIAN est appliqué dans la CONCLUSION. 0 IA.
async function _sbRetailRow() {
  const out = {}; SB_CURRENCIES.forEach(c => out[c] = 'Neutral');
  try {
    const data = await fetchCommunityOutlook('H1');
    const score = {}, cnt = {}; SB_CURRENCIES.forEach(c => { score[c] = 0; cnt[c] = 0; });
    (Array.isArray(data) ? data : []).forEach(s => {
      const sym = String(s.symbol || '').toUpperCase().replace(/[^A-Z]/g, '');
      if (sym.length !== 6) return;
      const base = sym.slice(0, 3), quote = sym.slice(3, 6);
      const lp = Number(s.longPct);
      if (!Number.isFinite(lp)) return;
      const lean = lp - 50;   // >0 : foule LONGUE la paire
      if (SB_CURRENCIES.includes(base))  { score[base]  += lean; cnt[base]++; }
      if (SB_CURRENCIES.includes(quote)) { score[quote] -= lean; cnt[quote]++; }
    });
    SB_CURRENCIES.forEach(c => {
      const a = cnt[c] ? score[c] / cnt[c] : 0;   // lean net de la foule (points de %)
      out[c] = a >= 18 ? 'Very Bullish' : a >= 6 ? 'Bullish' : a <= -18 ? 'Very Bearish' : a <= -6 ? 'Bearish' : 'Neutral';
    });
  } catch (e) { console.warn('[SmartBias] retail (crowd) indispo:', e.message); }
  return out;
}

// Fundamental Data RÉEL = 8 sous-indicateurs la référence dérivés du CALENDRIER (actual vs forecast, beat = haussier).
// MÊME source + MÊME logique que l'accordéon client. Renvoie {parent, subs} → parent = agrégat des 8 (cohérent). 0 IA.
// Sous-indicateurs alignés sur le PDF « Learning Economics News » (Inflation / Emploi / Croissance). Les libellés
// DOIVENT correspondre aux CATS de scrapers/tradingeconomics.js (clé de jointure TE). NFP/PCE/PPI = US-only →
// par devise on prend l'équivalent TE par pays. `inv:true` (chômage) : une surprise HAUSSIÈRE est BAISSIÈRE pour la devise.
const _SB_FUND_SUBS = [
  { label: 'Inflation (CPI)',    re: /\bCPI\b|inflation|consumer price|\bPPI\b|producer price|pce price|core pce/i },
  { label: 'Emploi (chômage)',   re: /unemployment rate|jobless/i, inv: true },
  { label: 'Salaires',           re: /average (hourly |weekly )?earnings|wage growth|\bwages\b/i },   // « average earnings » (UK, ex. « Average Earnings incl. Bonus ») en plus de « average hourly earnings » (US)
  // Ifo = indicateur AVANCÉ de la croissance de la zone euro (règle user 03/08 : « ifo = indicateur pour
  // déterminer la croissance de l'euro ») → capté en CROISSANCE, pas en Confiance (le veto user 21/07
  // « n'ajoute pas ça » portait sur Confiance/Sentiment — ZEW/Sentix y restent exclus).
  { label: 'Croissance (PIB)',   re: /\bGDP\b|gross domestic|economic growth|ifo business climate/i },
  { label: 'Ventes au détail',   re: /retail sales|retail trade/i },
  { label: 'PMI Manufacturier',  re: /manufacturing pmi|\bfactory\b|industrial production|ism manufactur|tankan|ivey|manufacturing production/i },
  { label: 'PMI Services',       re: /services? pmi|ism (services|non-manufactur)|tertiary industry/i },
];
function _sbFundStanceServer(actual, forecast) {
  const num = v => { const x = parseFloat(String(v == null ? '' : v).replace(/[^0-9.\-]/g, '')); return isNaN(x) ? null : x; };
  const a = num(actual), f = num(forecast);
  if (a == null || f == null) return null;
  const thr = Math.abs(f) * 0.001 + 0.0001;
  return a > f + thr ? 'Bullish' : a < f - thr ? 'Bearish' : 'Neutral';   // beat = surprise haussière de donnée
}
// HIÉRARCHIE ZONE EURO (règle user 03/08 : « l'Allemagne = 1er pays qui influence l'EUR, ensuite la
// France ») : sous EUR, une sortie ALLEMANDE (ou agrégée zone euro) pèse plein poids, une FRANÇAISE 0.7,
// les autres pays 0.45. Pays inconnu/vide → plein poids (ne jamais punir une donnée non étiquetée).
function _sbEurCtryW(ct) {
  const k = String(ct || '').toUpperCase();
  return (!k || k === 'DE' || k === 'EU' || k === 'EZ' || k === 'EMU') ? 1 : k === 'FR' ? 0.7 : 0.45;
}
// CALENDRIER PROFOND PARTAGÉ (11/08) : le cycle lourd télécharge 6 mois de publications ; on en garde une
// copie ALLÉGÉE (8 devises, publications chiffrées, champs utiles) pour que la couche live — qui ne voit
// que 21 jours — puisse mesurer les MÊMES niveaux. Sans ça, un indicateur mensuel n'a jamais assez de
// points hors du cycle lourd, et les colonnes Emploi/Niveau retombent à vide entre deux régénérations.
let _sbLongCal = { at: 0, items: [] }, _sbLongCalTry = 0;
// AMORÇAGE APRÈS REDÉMARRAGE : `_sbLongCal` naît vide (il est rempli par le cycle lourd, qui peut ne pas
// repasser avant ~20 h). Sans amorçage, chaque redéploiement priverait de nouveau la couche live de son
// historique — donc des NIVEAUX — pendant toute cette fenêtre. On le remplit une seule fois (throttle 1 h,
// jamais sur le chemin d'un utilisateur : appelé depuis le tic de fond).
async function _sbEnsureLongCal() {
  if (_sbLongCal.items.length && Date.now() - _sbLongCal.at < 26 * 3600000) return;
  if (Date.now() - _sbLongCalTry < 3600000) return;
  _sbLongCalTry = Date.now();
  try {
    const c6 = await _buildTVCalendarRange(6);
    if (c6 && c6.length) { _sbSetLongCal(_calHistMerge(c6)); console.log(`[SmartBias] calendrier profond amorcé : ${_sbLongCal.items.length} publications (6 mois)`); }
  } catch (e) { console.warn('[SmartBias] amorçage calendrier profond :', e.message); }
}
function _sbSetLongCal(cal) {
  try {
    const items = (cal || [])
      .filter(e => e && e.currency && SB_CURRENCIES.includes(e.currency) && e.title && e.actual != null && e.actual !== '')
      .map(e => ({ currency: e.currency, ctry: e.ctry || '', title: e.title, impact: e.impact, timestamp: e.timestamp || 0, actual: e.actual, forecast: e.forecast || '', previous: e.previous || '' }));
    if (items.length > 200) _sbLongCal = { at: Date.now(), items };   // garde-fou : un calendrier tronqué ne remplace pas un bon
  } catch {}
}
// Calendrier le PLUS PROFOND disponible : fenêtre courante (fraîche) + copie 6 mois (historique), dédupliquée
// à la minute pour ne jamais compter deux fois la même publication dans une série de tendance.
function _sbCalDeep() {
  const recent = _sbCalForDetail();
  if (!_sbLongCal.items.length || Date.now() - _sbLongCal.at > 26 * 3600000) return recent;
  const vus = new Set(recent.map(e => (e && e.currency) ? (e.currency + '|' + (e.ctry || '') + '|' + String(e.title).toLowerCase().trim() + '@' + Math.round((e.timestamp || 0) / 60000)) : ''));
  const out = recent.slice();
  for (const e of _sbLongCal.items) {
    const k = e.currency + '|' + (e.ctry || '') + '|' + String(e.title).toLowerCase().trim() + '@' + Math.round((e.timestamp || 0) / 60000);
    if (!vus.has(k)) out.push(e);
  }
  return out;
}
async function _sbFundamentalRows() {
  // SOURCE FIABLE : TradingEconomics (valeur réelle ACTUELLE + précédente de chaque indicateur → tendance,
  // toutes catégories renseignées). Bien plus robuste que le calendrier épars. REPLI : surprise du CALENDRIER
  // (actual vs forecast) par devise/catégorie si TE n'a pas l'indicateur — désormais AGRÉGÉE SUR ~3 MOIS de
  // publications (pondérée par récence) au lieu d'une seule sortie qui faisait basculer le biais sur une donnée
  // bruitée (demande user : « mise à jour des bias selon les datas sorties des mois passés »). Fenêtre = calendrier
  // du DESK (TradingView, 3 mois). Parent = agrégat des 8 enfants AFFICHÉS (cohérent). 0 IA — TE + règles détermin.
  let te = {};
  try { te = await fetchTEAll(SB_CURRENCIES); } catch (e) { console.warn('[SmartBias] TE indispo:', e.message); }
  let cal = [];
  try { cal = await _buildTVCalendarRange(6); } catch { try { cal = await _buildTVCalendar(); } catch {} }   // ~6 mois de publications (demande user : historique 6 mois pour des tendances fiables) ; repli : fenêtre courte
  try { cal = _calHistMerge(cal && cal.length ? cal : (allCalendar || [])); } catch { if (!cal || !cal.length) cal = allCalendar || []; }
  let usedCal = 0;
  const subs = _SB_FUND_SUBS.map(sub => {
    const values = {};
    SB_CURRENCIES.forEach(c => {
      // (1) DESK — datas RÉELLES publiées : agrégat des ~6 dernières sorties de cette famille sur 3 MOIS,
      //     pondéré par RÉCENCE (poids 1, 1/2, 1/3…) → surprise que PLUSIEURS publications confirment, pas
      //     une seule donnée bruitée. Source = calendrier du desk (familles du PDF). (Demande user.)
      const evs = (cal || [])
        .filter(e => e && e.currency === c && e.actual != null && e.actual !== '' && sub.re.test(e.title || ''))
        .sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0))
        .slice(0, 6);
      let score = 0, wsum = 0;
      evs.forEach((ev, i) => {
        const s0 = _sbFundStanceServer(ev.actual, ev.forecast);
        if (!s0) return;                                       // actual/forecast illisible → ne dilue pas
        // Récence (1, 1/2, 1/3…) × hiérarchie zone euro (DE/zone plein poids, FR 0.7, autres 0.45).
        const w = (1 / (i + 1)) * (c === 'EUR' ? _sbEurCtryW(ev.ctry) : 1);
        score += (s0 === 'Bullish' ? 1 : s0 === 'Bearish' ? -1 : 0) * w;
        wsum  += w;
      });
      let calNet = wsum ? score / wsum : null;                 // ∈ [-1,1] ou null (aucune publication)
      if (calNet != null && sub.inv) calNet = -calNet;         // chômage : surprise haussière = baissier devise
      const calScore = calNet == null ? null : calNet * 1.5;   // échelle comparable à _SB_AGG_SC (-2..+2)
      // (2) TE — tendance robuste (valeur réelle vs précédente), stance déjà orientée « impact devise »
      const teSub = te[c] && te[c].subs && te[c].subs.find(s => s.label === sub.label);
      const teScore = (teSub && teSub.name && _SB_AGG_SC[teSub.value] != null) ? _SB_AGG_SC[teSub.value] : null;
      // (3) MÉLANGE : le DESK (datas publiées des mois passés) PRIME (0.6) ; TE confirme la tendance (0.4).
      //     Quand ils divergent, les VRAIES sorties récentes du desk l'emportent. (Demande user.)
      let s;
      if (calScore != null && teScore != null) { s = 0.6 * calScore + 0.4 * teScore; usedCal++; }
      else if (calScore != null) { s = calScore; usedCal++; }
      else if (teScore != null) s = teScore;
      else s = 0;
      values[c] = _sbScoreToBias(s);
    });
    return { label: sub.label, values };
  });
  const parent = {};
  SB_CURRENCIES.forEach(c => { parent[c] = _sbAvgToBias(subs.map(s => s.values[c])); });   // parent = agrégat des 8 enfants affichés
  const teOk = Object.keys(te).length;
  _sbSetLongCal(cal);   // ← partage les 6 mois avec la couche live (sinon elle mesure sur 21 j et perd les niveaux)
  console.log(`[SmartBias] Fundamental = mélange DESK 3 mois (${usedCal} cellules) + TE (${teOk}/8 devises) : NZD parent=${parent.NZD} | calendrier profond partagé : ${_sbLongCal.items.length} publications`);
  return { parent, subs, cal };   // cal exposé → le MACRO TABLE en dérive niveau/tendance d'inflation sans re-fetch
}

// ── MACRO TABLE (demande user) : vue « MACRO DATA » par devise pour le Radar de Biais. Colonnes LISIBLES dérivées
//    des piliers DÉJÀ calculés (Politique monétaire, sous-piliers fondamentaux) + taux (direction hausse/baisse/
//    maintien) + Récap Hebdo (Driver). Le BIAIS de la colonne = la CONCLUSION déterministe (source de vérité
//    unique ; le Récap Hebdo s'aligne dessus). 0 IA — 100 % dérivé des données déjà calculées.
const _sbSense = v => /very bull|bull|uptrend|hawk/i.test(String(v)) ? 'up' : /very bear|bear|downtrend|dov/i.test(String(v)) ? 'down' : 'flat';
const _sbNum = v => { const x = parseFloat(String(v == null ? '' : v).replace(/[^0-9.\-]/g, '')); return isNaN(x) ? null : x; };
// TENDANCE sur l'HISTORIQUE (demande user « ça se base sur l'historique pour savoir si c'est en tendance
// haussière/baissière/neutre ») : on ne compare PLUS 2 points (bruité) mais la MOYENNE des publications RÉCENTES
