setTimeout(() => { _waFamLoad().catch(() => {}); }, 22000);   // rechargé au boot, avant la 1re génération

/* ── Pricing du desk sur les cartes de DÉCISION DE TAUX (30/08, suite de l'audit taux : « le
   template semaine à venir aussi, comme on a mis à jour le widget sur le desk »). Quand une journée
   porte une décision d'une des 8 banques suivies, la carte dit le taux actuel et le scénario pricé
   de CETTE réunion, avec sa source honnête (pricing de marché / estimation DTP). 100 % déterministe,
   dans l'esprit v20 : aucune IA, on RÉPÈTE des chiffres que l'onglet TAUX affiche déjà.
   Garde-fou : la phrase ne sort que si la PROCHAINE réunion pricée de la banque tombe ce jour-là
   (±2 j, fuseaux) — sinon on collerait à une décision les probabilités d'une AUTRE réunion ; le
   même garde-fou éteint naturellement la phrase en mode ARCHIVE (réunion pricée = future). */
const _WA_DECISION_RX = /interest rate decision|rate decision|official bank rate|federal funds rate|deposit facility rate|official cash rate|\bcash rate\b|\bpolicy rate\b|\bovernight rate\b/i;
const _WA_CB_NOM = { USD: 'Fed', EUR: 'BCE', GBP: 'BoE', JPY: 'BoJ', CAD: 'BoC', AUD: 'RBA', CHF: 'BNS', NZD: 'RBNZ' };
function _waPricingDecision(evs, jourISO) {
  try {
    const cibles = (evs || []).filter(e => e && _WA_CB_NOM[e.currency] && _WA_DECISION_RX.test(e.title || ''));
    if (!cibles.length) return '';
    const p = _buildRatesPayload();
    const banks = (p && Array.isArray(p.banks)) ? p.banks : [];
    const vues = new Set();
    const fr = n => String(n).replace('.', ',');
    const out = [];
    for (const e of cibles) {
      if (vues.has(e.currency)) continue;
      vues.add(e.currency);
      const b = banks.find(x => x.code === e.currency);
      if (!b || !b.scenario || !b.next) continue;
      if (Math.abs(Date.parse(b.next + 'T00:00:00Z') - Date.parse(jourISO + 'T00:00:00Z')) > 2 * 86400000) continue;
      const sc = b.scenario;
      const morceaux = [['maintien', sc.hold], ['hausse', sc.hike], ['baisse', sc.cut]]
        .filter(x => +x[1] > 0).sort((a, z) => z[1] - a[1]).map(x => `${x[0]} ${fr(x[1])}%`);
      if (!morceaux.length || !(typeof b.rate === 'number' && isFinite(b.rate))) continue;
      const src = b.source === 'market' ? 'pricing de marché' : 'estimation DTP';
      out.push(`Pricing du desk pour la décision de la ${_WA_CB_NOM[e.currency]} : ${morceaux.join(', ')}, taux actuel ${fr(b.rate)}% (${src}).`);
    }
    return out.join(' ');
  } catch (e) { return ''; }
}
