app.get('/api/v1/reports', requireApiKey, (req, res) => {
  /* ⚠️ LA LISTE ÉTAIT ÉCRITE EN DUR, ET IL Y MANQUAIT LES TROIS RÉCAPS DE SÉANCE (03/09, demande
     utilisateur : « il faut qu'on ait accès à tout du desk, si je veux récupérer les récaps »).
     `Asia Session Recap`, `London Session Recap` et `US Session Recap` sont produits chaque jour,
     lisibles dans l'onglet ANALYSTES — et l'API les ignorait purement et simplement : un client qui
     appelait /api/v1/reports recevait cinq types sur huit, sans que rien ne lui dise que trois
     manquaient. C'est exactement la faute déjà corrigée ailleurs dans ce dépôt : une liste recopiée
     à côté de sa source finit par mentir.
     ON LA DÉRIVE DONC DE LA SOURCE. Les types de séance viennent de `_SEA.FENETRES`, celui-là même
     qui décide de leur production : ajouter une quatrième séance un jour la rendra disponible ici
     sans que personne n'ait à y penser. Les cinq autres restent nommés, faute d'une table qui les
     porte — mais ils ne bougent pas, eux. */
  const TYPES = ['FX Daily Recap', 'DTP Daily', 'Weekly Market Recap', 'Global Economic Weekly', 'European Market Wrap']
    .concat(Object.keys(_SEA.FENETRES || {}));
  const type = String(req.query.type || '');
  const limit = Math.max(1, Math.min(50, parseInt(req.query.limit, 10) || 20));
  let items = allNews.filter(i => i && (TYPES.includes(i._reportType) || i._marketWrap));
  if (type) items = items.filter(i => i._reportType === type);
  const out = items.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0)).slice(0, limit).map(i => ({
    id: i.id, type: i._reportType || 'European Market Wrap', headline: i.headline,
    timestamp: i.timestamp || 0, publishedAt: i.timestamp ? new Date(i.timestamp).toISOString() : null,
    coveredDay: (i._fxr && i._fxr.day) || (i._dtpd && i._dtpd.day) || null,
    coveredWeek: (i._weekly && (i._weekly.weekRange || i._weekly.weekEnding)) || null,
  }));
  _v1(res, out, { count: out.length, types: TYPES, detail: 'GET /api/v1/reports/{id} → rapport complet (texte + données structurées)' });
});
