const DESC_FR_PAR_CYCLE = 8;
const DESC_FR_MAX_JOUR = (function () {
  const v = parseInt(process.env.DESC_FR_MAX_JOUR, 10);
  return Number.isFinite(v) ? v : 400;
})();
let _descFrJour = '', _descFrCount = 0, _descFrEssais = 0;
