  let currencies = [];
  try { currencies = await fetchCOTData('lev_money'); } catch (e) {}
  const data = { currencies: (currencies || []).slice(0, 4), type: 'lev_money', updatedAt: new Date().toISOString() };
  res.set('Cache-Control', 'no-store');
