const _DECRYPT_VETO_RX = /(prene[zs]|prend[sre]*|ouvre[zr]?)\s+(une\s+)?position|achete[zr]\b|vende[zr]\b|il faut (acheter|vendre)|signal (d'achat|de vente)|(conseille|recommande)\s+(d'acheter|de vendre)/i;
